	getBlockHits = function(block, blockpos)
		if not block then return 0 end
		local itemMeta = bedwars.ItemMeta[block.Name]
		local breaktype = itemMeta and itemMeta.block and itemMeta.block.breakType
		local tool = getBreakTool(breaktype)
		local toolMeta = tool and bedwars.ItemMeta[tool.itemType]
		tool = toolMeta and toolMeta.breakBlock and toolMeta.breakBlock[breaktype] or 2
		return math.max(tonumber(getBlockHealth(block, bedwars.BlockController:getBlockPosition(blockpos))) or tonumber(block:GetAttribute('MaxHealth')) or 1, 1) / math.max(tonumber(tool) or 2, 0.01)
	end

	--[[
		Pathfinding using a luau version of dijkstra's algorithm
		Source: https://stackoverflow.com/questions/39355587/speeding-up-dijkstras-algorithm-to-solve-a-3d-maze
	]]
	local function isMinable(pos)
		for _, side in {Vector3.new(0, 3, 0), Vector3.new(3, 0, 0), Vector3.new(0, 0, 3)} do
			side = pos + side
			local block = getPlacedBlock(side)
			if not block or (block:GetAttribute("PlacedByUserId") or 0) ~= 0 then
				return true
			end
		end
		return false
	end
	-- How a finished path is scored, i.e. which of several ways in gets picked.
	--
	--   Blatant (the default, prefs nil)  - quickest, and nothing else. Lowest total hits wins.
	--   Legit (prefs.Legit)               - must be in line of sight, then closest to the player,
	--                                       while still preferring the efficient way in: distance is
	--                                       added to the cost at half a hit per block, so a genuinely
	--                                       cheaper path still beats a nearer one, and two comparable
	--                                       paths are decided by which is nearer to you.
	--   prefs.FewestBlocks (Health mode)  - number of blocks to break always wins, whatever they
	--                                       cost, with cost only breaking ties.
	local function pathScore(node, cost, depth, prefs)
		local primary, secondary = cost, depth or 0
		if prefs and prefs.FewestBlocks then
			primary, secondary = depth or 0, cost
		end
		if prefs and prefs.Legit and entitylib.isAlive then
			local from = entitylib.character.RootPart.Position
			primary += ((node - from).Magnitude / 3) * 0.5
		end
		return primary, secondary
	end

	local function calculatePath(target, blockpos, method, angle, wallcheck, prefs)
		-- Breaker's "Legit" mode passes a line-of-sight predicate function as `wallcheck`.
		-- When present, only air nodes genuinely visible from the camera are eligible AND the
		-- entire break path to that node must be visible, so we never blindly mine through walls.
		-- Any non-function value keeps the original behaviour (boolean/Vector3 -> isMinable gate),
		-- so AutoTool and Blatant breaking are completely unaffected.
		local legitCheck = type(wallcheck) == 'function' and wallcheck or nil
		local visited, unvisited, distances, air, path = {}, {{0, blockpos, 0}}, {[blockpos] = 0}, {}, {}
		local depths, visibility = {[blockpos] = 0}, {}
		local function push(value)
			table.insert(unvisited, value)
			local index = #unvisited
			while index > 1 do
				local parent = math.floor(index / 2)
				if unvisited[parent][1] <= value[1] then break end
				unvisited[index], index = unvisited[parent], parent
			end
			unvisited[index] = value
		end
		local function pop()
			local root, tail = unvisited[1], table.remove(unvisited)
			if #unvisited > 0 then
				local index = 1
				while index * 2 <= #unvisited do
					local child = index * 2
					if child < #unvisited and unvisited[child + 1][1] < unvisited[child][1] then child += 1 end
					if unvisited[child][1] >= tail[1] then break end
					unvisited[index], index = unvisited[child], child
				end
				unvisited[index] = tail
			end
			return root
		end

		local function isNodeVisible(pos)
			if visibility[pos] == nil then
				visibility[pos] = not legitCheck or legitCheck(pos)
			end
			return visibility[pos]
		end

		for _ = 1, (legitCheck and 300 or 10000) do
			local node = pop()
			if not node then break end
			if node[1] ~= distances[node[2]] then continue end
			visited[node[2]] = true

			for _, side in sides do
				side = node[2] + side
				if visited[side] then continue end

				local block = getPlacedBlock(side)
				if not block or block:GetAttribute('NoBreak') or block == target then
					if not block and isNodeVisible(node[2]) then
						air[node[2]] = true
					end
					continue
				end

				local facing = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
				local direction = (block.Position - entitylib.character.RootPart.Position) * Vector3.new(1, 0, 1)
				if facing.Magnitude < 0.001 or direction.Magnitude < 0.001 or math.acos(math.clamp(facing.Unit:Dot(direction.Unit), -1, 1)) > (math.rad(angle) / 2) then
					continue
				end

				local curdist = (method and method(block, side) or getBlockHits(block, side)) + node[1]
				if curdist < (distances[side] or math.huge) then
					push({curdist, side, node[3] + 1})
					distances[side] = curdist
					depths[side] = node[3] + 1
					path[side] = node[2]
				end
			end
		end

		local pos, cost = nil, math.huge
		local bestPrimary, bestSecondary = math.huge, math.huge
		local function consider(node)
			local primary, secondary = pathScore(node, distances[node], depths[node], prefs)
			if primary < bestPrimary or (primary == bestPrimary and secondary < bestSecondary) then
				pos, cost = node, distances[node]
				bestPrimary, bestSecondary = primary, secondary
			end
		end
		for node in air do
			if legitCheck then
				local ok, cur, guard = true, node, 0
				while cur ~= blockpos do
					guard += 1
					if guard > 10000 or not isNodeVisible(cur) then
						ok = false
						break
					end
					cur = path[cur]
				end
				if ok then
					consider(node)
				end
			elseif not wallcheck or isMinable(node) then
				consider(node)
			end
		end

		if pos then
			cache[blockpos] = {
				pos,
				cost,
				path,
				depths[pos],
			}
			return pos, cost, path, depths[pos]
		end
		return nil
	end
	bedwars.calculateBreakPath = calculatePath

	bedwars.placeBlock = function(pos, item)
		local function place()
			if not getItem(item) then return end
			store.blockPlacer.blockType = item
			return store.blockPlacer:placeBlock(bedwars.BlockController:getBlockPosition(pos))
		end
		-- IgnorePlaceHitboxes only suppresses avatar queries for this one placement
		-- transaction. Leaving CanQuery disabled on characters also removes them from
		-- projectile raycasts, which is why arrows could stop registering hits.
		if bedwars.IgnorePlaceHitboxes then
			return bedwars.IgnorePlaceHitboxes(place)
		end
		return place()
	end

	bedwars.breakBlock = function(block, effects, anim, customHealthbar, visualise, sort, angle, wallcheck, prefs)
		if lplr:GetAttribute('DenyBlockBreak') or not entitylib.isAlive then return end

		local handler = bedwars.BlockController:getHandlerRegistry():getHandler(block.Name)
		local cost, pos, target, path = math.huge, nil, nil, nil
		local bestPrimary, bestSecondary = math.huge, math.huge

		for _, v in (handler and handler:getContainedPositions(block) or {block.Position / 3}) do
			local dpos, dcost, dpath, ddepth = calculatePath(block, v * 3, sort, angle or 360, wallcheck, prefs)
			if dpos then
				-- Score the whole entry the same way its nodes were scored, so a multi-cell block
				-- (a bed) picks the cell whose way in matches the mode too, not just the cheapest.
				local primary, secondary = pathScore(dpos, dcost, ddepth, prefs)
				if primary < bestPrimary or (primary == bestPrimary and secondary < bestSecondary) then
					cost, pos, target, path = dcost, dpos, v * 3, dpath
					bestPrimary, bestSecondary = primary, secondary
				end
			end
		end

		if pos then
			if (entitylib.character.RootPart.Position - pos).Magnitude > 30 then return end
			local dblock, dpos = getPlacedBlock(pos)
			if not dblock then return end

			local dmeta = bedwars.ItemMeta[dblock.Name]
			local breaktype = dblock.Name == 'gumdrop_bounce_pad' and 'stone' or (dmeta and dmeta.block and dmeta.block.breakType)
			-- getBreakTool searches the inventory for uncached break types like the bed
			-- frame, so the axe (or shears for wool) is selected instead of whatever is in
			-- hand. Fall back to the pickaxe when no better tool exists so we never silently
			-- mine the bed with a leftover pickaxe from a prior stone break.
			local tool = getBreakTool(breaktype) or store.tools.stone
			if tool then
				local now = workspace:GetServerTimeNow()
				local held = store.hand and store.hand.tool
				local holdingSword = held ~= nil and store.tools.sword ~= nil and held == store.tools.sword.tool
				local holdingProjectile = held ~= nil and store.hand.toolType == 'bow'
				-- Keep the sword equipped while a swing was just thrown so KillAura isn't
				-- interrupted, and keep the bow while ProjectileAura is actively firing so its
				-- shot isn't yanked away — but never leave the WRONG break tool equipped: if
				-- we're holding e.g. a leftover pickaxe on a wood block, still switch to the
				-- correct tool. The old guard blocked every switch during combat, which is how a
				-- pickaxe from a prior stone break ended up breaking wood while combat was active.
				local busyMelee = (now - bedwars.SwordController.lastAttack) <= 0.4 and holdingSword
				local busyProjectile = (now - (store.lastProjectileFire or 0)) <= 0.35 and holdingProjectile
				if not (busyMelee or busyProjectile) then
					if visualise then
						local hotbar = getHotbar(tool.tool)
						if hotbar then hotbarSwitch(hotbar) end
					end
					if not held or held ~= tool.tool then switchItem(tool.tool, 0) end
				end
			end

			if blockhealthbar.blockHealth == -1 or dpos ~= blockhealthbar.breakingBlockPosition then
				blockhealthbar.blockHealth = getBlockHealth(dblock, dpos)
				blockhealthbar.breakingBlockPosition = dpos
			end

			local request = bedwars.ClientDamageBlock:Get('DamageBlock'):CallServerAsync({
				blockRef = {blockPosition = dpos},
				hitPosition = pos,
				hitNormal = Vector3.FromNormalId(Enum.NormalId.Top)
			}):andThen(function(result)
				if result then
					if result == 'cancelled' then
						store.damageBlockFail = tick() + 0.25
						return result
					end

					-- Every BedWars call below is isolated so that one that shifted in a game
					-- update can't throw and abort the rest of this callback. Previously a single
					-- broken API (e.g. the removed BlockBreaker.healthbarMaid) silently took down
					-- both the healthbar and the swing animation that runs just after it.
					local showEffects = type(effects) == 'function' and effects() or effects
					local showAnimation = type(anim) == 'function' and anim() or anim
					if showEffects then
						local blockdmg = (blockhealthbar.blockHealth - (result == 'destroyed' and 0 or getBlockHealth(dblock, dpos)))
						local drawHealthbar = customHealthbar or bedwars.BlockBreaker.updateHealthbar
						if drawHealthbar then
							pcall(drawHealthbar, bedwars.BlockBreaker, {blockPosition = dpos}, blockhealthbar.blockHealth, tonumber(dblock:GetAttribute('MaxHealth')) or blockhealthbar.blockHealth, blockdmg, dblock)
						end
						blockhealthbar.blockHealth = math.max(blockhealthbar.blockHealth - blockdmg, 0)

						if blockhealthbar.blockHealth <= 0 then
							pcall(function() bedwars.BlockBreaker.breakEffect:playBreak(dblock.Name, dpos, lplr) end)
							if bedwars.BlockBreaker.healthbarMaid then
								pcall(function() bedwars.BlockBreaker.healthbarMaid:DoCleaning() end)
							end
							blockhealthbar.breakingBlockPosition = Vector3.zero
						else
							pcall(function() bedwars.BlockBreaker.breakEffect:playHit(dblock.Name, dpos, lplr) end)
						end
					end

					if showAnimation then
						pcall(function()
							local animation = bedwars.AnimationUtil:playAnimation(lplr, bedwars.BlockController:getAnimationController():getAssetId(1))
							bedwars.ViewmodelController:playAnimation(15)
							task.wait(0.3)
							animation:Stop()
							animation:Destroy()
						end)
					end
				end
				return result
			end)

			return pos, path, target, request
		end
		return nil
	end

	for _, v in Enum.NormalId:GetEnumItems() do
		table.insert(sides, Vector3.FromNormalId(v) * 3)
	end

	local function updateStore(new, old)
		if new.Bedwars ~= old.Bedwars then
			local state = type(new.Bedwars) == 'table' and new.Bedwars or {}
			local previousKit = store.equippedKit
			local previousReady = store.kitReady
			store.kitReady = type(new.Bedwars) == 'table'
			store.equippedKit = state.kit and state.kit ~= 'none' and state.kit or ''
			if (previousKit ~= store.equippedKit or previousReady ~= store.kitReady) and type(vape.RefreshGameInfo) == 'function' then
				vape:RefreshGameInfo()
			end
		end

		if new.Game ~= old.Game then
			local state = type(new.Game) == 'table' and new.Game or {}
			store.matchState = state.matchState or 0
			store.queueType = state.queueType or 'bedwars_test'
		end

		if new.Inventory ~= old.Inventory then
			local function normalizeInventory(value)
				value = type(value) == 'table' and value or {}
				local inventory = type(value.inventory) == 'table' and value.inventory or {}
				if type(value.inventory) == 'table' and type(inventory.items) == 'table'
					and type(inventory.armor) == 'table' and type(value.hotbar) == 'table' then return value end
				local normalized = table.clone(value)
				normalized.inventory = table.clone(inventory)
				normalized.inventory.items = type(inventory.items) == 'table' and inventory.items or {}
				normalized.inventory.armor = type(inventory.armor) == 'table' and inventory.armor or {}
				normalized.hotbar = type(value.hotbar) == 'table' and value.hotbar or {}
				return normalized
			end
			local newinv = normalizeInventory(new.Inventory and new.Inventory.observedInventory)
			local oldinv = normalizeInventory(old.Inventory and old.Inventory.observedInventory)
			store.inventory = newinv

			if newinv ~= oldinv then
				vapeEvents.InventoryChanged:Fire()
			end

			if newinv.inventory.items ~= oldinv.inventory.items then
				vapeEvents.InventoryAmountChanged:Fire()
				-- Rebuild from scratch so on-demand break tools memoised by getBreakTool
				-- (e.g. the bed's axe) are dropped and re-resolved against the new inventory.
				store.tools = {sword = getSword()}
				for _, v in {'stone', 'wood', 'wool'} do
					store.tools[v] = getTool(v)
				end
			end

			if newinv.inventory.hand ~= oldinv.inventory.hand then
				local currentHand, toolType = newinv.inventory.hand, ''
				if currentHand then
					local handData = bedwars.ItemMeta[currentHand.itemType]
					if handData then
						toolType = handData.sword and 'sword' or handData.block and 'block' or currentHand.itemType:find('bow') and 'bow'
					end
				end

				store.hand = {
					tool = currentHand and currentHand.tool,
					itemType = currentHand and currentHand.itemType,
					amount = currentHand and currentHand.amount or 0,
					toolType = toolType
				}
			end
		end
	end

	local storeChanged = bedwars.Store.changed:connect(updateStore)
	updateStore(bedwars.Store:getState(), {})
	if type(vape.RefreshGameInfo) == 'function' then vape:RefreshGameInfo() end

	for _, event in {'MatchEndEvent', 'EntityDeathEvent', 'BedwarsBedBreak', 'BalloonPopped', 'AngelProgress', 'GrapplingHookFunctions'} do
		if not vape.Connections then return end
		bedwars.Client:WaitFor(event):andThen(function(connection)
			vape:Clean(connection:Connect(function(...)
				vapeEvents[event]:Fire(...)
			end))
		end)
	end

	vape:Clean(bedwars.ZapNetworking.EntityDamageEventZap.On(function(...)
		local a = {
			entityInstance = ...,
			damage = select(2, ...),
			damageType = select(3, ...),
			fromPosition = select(4, ...),
			fromEntity = select(5, ...),
			knockbackMultiplier = select(6, ...),
			knockbackId = select(7, ...),
			disableDamageHighlight = select(13, ...)
		}
		shared.bindable:Fire(a)
		vapeEvents.EntityDamageEvent:Fire(a)
	end))

	vape:Clean(workspace.ChildAdded:Connect(function(projectile)
		task.delay(0, function()
			if projectile and projectile.Parent and entitylib.isAlive and projectile:GetAttribute('ProjectileShooter') == lplr.UserId then
				table.insert(store.selfProjectiles, projectile)
				projectile.Destroying:Once(function()
					local index = table.find(store.selfProjectiles, projectile)
					if index then
						table.remove(store.selfProjectiles, index)
					end
				end)
			end
		end)
	end))

	for _, event in {'BreakBlockEvent'} do
		vape:Clean(bedwars.ZapNetworking[event..'Zap'].On(function(...)
			local data = {
				blockRef = {
					blockPosition = ...,
				},
				player = select(5, ...)
			}
			for i, v in cache do
				if ((data.blockRef.blockPosition * 3) - v[1]).Magnitude <= 30 then
					table.clear(v[3])
					table.clear(v)
					cache[i] = nil
				end
			end
			vapeEvents[event]:Fire(data)
		end))
	end

	store.blocks = collection('block', vape)
	store.shop = collection({'BedwarsItemShop', 'TeamUpgradeShopkeeper'}, vape, function(tab, obj)
		table.insert(tab, {
			Id = obj.Name,
			RootPart = obj,
			Shop = obj:HasTag('BedwarsItemShop'),
			Upgrades = obj:HasTag('TeamUpgradeShopkeeper')
		})
	end)
	store.enchant = collection({'enchant-table', 'broken-enchant-table'}, vape, nil, function(tab, obj, tag)
		if obj:HasTag('enchant-table') and tag == 'broken-enchant-table' then return end
		obj = table.find(tab, obj)
		if obj then
			table.remove(tab, obj)
		end
	end)

	local kills = sessioninfo:AddItem('Kills')
	local beds = sessioninfo:AddItem('Beds')
	local wins = sessioninfo:AddItem('Wins')
	local games = sessioninfo:AddItem('Games')
	sessioninfo:AddItem('Cheater List', '', function()
		local text = ''
		for _, plr in playersService:GetPlayers() do
			if CheatersFlagged[plr] then
				text = text..'\n'..(plr.DisplayName ~= plr.Name and plr.DisplayName..' ('..plr.Name..')' or plr.Name)
			end
		end

		return text
	end, false)

	local mapname = 'Unknown'
	sessioninfo:AddItem('Map', 0, function()
		return mapname
	end, false)

	task.delay(1, function()
		games:Increment()
	end)

	task.spawn(function()
		pcall(function()
			repeat task.wait() until store.matchState ~= 0 or vape.Loaded == nil
			if vape.Loaded == nil then return end
			store.map = waitForChildYield(workspace, 9e9, 'Map', 'Worlds'):GetChildren()[1]
			mapname = store.map.Name
			mapname = string.gsub(string.split(mapname, '_')[2] or mapname, '-', '') or 'Blank'
			if store.map then
				-- Block/terrain-only raycast filter shared by the ground/clear-space checks in
				-- TP Aura, AntiFall and other movement modules. It Includes only the map world
				-- (islands, generators and the placed-Blocks folder), so every one of those casts
				-- hits solid geometry and never a player/NPC. Without this it was left nil, which
				-- made casts collide with characters - e.g. TP Aura's target-facing clear check hit
				-- the target itself and rejected every teleport spot, so the module did nothing.
				local blockRay = RaycastParams.new()
				blockRay.FilterType = Enum.RaycastFilterType.Include
				blockRay.FilterDescendantsInstances = {store.map}
				blockRay.RespectCanCollide = true
				store.blockRaycast = blockRay
				vape:Clean(store.map.Blocks.ChildAdded:Connect(function(v) -- bedwars game is so bad bro 😭 how did you even break this event
					task.delay(0, function()
						if v:GetAttribute('Block') and (v:GetAttribute('PlacedByUserId') or 0) ~= 0 then
							local data = {
								blockRef = {
									blockPosition = v.Position / 3,
								},
								player = playersService:GetPlayerByUserId(v:GetAttribute('PlacedByUserId')),
							}
							for i, v in cache do
								if ((data.blockRef.blockPosition * 3) - v[1]).Magnitude <= 30 then
									table.clear(v[3])
									table.clear(v)
									cache[i] = nil
								end
							end
							vapeEvents.PlaceBlockEvent:Fire(data)
						end
					end)
				end))
			end
		end)
	end)

	vape:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(bedTable)
		if bedTable.player and bedTable.player.UserId == lplr.UserId then
			beds:Increment()
		end
	end))

	vape:Clean(vapeEvents.MatchEndEvent.Event:Connect(function(winTable)
		if (bedwars.Store:getState().Game.myTeam or {}).id == winTable.winningTeamId or lplr.Neutral then
			wins:Increment()
		end
	end))

	vape:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
		local killer = playersService:GetPlayerFromCharacter(deathTable.fromEntity)
		local killed = playersService:GetPlayerFromCharacter(deathTable.entityInstance)
		if not killed or not killer then return end

		if killed ~= lplr and killer == lplr then
			kills:Increment()
		end
	end))

	task.spawn(function()
		local rayParams = RaycastParams.new()
		rayParams.FilterType = Enum.RaycastFilterType.Include
		rayParams.FilterDescendantsInstances = {workspace:WaitForChild('Map', 9e9)}
		store.airRay = rayParams

		repeat
			if entitylib.isAlive then
				entitylib.character.AirTime = workspace:Raycast((store.rootpart or entitylib.character.RootPart).Position, Vector3.new(0, -4.5, 0), rayParams) and tick() or entitylib.character.AirTime
			end

			for _, v in entitylib.List do
				v.LandTick = math.abs(v.RootPart.Velocity.Y) < 0.1 and v.LandTick or tick()
				if (tick() - v.LandTick) > 0.2 and v.Jumps ~= 0 then
					v.Jumps = 0
					v.Jumping = false
				end
			end
			task.wait()
		until vape.Loaded == nil
	end)

	pcall(function()
		if getthreadidentity and setthreadidentity or not canDebug then
			local old = getthreadidentity()
			setthreadidentity(2)

			bedwars.Shop = require(replicatedStorage.TS.games.bedwars.shop['bedwars-shop']).BedwarsShop
			-- The catalogue and the warm-up call are both nice-to-haves, and both are read
			-- through structure the game is free to change - an upvalue index and an item id.
			-- Left unguarded, either one throwing took the whole block down BEFORE shopLoaded
			-- was set, which silently switched off everything that waits on the shop, AutoBuy
			-- included. The shop table itself is what actually matters here.
			pcall(function()
				bedwars.ShopItems = debug.getupvalue(debug.getupvalue(bedwars.Shop.getShopItem, 1), 2)
			end)
			pcall(bedwars.Shop.getShopItem, 'iron_sword', lplr)

			setthreadidentity(old)
			store.shopLoaded = true
		else
			task.spawn(function()
				repeat
					task.wait(0.1)
				until vape.Loaded == nil or bedwars.AppController:isAppOpen('BedwarsItemShopApp')

				bedwars.Shop = require(replicatedStorage.TS.games.bedwars.shop['bedwars-shop']).BedwarsShop
				pcall(function()
					bedwars.ShopItems = debug.getupvalue(debug.getupvalue(bedwars.Shop.getShopItem, 1), 2)
				end)
				store.shopLoaded = true
			end)
		end
	end)

	vape:Clean(function()
		Client.Get = OldGet
		bedwars.BlockController.isBlockBreakable = OldBreak
		store.blockPlacer:disable()
		shared.bindable:Destroy()
		for _, v in vapeEvents do
			v:Destroy()
		end
		for _, v in cache do
			table.clear(v[3])
			table.clear(v)
		end
		table.clear(store.blockPlacer)
		table.clear(vapeEvents)
		table.clear(bedwars)
		table.clear(store)
		table.clear(cache)
		table.clear(sides)
		table.clear(remotes)
		storeChanged:disconnect()
		storeChanged = nil
	end)
end, 20)

for _, v in {'AntiRagdoll', 'TriggerBot', 'SilentAim', 'AutoRejoin', 'Rejoin', 'Disabler', 'Timer', 'ServerHop', 'NoFallDamage', 'MurderMystery', 'Invisible'} do
	vape:Remove(v)
end

-- MouseTP is universal, but its BedWars choice is installed only after the live BedWars
-- controllers and inventory helpers are ready. Other games keep the shorter Legit/TP list.
do
	local mouseTPBridge = vape.Libraries.MouseTPBridge
	if mouseTPBridge and type(mouseTPBridge.SetBedWars) == 'function' then
		mouseTPBridge:SetBedWars(function(position)
			if not entitylib.isAlive then return false, 'Character missing.' end
			local pearl = getItem('telepearl')
			local meta = bedwars.ProjectileMeta and bedwars.ProjectileMeta.telepearl
			if not pearl or not pearl.tool or not meta then return false, 'No Telepearl is available.' end

			local root = entitylib.character.RootPart
			local target = position
			local aim = prediction.SolveTrajectory(
				root.Position,
				meta.launchVelocity,
				meta.gravitationalAcceleration,
				target,
				Vector3.zero,
				workspace.Gravity,
				0,
				0
			)
			if not aim then return false, 'The selected position is outside Telepearl range.' end

			local remote
			local remoteOK = pcall(function() remote = bedwars.Client:Get(remotes.FireProjectile).instance end)
			if not remoteOK or not remote or type(remote.InvokeServer) ~= 'function' then
				return false, 'The BedWars projectile remote is unavailable.'
			end

			local old = store.hand
			local slot = getHotbar(pearl.tool)
			switchItem(pearl.tool, 0.1)
			if slot then hotbarSwitch(slot) end
			task.wait(0.03)

			local direction = CFrame.lookAt(root.Position, aim).LookVector * meta.launchVelocity
			local id = httpService:GenerateGUID(true)
			local draw = {drawDurationSeconds = 1, shotId = httpService:GenerateGUID(false)}
			local success, result = pcall(function()
				bedwars.ProjectileController:createLocalProjectile(
					meta,
					'telepearl',
					'telepearl',
					root.Position,
					id,
					direction,
					draw
				)
				return remote:InvokeServer(
					pearl.tool,
					'telepearl',
					'telepearl',
					root.Position,
					root.Position,
					direction,
					id,
					draw,
					workspace:GetServerTimeNow() - 0.045
				)
			end)

			if old and old.tool then
				task.delay(0.12, function()
					if old.tool.Parent then
						switchItem(old.tool)
						local oldSlot = getHotbar(old.tool)
						if oldSlot then hotbarSwitch(oldSlot) end
					end
				end)
			end
			return success and result ~= false, success and 'Telepearl launch was rejected.' or tostring(result)
		end)
		vape:Clean(function()
			if vape.Libraries.MouseTPBridge == mouseTPBridge then mouseTPBridge:SetBedWars(nil) end
		end)
	end
end

local AntiFallDirection
local Fly
local LongJump
-- LongJump is the authoritative compatible-tool detector. Anything that needs to know a
-- long-jump tool has genuinely entered its launch window listens for this edge instead of
-- maintaining a second, inevitably stale list of tool activation rules. (Extender used to be
-- its main consumer; it now hooks the four kit controllers directly.)
local longJumpActivation = Instance.new('BindableEvent')
vape:Clean(longJumpActivation)
local Attacking
-- Jade was changed from one hammer into three tiered item types. Keep the compatibility
-- list shared so movement/clutch modules cannot silently drift back to supporting only one tier.
-- BedWars has used both tiered tool ids and the shared jump id while moving Jade between
-- controller implementations. Keep one canonical set so every Jade consumer recognises the
-- held tool and the ability id instead of treating one of the live forms as a different kit.
local jadeHammerNames = {'jade_hammer_3', 'jade_hammer_2', 'jade_hammer_1', 'jade_hammer', 'jade_hammer_jump'}
local jadeJumpAbilities = {'jade_hammer_3_jump', 'jade_hammer_2_jump', 'jade_hammer_1_jump', 'jade_hammer_jump'}

local function normalizeJadeName(value)
	return type(value) == 'string' and value:lower():gsub('[%s%-]+', '_') or nil
end

local function isJadeHammerName(value)
	local normalized = normalizeJadeName(value)
	return normalized ~= nil and (normalized == 'jade_hammer_jump' or normalized:match('^jade_hammer(_%d+)?$') ~= nil)
end

local function getJadeAbility(item)
	if not item then return end
	local itemType = normalizeJadeName(item.itemType or (item.tool and item.tool.Name))
	if not isJadeHammerName(itemType) then return end
	-- Tiered hammers are inventory upgrades, but live builds disagree on whether the
	-- ability is tiered, shared, or exposed directly as jade_hammer_jump.
	local abilities, seen = {}, {}
	local function add(ability)
		if ability and not seen[ability] then seen[ability] = true; table.insert(abilities, ability) end
	end
	if itemType ~= 'jade_hammer_jump' then add(itemType..'_jump') end
	for _, ability in jadeJumpAbilities do add(ability) end
	for _, ability in abilities do
		local ok, ready = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, ability, {
			disableBlockedAbilityAlert = true
		})
		if ok and ready then return ability end
	end
	return abilities[1]
end

-- Equipping an inventory instance is not the same as pressing the hammer.  In particular,
-- useAbility by itself skips the Jade tool/controller input path in current BedWars builds.
-- Send the real primary-input edge after equipping so the controller creates the movement
-- state that the server expects (and that its movement checks use to permit the launch).
local function activateJadeTool(item)
	if not item or not item.tool then return false end
	switchItem(item.tool, 0.1)
	-- The input edge is ignored while the old hotbar item is still equipped.
	-- Wait briefly for the inventory store and character tool to agree before
	-- pressing the hammer, otherwise LongJump's Jade adapter can look enabled
	-- while the Jade controller never sees its activation.
	local equipDeadline = tick() + 0.6
	repeat
		task.wait()
	until (store.hand and store.hand.tool == item.tool) or tick() >= equipDeadline or not entitylib.isAlive
	local center = gameCamera.ViewportSize / 2
	local fired = pcall(function()
		local virtualInput = game:GetService('VirtualInputManager')
		if inputService.TouchEnabled then
			virtualInput:SendTouchEvent(0, Enum.UserInputState.Begin, center.X, center.Y)
			virtualInput:SendTouchEvent(0, Enum.UserInputState.End, center.X, center.Y)
		else
			virtualInput:SendMouseButtonEvent(center.X, center.Y, 0, true, game, 0)
			virtualInput:SendMouseButtonEvent(center.X, center.Y, 0, false, game, 0)
		end
	end)
	if not fired and mouse1click then fired = pcall(mouse1click) end
	return fired
end

--[[
    Combat
]]

run(function()
    local AimAssist
    local AimMode
    local Mode
    local Targets
    local Sort
    local AimPart
    local AimSpeed
    local Shake
    local Distance
    local AngleSlider
    local StrafeIncrease
    local BlockBreak
    local KillauraTarget
    local ClickAim
    local Mouse
    local Limit

    local function ease(t)
	return t < 0.5 and 4 * t * t * t or 1 - math.pow(-2 * t + 2, 3) / 2
    end

    local cache = {}
    local function getMousePosition()
	if inputService.TouchEnabled then
		return gameCamera.ViewportSize / 2
	end
	return inputService.GetMouseLocation(inputService)
    end

    local function getAim(ent)
	if AimPart.Value == 'Closest' then
		if not cache[ent.Character] then
			cache[ent.Character] = ent.Character:GetChildren()
		end
		local localPosition, magnitude, part = getMousePosition(), 9e9, nil
		for _, v in cache[ent.Character] do
			if v and v.Parent and v:IsA('BasePart') then
				local position, vis = gameCamera.WorldToViewportPoint(gameCamera, v.Position)

				if vis then
					local mag = (localPosition - Vector2.new(position.x, position.y)).Magnitude

					if mag < magnitude then
						magnitude = mag
						part = v
					end
				end
			end
		end
		if part then
			return part.Position
		end
	end
	return ent.RootPart.Position
    end

    local started, lasttarget = 0, nil
    local aimfuncs = {
	Simple = function(localcframe, ent, fps)
		local rng = Random.new()
		local speed = (AimSpeed.Value + (StrafeIncrease.Enabled and (inputService:IsKeyDown(Enum.KeyCode.A) or inputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 0))

		return localcframe:Lerp(CFrame.lookAt(localcframe.p, getAim(ent) + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
	end,
	Adaptive = function(localcframe, ent, fps)
		local prog, rng = ease(math.min(tick() - started, 1)), Random.new()
		local speed = (AimSpeed.Value * 0.1 * prog) + (1 - prog) + (StrafeIncrease.Enabled and (inputService:IsKeyDown(Enum.KeyCode.A) or inputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 5)
		return localcframe:Lerp(CFrame.lookAt(localcframe.p, getAim(ent) + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
	end
    }

    local function GetTarget()
	if lasttarget then
		local localPosition = entitylib.character.RootPart.Position
		if not lasttarget or not lasttarget.RootPart or not lasttarget.Humanoid or not lasttarget.Humanoid.Health or lasttarget.Humanoid.Health <= 0 then
			return false
		end
		if (localPosition - lasttarget.RootPart.Position).Magnitude > Distance.Value then
			return false
		end
		if Targets.Walls.Enabled and entitylib.Wallcheck(localPosition, lasttarget.RootPart.Position, Targets.Walls.Enabled) then
			return false
		end
		return lasttarget
	end

	return false
    end

    local function getAttackData()
	if Mouse.Enabled and not inputService:IsMouseButtonPressed(0) and (tick() - bedwars.SwordController.lastSwing) > 0.15 then
		return false
	end
	if ClickAim.Enabled and (tick() - bedwars.SwordController.lastSwing) > 0.3 then
		return false
	end
	if BlockBreak.Enabled and (tick() - store.lastHit) < 0.3 then
		return false
	end
	if Limit.Enabled and store.hand.toolType ~= 'sword' then
		return false
	end

	if (tick() - started) > 1 or not lasttarget or not lasttarget.Parent or not lasttarget.Humanoid or lasttarget.Humanoid.Health <= 0 then
		local ent = GetTarget() or KillauraTarget.Enabled and store.KillauraTarget or entitylib.EntityPosition({
			Range = Distance.Value,
			Part = 'RootPart',
			Wallcheck = Targets.Walls.Enabled,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Sort = sortmethods[Sort.Value],
		})
		if ent then
			started = tick()
		end
		lasttarget = ent
	end
	return lasttarget
    end

    AimAssist = vape.Categories.Combat:CreateModule({
	Name = 'AimAssist',
	Function = function(callback)
		if callback then
			local rotate = 0

			AimAssist:Clean(runService.PostSimulation:Connect(function(dt)
				if entitylib.isAlive then
					entitylib.character.Humanoid.AutoRotate = tick() > rotate

					local ent = getAttackData()
					if ent then
						local root = entitylib.character.RootPart
						local delta = (ent.RootPart.Position - root.Position)
						local localfacing = root.CFrame.LookVector * Vector3.new(1, 0, 1)
						local angle = math.acos(localfacing:Dot((delta * Vector3.new(1, 0, 1)).Unit))
						if angle >= (math.rad(AngleSlider.Value) / 2) then
							return
						end
						targetinfo.Targets[ent] = tick() + 1

						local cframe, speed = aimfuncs[Mode.Value](gameCamera.CFrame, ent, dt)
						if AimMode.Value == 'First person' or AimMode.Value == 'Dynamic' and entitylib.character.Head.LocalTransparencyModifier == 1 then
							gameCamera.CFrame = cframe
						elseif AimMode.Value == 'Third person' or AimMode.Value == 'Dynamic' and entitylib.character.Head.LocalTransparencyModifier ~= 1 then
							cframe, speed = aimfuncs[Mode.Value](root.CFrame, ent, dt)
							entitylib.character.Humanoid.AutoRotate = false
							root.CFrame = CFrame.lookAlong(root.Position, cframe.LookVector * Vector3.new(1, 0, 1))
							rotate = tick() + 0.1
						elseif AimMode.Value == 'Mouse' then
							local viewport = gameCamera:WorldToViewportPoint(cframe.Position)
							local pos = (Vector2.new(viewport.X, viewport.Y) - inputService:GetMouseLocation()) * (speed / 15)
							mousemoverel(pos.X, pos.Y)
						end
					end
				end
			end))
		end
	end,
	Tooltip = 'Smoothly aims to closest valid target with sword'
    })
    Targets = AimAssist:CreateTargets({
	Players = true,
	Walls = true,
    })
    local modes = {}
    for i in aimfuncs do
	table.insert(modes, i)
    end
    AimMode = AimAssist:CreateDropdown({
	Name = 'Aim perspective',
	Tooltip = 'First person - camera\nThird person - turns your character\nMouse - moves your mouse\nDynamic - whichever you are in',
	List = {'First person', 'Third person', 'Mouse', 'Dynamic'},
	Default = 'First person'
    })
    Mode = AimAssist:CreateDropdown({
	Name = 'Mode',
	List = modes,
	Tooltip = 'Simple - Smooth aiming\nAdaptive - Advanced tracking with adaptive behavior',
	Default = modes[1],
    })
    local methods = {'Damage', 'Distance'}
    for i in sortmethods do
	if not table.find(methods, i) then
		table.insert(methods, i)
	end
    end
    ClickAim = AimAssist:CreateToggle({
	Name = 'Click aim',
	Default = true,
    })
    Mouse = AimAssist:CreateToggle({Name = 'Require mouse down'})
    StrafeIncrease = AimAssist:CreateToggle({Name = 'Strafe increase'})
    BlockBreak = AimAssist:CreateToggle({Name = 'Check block break'})
    KillauraTarget = AimAssist:CreateToggle({Name = 'Use killaura target'})
    AimSpeed = AimAssist:CreateSlider({
	Name = 'Aim speed',
	Min = 1,
	Max = 20,
	Default = 6,
    })
    Distance = AimAssist:CreateSlider({
	Name = 'Distance',
	Min = 1,
	Max = 30,
	Default = 30,
	Suffix = function(val)
		return val == 1 and 'stud' or 'studs'
	end,
    })
    Shake = AimAssist:CreateSlider({
	Name = 'Shake',
	Min = 0,
	Max = 100,
	Default = 0,
	Tooltip = 'Adds random jitter to simulate human aim',
    })
    AngleSlider = AimAssist:CreateSlider({
	Name = 'Max angle',
	Min = 1,
	Max = 360,
	Default = 70,
    })
    Limit = AimAssist:CreateToggle({
	Name = 'Limit to items',
	Tooltip = 'Only attacks when sword is held',
    })
    Sort = AimAssist:CreateDropdown({
	Name = 'Target mode',
	List = methods,
	Default = 'Angle',
    })
    AimPart = AimAssist:CreateDropdown({
	Name = 'Target area',
	List = {'Center', 'Closest'},
	Default = 'Center',
    })
end)

run(function()
	local AutoClicker
	local CPS
	local BlockCPS = {}
	local Attacks
	local Blocks
	local Wool
	local Thread
	local heldInputs = {}
	local bridgeInputs = {}

	local function stopInput(source)
		heldInputs[source] = nil
		bridgeInputs[source] = nil
		if not next(heldInputs) and Thread then
			task.cancel(Thread)
			Thread = nil
		end
	end

	local function AutoClick(source, autoBridge)
		heldInputs[source] = true
		bridgeInputs[source] = autoBridge or nil
		if Thread then
			return
		end

		Thread = task.delay(1 / (store.hand.toolType == 'block' and BlockCPS or CPS).GetRandomValue(), function()
			repeat
				if not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) then
					local blockPlacer = bedwars.BlockPlacementController.blockPlacer
					if store.hand.toolType == 'block' and Blocks.Enabled and (not Wool.Enabled or store.hand.tool.Name:find('wool_')) and blockPlacer then
						if (workspace:GetServerTimeNow() - bedwars.BlockCpsController.lastPlaceTimestamp) >= ((1 / 12) * 0.5) then
							if next(bridgeInputs) and blockPlacer.autoBridge then
								blockPlacer:autoBridge(workspace:GetServerTimeNow() - bedwars.KnockbackController:getLastKnockbackTime() >= 0.2)
							else
								local mouseinfo = blockPlacer.clientManager:getBlockSelector():getMouseInfo(0)
								if mouseinfo and mouseinfo.placementPosition == mouseinfo.placementPosition then
									task.spawn(blockPlacer.placeBlock, blockPlacer, mouseinfo.placementPosition)
								end
							end
						end
					elseif store.hand.toolType == 'sword' and Attacks.Enabled then
						bedwars.SwordController:swingSwordAtMouse()
					end
				end

				task.wait(1 / (store.hand.toolType == 'block' and BlockCPS or CPS).GetRandomValue())
			until not AutoClicker.Enabled or not next(heldInputs)
			Thread = nil
		end)
	end

	AutoClicker = vape.Categories.Combat:CreateModule({
		Name = 'AutoClicker',
		Function = function(callback)
			if callback then
				AutoClicker:Clean(inputService.InputBegan:Connect(function(input, processed)
					if input.UserInputType == Enum.UserInputType.MouseButton1 then
						AutoClick(input, false)
					elseif input.UserInputType == Enum.UserInputType.Touch then
						-- World touches use the selector's suggested placement exactly like desktop.
						-- Gui buttons are handled below so camera/menu touches cannot start clicking.
						local overButton = false
						for _, object in guiService:GetGuiObjectsAtPosition(input.Position.X, input.Position.Y) do
							if object:IsA('GuiButton') then overButton = true; break end
						end
						if not processed and not overButton then AutoClick(input, false) end
					end
				end))

				AutoClicker:Clean(inputService.InputEnded:Connect(function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						stopInput(input)
					end
				end))

				if inputService.TouchEnabled then
					local hooked = {}
					local function hookButton(button)
						if hooked[button] or not button:IsA('GuiButton') then return end
						local name = button.Name:lower()
						local label = button:IsA('TextButton') and button.Text:lower() or ''
						local relevant = tonumber(button.Name) ~= nil or name:find('attack', 1, true) or name:find('place', 1, true)
							or name:find('build', 1, true) or name:find('block', 1, true) or label:find('build', 1, true)
						if not relevant then return end
						hooked[button] = true
						local autoBridge = tonumber(button.Name) ~= nil or name:find('build', 1, true) ~= nil
							or name:find('bridge', 1, true) ~= nil or label:find('build', 1, true) ~= nil
						AutoClicker:Clean(button.MouseButton1Down:Connect(function() AutoClick(button, autoBridge) end))
						AutoClicker:Clean(button.MouseButton1Up:Connect(function()
							stopInput(button)
						end))
						AutoClicker:Clean(button.InputEnded:Connect(function(input)
							if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then stopInput(button) end
						end))
						AutoClicker:Clean(button.AncestryChanged:Connect(function(_, parent)
							if not parent then stopInput(button) end
						end))
					end
					task.spawn(function()
						local mobileUI = lplr.PlayerGui:WaitForChild('MobileUI', 20)
						if not mobileUI or not AutoClicker.Enabled then return end
						for _, button in mobileUI:GetDescendants() do hookButton(button) end
						AutoClicker:Clean(mobileUI.DescendantAdded:Connect(hookButton))
					end)
				end
			else
				table.clear(heldInputs)
				table.clear(bridgeInputs)
				if Thread then
					task.cancel(Thread)
					Thread = nil
				end
			end
		end,
		Tooltip = 'Hold attack button to automatically click'
	})
	Attacks = AutoClicker:CreateToggle({
		Name = 'Attack',
		Default = true,
		Function = function(callback)
			if CPS and CPS.Object then
				CPS.Object.Visible = callback
			end
		end,
		Tooltip = 'Automatically attacks while the mouse button is held'
	})
	CPS = AutoClicker:CreateTwoSlider({
		Name = 'CPS',
		Min = 1,
		Max = 9,
		DefaultMin = 7,
		DefaultMax = 7
	})
	Blocks = AutoClicker:CreateToggle({
		Name = 'Place Blocks',
		Default = true,
		Function = function(callback)
			if BlockCPS.Object then
				BlockCPS.Object.Visible = callback
			end
			if Wool and Wool.Object then Wool.Object.Visible = callback end
		end
	})
	Wool = AutoClicker:CreateToggle({Name = 'Wool only', Tooltip = 'Only places while wool is held.', Darker = true})
	BlockCPS = AutoClicker:CreateTwoSlider({
		Name = 'Block CPS',
		Min = 1,
		Max = 12,
		DefaultMin = 12,
		DefaultMax = 12,
		Darker = true
	})
end)

run(function()
    local BowAssist
    local Targets
    local Sort
    local Shake
    local Speed
    local Angle
    local FOV
    local AimPart
    local Distance
    local Smoothness
    local Clear
    local Blacklist
    local Mouse
    local ThirdPerson
    local Projectiles
    local aimRandom = Random.new()

    local function ease(t)
	return t < 0.5 and 4 * t * t * t or 1 - math.pow(-2 * t + 2, 3) / 2
    end

    local function findAim(localcframe, predicted, fps, started, offset)
	local prog, rng = ease(math.min((tick() - started) / (1 / (Speed.Value * 0.5)), 1)), aimRandom
	local speed = (Speed.Value / Smoothness.Value) * prog

	return localcframe:Lerp(CFrame.lookAt(localcframe.p, predicted + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, offset + ((rng:NextNumber() - 0.5) * Shake.Value * fps), (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
    end

    local launchHook
    local lasttarget, started = nil, 0
    local function getAttackData()
	if not entitylib.isAlive then
		return false
	end
	if Mouse.Enabled and not inputService:IsMouseButtonPressed(0) then
		return false
	end
	if not store.hand.tool or not bedwars.ItemMeta[store.hand.tool.Name].projectileSource and store.hand.toolType ~= 'bow' then
		return false
	end
	if Blacklist.Enabled and table.find(Projectiles.ListEnabled, store.hand.tool.Name == 'glue_trap' and 'gloop' or store.hand.tool.Name) then
		return false
	end

	if (tick() - started) > 1 or not lasttarget or not lasttarget.Parent or not lasttarget.Humanoid or lasttarget.Humanoid.Health <= 0 then
		local ent = entitylib.EntityMouse({
			Origin = entitylib.character.RootPart.Position,
			Range = FOV.Value,
			Part = AimPart.Value,
			Wallcheck = Targets.Walls.Enabled,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Sort = sortmethods[Sort.Value],
		})
		if ent and (ent.RootPart.Position - entitylib.character.RootPart.Position).Magnitude > Distance.Value then ent = nil end
		if ent then
			started = tick()
		end
		lasttarget = ent
	end
	return lasttarget
    end

    local rayCheck = RaycastParams.new()

    BowAssist = vape.Categories.Combat:CreateModule({
	Name = 'BowAssist',
	Function = function(callback)
		if callback then
			local multi, predicted = 0, nil
			local lastpredicted = 0
			local lastent, found, update = nil, 0, 0

			launchHook = bedwars.ProjectileLaunchHook:Add('BowAssist', 10, function(nextLaunch, ...)
				local res = nextLaunch(...)
				local projmeta = select(2, ...)
				multi = projmeta and (projmeta.velocityMultiplier + 2) or 0
				if projmeta and tick() - update < 0.1 and lastent and lastent.RootPart then
					local meta = projmeta:getProjectileMeta()
					local gravity = (meta.gravitationalAcceleration or 196.2) * projmeta.gravityMultiplier
					local calc = prediction.SolveTrajectory(entitylib.character.RootPart.Position, (meta.launchVelocity or 100) * (1 - lplr:GetNetworkPing()), gravity, lastent.RootPart.Position, lastent.RootPart.Velocity, workspace.Gravity, entitylib.character.HipHeight, nil, rayCheck)
					predicted = calc
					lastpredicted = tick()
				else
					predicted = nil
				end
				return res
			end)

			BowAssist:Clean(runService.PostSimulation:Connect(function(dt)
				local ent = getAttackData()
				if ent then
					local delta = (ent.RootPart.Position - entitylib.character.RootPart.Position)
					local localfacing = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
					local angle = math.acos(localfacing:Dot((delta * Vector3.new(1, 0, 1)).Unit))
					if angle >= (math.rad(Angle.Value) / 2) then
						return
					end
					if ent ~= lastent then
						found = tick()
					end
					lastent = ent
					update = tick()
					if tick() - lastpredicted < 0.1 then
						targetinfo.Targets[ent] = tick() + 1
						local aimPosition = predicted or ent[AimPart.Value].Position
						if Clear.Enabled then
							rayCheck.FilterDescendantsInstances = {lplr.Character, ent.Character, gameCamera}
							if workspace:Raycast(gameCamera.CFrame.Position, aimPosition - gameCamera.CFrame.Position, rayCheck) then return end
						end
						local cframe, speed = findAim(gameCamera.CFrame, aimPosition, dt, found, multi + ((entitylib.character.RootPart.Position.Y - ent.RootPart.Position.Y) / 7))
						if inputService.MouseEnabled and entitylib.character.Head.LocalTransparencyModifier == 1 then
							gameCamera.CFrame = cframe
						elseif ThirdPerson.Enabled and inputService.MouseEnabled then
							local viewport = gameCamera:WorldToViewportPoint(aimPosition)
							local pos = (Vector2.new(viewport.X, viewport.Y) - inputService:GetMouseLocation()) * (speed / 15)
							mousemoverel(pos.X, pos.Y)
						end
					end
				end
			end))
		else
			if launchHook then
				launchHook()
				launchHook = nil
			end
		end
	end,
        Tooltip = 'Smoothly aims your projectile trajectory to the target'
    })

    Targets = BowAssist:CreateTargets({
	Players = true,
	Walls = true,
    })
    local methods = {'Damage', 'Distance'}
    for i in sortmethods do
	if not table.find(methods, i) then
		table.insert(methods, i)
	end
    end
    Sort = BowAssist:CreateDropdown({
	Name = 'Target mode',
	List = methods,
	Default = 'Angle',
    })
    AimPart = BowAssist:CreateDropdown({Name = 'Part', List = {'RootPart', 'Head'}})
    Distance = BowAssist:CreateSlider({Name = 'Distance', Min = 1, Max = 300, Default = 200, Suffix = ' studs'})
    Speed = BowAssist:CreateSlider({
	Name = 'Aim speed',
	Min = 1,
	Max = 20,
	Default = 7,
	Suffix = 'sp/s',
	Tooltip = 'How fast you will aim per second',
    })
    Smoothness = BowAssist:CreateSlider({Name = 'Smoothness', Min = 1, Max = 20, Default = 2, Decimal = 10, Tooltip = 'Divides aim speed to soften camera movement.'})
    Angle = BowAssist:CreateSlider({
	Name = 'Max angle',
	Min = 1,
	Max = 360,
	Default = 120,
    })
    Shake = BowAssist:CreateSlider({
	Name = 'Shake',
	Min = 1,
	Max = 100,
	Default = 5,
	Tooltip = 'Jitters your screen, Simulating human aim',
    })
    FOV = BowAssist:CreateSlider({
	Name = 'FOV',
	Min = 1,
	Max = 1000,
	Default = 200,
    })
    Mouse = BowAssist:CreateToggle({
	Name = 'Require mouse down',
	Default = inputService.KeyboardEnabled,
    })
    ThirdPerson = BowAssist:CreateToggle({
	Name = 'Use mouse aim',
	Tooltip = 'Aims using the mouse if you are on third person',
	Default = true,
    })
    Blacklist = BowAssist:CreateToggle({
	Name = 'Use blacklist',
	Default = true,
	Function = function(callback)
		if Projectiles then
			Projectiles.Object.Visible = callback
		end
	end,
	Tooltip = 'Doesn\'t bow-assist if your holding one of the blacklisted projectiles',
    })
    Projectiles = BowAssist:CreateTextList({
	Name = 'Blacklisted',
	Default = { 'fireball', 'telepearl', 'gloop' },
	Darker = true,
    })
    Clear = BowAssist:CreateToggle({Name = 'Clear shot only', Default = true, Tooltip = 'Stops assisting when the aim path is obstructed.'})
end)

run(function()
    local old

    vape.Categories.Combat:CreateModule({
        Name = 'NoClickDelay',
        Function = function(callback)
            if callback then
                old = bedwars.SwordController.isClickingTooFast
                bedwars.SwordController.isClickingTooFast = function(self)
                    self.lastSwing = os.clock()
                    return false
                end
            else
                bedwars.SwordController.isClickingTooFast = old
            end
        end,
        Tooltip = 'Remove the CPS cap'
    })
end)

run(function()
    if canDebug then
run(function()
	local HitregAdjuster, Hitreg
	local firstConnection, restoreConnection

	HitregAdjuster = vape.Categories.Combat:CreateModule({
		Name = 'HitregAdjuster',
		Function = function(enabled)
			if not enabled then return end
			local sync = bedwars.SyncEvents and bedwars.SyncEvents.SwordSwing
			if not sync then
				notif('HitregAdjuster', 'Sword swing events are unavailable.', 5, 'warning')
				HitregAdjuster:Toggle()
				return
			end
			local original
			firstConnection = sync:setPriority(150):connect(function(event)
				original = event.attackSpeed
				event.attackSpeed = 10 / math.max(Hitreg.Value - 1, 1)
			end)
			restoreConnection = sync:setPriority(300):connect(function(event)
				if original ~= nil then event.attackSpeed = original end
			end)
			HitregAdjuster:Clean(function()
				if firstConnection then firstConnection:Destroy(); firstConnection = nil end
				if restoreConnection then restoreConnection:Destroy(); restoreConnection = nil end
			end)
		end,
		Tooltip = 'Adjusts manual and AutoClicker sword swing spacing without changing Killaura timing.'
	})
	Hitreg = HitregAdjuster:CreateSlider({Name = 'Hitreg', Min = 1, Max = 36, Default = 35, Suffix = ' hits / 10s'})
end)

run(function()
	local DeathAdderAimbot, Mode, BedRange, Targets, Sort, TargetPart, FOV
	local originalDirection, hookedDirection

	local function aimPosition(origin)
		if Mode.Value == 'Bed' then
			local closest, distance
			for _, bed in collectionService:GetTagged('bed') do
				if not bed:GetAttribute(`Team{lplr:GetAttribute('Team') or -1}NoBreak`) then
					local magnitude = (origin - bed.Position).Magnitude
					if magnitude <= BedRange.Value and (not distance or magnitude < distance) then closest, distance = bed, magnitude end
				end
			end
			return closest and closest.Position
		end
		local ent = entitylib.EntityMouse({Range = FOV.Value, Part = 'RootPart', Wallcheck = Targets.Walls.Enabled,
			Players = Targets.Players.Enabled, NPCs = Targets.NPCs.Enabled, Origin = origin, Sort = sortmethods[Sort.Value]})
		if not ent then return end
		targetinfo.Targets[ent] = tick() + 1
		local tier = bedwars.SorcererBalance.getSorcererTierData(bedwars.SorcererBalance.getSorcererTier(lplr))
		local position = ent[TargetPart.Value].Position
		return position + ent.RootPart.AssemblyLinearVelocity * ((position - origin).Magnitude / ((tier and tier.projectileVelocity) or 70))
	end

	DeathAdderAimbot = vape.Categories.Blatant:CreateModule({Name = 'DeathAdderAimbot', Function = function(enabled)
		local controller = bedwars.SorcererController
		if enabled then
			if not controller or type(controller.getProjectileDirection) ~= 'function' then
				notif('DeathAdderAimbot', 'Death Adder controller is unavailable.', 5, 'warning'); DeathAdderAimbot:Toggle(); return
			end
			originalDirection = controller.getProjectileDirection
			hookedDirection = function(self, ...)
				if entitylib.isAlive then
					local origin = entitylib.character.RootPart.Position
					local aim = aimPosition(origin)
					if aim and aim ~= origin then return (aim - origin).Unit end
				end
				return originalDirection(self, ...)
			end
			controller.getProjectileDirection = hookedDirection
			DeathAdderAimbot:Clean(function()
				if controller.getProjectileDirection == hookedDirection then controller.getProjectileDirection = originalDirection end
				originalDirection, hookedDirection = nil, nil
			end)
		end
	end, Tooltip = 'Silently leads Death Adder spells toward a player or enemy bed.'})
	Mode = DeathAdderAimbot:CreateDropdown({Name = 'Mode', List = {'Player', 'Bed'}, Function = function(value)
		if BedRange then BedRange.Object.Visible = value == 'Bed'; FOV.Object.Visible = value == 'Player'; TargetPart.Object.Visible = value == 'Player'; Sort.Object.Visible = value == 'Player' end
	end})
	BedRange = DeathAdderAimbot:CreateSlider({Name = 'Bed range', Min = 1, Max = 60, Default = 60, Suffix = ' studs', Visible = false})
	Targets = DeathAdderAimbot:CreateTargets({Players = true, Walls = true})
	local methods = {'Distance', 'Damage'}
	for name in sortmethods do if not table.find(methods, name) then table.insert(methods, name) end end
	Sort = DeathAdderAimbot:CreateDropdown({Name = 'Target mode', List = methods, Default = 'Distance'})
	TargetPart = DeathAdderAimbot:CreateDropdown({Name = 'Part', List = {'RootPart', 'Head'}})
	FOV = DeathAdderAimbot:CreateSlider({Name = 'FOV', Min = 1, Max = 1000, Default = 1000})
end)

run(function()
	local BlockReach
		local BlockRange
		local BreakReach
		local BreakRange
		local SwordReach
		local SwordRange

		local old

		Reach = vape.Categories.Combat:CreateModule({
			Name = 'Reach',
			Tooltip = 'Allows you to place, attack, and break further',
			Function = function(callback)
				bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = callback and SwordReach.Enabled and SwordRange.Value + 2 or 14.4
				if callback then
					old = bedwars.BlockSelector.getMouseInfo
					bedwars.BlockSelector.getMouseInfo = function(...)
						local Self, Select, Args = ...
						if not Args then
							Args = {}
						end
						if Select == 0 then
							Args.range = BlockReach.Enabled and BlockRange.Value or 24
						elseif Select == 1 then
							Args.range = BreakReach.Enabled and BreakRange.Value or 18
						end
						return old(Self, Select, Args)
					end
				else
					bedwars.BlockSelector.getMouseInfo = old
					old = nil
				end
			end,
		})
		SwordReach = Reach:CreateToggle({
			Name = 'Sword Reach',
			Default = true,
			Function = function(callback)
				bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and callback and SwordRange.Value + 2 or 14.4
				pcall(function()
					SwordRange.Object.Visible = callback
				end)
			end,
		})
		SwordRange = Reach:CreateSlider({
			Name = 'Sword Range',
			Min = 1,
			Max = 18,
			Default = 18,
			Decimal = 5,
			Darker = true,
			Suffix = function(val)
				return val <= 1 and 'stud' or 'studs'
			end,
			Function = function(val)
				bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and SwordReach.Enabled and val or 14.4
			end,
		})
		BlockReach = Reach:CreateToggle({
			Name = 'Placement Reach',
			Function = function(callback)
				BlockRange.Object.Visible = callback
			end,
		})
		BlockRange = Reach:CreateSlider({
			Name = 'Placement Range',
			Min = 1,
			Max = 60,
			Default = 18,
			Darker = true,
			Suffix = function(val)
				return val <= 1 and 'stud' or 'studs'
			end,
			Visible = false,
		})
		BreakReach = Reach:CreateToggle({
			Name = 'Break Reach',
			Function = function(callback)
				BreakRange.Object.Visible = callback
			end,
		})
		BreakRange = Reach:CreateSlider({
			Name = 'Break Range',
			Min = 1,
			Max = 30,
			Default = 30,
			Decimal = 5,
			Darker = true,
			Suffix = function(val)
				return val <= 1 and 'stud' or 'studs'
			end,
			Visible = false,
		})
		Reach:CreateButton({
			Name = 'Reset to default reach',
			Tooltip = 'Resets every range back to default',
			Function = function()
				BreakRange:SetValue(18)
				BlockRange:SetValue(24)
				SwordRange:SetValue(12.4)
			end,
		})
	end)
    else
	local Value
	local rayParams = RaycastParams.new()
	rayParams.RespectCanCollide = true

	Reach = vape.Categories.Combat:CreateModule({
		Name = 'Reach',
		Function = function(callback)
			if callback then
				Reach:Clean(vapeEvents.CEAttacked.Event:Connect(function()
					local doAttack
					if not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) then
						if
							entitylib.isAlive
							and store.hand.toolType == 'sword'
							and bedwars.DaoController.chargingMaid == nil
						then
							local attackRange = Value.Value + 2
							rayParams.FilterDescendantsInstances = { lplr.Character }

							local unit = lplr:GetMouse().UnitRay
							local localPos = entitylib.character.RootPart.Position
							local rayRange = (attackRange or 14.4)
							local ray = workspace:Raycast(unit.Origin, unit.Direction * 200, rayParams)
							if ray and (localPos - ray.Instance.Position).Magnitude <= rayRange then
								for _, ent in entitylib.List do
									doAttack = ent.Targetable
										and ray.Instance:IsDescendantOf(ent.Character)
										and (localPos - ent.RootPart.Position).Magnitude <= rayRange
									if doAttack then
										break
									end
								end
							end

							local region = bedwars.SwordController:getTargetInRegion(attackRange or 3.8 * 3, 0)
							if doAttack then
								doAttack = region
							end
							if doAttack then
								local selfpos = entitylib.character.RootPart.Position
								local delta = (doAttack.RootPart.Position - selfpos)
								local dir = CFrame.lookAt(selfpos, doAttack.RootPart.Position).LookVector
								local pos = selfpos + dir * math.max(delta.Magnitude - 14.4, 0)

								bedwars.Client:Get('SwordHit'):SendToServer({
									weapon = store.hand.tool,
									chargedAttack = {chargeRatio = 0},
									entityInstance = doAttack.Character,
									validate = {
										raycast = {},
										targetPosition = {value = doAttack.RootPart.Position},
										selfPosition = {value = pos},
									},
								})
							end
						end
					end
				end))
			end
		end,
	})
	Value = Reach:CreateSlider({
		Name = 'Range',
		Min = 0,
		Max = 18,
		Default = 18,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end,
	})
    end
end)

run(function()
    local ShopQuickBuy
    local HoldDelay
    local CPS
    local purchaseSounds = {}

    local holding = false
    local clickThread

    -- SoundManager coalesces repeated requests for the same sound while its
    -- cached instance is still active. ShopClicker can complete several buys
    -- during that window, so give each successful purchase its own playback
    -- instance instead of asking the shared manager to replay its cached one.
    local function playPurchaseSound()
        local sound = Instance.new('Sound')
        sound.Name = 'AetherShopPurchase'
        sound.SoundId = bedwars.SoundList.BEDWARS_PURCHASE_ITEM
        sound.Parent = gameCamera
        purchaseSounds[sound] = true
        sound.Ended:Once(function()
            purchaseSounds[sound] = nil
            sound:Destroy()
        end)
        sound:Play()
        task.delay(10, function()
            if purchaseSounds[sound] then
                purchaseSounds[sound] = nil
                sound:Destroy()
            end
        end)
    end

    local function getShopId()
        if not entitylib.isAlive then return nil end
        local localPosition = entitylib.character.RootPart.Position
        local id
        for _, v in store.shop do
            if v.Shop and (v.RootPart.Position - localPosition).Magnitude <= 20 then
                id = v.Id
            end
        end
        return id
    end

    local function getHoveredItem()
        local mousepos = (inputService:GetMouseLocation() - guiService:GetGuiInset())
        for _, v in lplr.PlayerGui:GetGuiObjectsAtPosition(mousepos.X, mousepos.Y) do
            local obj = v
            while obj and obj ~= lplr.PlayerGui do
                local itemType = obj.Name:match('^(.+)_ShopItemCard$')
                if itemType then
                    return itemType
                end
                obj = obj.Parent
            end
        end
    end

    local function canBuy(item)
        if item.ignoredByKit and table.find(item.ignoredByKit, store.equippedKit or '') then return false end
        if item.lockedByForge or item.disabled then return false end
        if item.require and item.require.teamUpgrade then
            if (bedwars.Store:getState().Bedwars.teamUpgrades[item.require.teamUpgrade.upgradeId] or -1) < item.require.teamUpgrade.lowestTierIndex then
                return false
            end
        end
        local currency = getItem(item.currency)
        return (currency and currency.amount or 0) >= item.price
    end

    local function purchase(itemType, shopId)
        if bedwars.BedwarsShopController.alreadyPurchasedMap[itemType] ~= nil then return end

        local item = bedwars.Shop.getShopItem(itemType, lplr, {shopId = shopId})
        if not item or not canBuy(item) then return end

        bedwars.Client:Get('BedwarsPurchaseItem'):CallServerAsync({
            shopItem = item,
            shopId = shopId
        }):andThen(function(suc)
            if not suc then return end
            playPurchaseSound()
            bedwars.Store:dispatch({
                type = 'BedwarsAddItemPurchased',
                itemType = itemType
            })
            if item.tiered then
                bedwars.BedwarsShopController.alreadyPurchasedMap[itemType] = true
            end
        end)
    end

    local function startClicking(itemType)
        if clickThread then
            task.cancel(clickThread)
        end
        clickThread = task.spawn(function()
            repeat
                local shopId = bedwars.AppController:isAppOpen('BedwarsItemShopApp') and store.shopLoaded and getShopId()
                if shopId then
                    purchase(itemType, shopId)
                end
                task.wait(1 / CPS.Value)
            until not holding
            clickThread = nil
        end)
    end

    ShopQuickBuy = vape.Categories.Combat:CreateModule({
        Name = 'ShopClicker',
        Function = function(callback)
            if callback then
                ShopQuickBuy:Clean(inputService.InputBegan:Connect(function(input)
                    if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                    if not bedwars.AppController:isAppOpen('BedwarsItemShopApp') then return end

                    local itemType = getHoveredItem()
                    if not itemType then return end

                    holding = true
                    task.delay(HoldDelay.Value, function()
                        if holding and getHoveredItem() == itemType then
                            startClicking(itemType)
                        end
                    end)
                end))

                ShopQuickBuy:Clean(inputService.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then
                        holding = false
                    end
                end))
            else
                holding = false
                if clickThread then
                    task.cancel(clickThread)
                    clickThread = nil
                end
                for sound in purchaseSounds do
                    sound:Destroy()
                    purchaseSounds[sound] = nil
                end
            end
        end,
        Tooltip = 'Hold on a shop item to rapidly buy it'
    })
    HoldDelay = ShopQuickBuy:CreateSlider({
        Name = 'Hold Delay',
        Min = 0,
        Max = 1,
        Default = 0.15,
        Decimal = 20,
        Suffix = 'seconds'
    })
    CPS = ShopQuickBuy:CreateSlider({
        Name = 'CPS',
        Min = 1,
        Max = 20,
        Default = 20,
        Darker = true
    })
end)

run(function()
    local SilentAura
    local Targets
    local Speed
    local Range
    local Angle
    local Mode
    local Area
    local LegitAura
    local Mouse
    local NoSwing
    local Limit
    local SilentAim
    local SwingTime
    local Perfect
    local FaceTarget
    local Dynamic

    local Show
    local Targetcolor
    local Attackcolor

    --[[
        Hit pacing, taken from idk's SilentAura - the one place its implementation was clearly
        ahead of this one. Aether's aura had no attack gate at all: it fired the hit remote on
        every frame the target was in range, which the server throws away and which reads as
        obviously machine-driven. Every hit now waits for the sword's own swing cooldown.

        Dynamic hits replaces that with a delay scaled by how close the target is - a hit sent
        early from far away is the one the server is most likely to reject, so at range the
        delay stretches out and up close it tightens.
    ]]
    local lastHit = 0

    local function dynamicHitDelay(ent, meta)
        local delay = ((meta.displayName and meta.displayName:find(' Chainsaw')) and 0.11 or 0.29) + 0.03
        local distance = math.min(14.4, (entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude)
        return delay * distance / 14.4
    end

    local function readyToHit(ent, sword, meta)
        if Dynamic.Enabled then
            return (tick() - lastHit) >= dynamicHitDelay(ent, meta)
        end
        local ok, remaining = pcall(function()
            return bedwars.SwordController:getRemainingSwingCooldown(sword.tool.Name)
        end)
        if ok and type(remaining) == 'number' then
            return remaining <= 0
        end
        -- The controller does not expose the cooldown in this build. Fall back to the swing
        -- time the module is already configured with rather than to no gate at all.
        return (tick() - lastHit) >= (Perfect.Enabled and ((meta.sword and meta.sword.attackSpeed) or 0.11) or math.max(SwingTime.Value, 0.11))
    end

    local function getAttackData()
        if not entitylib.isAlive then
            return false
        end
        if Mouse.Enabled then
            if not inputService:IsMouseButtonPressed(0) and (tick() - bedwars.SwordController.lastSwing) > 0.3 then
                return false
            end
        end
        if LegitAura.Enabled and (tick() - bedwars.SwordController.lastSwing) > 0.3 then
            return false
        end

        if (lplr.Character:GetAttribute('StunnedUntilTime') or 0) - workspace:GetServerTimeNow() > 0 then
            return false
        end
        if bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) then
            return false
        end

        local sword = Limit.Enabled and store.hand or store.tools.sword
        if not sword or not sword.tool then
            return false
        end

        local meta = bedwars.ItemMeta[sword.tool.Name]
        if Limit.Enabled then
            if store.hand.toolType ~= 'sword' or bedwars.DaoController.chargingMaid then
                return false
            end
        end

        return sword, meta
    end

    local cache = {}
    local function getAim(ent)
        if Area.Value == 'Closest' then
            if not cache[ent.Character] then
                cache[ent.Character] = ent.Character:GetChildren()
            end
            local localPosition, magnitude, part = inputService.GetMouseLocation(inputService), 9e9, nil
            for _, v in cache[ent.Character] do
                if v and v.Parent and v:IsA('BasePart') then
                    local position, vis = gameCamera.WorldToViewportPoint(gameCamera, v.Position)

                    if vis then
                        local mag = (localPosition - Vector2.new(position.x, position.y)).Magnitude

                        if mag < magnitude then
                            magnitude = mag
                            part = v
                        end
                    end
                end
            end
            if part then
                return part.Position
            end
        end
        return ent.RootPart.Position
    end

    local function ease(t)
        return t < 0.5 and 4 * t * t * t or 1 - math.pow(-2 * t + 2, 3) / 2
    end

    local function findAim(localcframe, ent, fps, started)
        local prog, rng = ease(math.min((tick() - started) / (1 / (Speed.Value * 0.5)), 1)), Random.new()
        local speed = Speed.Value * prog
        return localcframe:Lerp(CFrame.lookAt(localcframe.p, getAim(ent) + Vector3.new((rng:NextNumber() - 0.5) * 15 * fps, (rng:NextNumber() - 0.5) * 15 * fps, (rng:NextNumber() - 0.5) * 15 * fps)), speed * fps), speed
    end

    local box = Instance.new('BoxHandleAdornment')
    box.Adornee = nil
    box.AlwaysOnTop = true
    box.Size = Vector3.new(3, 5, 3)
    box.CFrame = CFrame.new(0, -0.5, 0)
    box.ZIndex = 0
    box.Parent = vape.gui

    SilentAura = vape.Categories.Combat:CreateModule({
        Name = 'SilentAura',
        Function = function(callback)
            if callback then
                local lastent, lastfound = nil, 0
                local foundat = tick()
                local lastattacked = tick()

                SilentAura:Clean(runService.PostSimulation:Connect(function(dt)
                    -- Face target off: never rotate the body or move the camera toward the
                    -- target - fall through to restoring AutoRotate. Hits still land because
                    -- the attack below is computed from positions, not from where we face.
                    if entitylib.isAlive and tick() - lastfound < 0.5 and FaceTarget.Enabled then
                        targetinfo.Targets[lastent] = tick() + 0.5
                        entitylib.character.Humanoid.AutoRotate = not SilentAim.Enabled
                        local cframe, speed = findAim(gameCamera.CFrame, lastent, dt, foundat)
                        if SilentAim.Enabled then
                            entitylib.character.RootPart.CFrame = entitylib.character.RootPart.CFrame:Lerp(CFrame.lookAt(entitylib.character.RootPart.Position, Vector3.new(lastent.RootPart.Position.X, entitylib.character.RootPart.Position.Y, lastent.RootPart.Position.Z)), (speed + 2) * dt)
                        else
                            gameCamera.CFrame = cframe
                        end
                    elseif entitylib.isAlive then
                        entitylib.character.Humanoid.AutoRotate = true
                    end
                end))

                local frames = 9e9
                repeat
                    task.wait()
                    local sword, meta = getAttackData()
                    if sword then
                        local localPosition = entitylib.character.RootPart.Position
                        local ent = entitylib.EntityPosition({
                            Origin = localPosition,
                            Range = bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE + Range.Value,
                            Wallcheck = Targets.Walls.Enabled or nil,
                            Part = 'RootPart',
                            Players = Targets.Players.Enabled,
                            NPCs = Targets.NPCs.Enabled,
                            Limit = 1,
                            Sort = sortmethods[Mode.Value or 'Distance'],
                        })
                        local Slider = tick() - lastattacked < 0.1 and Attackcolor or Targetcolor
                        box.Adornee = Show.Enabled and ent and ent.RootPart or nil
                        box.Transparency = 1 - Slider.Opacity
                        box.Color3 = Color3.fromHSV(Slider.Hue, Slider.Sat, Slider.Value)
                        if ent then
                            if not store.hand or store.hand.tool ~= sword.tool then
                                local hotbar = getHotbar(sword.tool)
                                if hotbar then
                                    hotbarSwitch(hotbar)
                                else
                                    continue
                                end
                            end
                            if frames > 50 then
                                frames = 0
                            end
                            frames += 1

                            local localfacing = (inputService.KeyboardEnabled and gameCamera or entitylib.character.RootPart).CFrame.LookVector * Vector3.new(1, 0, 1)
                            local delta, flat = (ent.RootPart.Position - localPosition), ((ent.RootPart.Position - localPosition) * Vector3.new(1, 0, 1))
                            local facingdot = flat.Magnitude > 0 and localfacing.Magnitude > 0 and (localfacing / localfacing.Magnitude):Dot(flat / flat.Magnitude) or 0
                            if facingdot < math.cos(math.rad(Angle.Value) / 2) then
                                continue
                            end

                            if not LegitAura.Enabled and (tick() - bedwars.SwordController.lastSwing) >= (Perfect.Enabled and (meta.sword.attackSpeed or 0.11) or math.max(SwingTime.Value, 0.11)) then
                                bedwars.SwordController:playSwordEffect(meta, false)
                                bedwars.SwordController.lastSwing = tick()
                            end

                            if lastent ~= ent or facingdot < -0.5 then
                                foundat = tick()
                            end
                            lastent, lastfound = ent, tick()

                            if delta.Magnitude > bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE then
                                continue
                            end
                            lastattacked = tick()

                            if not readyToHit(ent, sword, meta) then
                                continue
                            end
                            lastHit = tick()

                            local dir = CFrame.lookAt(localPosition, ent.RootPart.Position).LookVector
                            local pos = localPosition + dir * math.max(delta.Magnitude - 14.4, 0)
                            bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
                            bedwars.Client:Get(remotes.AttackEntity):SendToServer({
                                weapon = sword.tool,
                                chargedAttack = {chargeRatio = 0},
                                entityInstance = ent.Character,
                                validate = {
                                    raycast = {
                                        cameraPosition = {value = pos},
                                        cursorDirection = {value = dir},
                                    },
                                    targetPosition = {
                                        -- The character's pivot rather than the root part's
                                        -- position: it is what the server resolves the hit
                                        -- against, so it is what should be reported.
                                        value = ent.Character:GetPivot().Position,
                                    },
                                    selfPosition = {value = pos},
                                },
                            })
                        else
                            lastfound = 0
                            frames = 0
                        end
                    else
                        box.Adornee = nil
                        lastfound = 0
                        frames = 0
                    end
                until not SilentAura.Enabled
            else
                if entitylib.isAlive then
                    entitylib.character.Humanoid.AutoRotate = true
                end
                box.Adornee = nil
            end
        end,
        Tooltip = 'Automatically aims and attacks nearby target',
    })

    Targets = SilentAura:CreateTargets({
        Players = true,
        NPCs = true,
    })
    Speed = SilentAura:CreateSlider({
        Name = 'Aim speed',
        Min = 1,
        Max = 10,
        Default = 6,
        Decimal = 5,
        Tooltip = 'How fast the Aura is going to aim',
    })
    SwingTime = SilentAura:CreateSlider({
        Name = 'Swing time',
        Darker = true,
        Visible = false,
        Min = 0,
        Max = 0.5,
        Default = 0.42,
        Decimal = 100,
    })
    Range = SilentAura:CreateSlider({
        Name = 'Extra swing distance',
        Tooltip = 'Where you will start swinging, not attacking',
        Min = 0,
        Max = 6,
        Suffix = function(val)
            return val <= 1 and 'stud' or 'studs'
        end,
        Decimal = 5,
        Default = 3,
    })
    Angle = SilentAura:CreateSlider({
        Name = 'Max angle',
        Min = 1,
        Max = 360,
        Default = 180,
    })
    local methods = {'Damage', 'Distance'}
    for i in sortmethods do
        if not table.find(methods, i) then
            table.insert(methods, i)
        end
    end
    Mode = SilentAura:CreateDropdown({
        Name = 'Target mode',
        List = methods,
        Tooltip = 'How Aura should prioritize targets',
        Default = 'Health',
    })
    Area = SilentAura:CreateDropdown({
        Name = 'Target area',
        Tooltip = 'Where the Aura will aim towards',
        List = {'Center', 'Closest'},
        Default = 'Center',
        Visible = false,
    })
    Perfect = SilentAura:CreateToggle({
        Name = 'Perfect Swing',
        Tooltip = 'Follows tool\'s swing time',
        Function = function(callback)
            SwingTime.Object.Visible = not callback
        end,
        Default = true,
    })
    Mouse = SilentAura:CreateToggle({Name = 'Require mouse down'})
    Dynamic = SilentAura:CreateToggle({
        Name = 'Dynamic hits',
        Tooltip = 'Times each hit off the range to the target instead of the swing cooldown, so the server keeps more of them'
    })
    LegitAura = SilentAura:CreateToggle({Name = 'Swing only'})
    SilentAim = SilentAura:CreateToggle({
        Name = 'Silent Aim',
        Tooltip = 'Silently aims while keeping natural-looking camera movement.',
        Default = true,
        Function = function(callback)
            Area.Object.Visible = not callback
        end,
    })
    FaceTarget = SilentAura:CreateToggle({
        Name = 'Face target',
        Tooltip = 'On - turns to face the target\nOff - never turns, though hits inside Max angle still land',
        Default = true,
    })
    Show = SilentAura:CreateToggle({
        Name = 'Show target',
        Default = true,
        Function = function(callback)
            pcall(function()
                Targetcolor.Object.Visible = callback
                Attackcolor.Object.Visible = callback
            end)
        end,
    })
    Targetcolor = SilentAura:CreateColorSlider({
        Name = 'Target color',
        Darker = true,
        DefaultOpacity = 0.5,
    })
    Attackcolor = SilentAura:CreateColorSlider({
        Name = 'Attack color',
        Darker = true,
        DefaultOpacity = 0.5,
    })
    Limit = SilentAura:CreateToggle({Name = 'Limit to items'})
end)

run(function()
    local Sprint
    local old

    Sprint = vape.Categories.Combat:CreateModule({
        Name = 'Sprint',
        Function = function(callback)
            if callback then
                if inputService.TouchEnabled then
                    pcall(function()
                        lplr.PlayerGui.MobileUI['4'].Visible = false
                    end)
                end
                old = bedwars.SprintController.stopSprinting
                bedwars.SprintController.stopSprinting = function(...)
                    local call = old(...)
                    bedwars.SprintController:startSprinting()
                    return call
                end
                Sprint:Clean(entitylib.Events.LocalAdded:Connect(function()
                    task.delay(0.1, function()
                        bedwars.SprintController:stopSprinting()
                    end)
                end))
                bedwars.SprintController:stopSprinting()
            else
                if inputService.TouchEnabled then
                    pcall(function()
                        lplr.PlayerGui.MobileUI['4'].Visible = true
                    end)
                end
                bedwars.SprintController.stopSprinting = old
                bedwars.SprintController:stopSprinting()
            end
        end,
        Tooltip = 'Sets your sprinting to true'
    })
end)

run(function()
    local TriggerBot
    local CPS
    local Projectile
    local ProjectileRange
    local ProjectileBlacklist
    local Targets
    local Range, Angle, Limit, Region, Mouse, GUI, ShowTarget, BoxColor, BoxTween, BoxSpeed
    local box
    local rayParams = RaycastParams.new()
    local projectileRemote = {InvokeServer = function() end}
    local nextFire = 0
    task.spawn(function()
        projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local function meleeTarget(origin, range)
        if Angle.Value > 0 then
            local ent = entitylib.EntityMouse({Part = 'RootPart', Range = Angle.Value, MouseOrigin = gameCamera.ViewportSize / 2,
                Players = Targets.Players.Enabled, NPCs = Targets.NPCs.Enabled, Wallcheck = Targets.Walls.Enabled, Origin = origin})
            return ent and (origin - ent.RootPart.Position).Magnitude <= range and ent or nil
        end
        local unit = lplr:GetMouse().UnitRay
        rayParams.FilterDescendantsInstances = {lplr.Character}
        local ray = bedwars.QueryUtil:raycast(unit.Origin, unit.Direction * 200, rayParams)
        if not ray then return end
        for _, ent in entitylib.List do
            if ent.Targetable and ray.Instance:IsDescendantOf(ent.Character) and (origin - ent.RootPart.Position).Magnitude <= range
                and (Targets.Players.Enabled and ent.Player or Targets.NPCs.Enabled and not ent.Player)
                and (not Targets.Walls.Enabled or not entitylib.Wallcheck(origin, ent.RootPart.Position, true, ent)) then return ent end
        end
    end

    local function getAmmo(source)
        for _, item in store.inventory.inventory.items do
            if source.ammoItemTypes and table.find(source.ammoItemTypes, item.itemType) then
                return item.itemType
            end
        end
    end

    -- Fires the held projectile at the target the way ProjectileAura does: equip the
    -- projectile item, solve the lead/arc with prediction, and fire it server-side.
    -- Returns false (without ever mouse-clicking) if there is nothing valid to fire.
    local function fireProjectileAt(ent)
        if tick() < nextFire then return false end
        local hand = store.hand.tool
        local meta = hand and bedwars.ItemMeta[hand.Name]
        local source = meta and meta.projectileSource
        if not (entitylib.isAlive and source and ent and ent.RootPart) then return false end

        local ammo = getAmmo(source) or (source.ammoItemTypes and source.ammoItemTypes[1]) or hand.Name
        local projectile = type(source.projectileType) == 'function' and source.projectileType(ammo) or source.projectileType or ammo
        if table.find(ProjectileBlacklist.ListEnabled, hand.Name) or table.find(ProjectileBlacklist.ListEnabled, ammo) or table.find(ProjectileBlacklist.ListEnabled, projectile) then return false end
        local projmeta = bedwars.ProjectileMeta[projectile] or bedwars.ProjectileMeta[ammo]
        if not projmeta then return false end

        local root = entitylib.character.RootPart
        local selfpos = root.Position
        local speed = projmeta.launchVelocity or source.launchVelocity or 100
        local gravity = projmeta.gravitationalAcceleration or 196.2
        rayParams.FilterDescendantsInstances = {lplr.Character, gameCamera}
        local target = prediction.SolveTrajectory(selfpos, speed, gravity, ent.RootPart.Position, ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, ent.HipHeight, ent.Jumping and 42.6 or nil, rayParams, nil, lplr:GetNetworkPing())
        if not target then return false end

        local dir = CFrame.lookAt(selfpos, target).LookVector
        local shootPosition = (CFrame.new(selfpos, target) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position

        switchItem(hand)
        local id = httpService:GenerateGUID(true)
        local success = pcall(function()
            -- Spawn the client-side projectile with the SAME id the server call uses, exactly
            -- like ProjectileAura. This is what makes the arrow actually appear and the shoot
            -- animation play; without it the shot fired silently with no visible projectile.
            bedwars.ProjectileController:createLocalProjectile(projmeta, ammo, projectile, shootPosition, id, dir * speed, {drawDurationSeconds = projmeta.drawDurationSeconds or 1})
            projectileRemote:InvokeServer(hand, ammo, projectile, shootPosition, selfpos, dir * speed, id, {
                drawDurationSeconds = projmeta.drawDurationSeconds or 1,
                shotId = httpService:GenerateGUID(false)
            }, workspace:GetServerTimeNow() - 0.045)
        end)
        if success then
            nextFire = tick() + (source.fireDelaySec or 0.25)
            local shoot = source.launchSound
            shoot = shoot and shoot[math.random(1, #shoot)] or nil
            if shoot then pcall(function() bedwars.SoundManager:playSound(shoot) end) end
            -- The manual remote path skips the game's input pipeline, so neither the viewmodel
            -- nor the character animates the shot on its own. Naming constants alone left it
            -- silent - FP_BOW_SHOOT and BOW_SHOOT are not in this build's AnimationType - so the
            -- exact names are only the first attempt, and anything the enum calls a bow release
            -- is matched by meaning after that. Charge and draw animations are rejected: they
            -- are the shot's neighbours in the enum and holding a bow bent is not a shot.
            local fp = resolveAnimation({'FP_BOW_SHOOT', 'FP_CROSSBOW_SHOOT', 'FP_SHOOT', 'FP_THROW'})
                or matchAnimation('fp_projectile', {
                    {'fp', 'bow', 'shoot'}, {'fp', 'bow', 'release'}, {'fp', 'bow', 'fire'},
                    {'fp', 'shoot'}, {'fp', 'fire'}, {'fp', 'throw'}, {'fp', 'launch'}, {'fp', 'bow'}
                }, {'charge', 'draw', 'pull', 'idle', 'equip', 'hold', 'walk', 'run', 'reload'})
                -- Last resort so the shot is never invisible: the generic item-use motion. Only
                -- ever on the viewmodel, where it reads as using what is in your hand.
                or resolveAnimation({'FP_USE_ITEM'})
            local body = resolveAnimation({'BOW_SHOOT', 'CROSSBOW_SHOOT', 'SHOOT', 'THROW'})
                or matchAnimation('body_projectile', {
                    {'bow', 'shoot'}, {'bow', 'release'}, {'bow', 'fire'},
                    {'shoot'}, {'throw'}, {'launch'}
                }, {'fp', 'charge', 'draw', 'pull', 'idle', 'equip', 'hold', 'walk', 'run', 'reload'})
            if fp then
                pcall(function()
                    bedwars.ViewmodelController:playAnimation(fp)
                end)
            end
            if body then
                pcall(function()
                    bedwars.GameAnimationUtil:playAnimation(lplr.Character, body)
                end)
            end
        end
        return success
    end

    TriggerBot = vape.Categories.Combat:CreateModule({
        Name = 'TriggerBot',
        Function = function(callback)
            if callback then
				if ShowTarget and ShowTarget.Enabled and not box then box = Instance.new('BoxHandleAdornment'); box.AlwaysOnTop = true; box.Size = Vector3.zero; box.CFrame = CFrame.new(0, -0.5, 0); box.Parent = vape.gui end
                repeat
                    local doAttack
                    if not GUI.Enabled or not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) then
                        local ent
                        if entitylib.isAlive and (not Mouse.Enabled or inputService:IsMouseButtonPressed(0)) and (not Limit.Enabled or store.hand.toolType == 'sword') and bedwars.DaoController.chargingMaid == nil then
                            local heldMeta = store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name]
                            local reach = heldMeta and heldMeta.sword and heldMeta.sword.attackRange or 14.4
                            local attackRange = math.clamp(Range.Value, 0, reach * 2)
                            ent = meleeTarget(entitylib.character.RootPart.Position, attackRange)
                            doAttack = ent ~= nil or (Region.Enabled and bedwars.SwordController:getTargetInRegion(attackRange, 0) ~= nil)
                            if ent then targetinfo.Targets[ent] = tick() + 1 end
                            if doAttack then
                                bedwars.SwordController:swingSwordAtMouse()
                            end
                        end
						if box then
							box.Adornee = ent and ent.RootPart or nil
							tweenService:Create(box, TweenInfo.new(BoxSpeed.Value, Enum.EasingStyle[BoxTween.Value]), {Size = ent and Vector3.new(4, 6, 4) or Vector3.zero}):Play()
							if ent then box.Color3 = Color3.fromHSV(BoxColor.Hue, BoxColor.Sat, BoxColor.Value); box.Transparency = 1 - BoxColor.Opacity end
						end

                        if entitylib.isAlive and Projectile.Enabled and store.hand.tool then
                            local unit = lplr:GetMouse().UnitRay
                            rayParams.FilterDescendantsInstances = {lplr.Character}
                            local ray = bedwars.QueryUtil:raycast(unit.Origin, unit.Direction * ProjectileRange.Value, rayParams)
                            if ray then
                                for _, ent in entitylib.List do
                                    if ent.Targetable and (Targets.Players.Enabled or not ent.Player) and (Targets.NPCs.Enabled or ent.Player) and ray.Instance:IsDescendantOf(ent.Character) then
                                        if fireProjectileAt(ent) then
                                            doAttack = true
                                        end
                                        break
                                    end
                                end
                            end
                        end
                    end

                    task.wait(doAttack and 1 / CPS.GetRandomValue() or 0.016)
                until not TriggerBot.Enabled
			elseif box then
				box:Destroy()
				box = nil
            end
        end,
        Tooltip = 'Automatically swings when hovering over a entity'
    })
    Targets = TriggerBot:CreateTargets({Players = true, NPCs = true, Walls = true})
    Range = TriggerBot:CreateSlider({Name = 'Range', Min = 1, Max = 18, Default = 18, Decimal = 10, Suffix = ' studs', Tooltip = 'Clamped by held weapon reach.'})
    Angle = TriggerBot:CreateSlider({Name = 'Angle', Min = 0, Max = 1000, Default = 0, Tooltip = 'Targets near screen center instead of only the cursor ray.'})
    CPS = TriggerBot:CreateTwoSlider({
        Name = 'CPS',
        Min = 1,
        Max = 9,
        DefaultMin = 7,
        DefaultMax = 7
    })
    Limit = TriggerBot:CreateToggle({Name = 'Limit to items', Default = true})
    Region = TriggerBot:CreateToggle({Name = 'Region check', Default = true})
    Mouse = TriggerBot:CreateToggle({Name = 'Require mouse down'})
    GUI = TriggerBot:CreateToggle({Name = 'GUI check'})
    Projectile = TriggerBot:CreateToggle({
        Name = 'Projectiles',
        Function = function(call)
            pcall(function()
                ProjectileRange.Object.Visible = call
                ProjectileBlacklist.Object.Visible = call
            end)
        end,
    })
    ProjectileRange = TriggerBot:CreateSlider({Name = 'Projectile Range', Min = 10, Max = 120, Default = 60, Suffix = 'studs', Visible = false})
    ProjectileBlacklist = TriggerBot:CreateTextList({Name = 'Projectile Blacklist', Default = {'telepearl', 'fireball'}, Visible = false})
    ShowTarget = TriggerBot:CreateToggle({Name = 'Show target', Function = function(enabled)
        if BoxColor then BoxColor.Object.Visible = enabled; BoxTween.Object.Visible = enabled; BoxSpeed.Object.Visible = enabled end
        if box then box:Destroy(); box = nil end
        if enabled then box = Instance.new('BoxHandleAdornment'); box.AlwaysOnTop = true; box.Size = Vector3.zero; box.CFrame = CFrame.new(0, -0.5, 0); box.Parent = vape.gui end
    end})
    local animations = {'Bounce'}
    for _, style in Enum.EasingStyle:GetEnumItems() do if not table.find(animations, style.Name) then table.insert(animations, style.Name) end end
    BoxTween = TriggerBot:CreateDropdown({Name = 'Box Animation', List = animations, Visible = false})
    BoxSpeed = TriggerBot:CreateSlider({Name = 'Animation Speed', Min = 0, Max = 10, Default = 0.9, Decimal = 30, Visible = false})
    BoxColor = TriggerBot:CreateColorSlider({Name = 'Target Color', DefaultHue = 0.6, DefaultOpacity = 0.5, Visible = false})
end)

run(function()
    local Velocity
    local Horizontal
    local Vertical
    local Chance
    local TargetCheck
    local Direction
    local rand, old = Random.new()

    local function rotateY(vector, degrees)
        local radians = math.rad(degrees)
        return Vector3.new(
            vector.X * math.cos(radians) - vector.Z * math.sin(radians),
            0,
            vector.X * math.sin(radians) + vector.Z * math.cos(radians)
        )
    end

    local function getDirectionalSource(root, sourcePosition)
        local direction = Direction.Value
        if direction == 'Default' then
            return sourcePosition
        elseif direction == 'Up' then
            root:ApplyImpulse(Vector3.new(0, root.AssemblyMass * 120, 0))
            return nil, true
        elseif direction == 'Void' then
            root:ApplyImpulse(Vector3.new(0, -root.AssemblyMass * 60, 0))
            return nil, true
        end

        local rootPosition = root.Position
        if direction == 'Left' then
            return rootPosition + root.CFrame.RightVector * 10
        elseif direction == 'Right' then
            return rootPosition - root.CFrame.RightVector * 10
        elseif direction == 'Reverse' and sourcePosition then
            return Vector3.new(2 * rootPosition.X - sourcePosition.X, sourcePosition.Y, 2 * rootPosition.Z - sourcePosition.Z)
        end

        local flatSource = sourcePosition and Vector3.new(sourcePosition.X, 0, sourcePosition.Z)
        local velocity = flatSource and ((rootPosition * Vector3.new(1, 0, 1)) - flatSource)
        if not velocity or velocity.Magnitude < 0.001 then
            return sourcePosition
        end

        velocity = velocity.Unit
        direction = direction == 'Random' and ({'Left', 'Right', 'Pull'})[rand:NextInteger(1, 3)] or direction
        local redirected = direction == 'Pull' and -velocity or table.find({'Left', 'Right'}, direction) and rotateY(velocity, direction == 'Left' and 90 or -90) or velocity
        return Vector3.new(rootPosition.X - redirected.X * 100, sourcePosition.Y, rootPosition.Z - redirected.Z * 100)
    end

    Velocity = vape.Categories.Combat:CreateModule({
        Name = 'Velocity',
        Function = function(callback)
            if callback then
                old = bedwars.KnockbackUtil.applyKnockback
                bedwars.KnockbackUtil.applyKnockback = function(root, mass, dir, knockback, ...)
                    if rand:NextNumber(0, 100) > Chance.Value then
                        return old(root, mass, dir, knockback, ...)
                    end
                    local check = (not TargetCheck.Enabled) or entitylib.EntityPosition({
                        Range = 50,
                        Part = 'RootPart',
                        Players = true
                    })

                    if check then
                        knockback = knockback or {}
                        if Horizontal.Value == 0 and Vertical.Value == 0 and Direction.Value == 'Default' then return end
                        if Horizontal.Value ~= 0 or Vertical.Value ~= 0 then
                            knockback.horizontal = (knockback.horizontal or 1) * (Horizontal.Value / 100)
                            knockback.vertical = (knockback.vertical or 1) * (Vertical.Value / 100)
                        end
                        local redirectedSource, skipOriginal = getDirectionalSource(root, dir)
                        if skipOriginal then return end
                        dir = redirectedSource or dir
                    end

                    return old(root, mass, dir, knockback, ...)
                end
            else
                bedwars.KnockbackUtil.applyKnockback = old
            end
        end,
        Tooltip = 'Reduces knockback taken'
    })
    Horizontal = Velocity:CreateSlider({
        Name = 'Horizontal',
        Min = 0,
        Max = 100,
        Default = 0,
        Suffix = '%'
    })
    Vertical = Velocity:CreateSlider({
        Name = 'Vertical',
        Min = 0,
        Max = 100,
        Default = 0,
        Suffix = '%'
    })
    Chance = Velocity:CreateSlider({
        Name = 'Chance',
        Min = 0,
        Max = 100,
        Default = 100,
        Suffix = '%'
    })
    TargetCheck = Velocity:CreateToggle({Name = 'Only when targeting'})
    Direction = Velocity:CreateDropdown({
        Name = 'Direction',
        List = {'Default', 'Backwards', 'Up', 'Void', 'Left', 'Right', 'Reverse', 'Pull', 'Random'},
        Default = 'Default',
        Tooltip = 'Redirects knockback direction inside the unified Velocity module'
    })
end)

run(function()
    local AntiFall
    local Mode
    local Material
    local Color
    local FlyRelease
    local ClutchBlocks
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true

    local CELL = 3

    local function getLowGround()
        local mag = math.huge
        for _, pos in bedwars.BlockController:getStore():getAllBlockPositions() do
            pos = pos * 3
            if pos.Y < mag and not getPlacedBlock(pos + Vector3.new(0, 3, 0)) then
                mag = pos.Y
            end
        end
        return mag
    end

    -- getLowGround walks every block on the map, so it is far too heavy to call from a per-frame
    -- check. The lowest block on a BedWars map barely moves, so cache it.
    local lowestValue, lowestAt = math.huge, 0
    local function lowestGround()
        if tick() - lowestAt > 5 then
            lowestValue = getLowGround()
            lowestAt = tick()
        end
        return lowestValue
    end

    -- Column results are cached for a few frames as well: the void check runs every frame while
    -- airborne, and that is exactly when the ray finds nothing and the store walk is reached.
    local columnKey, columnValue, columnAt = nil, nil, 0

    -- Is another module already flying/launching us? Nothing in here may fight those: they own the
    -- character's velocity while they run, and both the old clutch and the old Normal mode used to
    -- yank against them.
    local function beingCarried()
        local flyModule = Fly or vape.Modules.Fly
        local longJumpModule = LongJump or vape.Modules.LongJump
        if flyModule and flyModule.Enabled then return true end
        if longJumpModule and longJumpModule.Enabled then return true end
        return false
    end

    -- The one question both new modes hinge on: is there ANY land under us, or is this the void?
    --
    -- Answered two independent ways, because either one alone gives false answers that matter:
    --   * a long downward ray, which sees map geometry the block store knows nothing about, and
    --   * the block engine's own store walked down the column, which cannot be defeated by a
    --     collision group, a CanQuery flag or a filter.
    -- `drift` follows our horizontal velocity so the probe looks at the column we are actually
    -- heading for. That is the false-place fix: running off a ledge toward a lower platform used to
    -- read as "void" because the straight-down ray hit the ledge we were leaving.
    local function landBelow(root, lookahead)
        local pos = root.Position
        local horiz = root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
        local drift = horiz * math.clamp(lookahead or 0, 0, 2)
        local from = Vector3.new(pos.X + drift.X, pos.Y, pos.Z + drift.Z)

        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
        rayCheck.CollisionGroup = root.CollisionGroup
        local ray = workspace:Raycast(from, Vector3.new(0, -600, 0), rayCheck)
        if ray then return ray.Position.Y end

        -- Nothing physical: ask the block store, walking the column down to the lowest block on
        -- the map. One lookup per 3 studs, stopping at the first hit.
        local lowest = lowestGround()
        if lowest == math.huge then return nil end
        local cell = bedwars.BlockController:getBlockPosition(from)
        local key = cell.X .. ',' .. cell.Z
        if columnKey == key and (tick() - columnAt) < 0.15 then
            return columnValue
        end
        local floor = math.max(math.floor(lowest / CELL), cell.Y - 400)
        local found = nil
        for y = cell.Y, floor, -1 do
            if getPlacedBlock(Vector3.new(cell.X, y, cell.Z) * CELL) then
                found = y * CELL
                break
            end
        end
        columnKey, columnValue, columnAt = key, found, tick()
        return found
    end

    ----------------------------------------------------------------------------
    -- Clutch
    --
    -- Rebuilt. The old version waited until the barrier and then bridged in from a wall at BARRIER
    -- height - hundreds of studs below where the fall started - firing a placement every 0.01s
    -- without ever checking whether one landed. Over the void there is usually no wall within
    -- range at that height either, so the common case was a burst of refused placements and a
    -- death. It also had no idea whether the fall was real, so a hop off a ledge toward lower
    -- ground threw down a bridge for nothing.
    --
    -- What it does now: the instant a genuine void fall starts - while the island we just left is
    -- still beside us - it finds a real support block, lays a short platform in under our feet at
    -- our CURRENT height, and confirms each block arrived before asking for the next.
    ----------------------------------------------------------------------------
    local clutchUntil, clutchBusy, clutchGeneration = 0, false, 0

    -- Wool first (it is what everything else buys), then any other sane block. Anything that
    -- explodes, sticks, traps or cannot be stood on is no use as a floor.
    local badBlocks = {'tnt', 'cannon', 'bed', 'trap', 'gumdrop', 'glue', 'ladder', 'sludge', 'bomb', 'beacon', 'spawner', 'chest', 'barrel'}
    local function clutchBlock()
        local wool, amount = getWool()
        if wool and (amount or 0) > 0 then return wool end
        for _, item in store.inventory.inventory.items do
            local meta = bedwars.ItemMeta[item.itemType]
            if meta and meta.block and (item.amount or 0) > 0 then
                local bad = false
                for _, name in badBlocks do
                    if item.itemType:find(name) then
                        bad = true
                        break
                    end
                end
                if not bad then return item.itemType end
            end
        end
        return nil
    end

    local faceOffsets = {
        Vector3.new(CELL, 0, 0), Vector3.new(-CELL, 0, 0),
        Vector3.new(0, CELL, 0), Vector3.new(0, -CELL, 0),
        Vector3.new(0, 0, CELL), Vector3.new(0, 0, -CELL)
    }

    -- A block needs something to lean on, so a cell is only worth asking for once one of its six
    -- faces is filled. Blindly requesting mid-air placements is most of what made the old clutch
    -- look broken.
    local function hasSupport(world)
        for _, offset in faceOffsets do
            if getPlacedBlock(world + offset) then return true end
        end
        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
        for _, offset in faceOffsets do
            local probe = world + offset
            if workspace:Raycast(probe + Vector3.new(0, 1.4, 0), Vector3.new(0, -2.8, 0), rayCheck) then return true end
        end
        return false
    end

    -- Nearest cell we could build off, searched outward from our own column at the height we want
    -- the floor. Right at the start of a fall that is the edge of the island we just walked off.
    local function findSupportCell(centre)
        local best, bestDist
        local reach = math.clamp(ClutchBlocks and ClutchBlocks.Value or 6, 1, 10)
        for radius = 1, reach do
            for x = -radius, radius do
                for z = -radius, radius do
                    if math.max(math.abs(x), math.abs(z)) ~= radius then continue end
                    for y = -1, 2 do
                        local world = centre + Vector3.new(x * CELL, y * CELL, z * CELL)
                        if getPlacedBlock(world) then
                            local d = (world - centre).Magnitude
                            if not bestDist or d < bestDist then
                                best, bestDist = world, d
                            end
                        end
                    end
                end
            end
            if best then return best end
        end
        return best
    end

    local function placeClutch(world, block)
        if getPlacedBlock(world) then return true end
        if not hasSupport(world) then return false end
        pcall(bedwars.placeBlock, world, block, false)
        -- Confirm it actually arrived instead of firing the next one blind. A placement the server
        -- refused has to be seen as refused, or the whole bridge is built on nothing.
        -- A direct placement normally reaches the block store on the next few simulation steps.
        -- Waiting a third of a second before trying another supported cell was enough to fall
        -- outside of placement reach, so only reserve a short confirmation window here.
        local deadline = tick() + 0.12
        repeat
            task.wait(0.03)
        until getPlacedBlock(world) or tick() > deadline or not AntiFall.Enabled or Mode.Value ~= 'Clutch'
        return getPlacedBlock(world) ~= nil
    end

    local function clutch(predicted, token)
        if clutchBusy or tick() < clutchUntil or not entitylib.isAlive or Mode.Value ~= 'Clutch' or token ~= clutchGeneration then return end
        local root = entitylib.character.RootPart
        if not root or not isnetworkowner(root) then return end
        local block = clutchBlock()
        if not block then return end

        clutchBusy = true
        clutchUntil = tick() + 0.12

        -- Floor height: one cell under our feet, right where we are now. Catching us here instead
        -- of at barrier level is the difference between losing a couple of studs and losing the
        -- whole drop.
        local hip = entitylib.character.HipHeight or 3
        local feet = root.Position.Y - hip - (root.Size.Y * 0.5)
        local barrierTop = AntiFallPart and (AntiFallPart.Position.Y + (AntiFallPart.Size.Y * 0.5)) or -math.huge
        -- The floor must be placed at the live foot height, and its horizontal lead must stay
        -- inside a one-block placement reach. The old long ballistic prediction could put the
        -- first request ten studs ahead of the player before the clutch had a supporting block.
        local targetPosition = predicted or root.Position
        local lead = (targetPosition - root.Position) * Vector3.new(1, 0, 1)
        if lead.Magnitude > CELL then
            targetPosition = root.Position + lead.Unit * CELL
        end
        local floorCell = bedwars.BlockController:getBlockPosition(Vector3.new(targetPosition.X, feet - 1.5, targetPosition.Z))
        local floorY = floorCell.Y * CELL
        -- Never build into the barrier itself.
        if floorY <= barrierTop + 1 then
            floorY = math.floor((barrierTop + CELL + 1) / CELL) * CELL
        end

        local under = Vector3.new(floorCell.X * CELL, floorY, floorCell.Z * CELL)

        -- Directly beneath us first: if the island edge is still within a block of us (the normal
        -- case at the start of a fall) this single placement is the whole clutch.
        if placeClutch(under, block) then
            clutchBusy = false
            return
        end

        -- Otherwise walk in from the nearest real support, one confirmed block at a time, so each
        -- new block leans on the previous one.
        local support = findSupportCell(under)
        if not support then
            clutchBusy = false
            return
        end

        local delta = under - support
        local steps = (math.abs(delta.X) + math.abs(delta.Z)) / CELL
        steps = math.clamp(math.floor(steps + 0.5), 0, math.clamp(ClutchBlocks and ClutchBlocks.Value or 6, 1, 10))
        local cursor = Vector3.new(support.X, floorY, support.Z)
        for _ = 1, steps do
            if not AntiFall.Enabled or Mode.Value ~= 'Clutch' or token ~= clutchGeneration then break end
            if landBelow(root, 0.35) then break end
            if math.abs(under.X - cursor.X) > 0.1 then
                cursor += Vector3.new(math.sign(under.X - cursor.X) * CELL, 0, 0)
            else
                cursor += Vector3.new(0, 0, math.sign(under.Z - cursor.Z) * CELL)
            end
            if not placeClutch(cursor, block) then break end
            -- Landed on it already: nothing more to build.
            if entitylib.isAlive and entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air then break end
        end

        -- Finish under our feet (we have drifted while building, so recompute).
        if entitylib.isAlive and AntiFall.Enabled and Mode.Value == 'Clutch' and token == clutchGeneration then
            local now = entitylib.character.RootPart
            if now then
                local cell = bedwars.BlockController:getBlockPosition(Vector3.new(now.Position.X, floorY, now.Position.Z))
                placeClutch(Vector3.new(cell.X * CELL, floorY, cell.Z * CELL), block)
            end
        end
        clutchBusy = false
    end

    ----------------------------------------------------------------------------
    -- Fly mode: hand the fall to the Fly module the instant there is no land under us.
    --
    -- Driven off Heartbeat and tested every single frame, with no barrier, no timer and no fall
    -- speed threshold in the way, so it engages on the first frame the ground is gone - that is
    -- what keeps the Y drop to a couple of studs. Fly is only switched back off if this mode is
    -- what switched it on, so it can never take control away from you.
    ----------------------------------------------------------------------------
    local flyOwned, landSince = false, 0

    local function flyModule()
        return Fly or vape.Modules.Fly
    end

    local function stopFly(force)
        local module = flyModule()
        if not module then
            flyOwned = false
            return
        end
        if flyOwned and (force or module.Enabled) then
            flyOwned = false
            if module.Enabled then
                task.spawn(function()
                    module:Toggle()
                end)
            end
        end
    end

    local function updateFlyMode()
        if Mode.Value ~= 'Fly' then
            stopFly(true)
            return
        end
        if not entitylib.isAlive then
            stopFly(true)
            return
        end
        local root = entitylib.character.RootPart
        local module = flyModule()
        if not root or not module then return end

        local grounded = entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air
        -- Look a fraction of a second ahead so stepping off an edge counts as "no land" on the
        -- frame we leave it rather than a frame later.
        local land = grounded and root.Position.Y or landBelow(root, 0.25)

        if not land then
            landSince = 0
            if not module.Enabled then
                flyOwned = true
                -- Kill the drop we have already picked up before handing over, so Fly starts from
                -- a standstill instead of having to arrest a fall.
                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z)
                task.spawn(function()
                    module:Toggle()
                end)
            elseif not flyOwned then
                -- Already flying by your own choice: leave it entirely alone.
                return
            end
            return
        end

        -- Land is back. Hold the release briefly so a one-frame reading over a gap does not drop
        -- us, and only release once we are genuinely above something we can stand on.
        if flyOwned then
            if landSince == 0 then
                landSince = tick()
            end
            local safeDrop = (FlyRelease and FlyRelease.Value or 12)
            if (tick() - landSince) >= 0.2 and (root.Position.Y - land) <= safeDrop then
                stopFly(false)
            end
        else
            landSince = 0
        end
    end

    AntiFall = vape.Categories.Blatant:CreateModule({
        Name = 'AntiVoid',
        Function = function(callback)
            if callback then
                repeat task.wait() until store.matchState ~= 0 or (not AntiFall.Enabled)
                if not AntiFall.Enabled then return end

                clutchGeneration += 1
                flyOwned, landSince, clutchBusy = false, 0, false
                AntiFall:Clean(function()
                    stopFly(true)
                    clutchBusy = false
                    clutchGeneration += 1
                end)

                -- Fly mode owns the whole job itself, so it runs whether or not the map has a
                -- barrier height to work out.
                AntiFall:Clean(runService.Heartbeat:Connect(updateFlyMode))

                local pos, debounce = getLowGround(), tick()
                if pos ~= math.huge then
                    AntiFallPart = Instance.new('Part')
                    AntiFallPart.Size = Vector3.new(10000, 1, 10000)
                    AntiFallPart.Transparency = 1 - Color.Opacity
                    AntiFallPart.Material = Enum.Material[Material.Value]
                    AntiFallPart.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                    AntiFallPart.Position = Vector3.new(0, pos - 2, 0)
                    -- Clutch no longer collides with the barrier: the bridged blocks catch
                    -- the player, and a solid barrier would only stop them a moment before
                    -- (or on top of) the blocks and defeat the point of clutching.
                    AntiFallPart.CanCollide = Mode.Value == 'Collide'
                    AntiFallPart.Anchored = true
                    AntiFallPart.CanQuery = false
                    AntiFallPart.Parent = workspace
                    AntiFall:Clean(AntiFallPart)
                    AntiFall:Clean(AntiFallPart.Touched:Connect(function(touched)
                        if touched.Parent == lplr.Character and entitylib.isAlive and debounce < tick() then
                            debounce = tick() + 0.1
                            if Mode.Value == 'Normal' then
                                local top = getNearGround()
                                if top then
                                    local lastTeleport = lplr:GetAttribute('LastTeleported')
                                    local connection
                                    connection = runService.PreSimulation:Connect(function()
                                        if beingCarried() then
                                            connection:Disconnect()
                                            AntiFallDirection = nil
                                            return
                                        end

                                        if entitylib.isAlive and lplr:GetAttribute('LastTeleported') == lastTeleport then
                                            local delta = ((top - entitylib.character.RootPart.Position) * Vector3.new(1, 0, 1))
                                            local root = entitylib.character.RootPart
                                            AntiFallDirection = delta.Unit == delta.Unit and delta.Unit or Vector3.zero
                                            root.Velocity *= Vector3.new(1, 0, 1)
                                            rayCheck.FilterDescendantsInstances = {gameCamera, lplr.Character}
                                            rayCheck.CollisionGroup = root.CollisionGroup

                                            local ray = workspace:Raycast(root.Position, AntiFallDirection, rayCheck)
                                            if ray then
                                                for _ = 1, 10 do
                                                    local dpos = roundPos(ray.Position + ray.Normal * 1.5) + Vector3.new(0, 3, 0)
                                                    if not getPlacedBlock(dpos) then
                                                        top = dpos
                                                        break
                                                    end
                                                end
                                            end

                                            root.CFrame += Vector3.new(0, top.Y - root.Position.Y, 0)
                                            if not frictionTable.Speed then
                                                root.AssemblyLinearVelocity = (AntiFallDirection * getSpeed()) + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                                            end

                                            if delta.Magnitude < 1 then
                                                connection:Disconnect()
                                                AntiFallDirection = nil
                                            end
                                        else
                                            connection:Disconnect()
                                            AntiFallDirection = nil
                                        end
                                    end)
                                    AntiFall:Clean(connection)
                                end
                            elseif Mode.Value == 'Velocity' then
                                entitylib.character.RootPart.Velocity = Vector3.new(entitylib.character.RootPart.Velocity.X, 100, entitylib.character.RootPart.Velocity.Z)
                            elseif Mode.Value == 'Clutch' then
                                -- Last resort only. The predictive check below normally has us
                                -- caught long before the barrier is ever touched.
                                if not beingCarried() then
                                    task.spawn(clutch, nil, clutchGeneration)
                                end
                            end
                        end
                    end))
                end

                -- Clutch trigger. Fires on the first frame of a real void fall, while the island
                -- we just left is still next to us and its blocks can be built off, rather than
                -- waiting for the barrier by which time there is nothing in reach.
                AntiFall:Clean(runService.Heartbeat:Connect(function()
                    if Mode.Value ~= 'Clutch' or not entitylib.isAlive or clutchBusy then return end
                    if beingCarried() then return end
                    local root = entitylib.character.RootPart
                    if not root or not isnetworkowner(root) then return end
                    if entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air then return end
                    -- Start while the ledge is still nearby. A clutch is a placement problem,
                    -- not a barrier problem: once we are falling at -12, a normal sideways run
                    -- has already carried the player several cells beyond the island edge.
                    if root.AssemblyLinearVelocity.Y >= -2 then return end
                    -- And genuinely into the void: if there is anything at all to land on in the
                    -- column we are heading for, there is nothing to clutch. This single check is
                    -- what stops the false placing.
                    if landBelow(root, 0.45) then return end
                    local velocity = root.AssemblyLinearVelocity
                    -- Only a tiny horizontal lead is useful for a floor placed at our current
                    -- feet. It compensates for movement between the probe and request without
                    -- asking the server to place a block outside of clutch reach.
                    local time = math.clamp(0.08 + math.abs(velocity.Y) / workspace.Gravity * 0.12, 0.08, 0.18)
                    local predicted = root.Position + Vector3.new(velocity.X * time, 0, velocity.Z * time)
                    task.spawn(clutch, predicted, clutchGeneration)
                end))
            else
                AntiFallDirection = nil
                stopFly(true)
                clutchBusy = false
                clutchGeneration += 1
            end
        end,
        Tooltip = 'Helps prevent you from falling into the void'
    })
    Mode = AntiFall:CreateDropdown({
        Name = 'Move Mode',
        List = {'Normal', 'Collide', 'Velocity', 'Clutch', 'Fly'},
        Function = function(val)
            if AntiFallPart then
                -- Clutch stays non-colliding; only Collide mode walks on the barrier.
                AntiFallPart.CanCollide = val == 'Collide'
            end
            if val ~= 'Fly' then
                stopFly(true)
            end
            pcall(function()
                FlyRelease.Object.Visible = val == 'Fly'
                ClutchBlocks.Object.Visible = val == 'Clutch'
            end)
        end,
        Tooltip = 'Normal - slide to safety\nVelocity - launch up\nCollide - walk on it\nClutch - floor under you\nFly - fly over the void'
    })
    FlyRelease = AntiFall:CreateSlider({
        Name = 'Release height',
        Min = 3,
        Max = 60,
        Default = 12,
        Suffix = ' studs',
        Darker = true,
        Visible = false,
        Tooltip = 'How close above land Fly mode has to be before it hands control back'
    })
    ClutchBlocks = AntiFall:CreateSlider({
        Name = 'Clutch reach',
        Min = 1,
        Max = 10,
        Default = 6,
        Suffix = function(val)
            return val == 1 and ' block' or ' blocks'
        end,
        Darker = true,
        Visible = false,
        Tooltip = 'How far the clutch may build in from the nearest block it can lean on'
    })
    local materials = {'ForceField'}
    for _, v in Enum.Material:GetEnumItems() do
        if v.Name ~= 'ForceField' then
            table.insert(materials, v.Name)
        end
    end
    Material = AntiFall:CreateDropdown({
        Name = 'Material',
        List = materials,
        Function = function(val)
            if AntiFallPart then
                AntiFallPart.Material = Enum.Material[val]
            end
        end
    })
    Color = AntiFall:CreateColorSlider({
        Name = 'Color',
        DefaultOpacity = 0.5,
        Function = function(h, s, v, o)
            if AntiFallPart then
                AntiFallPart.Color = Color3.fromHSV(h, s, v)
                AntiFallPart.Transparency = 1 - o
            end
        end
    })

end)

run(function()
    local NoFall
    local Mode
    local MinVelocity
    local FallThreshold
    local SpoofState
    local GroundDistance
    local AnchorAttempts
    local BlockClutch
    local TelepearlClutch
    local DaoClutch
    local JadeHammerClutch
    local VoidAxeClutch
    local HealthCheck
    local Zephyr
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude
    -- Deliberately left on the default collision group - see groundBelow.
    local plainCheck = RaycastParams.new()
    plainCheck.RespectCanCollide = true
    plainCheck.FilterType = Enum.RaycastFilterType.Exclude
    local lastAnchor = 0
    local usedPearl = false
    local lastLegitUse = 0
    local clutchBusyUntil = 0
    local lastBlockPlace = 0
    local lastZephyrJump = 0
    local fallAnchorY
    local projectileRemote = {InvokeServer = function() end}
    task.spawn(function()
        projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local daoItems = {'wood_dao', 'stone_dao', 'iron_dao', 'diamond_dao', 'emerald_dao'}

    local function validCharacter()
        if not entitylib.isAlive then return end
        local character = entitylib.character
        local root = character.RootPart or character.HumanoidRootPart
        local humanoid = character.Humanoid
        if root and humanoid and humanoid.Health > 0 then
            return character, root, humanoid
        end
    end

    local function updateRay(root)
        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
        rayCheck.CollisionGroup = root.CollisionGroup
    end

    local function getGround(root, character, distance)
        updateRay(root)
        local hipHeight = character.HipHeight or (character.Humanoid and character.Humanoid.HipHeight) or 2
        local castDistance = -(distance + hipHeight + (root.Size.Y * 0.5))
        return workspace:Blockcast(root.CFrame, Vector3.new(3, 3, 3), Vector3.new(0, castDistance, 0), rayCheck)
    end

    -- Height of the floor below us, by three independent methods.
    --
    -- A cast that comes back empty is the single failure that stops TP mode dead: with no floor
    -- to aim at it does nothing at all, which is exactly what "TP doesn't teleport" looks like
    -- from the outside. So an empty result is never taken at face value here.
    --
    --   1. The box cast, tolerant of thin blocks and of ledges a thin ray slips past. This is the
    --      shipped script's own method, on the character's collision group.
    --   2. A plain long ray on the DEFAULT collision group. If the character sits in a group that
    --      does not collide with the map, (1) passes straight through the world and finds nothing
    --      while this still sees it.
    --   3. The block engine's own store, walked cell by cell down the column we are over. On a
    --      BedWars map the floor is nearly always a placed block, and a data lookup cannot be
    --      defeated by a collision group, a CanQuery flag or a filter at all.
    local function groundBelow(root, character)
        local ground = getGround(root, character, 1500)
        if ground then return ground.Position.Y end

        plainCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
        local ray = workspace:Raycast(root.Position, Vector3.new(0, -3000, 0), plainCheck)
        if ray then return ray.Position.Y end

        local success, blockY = pcall(function()
            local origin = root.Position
            for step = 1, 200 do
                local below = Vector3.new(origin.X, origin.Y - (step * 3), origin.Z)
                if getPlacedBlock(below) then
                    -- Top face of the block we found, which is what we would stand on.
                    return (bedwars.BlockController:getBlockPosition(below).Y * 3) + 1.5
                end
            end
            return nil
        end)
        return success and blockY or nil
    end

    -- The distance from the root's centre down to the floor we stand on. entitylib already folds
    -- half the root part into HipHeight, so adding it again (as this used to) put every floor
    -- estimate a stud out.
    local function standClearance(root, character)
        local humanoid = character.Humanoid
        return character.HipHeight or ((humanoid and humanoid.HipHeight or 2) + (root.Size.Y * 0.5))
    end

    -- The fall that has built up: the fastest we have been moving downwards since we were last on
    -- the ground. This, not the speed at any one instant, is what a fall is worth - a drop that
    -- has already reached 200 studs a second is a lethal fall even on the frame it happens to be
    -- reading -3 because it clipped something. Every mode below decides off this one number.
    local trackedFall = 0

    local function updateTrackedFall(root, humanoid)
        if humanoid and humanoid.FloorMaterial ~= Enum.Material.Air then
            trackedFall = 0
        else
            trackedFall = math.min(trackedFall, root.AssemblyLinearVelocity.Y)
        end
        return trackedFall
    end

    -- TP mode. BedWars charges for the landing you report, so the way to clear a long drop is to
    -- end it early: cast straight down, put the character on the floor it was heading for anyway
    -- and take the touchdown there with no speed left on it.
    --
    -- The old version teleported down for a couple of frames and then teleported back UP to
    -- "resume" the fall from where it would have got to. Moving upwards that fast is exactly what
    -- the server's movement check rejects, so every touch was rubber-banded straight back to
    -- where it started and the mode looked like it never teleported at all. A drop to the ground
    -- is a move the server is already expecting, so this one lands.
	local clearRegisteredFall
	local function tpNoFall(root, character)
        local groundY = groundBelow(root, character)
        if not groundY then return false end

        local floorY = groundY + standClearance(root, character)
        local drop = root.Position.Y - floorY
        -- Below the floor we found (inside a block, or it read a ceiling): leave it alone.
        if drop <= 1 then return false end

        local velocity = root.AssemblyLinearVelocity
		local landed = root.CFrame - Vector3.new(0, drop, 0)
		-- Pivot the complete character, not only its root. Moving a single part can
		-- be overwritten by the humanoid assembly before replication sees it.
		character:PivotTo(landed)
        -- Keep the horizontal travel so the landing spot is the one the fall was heading for,
        -- and arrive with nothing vertical left for the game to charge for. Dropping to the
        -- floor is a move the server is already expecting from someone who is falling, which is
        -- why this replicates where the old build's teleport back UP was always rejected.
        root.AssemblyLinearVelocity = Vector3.new(velocity.X, 0, velocity.Z)
        -- The fall is over as far as we are concerned. Without this the next pass would still be
        -- holding the old speed and would fire again before the humanoid has registered the
        -- landing, which is what turns one teleport into a burst of them.
		trackedFall = 0
		clearRegisteredFall(-1)
		return true
    end

    local function restoreTool(oldTool)
        if oldTool and oldTool.tool then
            task.delay(0.18, function()
                switchItem(oldTool.tool)
                local oldHotbar = getHotbar(oldTool.tool)
                if oldHotbar then hotbarSwitch(oldHotbar) end
            end)
        end
    end

    local function firePearl(root, spot, pearl)
        if usedPearl or not pearl or not projectileRemote or not projectileRemote.InvokeServer then return end
        local meta = bedwars.ProjectileMeta.telepearl
        if not meta then return end

        local calc = prediction.SolveTrajectory(root.Position, meta.launchVelocity, meta.gravitationalAcceleration, spot, Vector3.zero, workspace.Gravity, 0, 0)
        if not calc then return end

        local oldTool = store.hand
        local hotbar = getHotbar(pearl.tool)
        switchItem(pearl.tool, 0.1)
        if hotbar then hotbarSwitch(hotbar) end
        task.wait(0.03)

        local direction = CFrame.lookAt(root.Position, calc).LookVector * meta.launchVelocity
        local success = pcall(function()
            bedwars.ProjectileController:createLocalProjectile(meta, 'telepearl', 'telepearl', root.Position, nil, direction, {drawDurationSeconds = 1})
            projectileRemote:InvokeServer(pearl.tool, 'telepearl', 'telepearl', root.Position, root.Position, direction, httpService:GenerateGUID(true), {
                drawDurationSeconds = 1,
                shotId = httpService:GenerateGUID(false)
            }, workspace:GetServerTimeNow() - 0.045)
        end)
        restoreTool(oldTool)
        if success then
            usedPearl = true
            return true
        end
    end

    local function blockClutch(root)
        if tick() - lastBlockPlace < 0.08 then return end
        local wool, amount = getWool()
        if not wool or (amount or 0) < 1 then return end

        lastBlockPlace = tick()
        local placePosition = bedwars.BlockController:getBlockPosition(root.Position - Vector3.new(0, 4, 0)) * 3
        fallAnchorY = root.Position.Y
        if not getPlacedBlock(placePosition) and bedwars.placeBlock(placePosition, wool) then
            return true
        end
    end

    local function isFallFatal(root, humanoid, ground)
        if not HealthCheck or not HealthCheck.Enabled then return true end
        if not ground then return true end

        local health = (lplr.Character and lplr.Character:GetAttribute('Health')) or humanoid.Health
        local fallBlocks = math.max(0, ((fallAnchorY or root.Position.Y) - ground.Position.Y) / 3)
        local estimatedDamage = math.max(0, fallBlocks - 6) * 5
        return estimatedDamage >= health
    end

    local function abilityClutch(item, ability, callback)
        if not item then return end
        local oldTool = store.hand
        local hotbar = getHotbar(item.tool)
        switchItem(item.tool, 0.1)
        if hotbar then hotbarSwitch(hotbar) end
        task.wait(0.05)
        callback(item, ability)
        restoreTool(oldTool)
        return true
    end

    local function useToolAbility(ability, data)
        local success, result = pcall(function()
            return bedwars.AbilityController:useAbility(ability, newproxy(true), data)
        end)
        if success and result ~= false then return true end

        success, result = pcall(function()
            return bedwars.AbilityController:useAbility(ability, data)
        end)
        if success and result ~= false then return true end

        pcall(function()
            bedwars.Client:Get(remotes.UseAbility).instance:FireServer(ability, data)
        end)
        return true
    end

    local function jadeClutch(root)
        local item
        for _, hammer in jadeHammerNames do
            item = getItem(hammer)
            if item then break end
        end
        if not item then return end
        local ability = item.itemType..'_jump'
        if bedwars.AbilityController:canUseAbility(ability) then
            return abilityClutch(item, ability, function(_, abilityId)
                useToolAbility(abilityId, {direction = Vector3.yAxis, origin = root.Position})
                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(root.AssemblyLinearVelocity.Y, -3), root.AssemblyLinearVelocity.Z)
            end)
        end
    end

    local function voidClutch(root)
        local item = getItem('void_axe')
        if not item then return end
        local ability = item.itemType..'_jump'
        if bedwars.AbilityController:canUseAbility(ability) then
            return abilityClutch(item, ability, function(_, abilityId)
                useToolAbility(abilityId, {direction = Vector3.yAxis, origin = root.Position})
                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(root.AssemblyLinearVelocity.Y, -3), root.AssemblyLinearVelocity.Z)
            end)
        end
    end

    local function daoClutch(root)
        for _, itemName in daoItems do
            local item = getItem(itemName)
            if item and (lplr.Character:GetAttribute('CanDashNext') or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility('dash') then
                return abilityClutch(item, 'dash', function(dao)
                    bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
                    replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'].useAbility:FireServer('dash', {
                        direction = Vector3.new(root.CFrame.LookVector.X, -0.05, root.CFrame.LookVector.Z).Unit,
                        origin = root.Position,
                        weapon = dao.itemType
                    })
                    root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(root.AssemblyLinearVelocity.Y, -3), root.AssemblyLinearVelocity.Z)
                end)
            end
        end
    end

    local function toolClutch(root)
        if DaoClutch and DaoClutch.Enabled and daoClutch(root) then return true end
        if JadeHammerClutch and JadeHammerClutch.Enabled and jadeClutch(root) then return true end
        if VoidAxeClutch and VoidAxeClutch.Enabled and voidClutch(root) then return true end
    end

    local function shouldToolClutch(root, humanoid, groundDistance)
        if not groundDistance or groundDistance == math.huge then return false end
        local verticalSpeed = math.abs(root.AssemblyLinearVelocity.Y)
        if verticalSpeed <= 0 then return false end

        local bodyClearance = (humanoid.HipHeight or 2) + (root.Size.Y * 0.5)
        local remainingDistance = math.max(0, groundDistance - bodyClearance)
        return remainingDistance <= 4.5 or (remainingDistance / verticalSpeed) <= 0.16
    end

    local function telepearlClutch(root, ground, groundDistance)
        if usedPearl or not TelepearlClutch or not TelepearlClutch.Enabled then return end
        local pearl = getItem('telepearl')
        return pearl and ground and firePearl(root, ground.Position + Vector3.new(0, 3, 0), pearl)
    end

    local function legitClutch(root, humanoid, ground)
        local now = tick()
        if now < clutchBusyUntil or now - lastLegitUse < 0.06 then return end
        if humanoid.FloorMaterial ~= Enum.Material.Air or root.AssemblyLinearVelocity.Y >= 0 then
            fallAnchorY = root.Position.Y
            return
        end

        local groundDistance = ground and (root.Position.Y - ground.Position.Y) or math.huge
        fallAnchorY = fallAnchorY or root.Position.Y
        lastLegitUse = now

        if not isFallFatal(root, humanoid, ground) then return end

        if BlockClutch and BlockClutch.Enabled and groundDistance > 21 and (fallAnchorY - root.Position.Y) >= 15 then
            if blockClutch(root) then
                clutchBusyUntil = tick() + 0.08
                return true
            end
        end

        if root.AssemblyLinearVelocity.Y > -(MinVelocity and MinVelocity.Value or 60) then return end

        if TelepearlClutch and TelepearlClutch.Enabled and telepearlClutch(root, ground, groundDistance) then
            clutchBusyUntil = tick() + 0.65
            return true
        end

        if ground and shouldToolClutch(root, humanoid, groundDistance) and toolClutch(root) then
            clutchBusyUntil = tick() + 0.65
            return true
        end
    end

    -- Best-effort Zephyr kit detection. This is never a hard requirement: it
    -- returns true/false when the kit can be read and nil when it cannot, so
    -- callers can treat "unknown" as "go ahead anyway" and never break.
    local function hasZephyrKit()
        local success, result = pcall(function()
            local kit = store.equippedKit
            if kit == nil or kit == '' then
                kit = lplr:GetAttribute('PlayingAsKit')
            end
            if kit == nil then return nil end
            -- The Zephyr kit is internally named "WindWalker" (bedwars.WindWalkerController),
            -- so matching only the string 'zephyr' failed for everyone actually using the kit
            -- and made this clutch never fire. Accept both names.
            local name = string.lower(tostring(kit))
            return name:find('zephyr') ~= nil or name:find('wind') ~= nil
        end)
        if not success then return nil end
        return result
    end

    local zephyrFired = false
    local function zephyrClutch(root, humanoid, ground)
        local now = tick()
        if humanoid.FloorMaterial ~= Enum.Material.Air or root.AssemblyLinearVelocity.Y >= 0 then
            fallAnchorY = root.Position.Y
            zephyrFired = false
            return
        end

        fallAnchorY = fallAnchorY or root.Position.Y
        -- Fire at most once per fall; retriggering while the Jump flag is still
        -- latched is what caused the extra, unwanted hops after landing.
        if zephyrFired or now - lastZephyrJump < 0.3 then return end
        if not ground or not isFallFatal(root, humanoid, ground) then return end

        -- Detection is a soft gate only: skip the jump when we positively know
        -- the wrong kit is equipped, but proceed on failure or an unknown kit.
        if hasZephyrKit() == false then return end

        local groundDistance = root.Position.Y - ground.Position.Y
        local bodyClearance = (humanoid.HipHeight or 2) + (root.Size.Y * 0.5)
        local remainingDistance = math.max(0, groundDistance - bodyClearance)
        local verticalSpeed = math.abs(root.AssemblyLinearVelocity.Y)

        -- Short falls never deal damage in BedWars (~6 blocks of grace), so a
        -- jump there is pure noise even though isFallFatal passes with the
        -- health check disabled. Require a fall that can actually hurt.
        local totalFall = math.max(fallAnchorY - root.Position.Y, 0) + remainingDistance
        if totalFall < 20 then return end

        -- Jump the instant before ground contact so the fall resets on landing.
        if remainingDistance <= 3.5 or (verticalSpeed > 0 and (remainingDistance / verticalSpeed) <= 0.09) then
            lastZephyrJump = now
            zephyrFired = true
            pcall(function()
                humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                humanoid.Jump = true
            end)
            -- Release the latched Jump flag so the humanoid does not queue a
            -- second, unwanted jump for the frame after it lands.
            task.delay(0.2, function()
                pcall(function()
                    if humanoid.Parent then
                        humanoid.Jump = false
                    end
                end)
            end)
            return true
        end
    end

    local function anchorClutch(root)
        local attempts = AnchorAttempts and AnchorAttempts.Value or 5
        if tick() - lastAnchor < (1 / math.max(attempts, 1)) then return end
        lastAnchor = tick()
        root.AssemblyLinearVelocity = Vector3.zero
        root.Velocity = Vector3.zero
    end

    -- Blatant. Nothing physical happens here at all: the character falls at full speed, lands
    -- where and when it would have, and no velocity, position or humanoid state is ever touched.
    -- The only thing that changes is what the server has on its books for the fall.
    --
    -- BedWars settles fall damage off the ground-hit event the client sends it. While descending,
    -- replay the same GroundHit payload used by the game exploit so the fall is continuously
    -- settled and cleared before the real landing arrives.
    --
    -- The cadence is the mechanism, not a detail. One packet and then silence leaves the fall
    -- free to build straight back up before touchdown, which is why this is deliberately NOT
    -- rate limited - it fires on every pass of the module's poll for as long as the fall is
    -- dangerous, so at the moment of landing the server has at most one tick of drop recorded.
    -- An earlier build here rate limited it to one send every 120ms and that is precisely the
    -- kind of "tidying" that stops it working.
    --
    -- Every physical variant of this has now been tried and none of them hold: cancelling the
    -- registered velocity, bleeding the impact off in the last frames, capping the fall speed
    -- and giving the distance back. They all lose the same race against the landing frame, or
    -- lean on a field the game does not have. This one does not race anything - it is simply
    -- keeping the server's record of the fall empty the whole way down.
    local groundHit
    local groundHitBlock

    local function resolveGroundHit()
        if groundHit and groundHitBlock then return groundHit end
        local success, remote, block = pcall(function()
            local managed = replicatedStorage.rbxts_include.node_modules['@rbxts'].net.out._NetManaged
            return managed.GroundHit, workspace.Map.Worlds.tr_Range.Blocks:GetChildren()[222]
        end)
        groundHit = success and remote or nil
        groundHitBlock = success and block or nil
        return groundHit
    end
    task.spawn(resolveGroundHit)

	clearRegisteredFall = function()
        local remote = resolveGroundHit()
        if not remote or not groundHitBlock then return false end
		local success = pcall(function()
			remote:FireServer(
                groundHitBlock,
                Vector3.new(-10.598394393921, -35.038021087646, -16.960966110229),
                1785564031.154
            )
        end)
        return success
    end

    -- RakNet mode. The only one that works underneath the game entirely: it edits the physics
    -- packet on its way out of the client.
    --
    -- What a fall was worth is decided from what you replicate while you are in the air, and the
    -- humanoid state rides along in the standard 0x1b physics packet - the same packet and the
    -- same offset StateSpoofer writes to. So for as long as a dangerous fall is in progress this
    -- rewrites that one byte to a grounded state: the server is told about someone running, never
    -- about someone falling, and a fall that was never reported has nothing to settle on landing.
    --
    -- Nothing local changes. Not velocity, not position, not the state your own client is using -
    -- the fall looks and feels exactly as it always did on your screen, and the only difference
    -- is what leaves the machine.
    --
    -- A send hook runs on the network thread, where one error disconnects you, so there are two
    -- hard rules here: everything is inside a pcall with an explicit length check, and while the
    -- fall is not dangerous the hook returns immediately without touching the packet, so ordinary
    -- movement replicates byte for byte the way it normally would.
    local rakHook, spoofFall = nil, false

    local function addRakHook()
        if rakHook then return end
        rakHook = function(packet)
            if not spoofFall then return end
            pcall(function()
                local data = packet.AsBuffer
                local packetId = packet.AsArray and packet.AsArray[1]
                if not packetId and data and buffer.len(data) > 0 then
                    packetId = buffer.readu8(data, 0)
                end
                if packetId == 0x1b then
                    local state = SpoofState and Enum.HumanoidStateType[SpoofState.Value]
                    if data and state and buffer.len(data) >= 26 then
                        buffer.writeu8(data, 25, state.Value + 32)
                        packet:SetData(data)
                    end
                end
            end)
        end
        pcall(raknet.add_send_hook, rakHook)
    end

    local function removeRakHook()
        spoofFall = false
        if not rakHook then return end
        pcall(raknet.remove_send_hook, rakHook)
        rakHook = nil
    end

	local function setSettingsVisible()
		local legit = Mode and Mode.Value == 'Legit'
		if AnchorAttempts and AnchorAttempts.Object then AnchorAttempts.Object.Visible = false end
		for _, option in {BlockClutch, TelepearlClutch, DaoClutch, JadeHammerClutch, VoidAxeClutch, Zephyr} do
            if option and option.Object then
                option.Object.Visible = legit
            end
        end
		if MinVelocity and MinVelocity.Object then
			MinVelocity.Object.Visible = false
		end
		if FallThreshold and FallThreshold.Object then
			FallThreshold.Object.Visible = false
		end
		if SpoofState and SpoofState.Object then
			SpoofState.Object.Visible = false
		end
		if GroundDistance and GroundDistance.Object then
			GroundDistance.Object.Visible = legit
		end
	end

	NoFall = vape.Categories.Blatant:CreateModule({
		Name = 'NoFallDamage',
		Function = function(callback)
			if callback then
				-- Exact cv Blatant path.  Legit keeps the Aether clutch loop below;
				-- this path deliberately owns its own previous-frame velocity.
				if entitylib.isAlive and getconnections then
					for _, connection in getconnections(entitylib.character.Humanoid.StateChanged) do
						connection:Disable()
					end
				end
				local blatantTracked = 0
				local groundHit = bedwars.Handler:Get('GroundHit')
				NoFall:Clean(runService.PostSimulation:Connect(function()
					if Mode.Value == 'Blatant' and entitylib.isAlive and store.matchState == 1 and not store.infinitefly then
						local root = entitylib.character.RootPart
						local velocity = root.Velocity
						if blatantTracked < -45 then
							root.Velocity = Vector3.new(0, 2.5, 0)
							entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Landed)
							runService.PreRender:Wait()
							root.Velocity = velocity
							groundHit:Fire('SendToServer', nil, Vector3.new(0, blatantTracked, 0), workspace:GetServerTimeNow())
						end
						blatantTracked = velocity.Y
					end
				end))

				NoFall:Clean(entitylib.Events.LocalAdded:Connect(function(ent)
					local animator = ent.Humanoid:WaitForChild('Animator', 5)
					if animator and NoFall.Enabled then
						task.wait(0.5)
						NoFall:Toggle()
						NoFall:Toggle()
					end
				end))

				repeat
					local waitDelay = 0.1
					local character, root, humanoid = validCharacter()
                    if not character then
                        -- No character to read: never leave the packet hook rewriting state for
                        -- a fall that is no longer happening.
                        spoofFall = false
                    end
                    if character then
                        local fall = updateTrackedFall(root, humanoid)
						if humanoid.FloorMaterial ~= Enum.Material.Air then
                            usedPearl = false
                        elseif Mode.Value == 'Legit' then
                            local ground = getGround(root, character, HealthCheck and HealthCheck.Enabled and 300 or (GroundDistance and GroundDistance.Value or 30))
                            -- Zephyr is now a Legit sub-toggle: if it's on, try the
                            -- jump-before-landing negate first; only fall back to the
                            -- block/pearl/tool clutch order when it didn't fire.
                            local zephyred = false
                            if Zephyr and Zephyr.Enabled then
                                zephyred = zephyrClutch(root, humanoid, ground)
                                if zephyred then
                                    waitDelay = 0.05
                                end
                            end
                            if not zephyred then
                                legitClutch(root, humanoid, ground)
                            end
						end
                    end
                    task.wait(waitDelay)
                until not NoFall.Enabled
            else
                usedPearl = false
                lastAnchor = 0
                lastLegitUse = 0
                clutchBusyUntil = 0
                lastBlockPlace = 0
                lastZephyrJump = 0
                zephyrFired = false
                fallAnchorY = nil
                trackedFall = 0
                removeRakHook()
            end
        end,
		Tooltip = 'Prevents taking fall damage.\nBlatant uses idk\'s landed-state method; Legit keeps Aether\'s clutch logic'
	})
	Mode = NoFall:CreateDropdown({
		Name = 'Mode',
		List = {'Blatant', 'Legit'},
        Function = function()
            setSettingsVisible()
            if NoFall.Enabled then
                NoFall:Toggle()
                NoFall:Toggle()
            end
        end,
		Tooltip = 'Blatant - uses idk\'s landed-state method\nLegit - clutches with blocks, telepearls, or tools'
    })
    MinVelocity = NoFall:CreateSlider({
        Name = 'Minimum Velocity',
        Min = 35,
        Max = 120,
        Default = 60,
        Tooltip = 'How fast the drop has to be before Legit clutches or TP floors you. Blatant ignores it'
    })
    FallThreshold = NoFall:CreateSlider({
        Name = 'Fall threshold',
        Min = 40,
        Max = 120,
        Default = 85,
        Suffix = ' studs/s',
        Visible = false,
        Tooltip = 'RakNet: how fast the fall must get before packet spoofing starts. Blatant always sends it'
    })
    SpoofState = NoFall:CreateDropdown({
        Name = 'Reported state',
        List = {'Running', 'Landed', 'RunningNoPhysics'},
        Visible = false,
        Tooltip = 'RakNet only: the humanoid state sent during a dangerous fall. Running is safest, try Landed if it fails'
    })
    GroundDistance = NoFall:CreateSlider({
        Name = 'Ground Check',
        Min = 8,
        Max = 80,
        Default = 30
    })
    AnchorAttempts = NoFall:CreateSlider({
        Name = 'Attempts per second',
        Min = 1,
        Max = 12,
        Default = 5,
        Visible = false
    })
    BlockClutch = NoFall:CreateToggle({
        Name = 'Blocks',
        Default = true,
        Tooltip = 'Places blocks directly beneath you shortly before fall damage would apply'
    })
    HealthCheck = NoFall:CreateToggle({
        Name = 'Health check',
        Tooltip = 'Only clutches when the estimated fall damage would be lethal'
    })
    Zephyr = NoFall:CreateToggle({
        Name = 'Zephyr',
        Tooltip = 'Legit only: jumps just before landing so a Zephyr/WindWalker kit negates the fall'
    })
    TelepearlClutch = NoFall:CreateToggle({
        Name = 'Telepearl',
        Default = true,
        Tooltip = 'Throws a telepearl to nearby safe ground after block clutching is unavailable'
    })
    DaoClutch = NoFall:CreateToggle({
        Name = 'Dao',
        Default = true
    })
    JadeHammerClutch = NoFall:CreateToggle({
        Name = 'Jade Hammer',
        Default = true
    })
    VoidAxeClutch = NoFall:CreateToggle({
        Name = 'Void Axe',
        Default = true
    })

    setSettingsVisible()
end)

run(function()
    local AntiDeath
    local Targets
    local Melee
    local Projectiles
    local ProjectileStretch
    local Range

    -- oldchar is the character the parked root was taken OUT of. Reverting is only ever valid back
    -- into that same character: respawn while the root is parked and lplr.Character is a brand new
    -- model, and grafting the old root into it leaves the body being driven by a part nothing is
    -- welded to - which renders locally as a character frozen on the spot while you carry on moving
    -- normally everywhere else. See revertClone.
    local oldroot, oldchar, clone, hip = nil, nil, nil, 2.5
    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Include
    rayParams.RespectCanCollide = true

    local function doClone()
        if store.rootpart then return end
        if entitylib.isAlive and entitylib.character.Humanoid.Health > 0 then
            if oldroot and oldroot.Parent then
                return true
            end

            hip = entitylib.character.Humanoid.HipHeight
            oldroot = entitylib.character.HumanoidRootPart
            if not lplr.Character.Parent then return false end
            oldchar = lplr.Character
            lplr.Character.Parent = replicatedStorage
            clone = oldroot:Clone()
            clone.Parent = lplr.Character
            oldroot.Transparency = 1
            oldroot.Parent = workspace
            store.rootpart = oldroot
            lplr.Character.PrimaryPart = clone
            lplr.Character.Parent = workspace
            bedwars.QueryUtil:setQueryIgnored(clone, true)
            bedwars.QueryUtil:setQueryIgnored(oldroot, true)
            return true
        end
        return false
    end

    -- Nothing to give the root back to (died or respawned while it was parked). Bin the parts
    -- rather than leaving a stray root in workspace or a clone inside a dead character.
    local function dropClone()
        if oldroot then
            pcall(function() if oldroot.Parent == workspace then oldroot:Destroy() end end)
        end
        if clone then
            pcall(function() clone:Destroy() end)
        end
        if store.rootpart == oldroot then
            store.rootpart = nil
        end
        oldroot, oldchar, clone = nil, nil, nil
    end

    local projectileCache, projectileHistory = {}, {}

    -- BedWars projectiles replicate as Models parented directly to workspace, with the
    -- 'ProjectileShooter' attribute set on the model. Resolve the moving BasePart from either form.
    local function projectilePart(obj)
        return obj:IsA('BasePart') and obj or obj.PrimaryPart
    end

    local function isProjectile(obj)
        local shooter = obj:GetAttribute('ProjectileShooter')
        if shooter == nil or shooter == lplr.UserId then return false end
        return projectilePart(obj) ~= nil
    end

    -- Newly spawned projectiles often report a zero AssemblyLinearVelocity for a
    -- frame or two (they are server-simulated), which used to blind detection long
    -- enough to make the dodge fire late. We keep the last good velocity and fall
    -- back to a time-guarded finite difference so the estimate is stable from the
    -- first frame a projectile is in range.
    local function getProjectileVelocity(obj, part)
        local now = os.clock()
        local history = projectileHistory[obj]
        local assembly = part.AssemblyLinearVelocity
        local velocity
        if assembly.Magnitude > 1 then
            velocity = assembly
        elseif history and (now - history.Time) > 1e-4 then
            velocity = (part.Position - history.Position) / (now - history.Time)
        end
        if (not velocity or velocity.Magnitude <= 2) and history and history.Velocity then
            velocity = history.Velocity
        end
        velocity = velocity or Vector3.zero
        projectileHistory[obj] = {Position = part.Position, Time = now, Velocity = velocity.Magnitude > 2 and velocity or (history and history.Velocity)}
        return velocity
    end

    -- Returns the single soonest-to-hit threat (not merely the first found), so
    -- that when several projectiles are inbound we dodge the one about to land
    -- instead of an arbitrary one further away.
    --
    -- The closest-approach is evaluated along the projectile's *gravity-aware* arc
    -- rather than a straight line. A straight-line estimate reports a huge miss for
    -- an arcing arrow until it is almost on top of you, which is what made the dodge
    -- fire a frame or two after the hit already registered. Sampling the real
    -- parabola lets us see the threat while there is still time to move.
    -- Ballistic helpers ported from cv.lua's "Arrow Dodge" (AnticheatBypass).
    local function LaunchAngle(v, g, d, h, higherArc)
        local root = v * v * v * v - g * (g * d * d + 2 * h * v * v)
        if root < 0 then return nil end
        root = math.sqrt(root)
        local angle = higherArc and (v * v + root) or (v * v - root)
        return math.atan2(angle, g * d)
    end

    local function LaunchDirection(startPos, target, v, g, higherArc)
        local horizontal = Vector3.new(target.X - startPos.X, 0, target.Z - startPos.Z)
        local d = horizontal.Magnitude
        if d < 0.01 then return nil end
        local a = LaunchAngle(v, g, d, target.Y - startPos.Y, higherArc)
        if a == nil or a ~= a then return nil end
        local vec = horizontal.Unit * v
        local rotAxis = Vector3.new(-horizontal.Z, 0, horizontal.X)
        return CFrame.fromAxisAngle(rotAxis, a) * vec
    end

    local function FindLeadShot(targetPosition, targetVelocity, projectileSpeed, shooterPosition, shooterVelocity, gravity)
        local distance = (targetPosition - shooterPosition).Magnitude
        local vrel = targetVelocity - shooterVelocity
        local timeTaken = distance / projectileSpeed
        if gravity > 0 then
            timeTaken = projectileSpeed / gravity + math.sqrt(2 * distance / gravity + projectileSpeed ^ 2 / gravity ^ 2)
        end
        return Vector3.new(
            targetPosition.X + vrel.X * timeTaken,
            targetPosition.Y + vrel.Y * timeTaken,
            targetPosition.Z + vrel.Z * timeTaken
        )
    end

    -- Projectile detection replaced with Arrow Dodge logic: a projectile counts as a threat
    -- when its actual velocity matches the velocity that would be required to hit us from its
    -- position (i.e. it is genuinely aimed at us), rather than the old closest-approach arc
    -- heuristic. Returns the same {Object, Part, TimeToHit, Velocity} shape the dodge relies on.
    local function incomingProjectile(root)
        local best, bestTime = false, math.huge
        local rootPos = root.Position
        local aimPos = rootPos + Vector3.new(0, 0.8, 0)
        local range = math.max(Range.Value, 70)
        for obj in projectileCache do
            local part = obj.Parent and projectilePart(obj)
            if not part then
                projectileCache[obj] = nil
                projectileHistory[obj] = nil
                continue
            end
            local origin = part.Position
            local dist = (origin - rootPos).Magnitude
            if dist <= range then
                local velocity = getProjectileVelocity(obj, part)
                local speed = velocity.Magnitude
                if speed > 2 and velocity:Dot((rootPos - origin).Unit) > 0 then
                    local meta = bedwars.ProjectileMeta[obj.Name]
                    local grav = meta and meta.gravitationalAcceleration or workspace.Gravity
                    -- Velocity the projectile would need to land on us from where it is now.
                    local lead = FindLeadShot(aimPos, Vector3.zero, speed, origin, Vector3.zero, grav)
                    local arc = LaunchDirection(origin, aimPos, speed, grav, false)
                    local flat = (lead - origin)
                    if flat.Magnitude > 0 then
                        flat = flat.Unit * speed
                        local requiredVelo = Vector3.new(flat.X, arc and arc.Y or flat.Y, flat.Z)
                        if requiredVelo.Magnitude > 0 then
                            requiredVelo = requiredVelo.Unit * speed
                            -- Within Arrow Dodge's 20-stud tolerance -> it is aimed at us.
                            if (requiredVelo - velocity).Magnitude <= 20 then
                                local timeToHit = dist / speed
                                if timeToHit < bestTime then
                                    best = {Object = obj, Part = part, TimeToHit = timeToHit, Velocity = velocity}
                                    bestTime = timeToHit
                                end
                            end
                        end
                    end
                end
            end
        end
        return best
    end

    -- Note: during a dodge the character's real RootPart is parked below the
    -- map, so callers must pass the *visible* body (the clone) here - measuring
    -- against the hidden root made this test see every falling projectile as
    -- "still approaching" and hold the dodge for the full timeout.
    local function hasProjectilePassed(threat, body)
        local obj = threat and threat.Object
        local part = threat and threat.Part
        if not obj or not part or not part.Parent or not body then return true end
        local velocity = getProjectileVelocity(obj, part)
        if velocity.Magnitude <= 2 then return true end
        local toLocal = body.Position - part.Position
        return velocity:Dot(toLocal) <= 0 or toLocal.Magnitude > math.max(Range.Value, 70)
    end

    local function revertClone()
        if not oldroot then return false end
        -- Only ever back into the character it came out of. A respawn during the dodge replaces
        -- lplr.Character wholesale; putting a stale root into the new one - and making it the
        -- PrimaryPart - is what leaves your body rendered frozen in place client-side while you
        -- keep moving around normally.
        if oldchar ~= lplr.Character or not oldchar or not oldchar.Parent or not oldroot.Parent or not entitylib.isAlive then
            dropClone()
            return false
        end
        lplr.Character.Parent = replicatedStorage
        oldroot.Parent = lplr.Character
        if clone then
            oldroot.CFrame = clone.CFrame
            oldroot.Velocity = clone.Velocity
            clone:Destroy()
            clone = nil
        end
        lplr.Character.PrimaryPart = oldroot
        lplr.Character.Parent = workspace
        oldroot.CanCollide = true
        entitylib.character.Humanoid.HipHeight = hip or 2.6
        oldroot.Transparency = 1
        oldroot, oldchar = nil, nil
        store.rootpart = nil
        return true
    end

    AntiDeath = vape.Categories.Blatant:CreateModule({
	Name = 'AntiDeath',
	Tooltip = 'Dodges melee and projectiles "blatantly"',
	Function = function(call)
		if call then
			repeat
				task.wait()
			until store.matchState ~= 0 and store.map or not AntiDeath.Enabled
			if not AntiDeath.Enabled then
				return
			end

			table.clear(projectileCache)
			table.clear(projectileHistory)
			for _, obj in workspace:GetChildren() do
				if isProjectile(obj) then projectileCache[obj] = true end
			end
			AntiDeath:Clean(workspace.ChildAdded:Connect(function(obj)
				task.delay(0, function()
					if obj.Parent and isProjectile(obj) then projectileCache[obj] = true end
				end)
			end))

			rayParams.FilterDescendantsInstances = {store.map}
			local lowestpoint = 9e9
			local Dodge = false
			for _, v in store.blocks do
				local point = (v.Position.Y - (v.Size.Y / 2)) - 50
				if point < lowestpoint then
					lowestpoint = point
				end
			end

                AntiDeath:Clean(runService.PostSimulation:Connect(function()
                    if oldroot and oldroot.Parent then
                        local newpoint, pos = lowestpoint, CFrame.new(clone.CFrame.X, lowestpoint - 6, clone.CFrame.Z)
                        if Dodge then
                            newpoint = workspace:Raycast(pos.Position, Vector3.new(0, 1000, 0), rayParams)
                            if newpoint then
                                newpoint = CFrame.new(clone.CFrame.X, newpoint.Position.Y - 6, clone.CFrame.Z) * CFrame.Angles(math.rad(90), 0, 0)
                            end
                        end
                        oldroot.Velocity = Vector3.zero
                        oldroot.CFrame = Dodge and (newpoint or pos) or (clone.CFrame + Vector3.new(0, 1, 0)) * CFrame.Angles(math.rad(90), 0, 0)
                    end
                end))

                local last = true
                repeat
                    if entitylib.isAlive then
                        if oldroot then
                            local ownership = isnetworkowner(oldroot)
                            if not ownership and ownership ~= last then
                                notif('AntiDeath', 'Network ownership disowned', 7, 'alert')
                            end
                            last = ownership
                            if not ownership then
                                Dodge = false
                                revertClone()
                                task.wait()
                                continue
                            end
                        end

                        local projectileThreat = Projectiles.Enabled and incomingProjectile(entitylib.character.RootPart)
                        -- Fire earlier than the raw stretch window to cover reaction latency plus the
                        -- full network round-trip: the hitbox move has to replicate to the server before
                        -- it counts, so dodging only half a ping early still landed a touch late on fast
                        -- projectiles. Moving the hidden hitbox away early is harmless, so we bias early.
                        -- The hidden hitbox move has to replicate a full round trip to the
                        -- server before the projectile's hit is resolved there, so half a ping
                        -- of lead was not enough on fast arrows - the dodge played but the hit
                        -- still registered. Bias earlier by a fuller round trip (moving the
                        -- hidden hitbox early is harmless).
                        local reactionBuffer = math.min(lplr:GetNetworkPing() * 1.6 + 0.1, 0.6)
                        if projectileThreat and projectileThreat.TimeToHit > ProjectileStretch.Value + reactionBuffer then
                            projectileThreat = nil
                        end
                        local root = entitylib.character.RootPart
                        local grounded = root and workspace:Raycast(root.Position, Vector3.new(0, -(entitylib.character.HipHeight + 4), 0), store.blockRaycast)
                        local meleeThreat = Melee.Enabled and grounded and math.abs(root.AssemblyLinearVelocity.Y) < 35 and entitylib.EntityPosition({
                            Range = Range.Value,
                            Players = Targets.Players.Enabled,
                            NPCs = Targets.NPCs.Enabled,
                            Wallcheck = Targets.Walls.Enabled or nil,
                            Sort = sortmethods.Distance,
                            Part = 'RootPart',
                        })
                        if (projectileThreat or meleeThreat) and doClone() then
                            if projectileThreat then
                                Dodge = true
                                local started = tick()
                                repeat
                                    task.wait()
                                until hasProjectilePassed(projectileThreat, clone or entitylib.character.RootPart) or tick() - started > 1.35 or not AntiDeath.Enabled
                            else
                                Dodge = false
                                task.wait(0.2)
                                local root = entitylib.character.RootPart
                                local grounded = root and workspace:Raycast(root.Position, Vector3.new(0, -(entitylib.character.HipHeight + 4), 0), store.blockRaycast)
                                Dodge = grounded and math.abs(root.AssemblyLinearVelocity.Y) < 35
                                task.wait(0.4)
                            end
                        else
                            Dodge = false
                            revertClone()
                        end
                    elseif oldroot then
                        -- Died with the hitbox parked. Nothing to hand it back to, so bin it here
                        -- rather than leaving it to be inherited by the character we respawn into.
                        Dodge = false
                        dropClone()
                    end
                    task.wait()
                until not AntiDeath.Enabled
		else
			revertClone()
		end
	end,
    })

    Targets = AntiDeath:CreateTargets({
	Players = true,
	NPCs = false,
    })
    Melee = AntiDeath:CreateToggle({
	Name = 'Melee',
	Tooltip = 'Dodges melee attacks',
	Default = true,
	Function = function(call)
		pcall(function()
			Range.Object.Visible = call
		end)
	end,
    })
    Range = AntiDeath:CreateSlider({
	Name = 'Melee Range',
	Min = 1,
	Max = 30,
	Default = 30,
	Decimal = 5,
	Darker = true,
    })
    Projectiles = AntiDeath:CreateToggle({
	Name = 'Projectiles',
	Tooltip = 'Triggers AntiDeath when an incoming projectile is detected',
	Default = true,
	Function = function(call)
		pcall(function()
			ProjectileStretch.Object.Visible = call
		end)
	end,
    })
    ProjectileStretch = AntiDeath:CreateSlider({
	Name = 'Projectile Stretch Time',
	Tooltip = 'How soon before impact projectile dodging can trigger',
	Min = 0.05,
	Max = 1.5,
	Default = 0.55,
	Decimal = 2,
	Darker = true,
    })
end)


run(function()
    local ChillLighting
