-- Water: fills the void with real Roblox water, at exactly the height AntiFall puts its barrier.
--
-- Height comes from AntiFall's own barrier when that module is on, and is worked out the same way
-- (lowest block on the map, minus two) when it is not - so the surface always sits where the
-- barrier does, whether or not you use it.
--
-- Terrain mode is genuine Roblox water: waves, refraction, the lot. It is written locally, so it is
-- yours alone and never replicates. It follows you in slabs and clears the one behind you, because
-- filling a whole BedWars map at once is a lot of voxels for something you only ever see under your
-- feet. Part mode is the cheap version - one plane with the water material and Roblox's own water
-- texture on top - for anywhere terrain writes are unavailable.
run(function()
    local Water
    local Mode
    local Size
    local Depth
    local Waves
    local Color
    local part
    local filled
    local oldWater
    local fx        -- underwater screen effects (ColorCorrection / Blur / SunRays), Realistic mode only
    local oldFog    -- saved Lighting fog, put back the moment you surface
    local submerged -- currently below the water surface

    local function barrierHeight()
        if AntiFallPart and AntiFallPart.Parent then
            return AntiFallPart.Position.Y
        end
        local mag = math.huge
        pcall(function()
            for _, pos in bedwars.BlockController:getStore():getAllBlockPositions() do
                pos = pos * 3
                if pos.Y < mag and not getPlacedBlock(pos + Vector3.new(0, 3, 0)) then
                    mag = pos.Y
                end
            end
        end)
        if mag == math.huge then return nil end
        return mag - 2
    end

    local function clearTerrain()
        if not filled then return end
        pcall(function()
            workspace.Terrain:FillBlock(filled.CFrame, filled.Size, Enum.Material.Air)
        end)
        filled = nil
    end

    local function applyWaterLook()
        local terrain = workspace.Terrain
        if not oldWater then
            oldWater = {
                Color = terrain.WaterColor,
                Transparency = terrain.WaterTransparency,
                Reflectance = terrain.WaterReflectance,
                WaveSize = terrain.WaterWaveSize,
                WaveSpeed = terrain.WaterWaveSpeed
            }
        end
        terrain.WaterColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
        terrain.WaterTransparency = math.clamp(1 - Color.Opacity, 0, 1)
        terrain.WaterWaveSize = Waves.Enabled and 0.15 or 0
        terrain.WaterWaveSpeed = Waves.Enabled and 12 or 0
    end

    local function restoreWaterLook()
        if not oldWater then return end
        local terrain = workspace.Terrain
        pcall(function()
            terrain.WaterColor = oldWater.Color
            terrain.WaterTransparency = oldWater.Transparency
            terrain.WaterReflectance = oldWater.Reflectance
            terrain.WaterWaveSize = oldWater.WaveSize
            terrain.WaterWaveSpeed = oldWater.WaveSpeed
        end)
        oldWater = nil
    end

    local function makePart(height)
        if part then
            part.Position = Vector3.new(0, height, 0)
            return
        end
        part = Instance.new('Part')
        part.Name = 'AetherWater'
        part.Size = Vector3.new(10000, Depth.Value, 10000)
        part.Position = Vector3.new(0, height, 0)
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.Material = Enum.Material.Water
        part.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
        part.Transparency = math.clamp(1 - Color.Opacity, 0, 1)
        part.Parent = workspace
        -- Roblox's own water surface texture on the top face, so Part mode reads as water rather
        -- than as a flat blue slab.
        local texture = Instance.new('Texture')
        texture.Name = 'WaterSurface'
        texture.Face = Enum.NormalId.Top
        texture.Texture = 'rbxasset://textures/water/normal_1.dds'
        texture.StudsPerTileU = 24
        texture.StudsPerTileV = 24
        texture.Transparency = 0.35
        texture.Parent = part
        pcall(function()
            bedwars.QueryUtil:setQueryIgnored(part, true)
        end)
    end

    local function removePart()
        if part then
            part:Destroy()
            part = nil
        end
    end

    ----------------------------------------------------------------------------
    -- Realistic mode. Terrain water, but glassy and reflective, and it comes alive only while you
    -- are actually in it: the look (fog, colour grade, god-rays, sway) and the buoyancy are applied
    -- when your eyes / body go under the surface and taken straight back off when you surface, so
    -- nothing here ever touches the world while you are stood on dry land.
    ----------------------------------------------------------------------------
    local FX_NAME = 'AetherWaterFX'

    local function applyRealisticLook()
        local terrain = workspace.Terrain
        if not oldWater then
            oldWater = {
                Color = terrain.WaterColor,
                Transparency = terrain.WaterTransparency,
                Reflectance = terrain.WaterReflectance,
                WaveSize = terrain.WaterWaveSize,
                WaveSpeed = terrain.WaterWaveSpeed
            }
        end
        terrain.WaterColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
        terrain.WaterTransparency = math.clamp(1 - Color.Opacity, 0, 1)
        -- Glassy: reflect the sky and world off the surface, with livelier waves than the flat look.
		terrain.WaterReflectance = Waves.Enabled and 0.18 or 0.08
		terrain.WaterWaveSize = Waves.Enabled and 0.09 or 0.025
		terrain.WaterWaveSpeed = Waves.Enabled and 7 or 2
    end

    local function ensureFX()
        if fx then return end
        fx = {}
        local cc = Instance.new('ColorCorrectionEffect')
        cc.Name = FX_NAME
        cc.Enabled = false
        cc.Parent = lightingService
        fx.cc = cc
        local blur = Instance.new('BlurEffect')
        blur.Name = FX_NAME..'Blur'
        blur.Enabled = false
        blur.Size = 0
        blur.Parent = lightingService
        fx.blur = blur
        local rays = Instance.new('SunRaysEffect')
        rays.Name = FX_NAME..'Rays'
        rays.Enabled = false
        rays.Parent = lightingService
        fx.rays = rays
    end

    local function restoreFog()
        if not oldFog then return end
        pcall(function()
            lightingService.FogStart = oldFog.Start
            lightingService.FogEnd = oldFog.End
            lightingService.FogColor = oldFog.Color
        end)
        oldFog = nil
    end

    -- Came back up (or left Realistic mode): switch the look off and hand the fog back, but keep the
    -- effect instances around so diving straight back in does not churn them.
    local function surfaced()
        if not submerged then return end
        submerged = false
        restoreFog()
        if fx then
            pcall(function()
                fx.cc.Enabled = false
                fx.blur.Enabled = false
                fx.rays.Enabled = false
            end)
        end
    end

    local function removeFX()
        surfaced()
        if fx then
            for _, effect in fx do
                pcall(function() effect:Destroy() end)
            end
            fx = nil
        end
    end

    -- Called every frame while Realistic is on. surface is the top of the water slab.
    local function updateRealistic(surface)
        ensureFX()
        local cam = gameCamera
        local under = cam and cam.CFrame.Position.Y < surface

        if under then
            if not submerged then
                submerged = true
                if not oldFog then
                    oldFog = {Start = lightingService.FogStart, End = lightingService.FogEnd, Color = lightingService.FogColor}
                end
            end
            local col = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
            local sway = 0.5 + 0.5 * math.sin(tick() * 1.4)
            -- Fog closes in the deeper/less clear the water is, so it reads as real water rather
            -- than a blue filter.
            lightingService.FogColor = col
            lightingService.FogStart = 0
            lightingService.FogEnd = 55 + Color.Opacity * 55 + sway * 6
            fx.cc.Enabled = true
            fx.cc.TintColor = col:Lerp(Color3.new(1, 1, 1), 0.05 + 0.04 * sway)
            fx.cc.Brightness = -0.04
            fx.cc.Contrast = 0.12
            fx.cc.Saturation = -0.08
			-- Blur and animated sun rays made this mode both muddy-looking and one
			-- of the most expensive visual modules. Colour/fog provide depth without
			-- adding full-screen render passes.
			fx.blur.Enabled = false
			fx.rays.Enabled = false
        else
            surfaced()
        end

        -- Buoyancy: while your body is under the surface, water drags your speed and floats you back
        -- up, so falling into it feels like water instead of air.
        if entitylib.isAlive then
            local root = entitylib.character.RootPart
            if root and isnetworkowner(root) and root.Position.Y < surface then
                local vel = root.AssemblyLinearVelocity
                local lift = math.clamp(vel.Y * 0.6 + 6, -8, 10)
                root.AssemblyLinearVelocity = Vector3.new(vel.X * 0.85, lift, vel.Z * 0.85)
            end
        end
    end

    local function refresh()
        local height = barrierHeight()
        if not height then return end

        if Mode.Value == 'Part' then
            clearTerrain()
            restoreWaterLook()
            makePart(height)
            part.Size = Vector3.new(10000, Depth.Value, 10000)
            part.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
            part.Transparency = math.clamp(1 - Color.Opacity, 0, 1)
            return
        end

        removePart()
        if Mode.Value == 'Realistic' then
            applyRealisticLook()
        else
            applyWaterLook()
        end

        local centre = Vector3.new(0, height, 0)
        if entitylib.isAlive then
            local root = entitylib.character.RootPart
            centre = Vector3.new(root.Position.X, height, root.Position.Z)
        end
        -- Voxels are 4 studs, so snap to that grid: an unsnapped fill leaves seams between slabs.
        centre = Vector3.new(math.floor(centre.X / 4) * 4, math.floor(centre.Y / 4) * 4, math.floor(centre.Z / 4) * 4)
        local size = Vector3.new(Size.Value, math.max(Depth.Value, 4), Size.Value)

        if filled and (filled.CFrame.Position - centre).Magnitude < (Size.Value * 0.25) and filled.Size == size then
            return
        end
        clearTerrain()
        local cframe = CFrame.new(centre)
        local ok = pcall(function()
            workspace.Terrain:FillBlock(cframe, size, Enum.Material.Water)
        end)
        if ok then
            filled = {CFrame = cframe, Size = size}
        else
            -- Terrain writes refused: fall back to the plane rather than showing nothing.
            makePart(height)
        end
    end

    Water = (vape.Categories.Visuals or vape.Categories.Render):CreateModule({
        Name = 'Water',
        Function = function(callback)
            if callback then
                repeat task.wait() until (store.matchState ~= 0 and store.map) or not Water.Enabled
                if not Water.Enabled then return end
                Water:Clean(function()
                    clearTerrain()
                    restoreWaterLook()
                    removePart()
                    removeFX()
                end)
                Water:Clean(task.spawn(function()
                    while Water.Enabled do
                        refresh()
                        task.wait(0.5)
                    end
                end))
                -- Realistic mode's look and buoyancy have to react the instant you break the surface,
                -- so they run every frame rather than on the half-second refresh. Idle for the other
                -- modes, and it reverts itself the frame you surface or switch mode away.
				local nextRealisticUpdate = 0
				Water:Clean(runService.Heartbeat:Connect(function()
					if not Water.Enabled or Mode.Value ~= 'Realistic' then
						surfaced()
						return
					end
					if tick() < nextRealisticUpdate then return end
					nextRealisticUpdate = tick() + 0.1
                    local height = barrierHeight()
                    if not height then return end
                    updateRealistic(height + math.max(Depth.Value, 4) / 2)
                end))
            else
                clearTerrain()
                restoreWaterLook()
                removePart()
                removeFX()
            end
        end,
        Tooltip = 'Fills the void with Roblox water at AntiFall\'s barrier height',
        ExtraText = function()
            return Mode.Value
        end
    })
    Mode = Water:CreateDropdown({
        Name = 'Mode',
        List = {'Terrain', 'Part', 'Realistic'},
        Default = 'Terrain',
        Tooltip = 'Terrain - real Roblox water\nPart - one cheap plane across the map\nRealistic - reflective water with underwater effects',
        Function = function()
            if Water.Enabled then
                clearTerrain()
                restoreWaterLook()
                removePart()
                removeFX()
                task.spawn(refresh)
            end
        end
    })
    Size = Water:CreateSlider({
        Name = 'Area',
        Min = 128,
        Max = 2048,
        Default = 768,
        Suffix = ' studs',
        Tooltip = 'How wide a patch of water to keep filled around you, in Terrain mode'
    })
    Depth = Water:CreateSlider({
        Name = 'Depth',
        Min = 4,
        Max = 60,
        Default = 12,
        Suffix = ' studs',
        Tooltip = 'How deep the water goes below the surface'
    })
    Waves = Water:CreateToggle({
        Name = 'Waves',
        Default = true,
        Tooltip = 'Animate the surface. Off gives you a still, flat sheet',
        Function = function()
            if Water.Enabled and Mode.Value == 'Terrain' then
                applyWaterLook()
            end
        end
    })
    Color = Water:CreateColorSlider({
        Name = 'Color',
        DefaultOpacity = 0.7,
        Function = function()
            if not Water.Enabled then return end
            if Mode.Value == 'Terrain' then
                applyWaterLook()
            elseif part then
                part.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                part.Transparency = math.clamp(1 - Color.Opacity, 0, 1)
            end
        end
    })
end)

run(function()
    local ChatPosition
    local Vertical
    local Horizontal
    local moved

    -- The chat is one of two completely different systems and the old module only ever spoke to
    -- the wrong one. SetCore('ChatWindowPosition') drives the legacy Lua chat; BedWars runs on
    -- TextChatService, which ignores SetCore entirely - so the module did
    -- nothing. We drive both now: SetCore for the legacy chat, and for TextChatService we find the
    -- window it actually rendered and move that frame ourselves, re-asserting it because the chat
    -- rebuilds its GUI on respawn and channel changes.
    local function targetOffset()
        return Vector2.new(Horizontal and Horizontal.Value or 0, Vertical and Vertical.Value or 200)
    end

    -- Legacy chat is the supported path. Retry because the CoreScript registers the SetCore
    -- callback a moment after join and a single early call is silently dropped.
    local function applyLegacy()
        local off = targetOffset()
        pcall(function()
            starterGui:SetCore('ChatWindowPosition', UDim2.fromOffset(off.X, off.Y))
        end)
    end

    -- TextChatService's window has no public position property, so move the rendered frame. Its
    -- name is randomised, so match it by shape: a GuiObject holding the message list (a
    -- ScrollingFrame) under a chat-named ScreenGui in CoreGui or PlayerGui.
    local function findChatFrame()
        local roots = {coreGui}
        local pg = lplr:FindFirstChild('PlayerGui')
        if pg then table.insert(roots, pg) end
        for _, root in roots do
            for _, gui in root:GetChildren() do
                if gui:IsA('ScreenGui') and gui.Name:lower():find('chat') then
                    for _, child in gui:GetChildren() do
                        if child:IsA('GuiObject') and child:FindFirstChildWhichIsA('ScrollingFrame', true) then
                            return child
                        end
                    end
                end
            end
        end
    end

    local function apply()
        applyLegacy()
        local frame = findChatFrame()
        if frame then
            moved = frame
            pcall(function()
                frame.Position = UDim2.fromOffset(targetOffset().X, targetOffset().Y)
            end)
        end
    end

    local function restore()
        pcall(function()
            starterGui:SetCore('ChatWindowPosition', UDim2.new())
        end)
        if moved and moved.Parent then
            pcall(function() moved.Position = UDim2.new() end)
        end
        moved = nil
    end

    ChatPosition = vape.Categories.Render:CreateModule({
        Name = 'ChatPosition',
        Function = function(callback)
            if callback then
                ChatPosition:Clean(task.spawn(function()
                    while ChatPosition.Enabled do
                        apply()
                        task.wait(1)
                    end
                end))
            else
                restore()
            end
        end,
        Tooltip = 'Repositions the chat window. Works with both the legacy chat and TextChatService'
    })
    Vertical = ChatPosition:CreateSlider({
        Name = 'Vertical',
        Min = 0,
        Max = 700,
        Default = 200,
        Suffix = ' px',
        Tooltip = 'How far down from the top-left the chat window sits',
        Function = function()
            if ChatPosition.Enabled then apply() end
        end
    })
    Horizontal = ChatPosition:CreateSlider({
        Name = 'Horizontal',
        Min = 0,
        Max = 700,
        Default = 0,
        Suffix = ' px',
        Tooltip = 'How far right from the left edge the chat window sits',
        Function = function()
            if ChatPosition.Enabled then apply() end
        end
    })
end)

run(function()
    local BoostAirJump
    local Boost
    BoostAirJump = vape.Categories.Blatant:CreateModule({
        Name = 'BoostAirJump',
        Function = function(callback)
            if callback then
                repeat
                    -- Only boost while the player is actually holding jump (space / gamepad A)
                    -- and not typing in a text box, so it stops floating you up on its own.
                    if entitylib.isAlive and not inputService:GetFocusedTextBox()
                        and (inputService:IsKeyDown(Enum.KeyCode.Space) or inputService:IsKeyDown(Enum.KeyCode.ButtonA)) then
                        local root = entitylib.character.RootPart
                        if root then
                            root.AssemblyLinearVelocity = root.AssemblyLinearVelocity + Vector3.new(0, Boost and Boost.Value or 35, 0)
                        end
                    end
                    task.wait(0.1)
                until not BoostAirJump.Enabled
            end
        end,
        Tooltip = 'Adds upward velocity while you hold jump/space to bypass jump-height detection'
    })
    Boost = BoostAirJump:CreateSlider({
        Name = 'Boost',
        Min = 5,
        Max = 60,
        Default = 35,
        Suffix = ' studs/s',
        Tooltip = 'Upward velocity added each tick while jump is held'
    })
end)


-- KrystalDisabler lives further down, in the Kits window beside the rest of the kit modules.

-- (InfiniteSigrid removed. Re-asserting the ElkKitMounted remote to sustain the ride locked the
-- player server-side - you moved locally but stayed pinned for everyone else and could be hit.
-- A correct version needs the elk kit controller's real dismount/duration internals, which we
-- can't see from the repo, so the module is pulled rather than shipped broken and harmful.)

-- AutoBuildUp: towers you straight up. While you hold jump it fills the block-cell directly
-- beneath your feet - every cell as you rise, driven by position rather than a timer/apex - so
-- you build a gapless pillar and keep climbing as fast as you go up. Placement mirrors the
-- NoFall block clutch.
run(function()
    local AutoBuildUp
    local LimitItems
    local pending = {}
    local nextPlacement = 0
    local directions = {
        Vector3.new(3, 0, 0), Vector3.new(-3, 0, 0), Vector3.new(0, 3, 0),
        Vector3.new(0, -3, 0), Vector3.new(0, 0, 3), Vector3.new(0, 0, -3)
    }

    local function getBuildBlock()
        local hand = store.hand
        if hand and hand.toolType == 'block' and hand.tool then return hand.tool.Name end
        if LimitItems.Enabled then return nil end
        local wool = getWool()
        if wool then return wool end
        for _, item in store.inventory.inventory.items do
            local meta = bedwars.ItemMeta[item.itemType]
            if meta and meta.block and (item.amount or 0) > 0 then return item.itemType end
        end
    end

    local function adjacent(pos)
        for _, offset in directions do
            if getPlacedBlock(pos + offset) then return true end
        end
        return false
    end

    local function queuePlacement(pos, block)
        local key = tostring(pos)
        local request = pending[key]
        if request and tick() < request.retryAt then return end
        if not adjacent(pos) then return end
        pending[key] = {retryAt = tick() + math.clamp(0.22 + lplr:GetNetworkPing(), 0.25, 0.55), attempts = request and request.attempts + 1 or 1}
        nextPlacement = tick() + math.max(0.125, lplr:GetNetworkPing() * 0.6)
        task.spawn(function()
            bedwars.placeBlock(pos, block)
            task.delay(math.clamp(0.18 + lplr:GetNetworkPing(), 0.22, 0.5), function()
                if not AutoBuildUp.Enabled then return end
                if getPlacedBlock(pos) then
                    pending[key] = nil
                elseif pending[key] and pending[key].attempts >= 3 then
                    pending[key] = nil
                end
            end)
        end)
    end

    AutoBuildUp = vape.Categories.Blatant:CreateModule({
        Name = 'AutoBuildUp',
        Function = function(callback)
            table.clear(pending)
            nextPlacement = 0
            if not callback then return end
            AutoBuildUp:Clean(runService.Heartbeat:Connect(function()
                if not entitylib.isAlive or inputService:GetFocusedTextBox() then return end
                local character = entitylib.character
                local root, humanoid = character.RootPart, character.Humanoid
                if not root or not humanoid then return end
                local holding = humanoid.Jump or inputService:IsKeyDown(Enum.KeyCode.Space) or inputService:IsKeyDown(Enum.KeyCode.ButtonA)
                if not holding then return end
                local infinite = vape.Modules.InfiniteJump and vape.Modules.InfiniteJump.Enabled
                if infinite and root.AssemblyLinearVelocity.Y < 22 then
                    root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 28, root.AssemblyLinearVelocity.Z)
                end
                if tick() < nextPlacement then return end
                local block = getBuildBlock()
                if not block then return end
                local feet = root.Position.Y - (character.HipHeight or 3)
                local target = bedwars.BlockController:getBlockPosition(Vector3.new(root.Position.X, feet - 1.5, root.Position.Z)) * 3
                if feet < target.Y + 1.5 or getPlacedBlock(target) then return end
                queuePlacement(target, block)
            end))
        end,
        Tooltip = 'Towers upward while jump is held'
    })
    LimitItems = AutoBuildUp:CreateToggle({Name = 'Limit to items', Tooltip = 'Only towers with the held block'})
end)


run(function()
    local RecoveryTP
    local HealthThreshold
    local TeleportHeight
    local GroundTime
    local PlayerCheck
    local groundedSince = 0
	local trackedCharacter
	local recovered = false

	local function validCharacter()
		local character = entitylib.character
		if not entitylib.isAlive or not character or not character.Character or not character.Character.Parent then return end
		local humanoid, root = character.Humanoid, character.RootPart
		if not humanoid or humanoid.Health <= 0 or not root or not root.Parent then return end
		return character, humanoid, root
	end

	local function playerNearby(origin)
		local list = type(entitylib.List) == 'table' and entitylib.List or {}
		for _, ent in list do
			local root = ent and ent.RootPart
			local player = ent and ent.Player
			if player and player ~= lplr and player.Parent == playersService and root and root.Parent
				and (not ent.Health or ent.Health > 0) and (root.Position - origin).Magnitude <= 50 then
				return true
			end
		end
		return false
	end

    RecoveryTP = vape.Categories.Blatant:CreateModule({
        Name = 'RecoveryTP',
        Function = function(callback)
			groundedSince, trackedCharacter, recovered = 0, nil, false
			if not callback then return end
			RecoveryTP:Clean(lplr.CharacterAdded:Connect(function(character)
				trackedCharacter, groundedSince, recovered = character, 0, false
			end))
            RecoveryTP:Clean(runService.PostSimulation:Connect(function()
				if not RecoveryTP.Enabled then return end
				local character, humanoid, root = validCharacter()
				if not character then groundedSince, recovered = 0, false return end
				if trackedCharacter ~= character.Character then
					trackedCharacter, groundedSince, recovered = character.Character, 0, false
				end
				if humanoid.Health >= HealthThreshold.Value then groundedSince, recovered = 0, false return end
				if recovered then return end
				local ownsRoot = false
				pcall(function() ownsRoot = isnetworkowner(root) end)
				if not ownsRoot then groundedSince = 0 return end
				if PlayerCheck.Enabled and not playerNearby(root.Position) then groundedSince = 0 return end
				if humanoid.FloorMaterial == Enum.Material.Air then groundedSince = 0 return end
                local now = tick()
                if groundedSince == 0 then groundedSince = now return end
				if now - groundedSince < GroundTime.Value then return end
				groundedSince, recovered = 0, true
				root.CFrame = CFrame.new(root.Position.X, TeleportHeight.Value, root.Position.Z) * root.CFrame.Rotation
                root.AssemblyLinearVelocity = Vector3.zero
                humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
            end))
        end,
        Tooltip = 'Teleports you to a safe height when your health is critical'
    })
    HealthThreshold = RecoveryTP:CreateSlider({Name = 'Health threshold', Min = 1, Max = 99, Default = 35, Suffix = ' HP'})
    TeleportHeight = RecoveryTP:CreateSlider({Name = 'Safe height', Min = 80, Max = 300, Default = 180, Suffix = ' studs'})
    GroundTime = RecoveryTP:CreateSlider({Name = 'Ground time', Min = 0.1, Max = 3, Default = 0.5, Decimal = 100, Suffix = ' seconds'})
    PlayerCheck = RecoveryTP:CreateToggle({
        Name = 'Player check',
        Tooltip = 'Only teleports while a player is within 50 studs'
    })
end)

-- BedWars' placement check queries character geometry before it sends the placement
-- remote. Suppress those queries only for the synchronous placement request; keeping
-- CanQuery false after it returns also hides an avatar from arrow/projectile raycasts.
run(function()
    local IgnorePlaceHitboxes
    local function withIgnoredHitboxes(callback)
        local originals = {}
        for _, plr in playersService:GetPlayers() do
            local character = plr.Character
            if character then
                for _, part in character:GetDescendants() do
                    if part:IsA('BasePart') then
                        originals[part] = part.CanQuery
                        part.CanQuery = false
                    end
                end
            end
        end
        local results = table.pack(xpcall(callback, function(err) return err end))
        for part, value in originals do
            if part.Parent then part.CanQuery = value end
        end
        if not results[1] then error(results[2], 0) end
        return table.unpack(results, 2, results.n)
    end

    IgnorePlaceHitboxes = vape.Categories.World:CreateModule({
        Name = 'IgnorePlaceHitboxes',
        Tooltip = 'Allows block placement through players and your own character',
        Function = function(enabled)
            if enabled then
                bedwars.IgnorePlaceHitboxes = withIgnoredHitboxes
            else
                bedwars.IgnorePlaceHitboxes = nil
            end
        end
    })
end)

run(function()
    local ProjectileDodger
    local Range
    local Strength
    local Mode
    local TeleportDistance
    local EdgeCheck
    local projectiles = {}
    local projectileHistory = {}
    local dodgedProjectiles = {}
    local dodgeUntil, dodgeDirection = 0, Vector3.zero
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true

    -- Projectiles replicate as Models parented directly to workspace, tagged with 'ProjectileShooter'.
    local function projectilePart(obj)
        return obj:IsA('BasePart') and obj or obj.PrimaryPart
    end

    local function isProjectile(obj)
        local shooter = obj:GetAttribute('ProjectileShooter')
        if shooter == nil or shooter == lplr.UserId then return false end
        return projectilePart(obj) ~= nil
    end

    -- Keep the last good velocity so freshly spawned projectiles (which report a
    -- zero AssemblyLinearVelocity for a frame or two) are still dodged in time.
    local function getProjectileVelocity(obj, part)
        local now = os.clock()
        local history = projectileHistory[obj]
        local assembly = part.AssemblyLinearVelocity
        local velocity
        if assembly.Magnitude > 1 then
            velocity = assembly
        elseif history and (now - history.Time) > 1e-4 then
            velocity = (part.Position - history.Position) / (now - history.Time)
        end
        if (not velocity or velocity.Magnitude <= 2) and history and history.Velocity then
            velocity = history.Velocity
        end
        velocity = velocity or Vector3.zero
        projectileHistory[obj] = {Position = part.Position, Time = now, Velocity = velocity.Magnitude > 2 and velocity or (history and history.Velocity)}
        return velocity
    end

    local function safeDirection(root, dir)
        if dir ~= dir or dir.Magnitude <= 0 then
            dir = root.CFrame.RightVector
        end
        dir = Vector3.new(dir.X, 0, dir.Z)
        dir = dir.Magnitude > 0 and dir.Unit or root.CFrame.RightVector
        if not EdgeCheck.Enabled then return dir end
        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
        local rightSafe = workspace:Raycast(root.Position + (dir * 6), Vector3.new(0, -16, 0), rayCheck)
        if rightSafe then return dir end
        local left = -dir
        local leftSafe = workspace:Raycast(root.Position + (left * 6), Vector3.new(0, -16, 0), rayCheck)
        return leftSafe and left or dir
    end

    local function teleportDodge(root, side)
        local distance = TeleportDistance.Value * 3 -- slider is in blocks; BedWars blocks are 3 studs
        local options = {side, -side}
        for _, direction in options do
            local target = root.Position + (direction * distance)
            if not EdgeCheck.Enabled or workspace:Raycast(target + Vector3.new(0, 2, 0), Vector3.new(0, -12, 0), rayCheck) then
                root.CFrame = CFrame.new(target, target + root.CFrame.LookVector)
                root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                return true
            end
        end
        return false
    end

    -- Evaluates the threat along the projectile's real (gravity-aware) arc. A straight-line
    -- closest-approach reports a large miss for an arcing arrow until it is nearly on top of
    -- you, which is what made the sidestep fire too late; sampling the parabola catches it
    -- with time to spare.
    local function incomingDirection(obj, root, range)
        local part = obj.Parent and projectilePart(obj)
        if not part then return end
        local origin = part.Position
        local rootPos = root.Position
        if (origin - rootPos).Magnitude > math.max(range, 70) then return end
        local velocity = getProjectileVelocity(obj, part)
        if velocity.Magnitude < 2 then return end
        local toLocal = rootPos - origin
        if toLocal.Magnitude <= 0 then return end
        local closingSpeed = velocity:Dot(toLocal.Unit)
        if closingSpeed <= 0 then return end

        local meta = bedwars.ProjectileMeta[obj.Name]
        local grav = meta and meta.gravitationalAcceleration or workspace.Gravity
        local horizon = math.clamp((toLocal.Magnitude / closingSpeed) * 1.3, 0.05, 1.4)
        local miss, timeToHit = math.huge, horizon
        for i = 0, 16 do
            local t = horizon * i / 16
            local pos = origin + velocity * t - Vector3.new(0, 0.5 * grav * t * t, 0)
            local d = (pos - rootPos).Magnitude
            if d < miss then
                miss = d
                timeToHit = t
            end
        end
        if miss < 12 then
            return safeDirection(root, velocity.Unit:Cross(Vector3.yAxis)), timeToHit
        end
    end

    ProjectileDodger = vape.Categories.Blatant:CreateModule({
        Name = 'ProjectileDodger',
        Function = function(callback)
            if callback then
                table.clear(projectiles)
                table.clear(projectileHistory)
                table.clear(dodgedProjectiles)
                for _, obj in workspace:GetChildren() do
                    if isProjectile(obj) then projectiles[obj] = true end
                end
                ProjectileDodger:Clean(workspace.ChildAdded:Connect(function(obj)
                    task.delay(0, function()
                        if obj.Parent and isProjectile(obj) then projectiles[obj] = true end
                    end)
                end))

                -- Legit mode moves the real hitbox with a smooth, frame-rate-independent CFrame
                -- nudge every physics step. Setting AssemblyLinearVelocity alone does nothing here
                -- because the Humanoid movement controller overwrites it each step, which is why
                -- Legit mode previously appeared to do nothing at all.
                ProjectileDodger:Clean(runService.PostSimulation:Connect(function(dt)
                    if Mode.Value ~= 'Legit' or tick() >= dodgeUntil or dodgeDirection.Magnitude <= 0 then return end
                    if not entitylib.isAlive then return end
                    local root = entitylib.character.RootPart
                    if not root then return end
                    -- CFrame stepping only: also writing a full-strength velocity each
                    -- frame fought the humanoid controller and doubled the effective
                    -- speed, which is what made the sidestep overshoot and rubber-band.
                    local step = math.clamp(Strength.Value, 10, 80) * dt
                    local delta = Vector3.new(dodgeDirection.X * step, 0, dodgeDirection.Z * step)
                    -- Per-frame edge guard. The one-shot check at commit time only
                    -- probed 6 studs out, so a long Legit slide kept moving past the
                    -- last ground and walked the player off the edge even with Edge
                    -- Check on. Re-probe the ground directly beneath the *next*
                    -- position every frame and stop the slide the moment it would
                    -- leave a supported block.
                    if EdgeCheck.Enabled then
                        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
                        local nextPos = root.Position + delta
                        if not workspace:Raycast(nextPos + Vector3.new(0, 2, 0), Vector3.new(0, -(entitylib.character.HipHeight + 5), 0), rayCheck) then
                            dodgeUntil = 0
                            return
                        end
                    end
                    root.CFrame = root.CFrame + delta
                end))

                repeat
                    if entitylib.isAlive then
                        local root = entitylib.character.RootPart
                        -- While a dodge is in progress just wait it out; the PostSimulation stepper
                        -- above carries out the Legit movement, and Teleport already fired instantly.
                        if tick() >= dodgeUntil then
                            local best, bestTime, bestObj = nil, math.huge, nil
                            for obj in projectiles do
                                if not obj.Parent then
                                    projectiles[obj] = nil
                                    projectileHistory[obj] = nil
                                    continue
                                end
                                local side, timeToHit = incomingDirection(obj, root, Range.Value)
                                if side and (timeToHit or 1.25) < bestTime and (not dodgedProjectiles[obj] or tick() - dodgedProjectiles[obj] > 1.5) then
                                    best, bestTime, bestObj = side, timeToHit or 1.25, obj
                                end
                            end
                            -- Only commit once the hit is imminent. Dodging the moment a
                            -- threat appears (sometimes >1s early) let the player drift
                            -- back into the arc while the per-projectile lockout blocked a
                            -- second dodge - the main source of "dodged but still got hit".
                            local ping = 0
                            pcall(function() ping = lplr:GetNetworkPing() end)
                            -- Teleport is instant and can't overshoot back into the arc, so it
                            -- commits earlier and covers a fuller round-trip than the Legit slide.
                            -- Reacting too late here was what let fast arrows land in TP mode.
                            local reactionWindow = Mode.Value == 'Teleport'
                                and math.min(ping * 1.4 + 0.45, 0.9)
                                or math.min(ping + 0.45, 0.6)
                            if best and bestTime <= reactionWindow then
                                dodgeDirection = best
                                if Mode.Value == 'Teleport' then
                                    -- Only flag the projectile as handled once the teleport actually
                                    -- fires. Previously it was flagged unconditionally, so a blocked
                                    -- teleport (edge check) locked the arrow out for 1.5s and let it hit.
                                    if teleportDodge(root, best) then
                                        dodgedProjectiles[bestObj] = tick()
                                        -- brief lockout so a burst of arrows can't chain-teleport the player away
                                        dodgeUntil = tick() + math.clamp(bestTime, 0.12, 0.35)
                                    end
                                else
                                    dodgedProjectiles[bestObj] = tick()
                                    dodgeUntil = tick() + math.clamp(bestTime + 0.15, 0.25, 0.6)
                                end
                            end
                        end
                    end
                    task.wait()
                until not ProjectileDodger.Enabled
            else
                table.clear(projectiles)
                table.clear(projectileHistory)
                table.clear(dodgedProjectiles)
                dodgeUntil = 0
                dodgeDirection = Vector3.zero
            end
        end,
        Tooltip = 'Dodges incoming projectiles without stepping off edges'
    })
    Range = ProjectileDodger:CreateSlider({Name = 'Range', Min = 10, Max = 80, Default = 45, Suffix = 'studs'})
    Mode = ProjectileDodger:CreateDropdown({Name = 'Mode', List = {'Teleport', 'Legit'}, Default = 'Teleport', Function = function(val)
        pcall(function()
            TeleportDistance.Object.Visible = val == 'Teleport'
            Strength.Object.Visible = val == 'Legit'
        end)
    end})
    TeleportDistance = ProjectileDodger:CreateSlider({Name = 'Teleport Distance', Min = 1, Max = 2, Default = 2, Decimal = 1, Suffix = ' blocks'})
    Strength = ProjectileDodger:CreateSlider({Name = 'Dodge Strength', Min = 10, Max = 80, Default = 38, Suffix = 'studs', Visible = false})
    EdgeCheck = ProjectileDodger:CreateToggle({Name = 'Edge Check', Default = true})
end)

run(function()
    local TPAura
    local Targets
    local Range
    local TeleportRange
    local Delay
    local DodgeAttacks
    local Mode
    local HoldTime
    local SwitchAfter
    local StructureCheck
    local rand = Random.new()
    local overlapParams = OverlapParams.new()
    overlapParams.FilterType = Enum.RaycastFilterType.Exclude

    local function isValidTarget(ent)
        return ent and ent.RootPart and ent.RootPart.Parent and ent.RootPart.AssemblyLinearVelocity.Y > -35
    end

    local function isClearPosition(position, targetPosition)
        local path = position - targetPosition
        if path.Magnitude > 0.1 and workspace:Raycast(targetPosition + Vector3.new(0, 2.5, 0), path.Unit * math.max(path.Magnitude - 1.5, 0), store.blockRaycast) then return false end
        if workspace:Raycast(position, Vector3.new(0, entitylib.character.HipHeight + 3, 0), store.blockRaycast) then return false end

        overlapParams.FilterDescendantsInstances = {lplr.Character, gameCamera}
        local boxSize = Vector3.new(3.2, entitylib.character.HipHeight + 4, 3.2)
        local boxCFrame = CFrame.new(position + Vector3.new(0, boxSize.Y / 2 - 1.5, 0))
        for _, part in workspace:GetPartBoundsInBox(boxCFrame, boxSize, overlapParams) do
            if part.CanCollide and part.Transparency < 0.95 and not part:IsDescendantOf(lplr.Character) then
                return false
            end
        end
        return true
    end

    local function getGroundPosition(raw, targetPosition)
        local ground = workspace:Raycast(raw + Vector3.new(0, 16, 0), Vector3.new(0, -36, 0), store.blockRaycast)
        if not ground or math.abs(ground.Position.Y - targetPosition.Y) > 5 then return end
        local position = Vector3.new(raw.X, ground.Position.Y + entitylib.character.HipHeight + 2.5, raw.Z)
        -- Structure Check: reject spots that sit under a roof/bridge (something solid
        -- within ~12 studs overhead) so we never teleport into an enclosed pocket.
        if StructureCheck and StructureCheck.Enabled then
            if workspace:Raycast(position + Vector3.new(0, entitylib.character.HipHeight + 1, 0), Vector3.new(0, 12, 0), store.blockRaycast) then
                return
            end
        end
        return isClearPosition(position, targetPosition) and position or nil
    end

    -- Runtime state for target locking / switching.
    local lockedTarget, lockedUntil, lastSwitch, switchIndex = nil, 0, 0, 0

    -- Scanning: every targetable enemy inside Target Range, nearest first. Reuses
    -- entitylib.AllPosition so team filtering, vulnerability and the Walls line-of-sight
    -- option behave exactly like the rest of the combat modules.
    local function scanTargets(origin)
        return entitylib.AllPosition({
            Origin = origin,
            Range = Range.Value,
            Players = Targets.Players.Enabled,
            NPCs = Targets.NPCs.Enabled,
            Wallcheck = Targets.Walls.Enabled or nil,
            Part = 'RootPart',
            Sort = sortmethods.Distance
        })
    end

    -- Teleport placement: prefer the spot behind the target (Dodge attacks), otherwise
    -- sweep a ring around them for the first clear, ground-backed, unobstructed slot.
    local function findTeleportPosition(ent)
        local root = ent.RootPart
        local targetPosition = root.Position
        local radius = TeleportRange.Value
        local position
        if DodgeAttacks.Enabled then
            position = getGroundPosition(targetPosition - (root.CFrame.LookVector * radius), targetPosition)
        end
        for i = 1, 16 do
            if position then break end
            local angle = ((i / 16) * math.pi * 2) + rand:NextNumber(-0.15, 0.15)
            local distance = rand:NextNumber(math.max(2.5, radius - 1.5), radius)
            position = getGroundPosition(targetPosition + Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance), targetPosition)
        end
        return position, targetPosition
    end

    TPAura = vape.Categories.Blatant:CreateModule({
        Name = 'TPAura',
        Function = function(callback)
            if callback then
                lockedTarget, lockedUntil, lastSwitch, switchIndex = nil, 0, 0, 0
                local homePosition
                repeat
                    if entitylib.isAlive then
                        local root = entitylib.character.RootPart
                        -- Anchor the target search and every range gate to a stable
                        -- "home" position instead of the live root. The old code measured
                        -- range from wherever the last teleport left you (right on top of
                        -- an enemy), so each teleport quietly stretched the effective reach
                        -- far past the Target Range you set and let TP Aura chain across the
                        -- map. Home freezes while a valid target is being engaged and only
                        -- re-samples to your real position once you have nothing to fight.
                        local engaging = lockedTarget and isValidTarget(lockedTarget)
                            and (lockedTarget.RootPart.Position - (homePosition or root.Position)).Magnitude <= Range.Value
                        if not engaging or not homePosition then
                            homePosition = root.Position
                        end
                        local origin = homePosition
                        local targets = scanTargets(origin)
                        local target

                        if Mode.Value == 'Switch' then
                            -- Rotate to the next target every Switch Delay seconds, or
                            -- immediately if the current one died / left range.
                            local stillValid = lockedTarget and isValidTarget(lockedTarget) and (lockedTarget.RootPart.Position - origin).Magnitude <= Range.Value
                            if not stillValid or (tick() - lastSwitch) >= SwitchAfter.Value then
                                if #targets > 0 then
                                    switchIndex = (switchIndex % #targets) + 1
                                    target = targets[switchIndex]
                                    lockedTarget, lastSwitch = target, tick()
                                end
                            else
                                target = lockedTarget
                            end
                        else
                            -- Single: stick with one target until Hold Time elapses or it
                            -- becomes invalid, then re-acquire the nearest.
                            local stillValid = lockedTarget and isValidTarget(lockedTarget) and (lockedTarget.RootPart.Position - origin).Magnitude <= Range.Value
                            if stillValid and tick() < lockedUntil then
                                target = lockedTarget
                            else
                                target = targets[1]
                                lockedTarget = target
                                lockedUntil = tick() + HoldTime.Value
                            end
                        end

                        if target and isValidTarget(target) then
                            local targetRoot = target.RootPart
                            -- Only teleport when actually out of reach, or (with Dodge
                            -- attacks) when we are no longer behind the target. Skipping the
                            -- teleport while already in position removes the constant
                            -- micro-teleport jitter around a target.
                            local flat = (root.Position - targetRoot.Position) * Vector3.new(1, 0, 1)
                            local distance = (targetRoot.Position - root.Position).Magnitude
                            local behindOk = true
                            if DodgeAttacks.Enabled and flat.Magnitude > 0.5 then
                                behindOk = targetRoot.CFrame.LookVector:Dot(flat.Unit) > 0.15
                            end
                            if distance > TeleportRange.Value + 1.5 or not behindOk then
                                local position, targetPosition = findTeleportPosition(target)
                                if position then
                                    -- Face the target on a level plane so we don't tilt.
                                    root.CFrame = CFrame.lookAt(position, Vector3.new(targetPosition.X, position.Y, targetPosition.Z))
                                    root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                                end
                            end
                        end
                    end
                    task.wait(Delay.Value)
                until not TPAura.Enabled
            else
                lockedTarget = nil
            end
        end,
        Tooltip = 'Teleports around targets and faces them. Single locks one, Switch rotates between them'
    })
    Targets = TPAura:CreateTargets({Players = true, NPCs = true})
    Mode = TPAura:CreateDropdown({Name = 'Mode', List = {'Single', 'Switch'}, Default = 'Single'})
    Range = TPAura:CreateSlider({Name = 'Target Range', Min = 6, Max = 40, Default = 22, Suffix = 'studs'})
    TeleportRange = TPAura:CreateSlider({Name = 'Teleport Range', Min = 3, Max = 10, Default = 6, Decimal = 10, Suffix = 'studs'})
    Delay = TPAura:CreateSlider({Name = 'Teleport Delay', Min = 0.15, Max = 1, Default = 0.35, Decimal = 100, Suffix = 'seconds'})
    HoldTime = TPAura:CreateSlider({Name = 'Single Hold Time', Min = 0.5, Max = 8, Default = 3, Decimal = 10, Suffix = 'seconds'})
    SwitchAfter = TPAura:CreateSlider({Name = 'Switch Delay', Min = 0.35, Max = 4, Default = 1.25, Decimal = 100, Suffix = 'seconds'})
    StructureCheck = TPAura:CreateToggle({Name = 'Structure Check', Tooltip = 'Rejects teleport spots on roofs, bridges, or tall structures above the target', Default = true})
    DodgeAttacks = TPAura:CreateToggle({
        Name = 'Dodge attacks',
        Tooltip = 'Prioritizes teleporting behind where targets are facing'
    })
end)

-- cv's projectile charge routine, adapted to Aether's shared launch-hook registry.  The
-- registry composes with projectile modules already installed by Aether and restores the
-- original controller when the last hook is removed, avoiding the replacement/restore race the
-- reference implementation had when more than one module patched this method.
run(function()
	local AutoChargeProj
	local Percentage
	local removeHook

	local function clearHook()
		if removeHook then
			removeHook()
			removeHook = nil
		end
	end

	AutoChargeProj = vape.Categories.Blatant:CreateModule({
		Name = 'AutoChargeProj',
		Function = function(enabled)
			clearHook()
			if not enabled then return end
			if not (bedwars.ProjectileLaunchHook and bedwars.ProjectileController) then
				notif('AutoChargeProj', 'Projectile controller is unavailable.', 5, 'warning')
				task.defer(function() if AutoChargeProj.Enabled then AutoChargeProj:Toggle() end end)
				return
			end
			removeHook = bedwars.ProjectileLaunchHook:Add('AutoChargeProj', 80, function(nextHook, self, launchData, ...)
				local metadata = launchData and bedwars.ProjectileMeta[launchData.projectile]
				if metadata and metadata.predictionLifetimeSec and launchData.drawDurationSeconds then
					local charge = Percentage.Value / 100
					launchData.drawDurationSeconds = math.max(launchData.drawDurationSeconds, metadata.predictionLifetimeSec * charge)
					launchData.velocityMultiplier = math.max(launchData.velocityMultiplier or 0, charge)
				end
				return nextHook(self, launchData, ...)
			end)
			AutoChargeProj:Clean(clearHook)
		end,
		Tooltip = 'Instantly charges projectile items to a percentage of their full charge'
	})
	Percentage = AutoChargeProj:CreateSlider({
		Name = 'Percentage',
		Min = 0,
		Max = 100,
		Default = 50,
		Suffix = '%'
	})
end)

run(function()
	local CannonSpeed
	local Speed
	local originalSpeed

	local function setSpeed(value)
		local controller = bedwars.CannonHandController
		if not (canDebug and controller and type(controller.launchSelf) == 'function' and debug.setconstant) then
			return false
		end
		return pcall(debug.setconstant, controller.launchSelf, 15, value)
	end

	CannonSpeed = vape.Categories.Blatant:CreateModule({
		Name = 'CannonSpeed',
		Function = function(enabled)
			if enabled then
				local controller = bedwars.CannonHandController
				local ok, value = pcall(function()
					return canDebug and debug.getconstant and controller and debug.getconstant(controller.launchSelf, 15)
				end)
				originalSpeed = ok and value or nil
				if not setSpeed(Speed.Value) then
					notif('CannonSpeed', 'Cannon speed is unavailable in this BedWars build.', 5, 'warning')
					task.defer(function() if CannonSpeed.Enabled then CannonSpeed:Toggle() end end)
				end
			elseif originalSpeed ~= nil then
				setSpeed(originalSpeed)
				originalSpeed = nil
			end
		end,
		Tooltip = 'Changes the local cannon-launch speed where this BedWars build exposes it'
	})
	Speed = CannonSpeed:CreateSlider({
		Name = 'Speed',
		Min = 1,
		Max = 400,
		Default = 200,
		Suffix = ' studs',
		Function = function(value)
			if CannonSpeed.Enabled then setSpeed(value) end
		end
	})
	CannonSpeed:CreateButton({
		Name = 'Sync to legit speed',
		Function = function() Speed:SetValue(200) end
	})
end)

run(function()
    local DamageBoost
    local stack

    DamageBoost = vape.Categories.Blatant:CreateModule({
	Name = 'DamageBoost',
	Function = function(callback)
		if callback then
			DamageBoost:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
				if entitylib.isAlive and tick() > (stack or 0) and damageTable.entityInstance == lplr.Character and not LongJump.Enabled then
					local horizontal = (damageTable.knockbackMultiplier and damageTable.knockbackMultiplier.horizontal or 0)
					knockbackSpeed = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {
						vertical = 0,
						horizontal = horizontal,
					}).Magnitude * (0.9 + lplr:GetNetworkPing())
                        stack = tick() + (knockbackSpeed / 45)
                        knockbackBoost = tick() + (horizontal / 3.5)
				end
			end))
		end
	end,
        Tooltip = 'Makes you go slightly faster when damaged'
    })
end)

run(function()
    local FastBreak
    local BedCheck
    local Blacklist
    local Blacklisted
    local Time

    local newlist, old = {}, nil
    local function find(tab, ind)
	for i, v in tab do
		if v == ind or v:find(ind) then
			return i
		end
	end
	return nil
    end

    FastBreak = vape.Categories.Blatant:CreateModule({
	Name = 'FastBreak',
	Function = function(callback)
		if callback then
			old = bedwars.BlockBreaker.hitBlock
			bedwars.BlockBreaker.hitBlock = function(self, ...)
				local _, params = unpack({ ... })
				pcall(function()
					local block, info = nil, self.clientManager:getBlockSelector():getMouseInfo(1, {ray = params})
					block = info and info.target and info.target.blockInstance or nil
					if block and (not Blacklist.Enabled or not find(newlist, block.Name)) and (not BedCheck.Enabled or block.Name ~= 'bed') then
						bedwars.BlockBreakController.blockBreaker:setCooldown(Time.Value)
					end
				end)

				return old(self, ...)
			end

			repeat
				if (tick() - store.lastHit) > 0.3 then
					bedwars.BlockBreakController.blockBreaker:setCooldown(0.3)
				end
				task.wait(0.1)
			until not FastBreak.Enabled
		else
			bedwars.BlockBreaker.hitBlock = old
			bedwars.BlockBreakController.blockBreaker:setCooldown(0.3)
		end
	end,
	Tooltip = 'Decreases block hit cooldown'
    })
    Time = FastBreak:CreateSlider({
	Name = 'Break speed',
	Min = 0,
	Max = 0.3,
	Default = 0.25,
	Decimal = 100,
	Suffix = 'seconds',
    })
    BedCheck = FastBreak:CreateToggle({
	Name = 'Bed Check',
	Tooltip = "Doesn't increase speed if you are breaking a bed",
    })
    Blacklist = FastBreak:CreateToggle({
	Name = 'Use blacklist',
	Function = function(callback)
		if Blacklisted and Blacklisted.Object then
			Blacklisted.Object.Visible = callback
		end
	end,
    })
    Blacklisted = FastBreak:CreateTextList({
	Name = 'Blocks',
	Darker = true,
	Visible = false,
	Function = function(list)
		newlist = {}
		for _, v in list do
			if v:find('iron') then
				table.insert(newlist, 'iron_ore_mesh_block')
			else
				table.insert(newlist, v)
			end
		end
	end,
    })
end)

run(function()
    local FastPlace
    local CPS
    local originalCPS

    local function restore()
        if originalCPS ~= nil then
            bedwars.SharedConstants.BLOCK_PLACE_CPS = originalCPS
            originalCPS = nil
        end
    end

    FastPlace = vape.Categories.World:CreateModule({
        Name = 'FastPlace',
        Function = function(enabled)
            if enabled then
                -- Capture on every enable: other modules and game updates may legitimately change it.
                originalCPS = bedwars.SharedConstants.BLOCK_PLACE_CPS or 12
                bedwars.SharedConstants.BLOCK_PLACE_CPS = math.clamp(CPS.Value, 1, 20)
            else
                restore()
            end
        end,
        Tooltip = 'Reduces only the placement cooldown; does not hook placement or alter range.'
    })
    CPS = FastPlace:CreateSlider({
        Name = 'CPS', Min = 1, Max = 20, Default = 13,
        Function = function(value)
            if FastPlace.Enabled then bedwars.SharedConstants.BLOCK_PLACE_CPS = math.clamp(value, 1, 20) end
        end
    })
    FastPlace:CreateButton({Name = 'Use current BedWars CPS', Function = function()
        local current = originalCPS or bedwars.SharedConstants.BLOCK_PLACE_CPS or 12
        CPS:SetValue(math.clamp(current, 1, 20))
    end})
end)

-- Consumes the supplied Grim Reaper soul and applies a configurable horizontal speed only while
-- the character is in the controller's soul-collecting channel. Leaving the form immediately
-- hands velocity control back to the game.
run(function()
    local ReaperFix
    local ReaperSpeed

    local function getCharacterParts()
        local character = lplr.Character
        if not character then
            return
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")

        return character, humanoid, root
    end

    local function inSoulForm(character)
        if not character then
            return false
        end

        return character:GetAttribute("GrimReaperChannel") == true
    end

    ReaperFix = kits:CreateModule({
        Name = "ReaperBypass",
        Category = 'Ability',
        Function = function(callback)
            if not callback then
                return
            end

            local success, result = pcall(function()
                local event = replicatedStorage
                    .rbxts_include
                    .node_modules["@rbxts"]
                    .net
                    .out
                    ._NetManaged
                    .ConsumeGrimReaperSoul

                return event:InvokeServer({
                    secret = "a058cfb5-a4c9-4cc6-84e5-863108f23a89"
                })
            end)

            if not success then
                notif(
                    "ReaperBypass",
                    "Could not invoke ConsumeGrimReaperSoul: " .. tostring(result),
                    5,
                    "warning"
                )
            end

            ReaperFix:Clean(runService.PostSimulation:Connect(function()
                local character, humanoid, root = getCharacterParts()

                if not character or not humanoid or not root then
                    return
                end

                if humanoid.Health <= 0 or not inSoulForm(character) then
                    return
                end

                if not isnetworkowner(root) then
                    return
                end

                local direction = humanoid.MoveDirection
                direction = Vector3.new(direction.X, 0, direction.Z)

                if direction.Magnitude <= 0.05 then
                    return
                end

                local targetSpeed = tonumber(ReaperSpeed.Value) or 37
                local horizontalVelocity = direction.Unit * targetSpeed
                local currentVelocity = root.AssemblyLinearVelocity

                root.AssemblyLinearVelocity = Vector3.new(
                    horizontalVelocity.X,
                    currentVelocity.Y,
                    horizontalVelocity.Z
                )
            end))
        end,
        Tooltip = "Bypasses anticheat while consuming souls"
    })

    ReaperSpeed = ReaperFix:CreateSlider({
        Name = "Speed",
        Min = 1,
        Max = 80,
        Default = 37,
        Suffix = " studs/s"
    })
end)

run(function()
    local Value
    local VerticalValue
    local WallCheck
    local PopBalloons
    local TP
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    local up, down, old = 0, 0
    local KrystalKit, KrystalSpeed
    local SigridKit, SigridSpeed
    local GrimKit, GrimSpeed
    local ZephyrKit, ZephyrSpeed

    local function kitMovementSpeed(fallback)
        if not entitylib.isAlive then return fallback end
        local equipped = store.equippedKit
        if equipped == nil or equipped == '' then equipped = lplr:GetAttribute('PlayingAsKit') or lplr:GetAttribute('PlayingAsKits') end
        local kit = string.lower(tostring(equipped or ''))
        local char = lplr.Character
        local function has(words)
            for _, word in words do if kit:find(word, 1, true) then return true end end
            return false
        end
        if KrystalKit.Enabled and has({'glacial_skater', 'ice_skater', 'glacier', 'krystal'}) then return KrystalSpeed.Value end
        local riding = lplr:GetAttribute('ElkKitMounted') or lplr:GetAttribute('SigridMounted')
            or (char and (char:GetAttribute('ElkKitMounted') or char:GetAttribute('SigridMounted') or char:FindFirstChild('ElkMount', true)))
        if SigridKit.Enabled and has({'elk_master', 'elk', 'rider', 'sigrid'}) and riding then return SigridSpeed.Value end
        local soul = char and (char:GetAttribute('GrimReaperChannel') or char:GetAttribute('SoulForm') or char:GetAttribute('GrimReaperGhost') or char:FindFirstChild('GrimReaperChannel', true))
        if GrimKit.Enabled and has({'grim_reaper', 'grim', 'soul'}) and soul then return GrimSpeed.Value end
        local stacks = tonumber(lplr:GetAttribute('WindWalkerStacks') or lplr:GetAttribute('WindWalkerStack') or lplr:GetAttribute('WindStacks')
            or (char and (char:GetAttribute('WindWalkerStacks') or char:GetAttribute('WindWalkerStack') or char:GetAttribute('WindStacks'))) or 0) or 0
        if ZephyrKit.Enabled and has({'wind_walker', 'zephyr', 'wind'}) and stacks >= 1 then return ZephyrSpeed.Value end
        return fallback
    end

    Fly = vape.Categories.Blatant:CreateModule({
        Name = 'Fly',
        Function = function(callback)
            frictionTable.Fly = callback or nil
            updateVelocity()
            if callback then
                up, down, old = 0, 0, bedwars.BalloonController.deflateBalloon
                bedwars.BalloonController.deflateBalloon = function() end
                local tpTick, tpToggle, oldy = tick(), true

                if lplr.Character and (lplr.Character:GetAttribute('InflatedBalloons') or 0) == 0 and getItem('balloon') then
                    bedwars.BalloonController:inflateBalloon()
                end
                Fly:Clean(vapeEvents.AttributeChanged.Event:Connect(function(changed)
                    if changed == 'InflatedBalloons' and (lplr.Character:GetAttribute('InflatedBalloons') or 0) == 0 and getItem('balloon') then
                        bedwars.BalloonController:inflateBalloon()
                    end
                end))
                Fly:Clean(runService.PreSimulation:Connect(function(dt)
                    if entitylib.isAlive and isnetworkowner(entitylib.character.RootPart) then
                        local flyAllowed = (lplr.Character:GetAttribute('InflatedBalloons') and lplr.Character:GetAttribute('InflatedBalloons') > 0) or store.matchState == 2
                        local mass = (0.9 + (flyAllowed and 6 or 0) * (tick() % 0.4 < 0.2 and -1 or 1)) + ((up + down) * VerticalValue.Value)
                        local root, moveDirection = entitylib.character.RootPart, entitylib.character.Humanoid.MoveDirection
                        local velo = getSpeed()
                        local movementSpeed = kitMovementSpeed(Value.Value)
                        local destination = (moveDirection * math.max(movementSpeed - velo, 0) * dt)
                        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
                        rayCheck.CollisionGroup = root.CollisionGroup

                        if WallCheck.Enabled then
                            local ray = workspace:Raycast(root.Position, destination, rayCheck)
                            if ray then
                                destination = ((ray.Position + ray.Normal) - root.Position)
                            end
                        end

                        if not flyAllowed then
                            if tpToggle then
                                local airleft = (tick() - entitylib.character.AirTime)
                                if airleft > 2 then
                                    if not oldy then
                                        local ray = workspace:Raycast(root.Position, Vector3.new(0, -1000, 0), rayCheck)
                                        if ray and TP.Enabled then
                                            tpToggle = false
                                            oldy = root.Position.Y
                                            tpTick = tick() + 0.11
                                            root.CFrame = CFrame.lookAlong(Vector3.new(root.Position.X, ray.Position.Y + entitylib.character.HipHeight, root.Position.Z), root.CFrame.LookVector)
                                        end
                                    end
                                end
                            else
                                if oldy then
                                    if tpTick < tick() then
                                        local newpos = Vector3.new(root.Position.X, oldy, root.Position.Z)
                                        root.CFrame = CFrame.lookAlong(newpos, root.CFrame.LookVector)
                                        tpToggle = true
                                        oldy = nil
                                    else
                                        mass = 0
                                    end
                                end
                            end
                        end

                        root.CFrame += destination
                        root.AssemblyLinearVelocity = (moveDirection * math.max(velo, movementSpeed)) + Vector3.new(0, mass, 0)
                    end
                end))
                Fly:Clean(inputService.InputBegan:Connect(function(input)
                    if not inputService:GetFocusedTextBox() then
                        if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                            up = 1
                        elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                            down = -1
                        end
                    end
                end))
                Fly:Clean(inputService.InputEnded:Connect(function(input)
                    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                        up = 0
                    elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                        down = 0
                    end
                end))
                if inputService.TouchEnabled then
                    pcall(function()
                        local jumpButton = lplr.PlayerGui.TouchGui.TouchControlFrame.JumpButton
                        Fly:Clean(jumpButton:GetPropertyChangedSignal('ImageRectOffset'):Connect(function()
                            up = jumpButton.ImageRectOffset.X == 146 and 1 or 0
                        end))
                    end)
                end
            else
                bedwars.BalloonController.deflateBalloon = old
                if PopBalloons.Enabled and entitylib.isAlive and (lplr.Character:GetAttribute('InflatedBalloons') or 0) > 0 then
                    for _ = 1, 3 do
                        bedwars.BalloonController:deflateBalloon()
                    end
                end
            end
        end,
        ExtraText = function()
            return 'Heatseeker'
        end,
        Tooltip = 'Makes you go zoom'
    })
    Value = Fly:CreateSlider({
        Name = 'Speed',
        Min = 1,
        Max = 23,
        Default = 23,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    KrystalKit = Fly:CreateToggle({Name = 'Krystal', Function = function(callback) if KrystalSpeed and KrystalSpeed.Object then KrystalSpeed.Object.Visible = callback end end})
    KrystalSpeed = Fly:CreateSlider({Name = 'Krystal Speed', Min = 1, Max = 80, Default = 30, Suffix = ' studs/s', Darker = true, Visible = false})
    SigridKit = Fly:CreateToggle({Name = 'Sigrid', Function = function(callback) if SigridSpeed and SigridSpeed.Object then SigridSpeed.Object.Visible = callback end end})
    SigridSpeed = Fly:CreateSlider({Name = 'Sigrid Speed', Min = 1, Max = 80, Default = 30, Suffix = ' studs/s', Darker = true, Visible = false})
    GrimKit = Fly:CreateToggle({Name = 'Grim Reaper', Function = function(callback) if GrimSpeed and GrimSpeed.Object then GrimSpeed.Object.Visible = callback end end})
    GrimSpeed = Fly:CreateSlider({Name = 'Grim Reaper Speed', Min = 1, Max = 80, Default = 37, Suffix = ' studs/s', Darker = true, Visible = false})
    ZephyrKit = Fly:CreateToggle({Name = 'Zephyr', Function = function(callback) if ZephyrSpeed and ZephyrSpeed.Object then ZephyrSpeed.Object.Visible = callback end end})
    ZephyrSpeed = Fly:CreateSlider({Name = 'Zephyr Speed', Min = 1, Max = 80, Default = 30, Suffix = ' studs/s', Darker = true, Visible = false})
    VerticalValue = Fly:CreateSlider({
        Name = 'Vertical Speed',
        Min = 1,
        Max = 150,
        Default = 50,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    WallCheck = Fly:CreateToggle({
        Name = 'Wall Check',
        Default = true
    })
    PopBalloons = Fly:CreateToggle({
        Name = 'Pop Balloons',
        Default = true
    })
    TP = Fly:CreateToggle({
        Name = 'TP Down',
        Default = true
    })
end)

run(function()
    local Mode
    local Expand
    local objects, set = {}

    local function createHitbox(ent)
        if ent.Targetable and ent.Player then
            local hitbox = Instance.new('Part')
            hitbox.Size = Vector3.new(3, 6, 3) + Vector3.one * (Expand.Value / 5)
            hitbox.Position = ent.RootPart.Position
            hitbox.CanCollide = false
            hitbox.Massless = true
            hitbox.Transparency = 1
            hitbox.Parent = ent.Character
            local weld = Instance.new('Motor6D')
            weld.Part0 = hitbox
            weld.Part1 = ent.RootPart
            weld.Parent = hitbox
            objects[ent] = hitbox
        end
    end

    HitBoxes = vape.Categories.Blatant:CreateModule({
        Name = 'HitBoxes',
        Function = function(callback)
            if callback then
                if Mode.Value == 'Sword' then
                    debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, (Expand.Value / 3))
                    set = true
                else
                    HitBoxes:Clean(entitylib.Events.EntityAdded:Connect(createHitbox))
                    HitBoxes:Clean(entitylib.Events.EntityRemoving:Connect(function(ent)
                        if objects[ent] then
                            objects[ent]:Destroy()
                            objects[ent] = nil
                        end
                    end))
                    for _, ent in entitylib.List do
                        createHitbox(ent)
                    end
                end
            else
                if set then
                    debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, 3.8)
                    set = nil
                end
                for _, part in objects do
                    part:Destroy()
                end
                table.clear(objects)
            end
        end,
        Tooltip = 'Expands attack hitbox'
    })
    Mode = HitBoxes:CreateDropdown({
        Name = 'Mode',
        List = {'Sword', 'Player'},
        Function = function()
            if HitBoxes.Enabled then
                HitBoxes:Toggle()
                HitBoxes:Toggle()
            end
        end,
        Tooltip = 'Sword - Increases the range around you to hit entities\nPlayer - Increases the players hitbox'
    })
    Expand = HitBoxes:CreateSlider({
        Name = 'Expand amount',
        Min = 0,
        Max = 14.4,
        Default = 14.4,
        Decimal = 10,
        Function = function(val)
            if HitBoxes.Enabled then
                if Mode.Value == 'Sword' then
                    debug.setconstant(bedwars.SwordController.swingSwordInRegion, 6, (val / 3))
                else
                    for _, part in objects do
                        part.Size = Vector3.new(3, 6, 3) + Vector3.one * (val / 5)
                    end
                end
            end
        end,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
end)


run(function()
    local InstantKill
    local Mode
    local Range
    local Place

    local function getTurret(localPosition)
        for _, v in store.blocks do
            if v.Name == 'camera_turret' and v:GetAttribute('PlacedByUserId') == lplr.UserId and (localPosition - v.Position).Magnitude <= 30 then
                return v
            end
        end
        return nil
    end

    local function getPlacedPosition(pos)
        for _, v in {Vector3.new(3, 0, 0), Vector3.new(0, 0, 3)} do
            for i = 1, 10 do
                local ray = workspace:Blockcast(CFrame.new(pos + (v * i)), Vector3.new(3, 3, 3), Vector3.new(0, -30, 0), store.airRay)
                if ray and not getPlacedBlock(ray.Position) then
                    return roundPos(ray.Position)
                end
            end
        end
        return
    end

    InstantKill = vape.Categories.Blatant:CreateModule({
        Name = 'InstantKill',
        Function = function(callback)
            if callback then
                repeat task.wait() until store.matchState ~= 0 or not InstantKill.Enabled
                if not InstantKill.Enabled then return end
                if store.equippedKit ~= 'vulcan' then
                    notif('InstantKill', 'You need vulcan equipped for this!', 8, 'warning')
                    return
                end

                local delay, pickups = 0, {}
                repeat
                    if entitylib.isAlive and tick() > delay then
                        local localPosition = entitylib.character.RootPart.Position
                        local ent = entitylib.EntityPosition({
                            Origin = localPosition,
                            Range = Range.Value,
                            Part = 'RootPart',
                            Players = true,
                            Wallcheck = true,
                            Sort = sortmethods.Health,
                        })
                        if ent then
                            local turret = getTurret(localPosition)
                            local tablet = getItem('tablet')
                            if not turret and Place.Enabled then
                                local pos = getPlacedPosition(localPosition)
                                local item = getItem('camera_turret')
                                if pos and item then
                                    bedwars.placeBlock(pos, 'camera_turret', false)
                                    turret = getPlacedPosition(pos)
                                    if turret then
                                        table.insert(pickups, turret)
                                    end
                                end
                            end
                            if turret and tablet then
                                switchItem(tablet.tool)
                                for i = 1, 12 do
                                    task.spawn(function()
                                        bedwars.Client:Get('VulcanArtilleryMark'):CallServer(ent.Player)
                                    end)
                                end
                                delay = tick() + 2
                            end
                        end
                    end
                    if Mode.Value == 'On bind' then
                        if #pickups > 0 then
                            task.wait(0.1)
                            for _, v in pickups do

                            end
                        end
                        InstantKill:Toggle()
                        break
                    end
                    task.wait(0.1)
                until not InstantKill.Enabled
            end
        end,
        Tooltip = 'Automatically uses turret to instant kill targets'
    })

    Mode = InstantKill:CreateDropdown({
        Name = 'Mode',
        List = {'Toggle', 'On bind'},
        Default = 'Toggle'
    })
    Range = InstantKill:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 100,
        Default = 50,
        Suffix = function(val)
            return val <= 1 and 'stud' or 'studs'
        end
    })
    Place = InstantKill:CreateToggle({
        Name = 'Auto place',
        Tooltip = 'Automatically places turrets if can\'t find any on ground',
        Default = true
    })
end)

