--[[
    Kit extenders

    Four modules, one per kit mobility ability: JadeExtender, VoidRegentExtender, CatExtender
    and YuziExtender. Each hooks the single controller method that performs its ability and
    pushes the character on with an extra impulse the moment that method fires.

    Hooking the controller (rather than watching velocity or ability cooldowns) is what makes
    this exact: the impulse lands on the frame the game itself performs the move, so it can
    never fire on knockback, an explosion or a hotbar change, and an ability the server
    refuses never produces one either.

    They share `createKitExtender` below because only four things actually differ between
    them - the controller, the method, the kit and the impulse - but each is registered as its
    own module with its own Multiplier, so one of them failing to register cannot take the
    other three out with it.
]]

-- `spec` is everything that differs between the four:
--   Name       - module name.
--   Kit        - store.equippedKit value the ability belongs to.
--   Controller - field on `bedwars` holding the controller to hook.
--   Method     - method on that controller which performs the move.
--   Argument   - index into the call's arguments holding the move direction, when it takes one.
--   Impulse    - (root, direction, multiplier) -> impulse to apply, or nil to apply none.
--   Tooltip    - module tooltip.
local function createKitExtender(spec)
    local Extender
    local Multiplier
    local controller, original, hooked

    -- Kit controllers are built when the match starts, so a module switched on in the lobby
    -- has nothing to hook yet: wait for it rather than give up, and stop the moment the module
    -- is switched off again.
    local function install()
        local target = bedwars[spec.Controller]
        while not target and Extender.Enabled do
            task.wait(0.1)
            target = bedwars[spec.Controller]
        end
        if not Extender.Enabled or not target then return end

        local method = target[spec.Method]
        if typeof(method) ~= 'function' then return end
        -- A second install racing the first (a fast off/on) would otherwise capture our own
        -- hook as `original`, and disabling would then restore the hook rather than the
        -- game's method.
        if hooked and method == hooked then return end

        controller, original = target, method
        hooked = function(...)
            -- Read out of the varargs here: the guarded block below is a closure, which
            -- cannot see `...` of the function it sits in.
			local direction = spec.Argument and select(spec.Argument, ...) or nil
			if spec.Argument and typeof(direction) ~= 'Vector3' then
				for index = 1, select('#', ...) do
					local candidate = select(index, ...)
					if typeof(candidate) == 'Vector3' then direction = candidate end
				end
			end
            local results = table.pack(method(...))

            if Extender.Enabled and entitylib.isAlive
				and (not spec.Argument or typeof(direction) == 'Vector3') then
				-- Controllers spend their cooldown before returning and several of them
				-- write velocity again at the end of the same frame. A deferred impulse
				-- therefore both proves the ability ran and cannot be overwritten by it.
				task.defer(function()
					pcall(function()
						if not Extender.Enabled or not entitylib.isAlive then return end
						local root = entitylib.character.RootPart
						local impulse = spec.Impulse(root, direction, Multiplier.Value)
						if impulse then root:ApplyImpulse(impulse) end
					end)
				end)
            end

            return table.unpack(results, 1, results.n)
        end

        controller[spec.Method] = hooked
    end

    Extender = kits:CreateModule({
        Name = spec.Name,
        Category = 'Ability',
        Function = function(callback)
            if callback then
                Extender:Clean(task.spawn(install))
            else
                -- Only put the method back if it is still ours; something else may have
                -- re-hooked it since, and restoring over that would undo their hook.
                if controller and original and controller[spec.Method] == hooked then
                    controller[spec.Method] = original
                end
                controller, original, hooked = nil, nil, nil
            end
        end,
        Tooltip = spec.Tooltip
    })

    Multiplier = Extender:CreateSlider({
        Name = 'Multiplier',
        Min = 1,
        Max = 5,
        Default = 2,
        Decimal = 10,
        Suffix = 'x',
        Tooltip = 'How much further than normal the ability carries you. 1x is the game\'s own distance'
    })

    return Extender
end

run(function()
    createKitExtender({
        Name = 'CatExtender',
        Kit = 'cat',
        Controller = 'CatController',
        Method = 'leap',
        -- leap(self, character, direction): the direction is the third argument.
        Argument = 3,
        Impulse = function(root, direction, multiplier)
            local flat = direction * Vector3.new(1, 0, 1)
            if flat.Magnitude <= 0 then return nil end
            return flat.Unit * root.AssemblyMass * (multiplier - 1) * 70
        end,
        Tooltip = 'Extends how far the Cat/Yamini pounce launches you'
    })
end)

run(function()
    local old

    vape.Categories.Blatant:CreateModule({
        Name = 'NoSlowdown',
        Function = function(callback)
            local modifier = bedwars.SprintController:getMovementStatusModifier()
            if callback then
                old = modifier.addModifier
                modifier.addModifier = function(self, tab)
                    if tab.moveSpeedMultiplier then
                        tab.moveSpeedMultiplier = math.max(tab.moveSpeedMultiplier, 1)
                    end
                    return old(self, tab)
                end

                for i in modifier.modifiers do
                    if (i.moveSpeedMultiplier or 1) < 1 then
                        modifier:removeModifier(i)
                    end
                end
            else
                modifier.addModifier = old
                old = nil
            end
        end,
        Tooltip = 'Prevents slowing down when using items'
    })
end)

run(function()
    local OwlAura
    local Targets
    local Range

    local function getProjectileMeta()
        local meta = table.clone(bedwars.ProjectileMeta.owl_projectile)
        return meta
    end

    OwlAura = kits:CreateModule({
        Name = 'OwlAura',
        Category = 'Aim',
        Function = function(callback)
            if callback then
                local owls = collection('Owl', OwlAura, function(self, obj)
                    task.delay(1, function()
                        if obj and obj.Parent and obj:GetAttribute('Owner') == lplr.UserId then
                            table.insert(self, obj)
                        end
                    end)
                end)
                repeat
                    if store.equippedKit ~= 'owl' then
                        task.wait(3)
                        continue
                    end

                    if entitylib.isAlive then
                        local owl = owls[1]
                        if owl then
                            local origin = owl.Part.Position
                            local plr = entitylib.EntityPosition({
                                Origin = origin,
                                Range = Range.Value,
                                Part = 'RootPart',
                                Players = Targets.Players.Enabled,
                                NPCs = Targets.NPCs.Enabled,
                                Wallcheck = Targets.Walls.Enabled,
                                Sort = sortmethods.Health,
                            })

                            if plr then
                                local meta = getProjectileMeta()
                                local calc = prediction.SolveTrajectory(origin, meta.launchVelocity, meta.gravitationalAcceleration, plr.RootPart.Position, plr.RootPart.Velocity, workspace.Gravity, plr.HipHeight, plr.Jumping and 42.6 or nil)
                                if calc then
                                    local dir = CFrame.lookAt(origin, calc).LookVector * meta.launchVelocity
                                    bedwars.Client:Get('OwlAiming'):SendToServer({
                                        owl = owl.Part,
                                        starting = true,
                                    })
                                    bedwars.Client:Get('OwlFireProjectile'):SendToServer({
                                        ProjectileRefId = vape.Libraries.string:GenerateString(8),
                                        direction = dir,
                                        fromPosition = origin,
                                        initialVelocity = dir,
                                    })
                                    task.wait(lplr:GetNetworkPing())
                                end
                            end
                        end
                    end
                    task.wait(0.1)
                until not OwlAura.Enabled
            else
                bedwars.Client:Get('OwlAiming'):SendToServer({
                    starting = false,
                })
            end
        end,
        Tooltip = 'Automatically shoots projectiles with whisper kit'
    })

    Targets = OwlAura:CreateTargets({
        Players = true,
        Wallcheck = true,
    })
    Range = OwlAura:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 50,
        Suffix = function(val)
            return val <= 0 and 'stud' or 'studs'
        end,
        Default = 50,
    })
end)

run(function()
    local PlayerAttach
    local Range
    local Targets

    local rayCheck = RaycastParams.new()
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude

    PlayerAttach = vape.Categories.Blatant:CreateModule({
        Name = 'PlayerAttach',
        Tooltip = 'Attachs you to the nearest target',
        Function = function(call)
            if call then
                repeat
                    if entitylib.isAlive then
                        local plr = entitylib.AllPosition({
                            Range = Range.Value,
                            Wallcheck = Targets.Walls.Enabled or nil,
                            Part = 'RootPart',
                            Players = Targets.Players.Enabled,
                            NPCs = Targets.NPCs.Enabled,
                            Limit = 1,
                            Sort = function(a, b)
                                return a.Entity.Health < b.Entity.Health
                            end
                        })[1]
                        if plr then
                            rayCheck.FilterDescendantsInstances = {plr.RootPart.Parent, lplr.Character}

                            entitylib.character.RootPart.AssemblyLinearVelocity = Vector3.new(0, entitylib.character.RootPart.Size.Y / 2 + entitylib.character.Humanoid.HipHeight + 0.25 * 3, 0)
                            entitylib.character.RootPart.CFrame = plr.RootPart.CFrame + (not workspace:Raycast(plr.RootPart.Position, plr.RootPart.CFrame.LookVector, rayCheck) and (plr.RootPart.CFrame.LookVector * 1.4) or Vector3.zero)
                        end
                    end
                    task.wait()
                until not PlayerAttach.Enabled
            end
        end
    })

    Targets = PlayerAttach:CreateTargets({
        Players = true,
        NPCs = true
    })

    Range = PlayerAttach:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 35,
        Default = 23,
        Suffix = function(val)
            return val <= 1 and 'stud' or 'studs'
        end
    })
end)

run(function()
	local Blacklist
	local TargetPart
	local Targets
	local Sort
	local FOV
	local AutoCharge
	local Aim = {}
	local OtherProjectiles
	local MaxAccuracy
	local maxAccuracyScale = 1
	local maxAccuracyGeneration = 0
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Include
	rayCheck.FilterDescendantsInstances = {workspace:FindFirstChild('Map')}
	local launchHook

	local ProjectileAimbot = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAimbot',
		Function = function(callback)
			if callback then
				if vape.Modules.SilentAim and vape.Modules.SilentAim.Enabled then vape.Modules.SilentAim:Toggle() end
				launchHook = bedwars.ProjectileLaunchHook:Add('ProjectileAimbot', 12, function(nextLaunch, ...)
					local launch = nextLaunch(...)
					local projmeta, worldmeta = select(2, ...), select(3, ...)
					if type(launch) ~= 'table' or typeof(launch.positionFrom) ~= 'Vector3'
						or typeof(launch.initialVelocity) ~= 'Vector3' or not projmeta then return launch end
					local projectileType = tostring(projmeta.projectile or '')
					if projectileType == '' or ((not OtherProjectiles.Enabled) and not projectileType:find('arrow')) then return launch end
					local blacklistName = (projectileType == 'glue_trap' or projectileType == 'glue_projectile') and 'gloop' or projectileType
					if table.find(Blacklist.ListEnabled or {}, blacklistName) then return launch end

					local origin = launch.positionFrom
					local plr = entitylib.EntityMouse({
						Part = 'RootPart',
						Range = FOV.Value,
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Wallcheck = Targets.Walls.Enabled,
						Origin = origin,
						Sort = sortmethods[Sort.Value]
					})
					if plr then
						local targetPart = plr[TargetPart.Value]
						if not targetPart or not targetPart.Parent then return launch end
						local ok, meta = pcall(projmeta.getProjectileMeta, projmeta)
						meta = ok and meta or bedwars.ProjectileMeta[projectileType]
						if type(meta) ~= 'table' then return launch end
						local lifetime = (worldmeta and meta.predictionLifetimeSec or meta.lifetimeSec or 3)
						local gravity = launch.gravitationalAcceleration or ((meta.gravitationalAcceleration or 196.2) * (projmeta.gravityMultiplier or 1))
						local fullSpeed = tonumber(meta.launchVelocity) or launch.initialVelocity.Magnitude
						local speed = (AutoCharge.Enabled or not Aim.Enabled) and fullSpeed or launch.initialVelocity.Magnitude
						local solution = solveBedwarsProjectile(origin, speed, gravity, plr, targetPart.Position, {
							Lifetime = lifetime,
							PredictionScale = maxAccuracyScale,
							Stationary = projectileType == 'telepearl',
							RaycastParams = rayCheck
						})
						if solution then
							targetinfo.Targets[plr] = tick() + 1
							launch.initialVelocity = solution.Velocity
							launch.positionFrom = origin
							launch.deltaT = lifetime
							launch.gravitationalAcceleration = gravity
							if AutoCharge.Enabled then launch.drawDurationSeconds = 5 end
						end
					end
					return launch
				end)
				ProjectileAimbot:Clean(function()
					if launchHook then launchHook(); launchHook = nil end
				end)
			elseif launchHook then
				launchHook()
				launchHook = nil
			end
		end,
		Tooltip = 'Silently adjusts your aim towards the enemy'
	})
	Targets = ProjectileAimbot:CreateTargets({
		Players = true,
		Walls = true
	})
	local methods = {'Distance', 'Damage'}
	for i in sortmethods do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end
	Sort = ProjectileAimbot:CreateDropdown({
		Name = 'Target mode',
		List = methods,
		Default = 'Distance'
	})
	TargetPart = ProjectileAimbot:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head'}
	})
	MaxAccuracy = ProjectileAimbot:CreateToggle({
		Name = 'Max accuracy',
		Tooltip = 'Changes prediction based on ping to give you the most accurate shots',
		Function = function(callback)
			maxAccuracyGeneration += 1
			local generation = maxAccuracyGeneration
			if callback then
				MaxAccuracy:Clean(task.spawn(function()
					repeat
						maxAccuracyScale = math.clamp(1 - lplr:GetNetworkPing(), 0.1, 1)
						task.wait(1)
					until not MaxAccuracy.Enabled or generation ~= maxAccuracyGeneration
				end))
			else
				maxAccuracyScale = 1
			end
		end
	})
	FOV = ProjectileAimbot:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000
	})
	AutoCharge = ProjectileAimbot:CreateToggle({
		Name = 'Auto Charge',
		Function = function(callback)
			if Aim.Object then
				Aim.Object.Visible = callback
			end
		end,
		Default = true,
		Tooltip = 'Fully charges your bow, Allowing your projectile to deal more damage'
	})
	Aim = ProjectileAimbot:CreateToggle({
		Name = 'Aim change',
		Default = true,
		Darker = true,
		Tooltip = 'Changes your trajectory to match charge percentage.'
	})
	OtherProjectiles = ProjectileAimbot:CreateToggle({
		Name = 'Other Projectiles',
		Default = true
	})
	Blacklist = ProjectileAimbot:CreateTextList({
		Name = 'Blacklist',
		Default = {'telepearl'}
	})
end)

run(function()
	local SilentAim
	local Targets
	local TargetPart
	local Sort
	local Prediction
	local FOV
	local OtherProjectiles
	local Blacklist

	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Include
	rayCheck.FilterDescendantsInstances = {workspace:FindFirstChild('Map')}

	local launchHook

	local function getMousePosition()
		if inputService.TouchEnabled then
			return gameCamera.ViewportSize / 2
		end
		return inputService.GetMouseLocation(inputService)
	end

	local function getPosition(ent)
		if TargetPart.Value == 'Closest' then
			local localPosition, magnitude, part = getMousePosition(), 9e9, nil
			for _, v in ent:GetChildren() do
				if v:IsA('BasePart') then
					local position, vis = gameCamera.WorldToViewportPoint(gameCamera, v.Position)
					if vis then
						local mag = (localPosition - Vector2.new(position.x, position.y)).Magnitude
						if mag < magnitude then
							magnitude = mag
							part = v
						end
					end
				end
			end
			return part and part.Position or ent.PrimaryPart and ent.PrimaryPart.Position
		elseif TargetPart.Value == 'Dynamic' then
			local tool = store.hand.tool
			if tool and tool.Name:find('headhunter') and ent:FindFirstChild('Head') then
				return ent.Head.Position
			end
			return ent.PrimaryPart and ent.PrimaryPart.Position
		end
		return
	end

	local function solveSilent(launch, launchMeta)
		local origin = launch and launch.positionFrom
		local velocity = launch and launch.initialVelocity
		local projType = launchMeta and launchMeta.projectile
		if typeof(origin) ~= 'Vector3' or typeof(velocity) ~= 'Vector3' or type(projType) ~= 'string' then
			return
		end

		if (not OtherProjectiles.Enabled) and not projType:find('arrow') then
			return
		end

		if table.find(Blacklist.ListEnabled or {}, ((projType == 'glue_trap' or projType == 'glue_projectile') and 'gloop' or projType)) then
			return
		end

		local meta = launchMeta.getProjectileMeta and launchMeta:getProjectileMeta() or bedwars.ProjectileMeta[projType]
		if not meta then return end

		local speed = velocity.Magnitude
		if speed <= 0 then return end
		local gravity = launch.gravitationalAcceleration or meta.gravitationalAcceleration or 196.2

		local plr = entitylib.EntityMouse({
			Part = 'RootPart',
			Range = FOV.Value,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled,
			Sort = sortmethods[Sort.Value or 'Distance'],
			Origin = origin,
		})
		if not plr then return end

		local targetpart = plr[TargetPart.Value]
		local targetpos = getPosition(plr.Character) or targetpart and targetpart.Position
		if not targetpos then return end
		local pearl = projType == 'telepearl'
		local solution = solveBedwarsProjectile(origin, speed, gravity, plr, targetpos, {
			Lifetime = launch.deltaT or meta.lifetimeSec or 3,
			PredictionScale = Prediction.Value,
			Stationary = pearl,
			RaycastParams = rayCheck
		})
		if not solution then return end

		targetinfo.Targets[plr] = tick() + 1
		return solution.Velocity
	end

	SilentAim = vape.Categories.Combat:CreateModule({
		Name = 'SilentAim',
		Function = function(callback)
			if callback then
				if vape.Modules.ProjectileAimbot and vape.Modules.ProjectileAimbot.Enabled then
					notif('SilentAim', 'Disable ProjectileAimbot before enabling SilentAim.', 5, 'warning')
					SilentAim:Toggle()
					return
				end
				launchHook = bedwars.ProjectileLaunchHook:Add('SilentAim', 15, function(nextLaunch, ...)
					local launch = nextLaunch(...)
					-- ProjectileAimbot is the stronger explicit aim module; do not overwrite its result.
					if not (vape.Modules.ProjectileAimbot and vape.Modules.ProjectileAimbot.Enabled) then
						local velocity = solveSilent(launch, select(2, ...))
						if velocity then launch.initialVelocity = velocity end
					end
					return launch
				end)
				SilentAim:Clean(function()
					if launchHook then launchHook(); launchHook = nil end
				end)
			elseif launchHook then
				launchHook()
				launchHook = nil
			end
		end,
		Tooltip = 'Redirects projectile launch velocity toward the selected target without intercepting or blocking projectile remotes'
	})
	Targets = SilentAim:CreateTargets({
		Players = true,
		Walls = true,
	})
	TargetPart = SilentAim:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Dynamic', 'Closest'},
	})
	local methods = {'Damage', 'Distance'}
	for i in sortmethods do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end
	Sort = SilentAim:CreateDropdown({
		Name = 'Target Mode',
		List = methods,
		Default = 'Distance'
	})
	Prediction = SilentAim:CreateSlider({
		Name = 'Prediction',
		Min = 0.1,
		Max = 2,
		Default = 1,
		Decimal = 10
	})
	FOV = SilentAim:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000
	})
	OtherProjectiles = SilentAim:CreateToggle({
		Name = 'Other Projectiles',
		Function = function(call)
			if Blacklist and Blacklist.Object then
				Blacklist.Object.Visible = call
			end
		end,
	    Default = true
	})
	Blacklist = SilentAim:CreateTextList({
		Name = 'Blacklist',
		Default = {'gloop', 'telepearl'},
		Darker = true,
		Placeholder = 'projectile'
	})
end)

run(function()
	local ProjectileAura
	local Targets
	local FireRate
	local Range
	local List
	local UseSophia
	local UseWhim
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Exclude
	local projectileRemote
	local FireDelays = {}
	local generation = 0

	local function getProjectileRemote()
		if projectileRemote and type(projectileRemote.InvokeServer) == 'function' then return projectileRemote end
		local ok, remote = pcall(function()
			local handler = bedwars.Handler:Get('ProjectileFire')
			return handler and handler.Remote and handler.Remote.instance
		end)
		if not ok or not remote then
			ok, remote = pcall(function() return bedwars.Client:Get(remotes.FireProjectile).instance end)
		end
		if ok and remote and type(remote.InvokeServer) == 'function' then projectileRemote = remote end
		return projectileRemote
	end

	ProjectileAura = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAura',
		Function = function(callback)
			generation += 1
			if not callback then return end
			local token = generation
			repeat
				if (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) > 0.3 and entitylib.isAlive then
					local ent = entitylib.EntityPosition({
						Part = 'RootPart',
						Range = Range.Value,
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Wallcheck = Targets.Walls.Enabled
					})
					local remote = ent and getProjectileRemote()
					if ent and ent.RootPart and remote then
						local rootPosition = entitylib.character.RootPart.Position
						for _, data in getProjectiles(List.ListEnabled, UseSophia.Enabled, UseWhim.Enabled) do
							if token ~= generation or not ProjectileAura.Enabled then break end
							local item, ammo, projectile, source, meta = unpack(data)
							local now = workspace:GetServerTimeNow()
							if item.tool and item.tool.Parent and (FireDelays[item.itemType] or 0) <= now then
								rayCheck.FilterDescendantsInstances = {lplr.Character, ent.Character, gameCamera}
								local speed = meta.launchVelocity
								local first = solveBedwarsProjectile(rootPosition, speed, meta.gravitationalAcceleration, ent, ent.RootPart.Position, {
									RaycastParams = rayCheck,
									Lifetime = meta.lifetimeSec or 3
								})
								local shootPosition = first and projectileLaunchOrigin(rootPosition, first.Velocity)
								local solution = shootPosition and solveBedwarsProjectile(shootPosition, speed, meta.gravitationalAcceleration, ent, ent.RootPart.Position, {
									RaycastParams = rayCheck,
									Lifetime = meta.lifetimeSec or 3
								})
								if solution then
									switchItem(item.tool, 0)
									FireDelays[item.itemType] = now + (source.fireDelaySec or 0) + FireRate:GetRandomValue()
									task.spawn(function()
										if token ~= generation or not ProjectileAura.Enabled or not item.tool.Parent then return end
										local velocity = solution.Velocity
										local id = httpService:GenerateGUID(true)
										local draw = {drawDurationSeconds = 1, shotId = httpService:GenerateGUID(false)}
										pcall(bedwars.ProjectileController.createLocalProjectile, bedwars.ProjectileController, meta, ammo, projectile, shootPosition, id, velocity, draw)
										local ok, result = pcall(remote.InvokeServer, remote, item.tool, ammo, projectile, shootPosition, rootPosition, velocity, id, draw, workspace:GetServerTimeNow() - 0.045)
										if token ~= generation or not ProjectileAura.Enabled then return end
										if ok and result ~= false then
											store.lastProjectileFire = workspace:GetServerTimeNow()
											targetinfo.Targets[ent] = tick() + 1
											prediction.trackShot(ent.RootPart)
											local sounds = source.launchSound
											local sound = type(sounds) == 'table' and #sounds > 0 and sounds[math.random(1, #sounds)] or nil
											if sound then pcall(bedwars.SoundManager.playSound, bedwars.SoundManager, sound) end
										else
											FireDelays[item.itemType] = workspace:GetServerTimeNow()
										end
									end)
									task.wait(FireRate:GetRandomValue())
								end
							end
						end
					end
				end
				task.wait(0.03)
			until not ProjectileAura.Enabled or token ~= generation
		end,
		Tooltip = 'Shoots people around you'
	})
	Targets = ProjectileAura:CreateTargets({
		Players = true,
		Walls = true
	})
	List = ProjectileAura:CreateTextList({
		Name = 'Projectiles',
		Default = {'arrow', 'snowball'}
	})
	UseSophia = ProjectileAura:CreateToggle({
		Name = 'Use sophia',
		Tooltip = 'Also shoots sophia\'s frost staff, swapping it out of mist mode on its own'
	})
