run(function()
    local ItemESP
    local Distance
    local Transparency
    local Scale
    local WhitelistOnly
    local Whitelist = {ListEnabled = {}, Object = nil}

    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui

    local Reference, Strings, Sizes = {}, {}, {}

    local function Added(ent)
	local Name = bedwars.ItemMeta[ent.Name] and bedwars.ItemMeta[ent.Name].displayName or ent.Name
	if WhitelistOnly.Enabled and not table.find(Whitelist.ListEnabled, Name:lower()) then
		return
	end

	Strings[ent] = Name .. '%s'
	if Distance.Enabled then
		Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '.. Strings[ent]
	end

	local nametag = Instance.new('TextLabel')
	nametag.TextSize = 14 * Scale.Value
	nametag.Font = Enum.Font.Arial
	local size = getfontsize(removeTags(ent.Name), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
	nametag.Name = ent.Name
	nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
	nametag.AnchorPoint = Vector2.new(0.5, 1)
	nametag.BackgroundColor3 = Color3.new()
	nametag.BackgroundTransparency = 0.5
	nametag.BorderSizePixel = 0
	nametag.Visible = false
	local amount = ent:GetAttribute('Amount') or 1
	local suffix = amount >= 2 and ' x' .. tostring(amount) or ''
	nametag.Text = Distance.Enabled and string.format(Strings[ent], 0, suffix) or string.format(Strings[ent], suffix)
	nametag.TextColor3 = Color3.new(1, 1, 1)
	nametag.RichText = true
	nametag.Parent = Folder
	Reference[ent] = nametag
    end
    local function Updated(ent)
	if Reference[ent] then
		Reference[ent].TextSize = 14 * Scale.Value
		Reference[ent].BackgroundTransparency = Transparency.Value
	end
    end
    local function Removing(ent)
	if Reference[ent] then
		Reference[ent]:Destroy()
		Reference[ent] = nil
	end
    end

    ItemESP = vape.Categories.Render:CreateModule({
	Name = 'ItemESP',
	Function = function(call)
		if call then
			ItemESP:Clean(collectionService:GetInstanceAddedSignal('ItemDrop'):Connect(Added))
			ItemESP:Clean(collectionService:GetInstanceRemovedSignal('ItemDrop'):Connect(Removing))
			ItemESP:Clean(runService.PreRender:Connect(function()
				for ent, nametag in Reference do
					local headPos, headVis = gameCamera:WorldToViewportPoint(ent.Position + Vector3.new(0, 1, 0))
					nametag.Visible = headVis
					if not headVis then
						continue
					end

					local amount = ent:GetAttribute('Amount') or 1
					local mag = Distance.Enabled and entitylib.isAlive
						and math.floor((entitylib.character.RootPart.Position - ent.Position).Magnitude) or nil
					local cache = tostring(mag or '') .. ':' .. tostring(amount)
					if Sizes[ent] ~= cache then
						local suffix = amount >= 2 and ' x' .. tostring(amount) or ''
						nametag.Text = Distance.Enabled and string.format(Strings[ent], mag or 0, suffix)
							or string.format(Strings[ent], suffix)
						local size = getfontsize(removeTags(nametag.Text), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
						nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
						Sizes[ent] = cache
					end
					nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
				end
			end))

			for _, v in collectionService:GetTagged('ItemDrop') do
				Added(v)
			end
		else
			for i in Reference do
				Removing(i)
			end
		end
	end,
	Tooltip = 'Renders tags dropped items'
    })
    Distance = ItemESP:CreateToggle({
	Name = 'Distance',
	Tooltip = 'Shows the distance of the item',
	Function = function(callback)
		if ItemESP.Enabled then
			for ent in Reference do
				local Name = bedwars.ItemMeta[ent.Name] and bedwars.ItemMeta[ent.Name].displayName or ent.Name
				Strings[ent] = callback and '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '.. Strings[ent] or Name.. '%s'
			end
		end
	end
    })
    ItemESP:CreateToggle({
	Name = 'Group items',
	Tooltip = 'Group items into easier to read tags'
    })
    Transparency = ItemESP:CreateSlider({
	Name = 'Transparency',
	Function = function()
		if ItemESP.Enabled then
			for ent in Reference do
				Updated(ent)
			end
		end
	end,
	Default = 0.5,
	Min = 0,
	Max = 1,
	Decimal = 100
    })
    Scale = ItemESP:CreateSlider({
	Name = 'Scale',
	Default = 1,
	Min = 0.1,
	Max = 1.5,
	Decimal = 10,
	Function = function()
		if ItemESP.Enabled then
			for ent in Reference do
				Updated(ent)
			end
		end
	end
    })
    WhitelistOnly = ItemESP:CreateToggle({
	Name = 'Whitelist Only',
	Tooltip = 'Only renders whitelisted items',
	Function = function(call)
		if Whitelist.Object then
			Whitelist.Object.Visible = call

			if ItemESP.Enabled then
				ItemESP:Toggle()
				ItemESP:Toggle()
			end
		end
	end
    })
    Whitelist = ItemESP:CreateTextList({
	Name = 'Allowed items',
	Visible = false,
	Darker = true,
	Function = function()
		if ItemESP.Enabled then
			ItemESP:Toggle()
			ItemESP:Toggle()
		end
	end
    })
end)

run(function()
    local KitDisplay

    local function getKitMeta(player)
	local kit = player:GetAttribute('PlayingAsKits') or player:GetAttribute('PlayingAsKit') or 'none'
	return bedwars.BedwarsKitMeta[kit] or bedwars.BedwarsKitMeta.none
    end

    local function getPlayerFromDraft(render, name)
	local id = render and render:match('id=(%d+)')
	if id then
		local player = playersService:GetPlayerByUserId(tonumber(id))
		if player then
			return player
		end
	end

	for _, v in playersService:GetPlayers() do
		if render and render:find('id=' .. v.UserId, 1, true) then
			return v
		end

		if name and (v.Name == name or v.DisplayName == name or v:GetAttribute('DisguiseDisplayName') == name) then
			return v
		end

		local displayName
		pcall(function()
			displayName = bedwars.StreamerModeController:getDisplayName(v)
		end)
		if name and displayName == name then
			return v
		end
	end
	return nil
    end

    local waitForChild = function(start, ...)
	local parent = start
	for _, v in {...} do
		parent = parent and parent:WaitForChild(v, 5)
		if not parent then
			break
		end
	end
	return parent
    end

    local function getPlayerName(card)
	local textbar = card and card:FindFirstChild('TextBackgroundBar')
	local label = textbar and textbar:FindFirstChild('PlayerName') or card and card:FindFirstChild('PlayerName', true)
	return label and label.Text or ''
    end

    local function getDraftCard(container)
	if not container then
		return
	end
	return container.Name == 'MatchDraftPlayerCard' and container or container:FindFirstChild('MatchDraftPlayerCard', true)
    end

    local function callback5v5(v, plr)
	if not v then
		return
	end
	local render = v:FindFirstChild('PlayerRender', true)
	local player = plr or getPlayerFromDraft(render and render.Image or '', getPlayerName(v))

	if player then
		local kitImage = getKitMeta(player)
		local roact = v:FindFirstChild('KitImage')

		if not roact then
			roact = Instance.new('ImageLabel', v)
			roact.BackgroundTransparency = 1
			roact.AnchorPoint = Vector2.new(1, 0.5)
			roact.Position = UDim2.fromScale(1.05, 0.5)
			roact.Name = 'KitImage'
			roact.Size = UDim2.fromScale(1.5, 1.5)
			roact.ZIndex = 1
			roact.ImageTransparency = 0.4
			roact.SliceCenter = Rect.new(0, 0, 0, 0)
			roact.SliceScale = 1
			roact.ScaleType = Enum.ScaleType.Crop

			KitDisplay:Clean(roact)

			local ratio = Instance.new('UIAspectRatioConstraint', roact)
			ratio.Name = '1'
			ratio.AspectRatio = 1
			ratio.AspectType = Enum.AspectType.FitWithinMaxSize
			ratio.DominantAxis = Enum.DominantAxis.Width
		end

		roact.Image = kitImage.renderImage
		roact.Position = UDim2.fromScale(1.05, 0)
		tweenService:Create(roact, TweenInfo.new(0.2, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {Position = UDim2.fromScale(1.05, 0.4)}):Play()

		local function update()
			kitImage = getKitMeta(player)
			roact.Image = kitImage.renderImage
		end

		KitDisplay:Clean(player:GetAttributeChangedSignal('PlayingAsKits'):Connect(update))
		KitDisplay:Clean(player:GetAttributeChangedSignal('PlayingAsKit'):Connect(update))
	end
    end

    local function callbacksquad(v)
	if not v then
		return
	end
	local render = v:FindFirstChild('PlayerRender', true)
	local player = render and getPlayerFromDraft(render.Image, '') or nil

	if player then
		local kitImage = getKitMeta(player)
		local Roact = v:FindFirstChild('Kitcvrender')

		if not Roact then
			local base = v:FindFirstChild('3') or v:WaitForChild('3', 5)
			if not base then
				return
			end
			Roact = base:Clone()
			Roact.Parent = v
			Roact.Name = 'Kitcvrender'
			KitDisplay:Clean(Roact)
		end

		Roact.Image = kitImage.renderImage

		KitDisplay:Clean(render:GetPropertyChangedSignal('Image'):Connect(function()
			local newplayer = getPlayerFromDraft(render.Image, '')
			if newplayer then
				player = newplayer
				kitImage = getKitMeta(player)
				Roact.Image = kitImage.renderImage
			end
		end))

		local function update()
			kitImage = getKitMeta(player)
			Roact.Image = kitImage.renderImage
		end

		KitDisplay:Clean(player:GetAttributeChangedSignal('PlayingAsKits'):Connect(update))
		KitDisplay:Clean(player:GetAttributeChangedSignal('PlayingAsKit'):Connect(update))
	end
    end

    local function setup5v5(DraftApp)
	local Background = DraftApp:FindFirstChild('DraftAppBackground')
	local BodyContainer = Background and Background:FindFirstChild('1') and Background['1']:FindFirstChild('BodyContainer')
	local hooked = false

	for i = 1, 2 do
		local dtc = BodyContainer and BodyContainer:FindFirstChild('Team' .. i .. 'Column')
		if dtc then
			hooked = true
			KitDisplay:Clean(dtc.ChildAdded:Connect(function(child)
				task.delay(0.2, function()
					if KitDisplay.Enabled then
						callback5v5(getDraftCard(child))
					end
				end)
			end))

			for _, v in dtc:GetChildren() do
				if v:IsA('Frame') then
					callback5v5(getDraftCard(v))
				end
			end
		end
	end

	if not hooked then
		for _, label in DraftApp:GetDescendants() do
			if label:IsA('TextLabel') and label.Name == 'PlayerName' then
				local container = label.Parent
				for _ = 1, 3 do
					container = container and container.Parent
				end
				if container then
					callback5v5(getDraftCard(container))
				end
			end
		end

		KitDisplay:Clean(DraftApp.DescendantAdded:Connect(function(child)
			if child:IsA('TextLabel') and child.Name == 'PlayerName' then
				task.delay(0.2, function()
					local container = child.Parent
					for _ = 1, 3 do
						container = container and container.Parent
					end
					if KitDisplay.Enabled and container then
						callback5v5(getDraftCard(container))
					end
				end)
			end
		end))
	end

	return hooked
    end

    local function setupSquad(DraftApp)
	local Background = DraftApp:FindFirstChild('DraftAppBackground')
	local BodyContainer = Background and Background:FindFirstChild('1') and Background['1']:FindFirstChild('BodyContainer')
	local TeamsColumn = BodyContainer and BodyContainer:FindFirstChild('TeamsColumn')
	if not TeamsColumn then
		return
	end

	for _, v: Instance in TeamsColumn:GetChildren() do
		if v:IsA('Frame') then
			local plrframe = waitForChild(v, '1', '2', '4')
			if plrframe then
				for _, plr in plrframe:GetChildren() do
					callbacksquad(plr)
				end

				KitDisplay:Clean(plrframe.ChildAdded:Connect(function(plr)
					KitDisplay:Toggle()
					KitDisplay:Toggle()
				end))
			end
		end
	end
    end

    KitDisplay = kits:CreateModule({
	Name = 'KitDisplay',
	Category = 'Visual',
	Function = function(call)
		if call then
			local DraftApp = lplr.PlayerGui:WaitForChild('MatchDraftApp', 9e9)
			setup5v5(DraftApp)
			setupSquad(DraftApp)
		end
	end,
	Tooltip = 'Allows you to see the other opponent kits'
    })
end)

run(function()
    local KitESP
    local Background
    local Color = {}
    local Reference = {}
    local kitGeneration = 0
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui

    local ESPKits = {
	alchemist = {'alchemist_ingedients', 'wild_flower'},
	beekeeper = {'bee', 'bee'},
	bigman = {'treeOrb', 'natures_essence_1'},
	ghost_catcher = {'ghost', 'ghost_orb'},
	metal_detector = {'hidden-metal', 'iron'},
	sheep_herder = {'SheepModel', 'purple_hay_bale'},
	sorcerer = {'alchemy_crystal', 'wild_flower'},
	star_collector = {'stars', 'crit_star'},
    }

    local function Added(v, icon)
	local billboard = Instance.new('BillboardGui')
	billboard.Parent = Folder
	billboard.Name = icon
	billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	billboard.Size = UDim2.fromOffset(36, 36)
	billboard.AlwaysOnTop = true
	billboard.ClipsDescendants = false
	billboard.Adornee = v
	local blur = addBlur(billboard)
	blur.Visible = Background.Enabled
	local image = Instance.new('ImageLabel')
	image.Size = UDim2.fromOffset(36, 36)
	image.Position = UDim2.fromScale(0.5, 0.5)
	image.AnchorPoint = Vector2.new(0.5, 0.5)
	image.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	image.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	image.BorderSizePixel = 0
	image.Image = bedwars.getIcon({ itemType = icon }, true)
	image.Parent = billboard
	local uicorner = Instance.new('UICorner')
	uicorner.CornerRadius = UDim.new(0, 4)
	uicorner.Parent = image
	Reference[v] = billboard
    end

    local function addKit(kitName, tag, icon)
	KitESP:Clean(collectionService:GetInstanceAddedSignal(tag):Connect(function(v)
		if store.equippedKit == kitName and v.PrimaryPart then Added(v.PrimaryPart, icon) end
	end))
	KitESP:Clean(collectionService:GetInstanceRemovedSignal(tag):Connect(function(v)
		if v.PrimaryPart and Reference[v.PrimaryPart] then
			Reference[v.PrimaryPart]:Destroy()
			Reference[v.PrimaryPart] = nil
		end
	end))
    end
	local function refreshKit()
		Folder:ClearAllChildren()
		table.clear(Reference)
		local kit = ESPKits[store.equippedKit]
		if not kit then return end
		for _, object in collectionService:GetTagged(kit[1]) do if object.PrimaryPart then Added(object.PrimaryPart, kit[2]) end end
	end

    KitESP = kits:CreateModule({
	Name = 'KitESP',
	Category = 'Visual',
	Function = function(callback)
		kitGeneration += 1
		if callback then
			local generation = kitGeneration
			for kitName, kit in ESPKits do addKit(kitName, kit[1], kit[2]) end
			local activeKit = store.equippedKit
			refreshKit()
			-- Kit changes are store-driven but this store wrapper has no change signal. Polling four
			-- times a second is indistinguishable to the user and avoids a comparison every frame.
			task.spawn(function()
				while KitESP.Enabled and kitGeneration == generation do
					task.wait(0.25)
					if kitGeneration ~= generation then break end
					if store.equippedKit ~= activeKit then activeKit = store.equippedKit; refreshKit() end
				end
			end)
		else
			Folder:ClearAllChildren()
			table.clear(Reference)
		end
	end,
	Tooltip = 'ESP for certain kit related objects'
    })
    Background = KitESP:CreateToggle({
	Name = 'Background',
	Function = function(callback)
		if Color.Object then
			Color.Object.Visible = callback
		end
		for _, v in Reference do
			v.ImageLabel.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
			v.Blur.Visible = callback
		end
	end,
	Default = true,
    })
    Color = KitESP:CreateColorSlider({
	Name = 'Background Color',
	DefaultValue = 0,
	DefaultOpacity = 0.5,
	Function = function(hue, sat, val, opacity)
		for _, v in Reference do
			v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
			v.ImageLabel.BackgroundTransparency = 1 - opacity
		end
	end,
	Darker = true,
    })
end)

run(function()
    local NameTags
    local Targets
    local Color
    local Background
    local DisplayName
    local Health
    local Distance
    local Equipment
    local Rank
    local Enchant
    local DrawingToggle
    local Scale
    local FontOption
    local Teammates
    local DistanceCheck
    local DistanceLimit
    local Strings, Sizes, Reference = {}, {}, {}
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui
    local methodused

    local Added = {
	Normal = function(ent)
		if not Targets.Players.Enabled and ent.Player then
			return
		end
		if not Targets.NPCs.Enabled and ent.NPC then
			return
		end
		if Teammates.Enabled and not ent.Targetable and not ent.Friend then
			return
		end

		local nametag = Instance.new('TextLabel')
		Strings[ent] = ent.Player
				and whitelist:tag(ent.Player, true, true) .. (DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name)
			or ent.Character.Name

		if Health.Enabled then
			local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
			Strings[ent] = Strings[ent]
				.. ' <font color="rgb('
				.. tostring(math.floor(healthColor.R * 255))
				.. ','
				.. tostring(math.floor(healthColor.G * 255))
				.. ','
				.. tostring(math.floor(healthColor.B * 255))
				.. ')">'
				.. math.round(ent.Health)
				.. '</font>'
		end

		if Distance.Enabled then
			Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '
				.. Strings[ent]
		end

		if Equipment.Enabled then
			for i, v in {'Hand', 'Helmet', 'Chestplate', 'Boots', 'Kit'} do
				local Icon = Instance.new('ImageLabel')
				Icon.Name = v
				Icon.Size = UDim2.fromOffset(30, 30)
				Icon.Position = UDim2.fromOffset(-60 + (i * 30), -30)
				Icon.BackgroundTransparency = 1
				Icon.Image = ''
				Icon.Parent = nametag
			end
		end

		nametag.TextSize = 14 * Scale.Value
		nametag.FontFace = FontOption.Value
		local size =
			getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
		nametag.Name = ent.Player and ent.Player.Name or ent.Character.Name
		nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
		nametag.AnchorPoint = Vector2.new(0.5, 1)
		nametag.BackgroundColor3 = Color3.new()
		nametag.BackgroundTransparency = Background.Value
		nametag.BorderSizePixel = 0
		nametag.Visible = false
		nametag.Text = Strings[ent]
		nametag.TextColor3 = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		nametag.RichText = true
		nametag.Parent = Folder
		task.spawn(function()
			if Rank.Enabled and ent.Player then
				local Icon = Instance.new('ImageLabel')
				Icon.Name = 'RankIcon'
				Icon.Size = UDim2.fromOffset(30, 30)
				Icon.Position = UDim2.fromOffset(size.X + 10, -4)
				Icon.BackgroundTransparency = 1
				Icon.Image = store.rank[ent.Player]:async() and bedwars.RankMeta[store.rank[ent.Player]:async()].image
					or ''
				Icon.Parent = nametag
			end
		end)
		task.spawn(function()
			if Enchant.Enabled and ent.Player then
				local Icon = Instance.new('ImageLabel')
				Icon.Name = 'EnchantIcon'
				Icon.Size = UDim2.fromOffset(30, 30)
				Icon.Position = UDim2.fromOffset(-30, -4)
				Icon.BackgroundTransparency = 1
				Icon.Image = store.enchants[ent.Player]:async() or ''
				Icon.Parent = nametag
			end
		end)
		Reference[ent] = nametag
	end,
	Drawing = function(ent)
		if not Targets.Players.Enabled and ent.Player then
			return
		end
		if not Targets.NPCs.Enabled and ent.NPC then
			return
		end
		if Teammates.Enabled and not ent.Targetable and not ent.Friend then
			return
		end

		local nametag = {}
		nametag.BG = Drawing.new('Square')
		nametag.BG.Filled = true
		nametag.BG.Transparency = 1 - Background.Value
		nametag.BG.Color = Color3.new()
		nametag.BG.ZIndex = 1
		nametag.Text = Drawing.new('Text')
		nametag.Text.Size = 15 * Scale.Value
		nametag.Text.Font = 0
		nametag.Text.ZIndex = 2
		Strings[ent] = ent.Player
				and whitelist:tag(ent.Player, true) .. (DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name)
			or ent.Character.Name

		if Health.Enabled then
			Strings[ent] = Strings[ent] .. ' ' .. math.round(ent.Health)
		end

		if Distance.Enabled then
			Strings[ent] = '[%s] ' .. Strings[ent]
		end

		nametag.Text.Text = Strings[ent]
		nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
		Reference[ent] = nametag
	end,
    }

    local Removed = {
	Normal = function(ent)
		local v = Reference[ent]
		if v then
			Reference[ent] = nil
			Strings[ent] = nil
			Sizes[ent] = nil
			v:Destroy()
		end
	end,
	Drawing = function(ent)
		local v = Reference[ent]
		if v then
			Reference[ent] = nil
			Strings[ent] = nil
			Sizes[ent] = nil
			for _, obj in v do
				pcall(function()
					obj.Visible = false
					obj:Remove()
				end)
			end
		end
	end,
    }

    local Updated = {
	Normal = function(ent)
		local nametag = Reference[ent]
		if nametag then
			Sizes[ent] = nil
			Strings[ent] = ent.Player
					and whitelist:tag(ent.Player, true, true) .. (DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name)
				or ent.Character.Name

			if Health.Enabled then
				local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
				Strings[ent] = Strings[ent]
					.. ' <font color="rgb('
					.. tostring(math.floor(healthColor.R * 255))
					.. ','
					.. tostring(math.floor(healthColor.G * 255))
					.. ','
					.. tostring(math.floor(healthColor.B * 255))
					.. ')">'
					.. math.round(ent.Health)
					.. '</font>'
			end

			if Distance.Enabled then
				Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '
					.. Strings[ent]
			end

			if Equipment.Enabled and store.inventories[ent.Player] then
				local kit = ent.Player:GetAttribute('PlayingAsKit')
				local inventory = store.inventories[ent.Player]
				nametag.Hand.Image = bedwars.getIcon(inventory.hand or {itemType = ''}, true)
				nametag.Helmet.Image = bedwars.getIcon(inventory.armor[4] or {itemType = ''}, true)
				nametag.Chestplate.Image = bedwars.getIcon(inventory.armor[5] or {itemType = ''}, true)
				nametag.Boots.Image = bedwars.getIcon(inventory.armor[6] or {itemType = ''}, true)
				nametag.Kit.Image = kit and bedwars.BedwarsKitMeta[kit].renderImage or ''
			end

			if Enchant.Enabled and nametag:FindFirstChild('EnchantIcon') then
				nametag.EnchantIcon.Image = store.enchants[ent.Player]:async() or ''
			end

			local size = getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
			nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
			nametag.Text = Strings[ent]
		end
	end,
	Drawing = function(ent)
		local nametag = Reference[ent]
		if nametag then
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			Sizes[ent] = nil
			Strings[ent] = ent.Player
					and whitelist:tag(ent.Player, true) .. (DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name)
				or ent.Character.Name

			if Health.Enabled then
				Strings[ent] = Strings[ent] .. ' ' .. math.round(ent.Health)
			end

			if Distance.Enabled then
				Strings[ent] = '[%s] ' .. Strings[ent]
				nametag.Text.Text = entitylib.isAlive and string.format(Strings[ent], math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude)) or Strings[ent]
			else
				nametag.Text.Text = Strings[ent]
			end

			nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
			nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		end
	end,
    }

    local ColorFunc = {
	Normal = function(hue, sat, val)
		local color = Color3.fromHSV(hue, sat, val)
		for i, v in Reference do
			v.TextColor3 = entitylib.getEntityColor(i) or color
		end
	end,
	Drawing = function(hue, sat, val)
		local color = Color3.fromHSV(hue, sat, val)
		for i, v in Reference do
			v.Text.Color = entitylib.getEntityColor(i) or color
		end
	end,
    }

    local Loop = {
	Normal = function()
		local alive = entitylib.isAlive
		local localPosition = alive and entitylib.character.RootPart.Position
		for ent, nametag in Reference do
			local distance
			if alive and (DistanceCheck.Enabled or Distance.Enabled) then
				distance = (localPosition - ent.RootPart.Position).Magnitude
			end

			if DistanceCheck.Enabled then
				distance = distance or math.huge
				if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
					nametag.Visible = false
					continue
				end
			end

			local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
			nametag.Visible = headVis
			if not headVis then
				continue
			end

			if Distance.Enabled then
				local mag = alive and math.floor(distance) or 0
				if Sizes[ent] ~= mag then
					nametag.Text = string.format(Strings[ent], mag)
					local ize = getfontsize(
						removeTags(nametag.Text),
						nametag.TextSize,
						nametag.FontFace,
						Vector2.new(100000, 100000)
					)
					nametag.Size = UDim2.fromOffset(ize.X + 8, ize.Y + 7)
					Sizes[ent] = mag
				end
			end
			nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
		end
	end,
	Drawing = function()
		local alive = entitylib.isAlive
		local localPosition = alive and entitylib.character.RootPart.Position
		for ent, nametag in Reference do
			local distance
			if alive and (DistanceCheck.Enabled or Distance.Enabled) then
				distance = (localPosition - ent.RootPart.Position).Magnitude
			end

			if DistanceCheck.Enabled then
				distance = distance or math.huge
				if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
					nametag.Text.Visible = false
					nametag.BG.Visible = false
					continue
				end
			end

			local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
			nametag.Text.Visible = headVis
			nametag.BG.Visible = headVis
			if not headVis then
				continue
			end

			if Distance.Enabled then
				local mag = alive and math.floor(distance) or 0
				if Sizes[ent] ~= mag then
					nametag.Text.Text = string.format(Strings[ent], mag)
					nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
					Sizes[ent] = mag
				end
			end
			nametag.BG.Position = Vector2.new(headPos.X - (nametag.BG.Size.X / 2), headPos.Y - nametag.BG.Size.Y)
			nametag.Text.Position = nametag.BG.Position + Vector2.new(4, 3)
		end
	end,
    }

    NameTags = vape.Categories.Render:CreateModule({
	Name = 'NameTags',
	Function = function(callback)
		if callback then
			methodused = DrawingToggle.Enabled and 'Drawing' or 'Normal'
			if Removed[methodused] then
				NameTags:Clean(entitylib.Events.EntityRemoved:Connect(Removed[methodused]))
			end
			if Added[methodused] then
				for _, v in entitylib.List do
					if Reference[v] then
						Removed[methodused](v)
					end
					Added[methodused](v)
				end
				NameTags:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
					if Reference[ent] then
						Removed[methodused](ent)
					end
					Added[methodused](ent)
				end))
			end
			if Updated[methodused] then
				NameTags:Clean(entitylib.Events.EntityUpdated:Connect(Updated[methodused]))
				for _, v in entitylib.List do
					Updated[methodused](v)
				end
			end
			if ColorFunc[methodused] then
				NameTags:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
					ColorFunc[methodused](Color.Hue, Color.Sat, Color.Value)
				end))
			end
			if Loop[methodused] then
				NameTags:Clean(runService.RenderStepped:Connect(Loop[methodused]))
			end
		else
			if Removed[methodused] then
				for i in Reference do
					Removed[methodused](i)
				end
			end
		end
	end,
	Tooltip = 'Renders nametags on entities through walls'
    })
    Targets = NameTags:CreateTargets({
	Players = true,
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
    })
    FontOption = NameTags:CreateFont({
	Name = 'Font',
	Blacklist = 'Arial',
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
    })
    Color = NameTags:CreateColorSlider({
	Name = 'Player Color',
	Function = function(hue, sat, val)
		if NameTags.Enabled and ColorFunc[methodused] then
			ColorFunc[methodused](hue, sat, val)
		end
	end,
    })
    Scale = NameTags:CreateSlider({
	Name = 'Scale',
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
	Default = 1,
	Min = 0.1,
	Max = 1.5,
	Decimal = 10,
    })
    Background = NameTags:CreateSlider({
	Name = 'Transparency',
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
	Default = 0.5,
	Min = 0,
	Max = 1,
	Decimal = 10,
    })
    Health = NameTags:CreateToggle({
	Name = 'Health',
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
    })
    Distance = NameTags:CreateToggle({
	Name = 'Distance',
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
    })
    Rank = NameTags:CreateToggle({
	Name = 'Rank',
	Tooltip = "Displays player's rank",
    })
    Enchant = NameTags:CreateToggle({
	Name = 'Enchant',
	Tooltip = "Displays player's enchant",
	Default = true,
    })
    Equipment = NameTags:CreateToggle({
	Name = 'Equipment',
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
    })
    DisplayName = NameTags:CreateToggle({
	Name = 'Use Displayname',
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
	Default = true,
    })
    Teammates = NameTags:CreateToggle({
	Name = 'Priority Only',
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
	Default = true,
    })
    DrawingToggle = NameTags:CreateToggle({
	Name = 'Drawing',
	Function = function()
		if NameTags.Enabled then
			NameTags:Toggle()
			NameTags:Toggle()
		end
	end,
    })
    DistanceCheck = NameTags:CreateToggle({
	Name = 'Distance Check',
	Function = function(callback)
		DistanceLimit.Object.Visible = callback
	end,
    })
    DistanceLimit = NameTags:CreateTwoSlider({
	Name = 'Player Distance',
	Min = 0,
	Max = 256,
	DefaultMin = 0,
	DefaultMax = 64,
	Darker = true,
	Visible = false,
    })
end)

run(function()
	local ProjectileLanding
	local MarkerColor
	local launchHook
	local aimingInput = false
	local lastLaunch
	local states, watchers = {}, {}
	local aimVisual
	local rayParams = RaycastParams.new()
	rayParams.FilterType = Enum.RaycastFilterType.Exclude
	rayParams.RespectCanCollide = true

	local function newVisual(name)
		local marker = Instance.new('Part')
		marker.Name = name
		marker.Shape = Enum.PartType.Ball
		marker.Size = Vector3.new(1.85, 1.85, 1.85)
		marker.Anchored = true
		marker.CanCollide = false
		marker.CanQuery = false
		marker.CanTouch = false
		marker.Material = Enum.Material.Neon
		marker.Transparency = 1
		marker.Parent = gameCamera
		return {Marker = marker}
	end

	local function destroyVisual(visual)
		if not visual then return end
		if visual.Highlight then visual.Highlight:Destroy() end
		if visual.Marker then visual.Marker:Destroy() end
		visual.Highlight = nil
		visual.Marker = nil
	end

	local function entityForInstance(instance)
		local model = instance and instance:FindFirstAncestorOfClass('Model')
		if not model then return end
		if entitylib.getEntityFromCharacter then
			local ent = entitylib.getEntityFromCharacter(model)
			if ent then return ent end
		end
		for _, ent in entitylib.List do
			if ent.Character == model then return ent end
		end
	end

	local function updateVisual(visual, result)
		if not visual or not visual.Marker then return end
		local color = Color3.fromHSV(MarkerColor.Hue, MarkerColor.Sat, MarkerColor.Value)
		visual.Marker.Color = color
		if not result or typeof(result.Position) ~= 'Vector3' then
			visual.Marker.Transparency = 1
			if visual.Highlight then visual.Highlight:Destroy(); visual.Highlight = nil end
			return
		end
		visual.Marker.CFrame = CFrame.new(result.Position + Vector3.new(0, 0.55, 0))
		visual.Marker.Transparency = math.clamp(MarkerColor.Opacity or 0, 0, 1)
		local ent = entityForInstance(result.Instance)
		local model = ent and ent.Character
		if model ~= visual.HighlightModel then
			if visual.Highlight then visual.Highlight:Destroy() end
			visual.Highlight, visual.HighlightModel = nil, model
			if model then
				local highlight = Instance.new('Highlight')
				highlight.Name = 'ProjectileLandingHit'
				highlight.Adornee = model
				highlight.FillTransparency = 0.55
				highlight.OutlineTransparency = 0.05
				highlight.Parent = gameCamera
				visual.Highlight = highlight
			end
		end
		if visual.Highlight then
			visual.Highlight.FillColor = color
			visual.Highlight.OutlineColor = color
		end
	end

	local function closestPoint(point, a, b)
		local segment = b - a
		local length = segment:Dot(segment)
		if length <= 1e-6 then return a end
		return a + segment * math.clamp((point - a):Dot(segment) / length, 0, 1)
	end

	local function movingEntityCollision(a, b, startTime, endTime)
		local bestPosition, bestInstance, bestDistance
		local sampleTime = (startTime + endTime) * 0.5
		for _, ent in entitylib.List do
			local root = ent.RootPart
			if root and root.Parent and (not ent.Health or ent.Health > 0) then
				local velocity = root.AssemblyLinearVelocity
				local center = root.Position + velocity * sampleTime
				local point = closestPoint(center, a, b)
				local delta = point - center
				local horizontal = Vector3.new(delta.X, 0, delta.Z).Magnitude
				if horizontal <= 2.1 and math.abs(delta.Y) <= 3.5 then
					local distance = (point - a).Magnitude
					if not bestDistance or distance < bestDistance then
						bestPosition, bestInstance, bestDistance = point, root, distance
					end
				end
			end
		end
		return bestPosition, bestInstance
	end

	local function trace(origin, velocity, gravity, lifetime, extraIgnore)
		if typeof(origin) ~= 'Vector3' or typeof(velocity) ~= 'Vector3' or velocity.Magnitude <= 0.1 then return end
		local ignored = {lplr.Character, gameCamera}
		if extraIgnore then table.insert(ignored, extraIgnore) end
		for _, ent in entitylib.List do
			if ent.Character then table.insert(ignored, ent.Character) end
		end
		rayParams.FilterDescendantsInstances = ignored
		return prediction.TraceTrajectory(origin, velocity, projectileAcceleration(gravity), rayParams, lifetime, {
			Radius = 0.45,
			SegmentLength = 1,
			MaximumSteps = 600,
			CollisionTest = movingEntityCollision
		})
	end

	local function projectilePart(projectile)
		return projectile:IsA('BasePart') and projectile or projectile:IsA('Model') and projectile.PrimaryPart or nil
	end

	local function projectileMeta(projectile, part)
		return bedwars.ProjectileMeta[projectile.Name] or (part and bedwars.ProjectileMeta[part.Name]) or {}
	end

	local function clearWatcher(projectile)
		local watcher = watchers[projectile]
		if not watcher then return end
		watchers[projectile] = nil
		for _, connection in watcher do connection:Disconnect() end
	end

	local function removeProjectile(projectile)
		local state = states[projectile]
		if not state then return end
		states[projectile] = nil
		if state.Connection then state.Connection:Disconnect() end
		destroyVisual(state.Visual)
	end

	local function trackProjectile(projectile)
		if states[projectile] or projectile:GetAttribute('ProjectileShooter') ~= lplr.UserId then return end
		local part = projectilePart(projectile)
		if not part then return end
		clearWatcher(projectile)
		local meta = projectileMeta(projectile, part)
		local state = {
			Part = part,
			Born = tick(),
			Lifetime = math.clamp(tonumber(meta.lifetimeSec or meta.lifetime) or 7, 0.1, 10),
			Gravity = meta.gravitationalAcceleration or workspace.Gravity,
			Visual = newVisual('ProjectileLandingMarker')
		}
		states[projectile] = state
		state.Connection = projectile.AncestryChanged:Connect(function(_, parent)
			if not parent then removeProjectile(projectile) end
		end)
	end

	local function candidateProjectile(projectile)
		if not (projectile:IsA('BasePart') or projectile:IsA('Model')) then return false end
		if projectile:GetAttribute('ProjectileShooter') ~= nil or bedwars.ProjectileMeta[projectile.Name] then return true end
		local name = projectile.Name:lower()
		return name:find('projectile', 1, true) or name:find('arrow', 1, true)
			or name:find('snowball', 1, true) or name:find('fireball', 1, true)
			or name:find('telepearl', 1, true)
	end

	local function watchProjectile(projectile)
		if not candidateProjectile(projectile) then return end
		if projectile:GetAttribute('ProjectileShooter') ~= nil then
			trackProjectile(projectile)
			return
		end
		if states[projectile] or watchers[projectile] then return end
		local watcher = {}
		watcher.Attribute = projectile:GetAttributeChangedSignal('ProjectileShooter'):Connect(function()
			trackProjectile(projectile)
		end)
		watcher.Ancestry = projectile.AncestryChanged:Connect(function(_, parent)
			if not parent then clearWatcher(projectile) end
		end)
		watchers[projectile] = watcher
	end

	local function setAiming(input, value)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch
			or input.KeyCode == Enum.KeyCode.ButtonR2 then
			aimingInput = value
		end
	end

	local function recordLaunch(nextLaunch, ...)
		local result = nextLaunch(...)
		if type(result) == 'table' and typeof(result.positionFrom) == 'Vector3'
			and typeof(result.initialVelocity) == 'Vector3' then
			lastLaunch = {
				Origin = result.positionFrom,
				Velocity = result.initialVelocity,
				Gravity = result.gravitationalAcceleration or workspace.Gravity,
				Lifetime = tonumber(result.lifetimeSec) or 7,
				Time = tick()
			}
		end
		return result
	end

	local function fallbackLaunch()
		if not entitylib.isAlive or not store.hand or not store.hand.tool then return end
		local itemMeta = bedwars.ItemMeta[store.hand.tool.Name]
		local source = itemMeta and itemMeta.projectileSource
		if not source then return end
		local ammo
		local inventory = store.inventory and store.inventory.inventory
		for _, item in inventory and inventory.items or {} do
			if table.find(source.ammoItemTypes or {}, item.itemType) then ammo = item.itemType; break end
		end
		local projectileType = ammo
		if type(source.projectileType) == 'function' then
			local ok, value = pcall(source.projectileType, ammo)
			if ok then projectileType = value end
		end
		local meta = bedwars.ProjectileMeta[projectileType] or {}
		local speed = (tonumber(meta.launchVelocity or source.launchVelocity) or 100) * (tonumber(source.velocityMultiplier) or 1)
		local origin = gameCamera.CFrame.Position
		pcall(function()
			local value = bedwars.ProjectileController:getLaunchPosition(gameCamera.CFrame)
			if typeof(value) == 'Vector3' then origin = value elseif typeof(value) == 'CFrame' then origin = value.Position end
		end)
		local mouseRay = lplr:GetMouse().UnitRay
		return origin, mouseRay.Direction.Unit * speed,
			(tonumber(meta.gravitationalAcceleration) or workspace.Gravity) * (tonumber(source.gravityMultiplier) or 1),
			tonumber(meta.lifetimeSec) or 7
	end

	local function update()
		for projectile, state in states do
			local part = state.Part
			local remaining = state.Lifetime - (tick() - state.Born)
			if remaining <= 0 or not projectile.Parent or not part.Parent then
				removeProjectile(projectile)
			else
				updateVisual(state.Visual, trace(part.Position, part.AssemblyLinearVelocity, state.Gravity, remaining, projectile))
			end
		end

		local result
		if aimingInput then
			if lastLaunch and tick() - lastLaunch.Time <= 0.25 then
				result = trace(lastLaunch.Origin, lastLaunch.Velocity, lastLaunch.Gravity, lastLaunch.Lifetime)
			else
				local origin, velocity, gravity, lifetime = fallbackLaunch()
				if origin then result = trace(origin, velocity, gravity, lifetime) end
			end
		end
		updateVisual(aimVisual, result)
	end

	local function clear()
		for projectile in states do removeProjectile(projectile) end
		for projectile in watchers do clearWatcher(projectile) end
		destroyVisual(aimVisual)
		aimVisual = nil
		lastLaunch = nil
		aimingInput = false
	end

	ProjectileLanding = vape.Categories.Render:CreateModule({
		Name = 'ProjectileLanding',
		Function = function(enabled)
			if not enabled then clear(); return end
			aimVisual = newVisual('ProjectileLandingAimMarker')
			if bedwars.ProjectileLaunchHook then
				launchHook = bedwars.ProjectileLaunchHook:Add('ProjectileLanding', 1, recordLaunch)
				ProjectileLanding:Clean(function()
					if launchHook then launchHook(); launchHook = nil end
				end)
			end
			ProjectileLanding:Clean(workspace.ChildAdded:Connect(watchProjectile))
			ProjectileLanding:Clean(inputService.InputBegan:Connect(function(input, processed)
				if not processed then setAiming(input, true) end
			end))
			ProjectileLanding:Clean(inputService.InputEnded:Connect(function(input) setAiming(input, false) end))
			for _, child in workspace:GetChildren() do watchProjectile(child) end
			local elapsed = 0
			ProjectileLanding:Clean(runService.Heartbeat:Connect(function(dt)
				elapsed += dt
				if elapsed < 0.05 then return end
				elapsed = 0
				update()
			end))
			ProjectileLanding:Clean(clear)
		end,
		Tooltip = 'Predicts held and local projectile landings with bounded deterministic trajectory simulation'
	})
	MarkerColor = ProjectileLanding:CreateColorSlider({Name = 'Marker Color', DefaultOpacity = 0})
end)
run(function()
    local BulletTracers
    local Material
    local Lifetime
    local Curve
    local Opacity
    local Thickness
    local Color
    local Fade

    local rayCheck = RaycastParams.new()
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude

    BulletTracers = vape.Categories.Render:CreateModule({
	Name = 'ProjectileTracers',
	Function = function(callback)
		if callback then
			BulletTracers:Clean(workspace.ChildAdded:Connect(function(projectile)
				task.delay(0, function()
					rayCheck.FilterDescendantsInstances = {projectile, lplr.Character}
					if projectile:GetAttribute('ProjectileShooter') ~= lplr.UserId then
						return
					end
					local origin = projectile:GetPivot().Position
					local velocity = projectile.PrimaryPart and projectile.PrimaryPart.Velocity or Vector3.zero
					local velocityMagnitude = velocity.Magnitude
					if velocityMagnitude <= 0 then
						return
					end
					local velocityUnit = velocity / velocityMagnitude
					local gravity = bedwars.ProjectileMeta[projectile.Name].gravitationalAcceleration
					local ray = workspace:Raycast(origin, velocityUnit * 2000, rayCheck)
					local endpoint = ray and ray.Position or (origin + velocityUnit * 2000)
					local travelTime = (endpoint - origin).Magnitude / velocityMagnitude

					prediction.SpawnArcTracer(
						origin,
						velocityUnit,
						velocityMagnitude,
						gravity,
						travelTime,
						Curve.Value,
						{
							Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value),
							Transparency = Opacity.Value,
							Thick = Thickness.Value,
							Material = Enum.Material[Material.Value],
							Lifetime = Lifetime.Value,
							Fade = Fade.Enabled,
						}
					)
				end)
			end))
		end
	end,
	Tooltip = 'Replacement tracers for projectiles'
    })

    local materials = {'SmoothPlastic'}
    for _, v in Enum.Material:GetEnumItems() do
	if v.Name ~= 'SmoothPlastic' then
		table.insert(materials, v.Name)
	end
    end
    Material = BulletTracers:CreateDropdown({
	Name = 'Material',
	List = materials
    })
    Color = BulletTracers:CreateColorSlider({
	Name = 'Tracer Color',
	DefaultOpacity = 0.5
    })
    Thickness = BulletTracers:CreateSlider({
	Name = 'Thickness',
	Min = 0.01,
	Max = 1,
	Default = 0.1,
	Decimal = 100
    })
    Curve = BulletTracers:CreateSlider({
	Name = 'Curveness',
	Min = 1,
	Max = 100,
	Default = 40,
	Tooltip = 'How curve the projectile is gonna be\n(More curve = more lag)'
    })
    Opacity = BulletTracers:CreateSlider({
	Name = 'Opacity',
	Min = 0,
	Max = 1,
	Default = 0,
	Decimal = 100
    })
    Lifetime = BulletTracers:CreateSlider({
	Name = 'Lifetime',
	Min = 0,
	Max = 5,
	Decimal = 100,
	Default = 2,
	Suffix = 'secs'
    })
    Fade = BulletTracers:CreateToggle({
	Name = 'Fade',
	Default = true
    })
end)

--[[
    SkinChanger

    Replaced with the reference build's approach. Rather than cloning skin models onto your
    hand and welding them, it sets the itemSkin field the game already carries on every
    inventory entry and re-renders the viewmodel, so the item shows up with that skin (and its
    sounds) through the game's own path. One dropdown per item kind - pick the skin family and
    every matching item you hold uses it.

    Client-side only: nobody else sees the change.
]]
run(function()
	local SkinChanger
	local Options = {}
	local skins, items = {}, {}

	local function prettify(text)
		return (text:gsub('_', ' '):gsub('%a+', function(word)
			return `{word:sub(1, 1):upper()}{word:sub(2)}`
		end))
	end

	local function getLabel(itemType, skin)
		local label = `_{skin}_`
		for word in itemType:gmatch('[^_]+') do
			label = label:gsub(`_{word}_`, '_')
		end
		label = label:gsub('^_+', ''):gsub('_+$', '')
		return label ~= '' and prettify(label) or prettify(skin)
	end

	for _, skin in bedwars.ItemSkinType do
		local meta = bedwars.getItemSkinMeta(skin)
		local item = meta and meta.itemType and bedwars.ItemMeta[meta.itemType]
		if item and not item.block then
			skins[meta.itemType] = skins[meta.itemType] or {}
			skins[meta.itemType][getLabel(meta.itemType, skin)] = skin
		end
	end

	for itemType in skins do
		table.insert(items, itemType)
	end
	table.sort(items, function(a, b)
		return prettify(a) < prettify(b)
	end)

	local function getSkin(itemType)
		local option = SkinChanger.Enabled and Options[itemType]
		return option and skins[itemType][option.Value] or nil
	end

	local function applySkins()
		local inventory = store.inventory.inventory
		for _, item in inventory.items do
			item.itemSkin = getSkin(item.itemType)
		end
		if inventory.hand then
			inventory.hand.itemSkin = getSkin(inventory.hand.itemType)
		end
		bedwars.InventoryViewmodelController:handleStore(bedwars.Store:getState())
	end

	SkinChanger = vape.Categories.Render:CreateModule({
		Name = 'SkinChanger',
		Function = function(callback)
			if callback then
				SkinChanger:Clean(vapeEvents.InventoryChanged.Event:Connect(applySkins))
				SkinChanger:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(applySkins))
				SkinChanger:Clean(lplr.CharacterAdded:Connect(function()
					task.spawn(function()
						for _ = 1, 10 do
							task.wait(0.4)
							if not SkinChanger.Enabled then return end
							applySkins()
						end
					end)
				end))
			end
			applySkins()
		end,
		Tooltip = 'Reskins the items you hold with their sounds, only you can see it'
	})

	for _, itemType in items do
		local list = {}
		for label in skins[itemType] do
			table.insert(list, label)
		end
		table.sort(list)
		table.insert(list, 1, 'None')

		Options[itemType] = SkinChanger:CreateDropdown({
			Name = prettify(itemType),
			List = list,
			Function = function()
				if SkinChanger.Enabled then
					applySkins()
				end
			end
		})
	end

end)

run(function()
    local StorageESP
    local List
    local Background
    local Color
    local Reference = {}
    local Connections = {}
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui

    local function nearStorageItem(item)
	for _, v in List.ListEnabled do
		if item:find(v) then
			return v
		end
	end
	return nil
    end

    local function refreshAdornee(v)
	local chest = v.Adornee:FindFirstChild('ChestFolderValue')
	chest = chest and chest.Value or nil
	if not chest then
		v.Enabled = false
		return
	end

	local chestitems = chest and chest:GetChildren() or {}
	for _, obj in v.Frame:GetChildren() do
		if obj:IsA('ImageLabel') and obj.Name ~= 'Blur' then
			obj:Destroy()
		end
	end

	v.Enabled = false
	local alreadygot = {}
	for _, item in chestitems do
		if not alreadygot[item.Name] and (table.find(List.ListEnabled, item.Name) or nearStorageItem(item.Name)) then
			alreadygot[item.Name] = true
			v.Enabled = true
			local blockimage = Instance.new('ImageLabel')
			blockimage.Size = UDim2.fromOffset(32, 32)
			blockimage.BackgroundTransparency = 1
			blockimage.Image = bedwars.getIcon({ itemType = item.Name }, true)
			blockimage.Parent = v.Frame
		end
	end
	table.clear(chestitems)
    end

    local function Removing(v)
	local billboard = Reference[v]
	if billboard then
		billboard:Destroy()
		Reference[v] = nil
	end

	local connections = Connections[v]
	if connections then
		for _, connection in connections do
			connection:Disconnect()
		end
		table.clear(connections)
		Connections[v] = nil
	end
    end

    local function Clear()
	local references = table.clone(Reference)
	for v in references do
		Removing(v)
	end
	table.clear(references)
	Folder:ClearAllChildren()
    end

    local function Added(v)
	local chest = v:WaitForChild('ChestFolderValue', 3)
	if not (chest and StorageESP.Enabled and v:HasTag('chest')) then
		return
	end
	if Reference[v] then
		Removing(v)
	end
	chest = chest.Value
	if not chest then
		return
	end
	local billboard = Instance.new('BillboardGui')
	billboard.Parent = Folder
	billboard.Name = 'chest'
	billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	billboard.Size = UDim2.fromOffset(36, 36)
	billboard.AlwaysOnTop = true
	billboard.ClipsDescendants = false
	billboard.Adornee = v
	local blur = addBlur(billboard)
	blur.Visible = Background.Enabled
	local frame = Instance.new('Frame')
	frame.Size = UDim2.fromScale(1, 1)
	frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	frame.Parent = billboard
	local layout = Instance.new('UIListLayout')
	layout.FillDirection = Enum.FillDirection.Horizontal
	layout.Padding = UDim.new(0, 4)
	layout.VerticalAlignment = Enum.VerticalAlignment.Center
	layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	local layoutConnection = layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
		billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 4, 36), 36)
	end)
	layout.Parent = frame
	local corner = Instance.new('UICorner')
	corner.CornerRadius = UDim.new(0, 4)
	corner.Parent = frame
	Reference[v] = billboard
	Connections[v] = {
		layoutConnection,
		chest.ChildAdded:Connect(function(item)
			if table.find(List.ListEnabled, item.Name) or nearStorageItem(item.Name) then
				refreshAdornee(billboard)
			end
		end),
		chest.ChildRemoved:Connect(function(item)
			if table.find(List.ListEnabled, item.Name) or nearStorageItem(item.Name) then
				refreshAdornee(billboard)
			end
		end),
	}
	task.spawn(refreshAdornee, billboard)
    end

    StorageESP = vape.Categories.Render:CreateModule({
	Name = 'StorageESP',
	Function = function(callback)
		if callback then
			StorageESP:Clean(collectionService:GetInstanceAddedSignal('chest'):Connect(Added))
			StorageESP:Clean(collectionService:GetInstanceRemovedSignal('chest'):Connect(Removing))
			StorageESP:Clean(Clear)
			for _, v in collectionService:GetTagged('chest') do
				task.spawn(Added, v)
			end
		else
			Clear()
		end
	end,
	Tooltip = 'Displays items in chests'
    })
    List = StorageESP:CreateTextList({
	Name = 'Item',
	Function = function()
		for _, v in Reference do
			task.spawn(refreshAdornee, v)
		end
	end,
    })
    Background = StorageESP:CreateToggle({
	Name = 'Background',
	Function = function(callback)
		if Color and Color.Object then
			Color.Object.Visible = callback
		end
		for _, v in Reference do
			v.Frame.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
			v.Blur.Visible = callback
		end
	end,
	Default = true,
    })
    Color = StorageESP:CreateColorSlider({
	Name = 'Background Color',
	DefaultValue = 0,
	DefaultOpacity = 0.5,
	Function = function(hue, sat, val, opacity)
		for _, v in Reference do
			v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
			v.Frame.BackgroundTransparency = 1 - opacity
		end
	end,
	Darker = true,
    })
end)

-- Lobby milestone state remains available when BedWars transitions into a match.  Keep this
-- integration defensive because older queues do not load the milestone controller or metadata.
run(function()
    local ClaimRewards, CratesOnly, Notify
    local claimGeneration = 0

    local function rewardApi()
        local controller = bedwars.MilestonesController
        local rewards = bedwars.MilestoneRewards
        local state = bedwars.Store and bedwars.Store:getState()
        state = state and state.Bedwars
        if not controller or type(rewards) ~= 'table' or not state then return end
        return controller, rewards, state
    end

    ClaimRewards = vape.Categories.Utility:CreateModule({
        Name = 'ClaimRewards',
        Function = function(enabled)
            claimGeneration += 1
            if not enabled then return end
            local generation = claimGeneration
            task.spawn(function()
                while ClaimRewards.Enabled and claimGeneration == generation do
                    local controller, rewards, state = rewardApi()
                    if not controller then
                        notif('ClaimRewards', 'Milestone rewards are unavailable in this queue.', 5, 'warning')
                        ClaimRewards:Toggle()
                        break
                    end
                    local claimed = controller.milestoneRewardsClaimed or state.milestoneRewardsClaimed or {}
                    local level = state.playerLevel or 0
                    for _, reward in rewards do
                        if not ClaimRewards.Enabled or claimGeneration ~= generation then break end
                        if reward.levelRequirement <= level and not table.find(claimed, reward.id) and (not CratesOnly.Enabled or reward.instantClaim) then
						local remote = bedwars.Client and bedwars.Client:Get('ClaimMilestoneReward')
						local ok, result = false, nil
						if remote then ok, result = pcall(remote.CallServer, remote, reward.id) end
                            if ok and result then
                                table.insert(claimed, reward.id)
                                if Notify.Enabled then notif('ClaimRewards', `Claimed {reward.description or reward.id}`, 5) end
                            end
                            task.wait(1)
                        end
                    end
                    task.wait(5)
                end
            end)
        end,
        Tooltip = 'Claims unlocked level milestone rewards with the native reward remote.'
    })
    CratesOnly = ClaimRewards:CreateToggle({Name = 'Crates only', Tooltip = 'Only claim instant crate rewards.'})
    Notify = ClaimRewards:CreateToggle({Name = 'Notify', Default = true})
end)

run(function()
	local category = vape.Categories.Inventory or vape.Categories.Utility or vape.Categories.World
	if not category or type(category.CreateModule) ~= 'function' then
		warn('[AetherV2] AutoEnchant could not find a module category')
		return
	end

	local AutoEnchant, Repair, Desired, MaximumRolls, Reserve, Interval
	local generation = 0
	local enchantNames = {}

	local function normalise(value)
		return tostring(value or ''):lower():gsub('[%s_%-]+', '')
	end

	local function displayName(key, meta)
		return tostring((type(meta) == 'table' and (meta.displayName or meta.name)) or key):gsub('_', ' ')
	end

	if type(bedwars.EnchantMeta) == 'table' then
		for key, meta in pairs(bedwars.EnchantMeta) do
			table.insert(enchantNames, displayName(key, meta))
		end
	end
	if #enchantNames == 0 then
		enchantNames = {'Critical Strike', 'Fire', 'Life Steal', 'Shield Gen', 'Static', 'Updraft', 'Wind'}
	end
	table.sort(enchantNames)

	local function diamonds()
		local item = getItem('diamond')
		return item and tonumber(item.amount) or 0
	end

	local function currentEnchant()
		local state
		pcall(function() state = bedwars.Store:getState() end)
		local value = type(state) == 'table' and state.Bedwars and state.Bedwars.enchant or nil
		value = value or lplr:GetAttribute('Enchant')
		if type(value) == 'table' then value = value.enchant or value.type or value.itemType end
		if value == nil or tostring(value) == '' or tostring(value):lower() == 'none' then return '' end
		return displayName(value, type(bedwars.EnchantMeta) == 'table' and bedwars.EnchantMeta[value] or nil)
	end

	local function hasDesired(value)
		return Desired and normalise(Desired.Value) == normalise(value)
	end

	local function findTable()
		if not entitylib.isAlive or not entitylib.character or not entitylib.character.RootPart then return end
		local nearest, nearestDistance
		for _, object in pairs(store.enchant or {}) do
			if typeof(object) == 'Instance' and object.Parent then
				local ok, position = pcall(function()
					return object:IsA('Model') and object:GetPivot().Position or object.Position
				end)
				if ok and typeof(position) == 'Vector3' then
					local distance = (entitylib.character.RootPart.Position - position).Magnitude
					if not nearestDistance or distance < nearestDistance then nearest, nearestDistance = object, distance end
				end
			end
		end
		return nearest, nearestDistance
	end

	local function request(controllerNames, remoteNames, tableModel)
		local controller = bedwars.EnchantTableController or bedwars.EnchantController
		for _, name in ipairs(controllerNames) do
			if controller and type(controller[name]) == 'function' then
				local ok, result = pcall(controller[name], controller, tableModel)
				if ok and result ~= false then return true end
			end
		end
		for _, name in ipairs(remoteNames) do
			local ok = pcall(function()
				local handler = bedwars.Handler and bedwars.Handler:Get(name)
				if not handler then error('missing remote') end
				handler:Fire('CallServerAsync', tableModel)
			end)
			if ok then return true end
		end
		return false
	end

	AutoEnchant = category:CreateModule({
		Name = 'AutoEnchant',
		Tooltip = 'Rolls a nearby team enchant table until an accepted enchant is obtained.',
		Function = function(enabled)
			generation += 1
			if not enabled then return end
			local token = generation
			local worker = task.spawn(function()
				local rolls, character = 0, lplr.Character
				while AutoEnchant.Enabled and token == generation do
					if lplr.Character ~= character then
						character, rolls = lplr.Character, 0
					end
					local tableModel, distance = findTable()
					if not tableModel or not distance or distance > 18 then
						task.wait(0.25)
						continue
					end
					if hasDesired(currentEnchant()) then
						rolls = 0
						task.wait(0.25)
						continue
					end
					if rolls >= MaximumRolls.Value then
						notif('AutoEnchant', 'Maximum rolls reached without the selected enchant.', 5, 'warning')
						task.defer(function() if AutoEnchant.Enabled and token == generation then AutoEnchant:Toggle() end end)
						break
					end
					local broken = false
					pcall(function() broken = collectionService:HasTag(tableModel, 'broken-enchant-table') end)
					if broken then
						if not Repair.Enabled or diamonds() < Reserve.Value + 8 then task.wait(0.25); continue end
						if not request({'repairEnchantTable', 'repair'}, {'RepairEnchantTable', 'RepairEnchantTableRemote'}, tableModel) then
							task.wait(1)
							continue
						end
						task.wait(math.max(Interval.Value, 0.25))
						continue
					end
					local state
					pcall(function() state = bedwars.Store:getState() end)
					local bedwarsState = type(state) == 'table' and type(state.Bedwars) == 'table' and state.Bedwars or {}
					local gameState = type(state) == 'table' and type(state.Game) == 'table' and state.Game or {}
					local cost = tonumber(bedwarsState.enchantCost or gameState.enchantCost) or 2
					if diamonds() - cost < Reserve.Value then task.wait(0.25); continue end
					local before = currentEnchant()
					if not request({'purchaseEnchant', 'rollEnchant'}, {'PurchaseEnchant', 'RequestEnchant'}, tableModel) then
						task.wait(1)
						continue
					end
					rolls += 1
					local deadline = tick() + 4
					repeat task.wait() until not AutoEnchant.Enabled or token ~= generation or lplr.Character ~= character or currentEnchant() ~= before or tick() >= deadline
					if AutoEnchant.Enabled and token == generation and lplr.Character == character then
						task.wait(Interval.Value)
					end
				end
			end)
			AutoEnchant:Clean(worker)
		end
	})
	Desired = AutoEnchant:CreateDropdown({Name = 'Desired enchant', List = enchantNames, Default = enchantNames[1], Tooltip = 'Stops rolling as soon as this enchant is obtained.'})
	Repair = AutoEnchant:CreateToggle({Name = 'Repair enchant table', Default = true})
	MaximumRolls = AutoEnchant:CreateSlider({Name = 'Maximum rolls', Min = 1, Max = 50, Default = 10})
	Reserve = AutoEnchant:CreateSlider({Name = 'Resource reserve', Min = 0, Max = 32, Default = 0, Suffix = ' diamonds'})
	Interval = AutoEnchant:CreateSlider({Name = 'Request interval', Min = 0.25, Max = 2, Default = 0.6, Decimal = 100, Suffix = 's'})
end)

run(function()
    local StreamRemover
    local hooks, originalText = {}, setmetatable({}, {__mode = 'k'})
    local refreshQueued = false
    local replacementCache = {}
    local function playerFromArgs(...)
        for i = 1, select('#', ...) do
            local value = select(i, ...)
            if typeof(value) == 'Instance' then
                if value:IsA('Player') then return value end
                local player = playersService:GetPlayerFromCharacter(value); if player then return player end
            elseif type(value) == 'table' then
                local candidate = rawget(value, 'player') or rawget(value, 'Player')
                if typeof(candidate) == 'Instance' and candidate:IsA('Player') then return candidate end
            end
        end
    end
    local function realValue(method, player, value)
        local lower = method:lower()
        if lower:find('display') and lower:find('name') then return player.DisplayName end
        if lower:find('user') and lower:find('name') or lower == 'getname' then return player.Name end
        if lower:find('level') then return tonumber(player:GetAttribute('PlayerLevel')) or value end
        return value
    end
    local function refreshController()
        local controller = (bedwars.Knit.Controllers and bedwars.Knit.Controllers.StreamerModeController) or bedwars.StreamerModeController
        if controller then pcall(function() controller:updateNametags(true) end) end
    end
    local function replacements()
        local result = {}
        for _, player in playersService:GetPlayers() do
            table.insert(result, {
                Player = player,
                Display = player:GetAttribute('DisguiseDisplayName'),
                Username = player:GetAttribute('DisguiseUsername'),
                Level = tostring(tonumber(player:GetAttribute('PlayerLevel')) or 0)
            })
        end
        replacementCache = result
        return result
    end
    local function refreshObject(object, players)
        if not object:IsA('TextLabel') and not object:IsA('TextButton') then return end
        local text = object.Text
        for _, data in players do
                local player = data.Player
                local disguised, username, level = data.Display, data.Username, data.Level
                local relevant = text == 'Me' or text == '[?]' or (disguised and disguised ~= '' and text:find(disguised, 1, true)) or (username and username ~= '' and text:find(username, 1, true))
                if relevant then
                    originalText[object] = originalText[object] or text
                    object.Text = text == '[?]' and '['..level..']' or text == 'Me' and player.DisplayName or text:gsub(disguised or '\0', player.DisplayName):gsub(username or '\0', player.Name)
                end
        end
    end
    local function refreshGui(root)
        for _, object in root:GetDescendants() do refreshObject(object, replacementCache) end
    end
    local function queueRefresh()
        if refreshQueued then return end
        refreshQueued = true
        task.defer(function()
            refreshQueued = false
            if StreamRemover.Enabled then replacements(); refreshController(); refreshGui(lplr.PlayerGui) end
        end)
    end
    local function installHooks()
        local gamePlayer = require(replicatedStorage.TS.player['game-player'])
        for name, fn in gamePlayer do
            if type(fn) == 'function' and (name:lower():find('name') or name:lower():find('level') or name:lower():find('disguise')) then
                hooks[name] = fn
                gamePlayer[name] = function(...)
                    local result = fn(...)
                    local player = playerFromArgs(...)
                    return player and realValue(name, player, result) or result
                end
            end
        end
        bedwars.GamePlayer = gamePlayer
    end
    StreamRemover = vape.Categories.Render:CreateModule({
        Name = 'StreamRemover',
        Function = function(enabled)
            if enabled then
                installHooks(); replacements(); refreshController(); refreshGui(lplr.PlayerGui)
                local function watch(player)
                    for _, attribute in {'DisguiseDisplayName', 'DisguiseUsername', 'PlayerLevel'} do
                        StreamRemover:Clean(player:GetAttributeChangedSignal(attribute):Connect(queueRefresh))
                    end
                    StreamRemover:Clean(player.CharacterAdded:Connect(function() task.defer(refreshController) end))
                end
                for _, player in playersService:GetPlayers() do watch(player) end
                StreamRemover:Clean(playersService.PlayerAdded:Connect(function(player) replacements(); watch(player) end))
                StreamRemover:Clean(playersService.PlayerRemoving:Connect(function() task.defer(replacements) end))
                StreamRemover:Clean(lplr.PlayerGui.DescendantAdded:Connect(function(object)
                    -- Process only the new text object. Attribute changes use the coalesced full
                    -- refresh above, so a kill-feed tree being constructed cannot trigger dozens
                    -- of complete PlayerGui scans in the same frame.
                    if object:IsA('TextLabel') or object:IsA('TextButton') then refreshObject(object, replacementCache) end
                end))
            else
                local gamePlayer = bedwars.GamePlayer
                for name, fn in hooks do gamePlayer[name] = fn end
                table.clear(hooks)
                for object, text in originalText do if object.Parent then object.Text = text end end
                table.clear(originalText); refreshController()
            end
        end,
        Tooltip = 'Reversibly reveals real display names, usernames, and player levels in streamer-mode UI'
    })
end)

run(function()
    local TrapESP
    local Background
    local Color

    local Reference = {}
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui

    local function Added(v)
	local billboard = Instance.new('BillboardGui')
	billboard.Parent = Folder
	billboard.Name = 'bed'
	billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	billboard.Size = UDim2.fromOffset(36, 36)
	billboard.AlwaysOnTop = true
	billboard.ClipsDescendants = false
	billboard.Adornee = v
	local blur = addBlur(billboard)
	blur.Visible = Background.Enabled
	local frame = Instance.new('Frame')
	frame.Size = UDim2.fromScale(1, 1)
	frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	frame.Parent = billboard
	local image = Instance.new('ImageLabel')
	image.Size = UDim2.fromOffset(32, 32)
	image.BackgroundTransparency = 1
	image.Image = bedwars.getIcon({ itemType = 'snap_trap' }, true)
	image.Parent = frame
	local layout = Instance.new('UIListLayout')
	layout.FillDirection = Enum.FillDirection.Horizontal
	layout.Padding = UDim.new(0, 4)
	layout.VerticalAlignment = Enum.VerticalAlignment.Center
	layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
		billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 4, 36), 36)
	end)
	layout.Parent = frame
	local corner = Instance.new('UICorner')
	corner.CornerRadius = UDim.new(0, 4)
	corner.Parent = frame
	Reference[v] = billboard
    end

    TrapESP = vape.Categories.Render:CreateModule({
	Name = 'TrapESP',
	Function = function(callback)
		if callback then
			repeat
				task.wait()
			until store.matchState ~= 0 or not TrapESP.Enabled
			if not TrapESP.Enabled then
				return
			end

			TrapESP:Clean(collectionService:GetInstanceAddedSignal('snap_trap'):Connect(Added))
			TrapESP:Clean(collectionService:GetInstanceRemovedSignal('snap_trap'):Connect(function(v)
				if Reference[v] then
					Reference[v]:Destroy()
					Reference[v] = nil
				end
			end))
		else
			table.clear(Reference)
			Folder:ClearAllChildren()
		end
	end,
	Tooltip = 'Render traps placed by other teams'
    })

    Background = TrapESP:CreateToggle({
	Name = 'Background',
	Function = function(callback)
		if Color and Color.Object then
			Color.Object.Visible = callback
		end
		for _, v in Reference do
			v.Frame.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
			v.Blur.Visible = callback
		end
	end,
	Default = true
    })
    Color = TrapESP:CreateColorSlider({
	Name = 'Background Color',
	DefaultValue = 0,
	DefaultOpacity = 0.5,
	Function = function(hue, sat, val, opacity)
		for _, v in Reference do
			v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
			v.Frame.BackgroundTransparency = 1 - opacity
		end
	end,
	Darker = true
    })
end)

run(function()
    local ViewmodelVisuals
    local StrokeColor
    local Color

    local Instances = {}

    ViewmodelVisuals = vape.Categories.Render:CreateModule({
        Name = 'ViewmodelVisuals',
        Function = function(call)
            if call then
                local viewmodel = gameCamera:WaitForChild('Viewmodel', 9e9)
                if not ViewmodelVisuals.Enabled then
                    return
                end

                for i,v in viewmodel:GetChildren() do
                    if v:IsA('Accessory') then
                        local highlight = v.Handle:FindFirstChildOfClass('Highlight') or Instance.new('Highlight', v.Handle)
                        highlight.FillColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                        highlight.FillTransparency = Color.Opacity
                        highlight.OutlineTransparency = StrokeColor.Opacity
                        highlight.OutlineColor = Color3.fromHSV(StrokeColor.Hue, StrokeColor.Sat, StrokeColor.Value)

                        ViewmodelVisuals:Clean(highlight)
                        table.insert(Instances, highlight)

                        break
                    end
                end

                ViewmodelVisuals:Clean(viewmodel.ChildAdded:Connect(function(visual)
                    if visual:IsA('Accessory') then
                        local highlight = visual.Handle:FindFirstChildOfClass('Highlight') or Instance.new('Highlight', visual.Handle)
                        highlight.FillColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                        highlight.FillTransparency = Color.Opacity
                        highlight.OutlineTransparency = StrokeColor.Opacity
                        highlight.OutlineColor = Color3.fromHSV(StrokeColor.Hue, StrokeColor.Sat, StrokeColor.Value)

                        ViewmodelVisuals:Clean(highlight)
                        table.insert(Instances, highlight)
                    end
                end))

                ViewmodelVisuals:Clean(gameCamera.ChildAdded:Connect(function(visual)
                    if visual.Name == 'Viewmodel' then
                        ViewmodelVisuals:Toggle()
                        ViewmodelVisuals:Toggle()
                    end
                end))
            end
        end
    })

    Color = ViewmodelVisuals:CreateColorSlider({
        Name = 'Color',
        Default = Color3.new(1, 1, 1),
        Function = function(hue, sat, val, opacity)
            for _, v in Instances do
                v.FillColor = Color3.fromHSV(hue, sat, val)
                v.FillTransparency = opacity
            end
        end
    })
    StrokeColor = ViewmodelVisuals:CreateColorSlider({
        Name = 'Stroke Color',
        Default = Color3.new(),
        Function = function(hue, sat, val, opacity)
            for _, v in Instances do
                v.OutlineColor = Color3.fromHSV(hue, sat, val)
                v.OutlineTransparency = opacity
            end
        end
    })
end)

--[[
    Utility
]]

-- MP3Player: plays your own .mp3 files out of the aetherv2/songs folder the loader creates.
--
-- The folder is scanned live, so songs added or deleted while you are in a game are picked up
-- without a reinject (Auto refresh, plus a Refresh button for right now). Anything the executor
-- can turn into an asset works - mp3, wav, ogg.
--
run(function()
    local MP3Player
    local Volume
    local Speed
    local Shuffle
    local Loop
    local AutoRefresh
    local PlayField
    local Playlist
    local ShowHUD
    local HUDProgress
    local HUDTime
    local HUDColor

    local SONGS = 'aetherv2/songs'
    local SPOTIFY = 'aetherv2/spotify'

    local sound
    local tracks, index = {}, 0
    local hudName, hudTime, hudBarFill, hudBackground
    local lastScan = 0
    local scanKey = ''
    -- When the current track was started, so the watchdog below can tell a song that has
    -- finished from one that has only just been asked to start.
    local lastPlay = 0

    -- Every filesystem call is optional: some executors ship none of them, and the module has to
    -- degrade to "no songs found" rather than erroring on load.
    local function fsList(path)
        local ok, res = pcall(function()
            if isfolder and not isfolder(path) then
                if makefolder then makefolder(path) end
                return {}
            end
            return listfiles and listfiles(path) or {}
        end)
        return ok and res or {}
    end

    local function isAudio(path)
        path = tostring(path):lower()
        return path:sub(-4) == '.mp3' or path:sub(-4) == '.wav' or path:sub(-4) == '.ogg'
    end

    local function fileName(path)
        local normalised = tostring(path):gsub('\\', '/')
        local name = normalised:match('([^/]+)$') or normalised
        return (name:gsub('%.[^%.]+$', ''))
    end

    local function scan(announce)
        local found = {}
        for _, file in fsList(SONGS) do
            if isAudio(file) then
                table.insert(found, {Name = fileName(file), Path = tostring(file):gsub('\\', '/')})
            end
        end
        for _, file in fsList(SPOTIFY) do
            if isAudio(file) then
                table.insert(found, {Name = fileName(file), Path = tostring(file):gsub('\\', '/')})
            end
        end
        table.sort(found, function(a, b)
            return a.Name:lower() < b.Name:lower()
        end)

        -- Playlist, when you have filled one in, is both the filter and the order.
        local wanted = Playlist and Playlist.ListEnabled or {}
        if #wanted > 0 then
            local ordered = {}
            for _, entry in wanted do
                local needle = entry:lower()
                for _, track in found do
                    if track.Name:lower():find(needle, 1, true) then
                        table.insert(ordered, track)
                        break
                    end
                end
            end
            if #ordered > 0 then
                found = ordered
            end
        end

        local key = ''
        for _, track in found do
            key = key .. track.Path .. ';'
        end
        local changed = key ~= scanKey
        scanKey = key
        tracks = found
        if changed and announce and MP3Player.Enabled then
            notif('MP3Player', #tracks > 0 and (#tracks .. ' song' .. (#tracks == 1 and '' or 's') .. ' loaded') or 'No songs in the songs folder yet', 3)
        end
        return changed
    end

    local function assetFor(path)
        local ok, asset = pcall(function()
            return getcustomasset(path)
        end)
        return ok and asset or nil
    end

    local function refreshHUD()
        if not hudName then return end
        local track = tracks[index]
        local colour = HUDColor and Color3.fromHSV(HUDColor.Hue, HUDColor.Sat, HUDColor.Value) or Color3.new(1, 1, 1)
        hudName.TextColor3 = colour
        hudName.Text = track and track.Name or 'No song loaded'
        if hudBackground then
            hudBackground.BackgroundTransparency = HUDColor and (1 - (HUDColor.Opacity * 0.65)) or 0.35
        end

        local length = sound and sound.TimeLength or 0
        local at = sound and sound.TimePosition or 0
        if hudTime then
            hudTime.Visible = HUDTime == nil or HUDTime.Enabled
            hudTime.TextColor3 = colour
            local function clock(t)
                t = math.max(math.floor(t), 0)
                return string.format('%d:%02d', t // 60, t % 60)
            end
            hudTime.Text = track and (clock(at) .. ' / ' .. clock(length)) or ''
        end
        if hudBarFill then
            hudBarFill.Parent.Visible = HUDProgress == nil or HUDProgress.Enabled
            hudBarFill.BackgroundColor3 = colour
            hudBarFill.Size = UDim2.fromScale(length > 0 and math.clamp(at / length, 0, 1) or 0, 1)
        end
    end

    local function stop()
        if sound then
            pcall(function()
                sound:Stop()
            end)
        end
    end

    -- Looping is the engine's job, not ours.
    --
    -- Repeating a song used to mean replaying it from the Ended handler, which is two
    -- problems at once: it leaves an audible gap at every repeat, and Ended is not
    -- something to depend on - a sound whose asset was still loading when Play ran can
    -- fire it immediately or never, and then the music just stops. Looped restarts the
    -- track inside the engine with no gap and no event involved.
    --
    -- Called on every play AND from the two toggles, so turning Loop on part way through a
    -- song loops that song rather than quietly waiting for the next one - which is what
    -- made the toggle look like it did nothing at all.
    local function applyLoop()
        if not (sound and Loop and Shuffle) then return end
        sound.Looped = Loop.Enabled and not Shuffle.Enabled
    end

    local function play(newIndex)
        if #tracks <= 0 then
            index = 0
            refreshHUD()
            return
        end
        -- Stamped before the asset is resolved, not after: a track the executor cannot load
        -- returns below, and leaving the stamp stale would have the watchdog walk the
        -- playlist several times a second complaining about each one.
        lastPlay = tick()
        index = ((newIndex - 1) % #tracks) + 1
        local track = tracks[index]
        local asset = track and assetFor(track.Path)
        if not asset then
            notif('MP3Player', 'Could not load ' .. (track and track.Name or 'that song'), 4, 'warning')
            return
        end
        if not sound then return end
        sound.SoundId = asset
        sound.Volume = Volume.Value / 100
        sound.PlaybackSpeed = Speed.Value
        sound.TimePosition = 0
        applyLoop()
        pcall(function()
            sound:Play()
        end)
        refreshHUD()
    end

    local function advance(step)
        if #tracks <= 0 then return end
        if Shuffle.Enabled and #tracks > 1 then
            local pick = index
            for _ = 1, 8 do
                pick = math.random(1, #tracks)
                if pick ~= index then break end
            end
            play(pick)
            return
        end
        play(index + step)
    end

    MP3Player = vape.Categories.Utility:CreateModule({
        Name = 'MP3Player',
        Function = function(callback)
            if callback then
                if not (listfiles and getcustomasset) then
                    notif('MP3Player', 'Your executor cannot read local files, so there is nothing to play', 6, 'warning')
                    return task.spawn(function()
                        if MP3Player.Enabled then MP3Player:Toggle() end
                    end)
                end
                if isfolder and makefolder then
                    if not isfolder(SONGS) then makefolder(SONGS) end
                end

                sound = Instance.new('Sound')
                sound.Name = 'AetherMP3'
                sound.Volume = Volume.Value / 100
                sound.PlaybackSpeed = Speed.Value
                sound.Parent = vape.gui
                MP3Player:Clean(sound)
                -- Only ever advances: a looping track never ends, because Looped keeps it
                -- going inside the engine.
                MP3Player:Clean(sound.Ended:Connect(function()
                    if not MP3Player.Enabled then return end
                    advance(1)
                end))

                -- Toggle() shows the HUD frame for any module with a Size, so put Show HUD back in
                -- charge of it now that the module is on.
                if MP3Player.Children then
                    MP3Player.Children.Visible = ShowHUD.Enabled
                end

                scan(true)
                if #tracks > 0 then
                    play(Shuffle.Enabled and math.random(1, #tracks) or 1)
                end

                MP3Player:Clean(task.spawn(function()
                    while MP3Player.Enabled do
                        if AutoRefresh.Enabled and tick() - lastScan > 3 then
                            lastScan = tick()
                            local changed = scan(true)
                            -- Nothing playing and songs have just appeared: start on them.
                            if changed and sound and not sound.IsPlaying and #tracks > 0 then
                                play(index > 0 and index or 1)
                            end
                        end
                        -- Backstop for a track that finished without Ended firing, which is
                        -- what left the playlist sitting in silence part way through. A
                        -- looping track is still playing, so this never touches it, and the
                        -- second since the last start keeps it off a song that is loading.
                        if sound and #tracks > 0 and sound.SoundId ~= '' and sound.IsLoaded
                            and not sound.IsPlaying and not sound.IsPaused
                            and (tick() - lastPlay) > 1 then
                            advance(1)
                        end
                        refreshHUD()
                        task.wait(0.2)
                    end
                end))
            else
                stop()
                sound = nil
                index = 0
                scanKey = ''
                refreshHUD()
            end
        end,
        Tooltip = 'Plays your own mp3 files from the aetherv2/songs folder, with a HUD and a live-refreshing playlist',
        Size = UDim2.fromOffset(236, 66),
        ExtraText = function()
            local track = tracks[index]
            return track and track.Name or nil
        end
    })

    -- HUD, built into the draggable frame the GUI hands us (same pattern AutoWin uses).
    if MP3Player.Children then
        local hud = MP3Player.Children
        if hud.Position == UDim2.new() then
            hud.Position = UDim2.fromOffset(16, 340)
        end
        hudBackground = Instance.new('Frame')
        hudBackground.Size = UDim2.fromScale(1, 1)
        hudBackground.BackgroundColor3 = Color3.new()
        hudBackground.BackgroundTransparency = 0.35
        hudBackground.BorderSizePixel = 0
        hudBackground.Parent = hud
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 5)
        corner.Parent = hudBackground

        local title = Instance.new('TextLabel')
        title.Size = UDim2.new(1, -14, 0, 16)
        title.Position = UDim2.fromOffset(9, 5)
        title.BackgroundTransparency = 1
        title.Font = Enum.Font.GothamBold
        title.TextSize = 12
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.TextColor3 = Color3.fromRGB(170, 170, 170)
        title.Text = 'MP3Player'
        title.Parent = hudBackground

        hudName = Instance.new('TextLabel')
        hudName.Size = UDim2.new(1, -18, 0, 18)
        hudName.Position = UDim2.fromOffset(9, 21)
        hudName.BackgroundTransparency = 1
        hudName.Font = Enum.Font.GothamMedium
        hudName.TextSize = 13
        hudName.TextXAlignment = Enum.TextXAlignment.Left
        hudName.TextTruncate = Enum.TextTruncate.AtEnd
        hudName.TextColor3 = Color3.new(1, 1, 1)
        hudName.Text = 'No song loaded'
        hudName.Parent = hudBackground

        hudTime = Instance.new('TextLabel')
        hudTime.Size = UDim2.new(1, -18, 0, 14)
        hudTime.Position = UDim2.fromOffset(-9, 5)
        hudTime.BackgroundTransparency = 1
        hudTime.Font = Enum.Font.Gotham
        hudTime.TextSize = 11
        hudTime.TextXAlignment = Enum.TextXAlignment.Right
        hudTime.TextColor3 = Color3.new(1, 1, 1)
        hudTime.Text = ''
        hudTime.Parent = hudBackground

        local bar = Instance.new('Frame')
        bar.Size = UDim2.new(1, -18, 0, 4)
        bar.Position = UDim2.fromOffset(9, 46)
        bar.BackgroundColor3 = Color3.fromRGB(70, 70, 70)
        bar.BorderSizePixel = 0
        bar.Parent = hudBackground
        local barCorner = Instance.new('UICorner')
        barCorner.CornerRadius = UDim.new(1, 0)
        barCorner.Parent = bar

        hudBarFill = Instance.new('Frame')
        hudBarFill.Size = UDim2.fromScale(0, 1)
        hudBarFill.BackgroundColor3 = Color3.new(1, 1, 1)
        hudBarFill.BorderSizePixel = 0
        hudBarFill.Parent = bar
        local fillCorner = Instance.new('UICorner')
        fillCorner.CornerRadius = UDim.new(1, 0)
        fillCorner.Parent = hudBarFill
    end

    MP3Player:CreateButton({
        Name = 'Play / Pause',
        Function = function()
            if not sound then return end
            if sound.IsPlaying then
                sound:Pause()
            elseif sound.SoundId ~= '' then
                sound:Resume()
            else
                play(index > 0 and index or 1)
            end
        end,
        Tooltip = 'Pause or resume the current song'
    })
    MP3Player:CreateButton({
        Name = 'Next song',
        Function = function()
            advance(1)
        end
    })
    MP3Player:CreateButton({
        Name = 'Previous song',
        Function = function()
            advance(-1)
        end
    })
    MP3Player:CreateButton({
        Name = 'Refresh songs',
        Function = function()
            lastScan = tick()
            scan(true)
            refreshHUD()
        end,
        Tooltip = 'Re-read the songs folder right now'
    })
    Volume = MP3Player:CreateSlider({
        Name = 'Volume',
        Min = 0,
        Max = 100,
        Default = 40,
        Suffix = '%',
        Function = function(val)
            if sound then
                sound.Volume = val / 100
            end
        end
    })
    Speed = MP3Player:CreateSlider({
        Name = 'Speed',
        Min = 0.5,
        Max = 2,
        Default = 1,
        Decimal = 100,
        Suffix = 'x',
        Function = function(val)
            if sound then
                sound.PlaybackSpeed = val
            end
        end,
        Tooltip = 'Playback speed'
    })
    Shuffle = MP3Player:CreateToggle({
        Name = 'Shuffle',
        Function = applyLoop,
        Tooltip = 'Pick the next song at random instead of in order'
    })
    Loop = MP3Player:CreateToggle({
        Name = 'Loop song',
        Function = applyLoop,
        Tooltip = 'Repeat the current song instead of moving on'
    })
    AutoRefresh = MP3Player:CreateToggle({
        Name = 'Auto refresh',
        Default = true,
        Tooltip = 'Watch the songs folder and pick up new or deleted files while you play'
    })
    PlayField = MP3Player:CreateTextBox({
        Name = 'Play song',
        Placeholder = 'song name',
        -- TextBox hands us `enter`, not the text, and fires on every keystroke - so only act once
        -- the name has actually been submitted.
        Function = function(enter)
            if not enter then return end
            local val = PlayField and PlayField.Value or ''
            if val == '' then return end
            scan(false)
            local needle = val:lower()
            for i, track in tracks do
                if track.Name:lower():find(needle, 1, true) then
                    play(i)
                    return
                end
            end
            notif('MP3Player', 'No song matching "' .. val .. '"', 4, 'warning')
        end,
        Tooltip = 'Type part of a song name to jump straight to it'
    })
    Playlist = MP3Player:CreateTextList({
        Name = 'Playlist',
        Placeholder = 'song name',
        Function = function()
            scan(true)
        end,
        Tooltip = 'Leave empty to play everything in the folder. Add names and only those play, in the order you list them'
    })
    ShowHUD = MP3Player:CreateToggle({
        Name = 'Show HUD',
        Default = true,
        Tooltip = 'Show the now-playing panel. Drag it by its own frame to move it',
        Function = function(callback)
            pcall(function()
                HUDProgress.Object.Visible = callback
                HUDTime.Object.Visible = callback
                HUDColor.Object.Visible = callback
            end)
            if MP3Player.Children then
                MP3Player.Children.Visible = callback and MP3Player.Enabled
            end
        end
    })
    HUDProgress = MP3Player:CreateToggle({
        Name = 'Progress bar',
        Default = true,
        Darker = true,
        Tooltip = 'Show how far through the song you are'
    })
    HUDTime = MP3Player:CreateToggle({
        Name = 'Show time',
        Default = true,
        Darker = true,
        Tooltip = 'Show elapsed and total time'
    })
    HUDColor = MP3Player:CreateColorSlider({
        Name = 'HUD color',
        Darker = true,
        DefaultOpacity = 0.55,
        Function = refreshHUD
    })
end)

run(function()
    local AntiSuffocate
    local Mode

    -- Burial check. Push mode needs the player fully buried (body plus the
    -- cells above and below) before nudging, but TP mode must also fire when
    -- only part of the body is inside a block - most importantly legs-only
    -- suffocation, where the body/head cells are still free.
    local function isSolidBlock(block)
		return block and block:IsA('BasePart') and block.CanCollide and block.CanQuery
			and block.Transparency < 1 and block.Size.Magnitude > 0
	end

    local function isSuffocating(root, mode)
        local body = getPlacedBlock(root.Position)
        local head = getPlacedBlock(root.Position + Vector3.new(0, 2, 0))
        local legs = getPlacedBlock(root.Position - Vector3.new(0, 2, 0))
		body, head, legs = isSolidBlock(body), isSolidBlock(head), isSolidBlock(legs)
        if mode == 'TP' then
            return (body or legs) and true or false
        end
        return (body and head and legs) and true or false
    end

    -- TP mode: pop straight up to the top of the block column we are stuck in so our
    -- feet rest on the highest ground with nothing above our head.
    local function teleportOut(root)
        local hip = entitylib.character.HipHeight or 2.5
        local base = root.Position
        for step = 1, 26 do
            local probe = base + Vector3.new(0, step, 0)
            local ground = getPlacedBlock(probe - Vector3.new(0, 2, 0))
            if isSolidBlock(ground) and not isSolidBlock(getPlacedBlock(probe)) and not isSolidBlock(getPlacedBlock(probe + Vector3.new(0, 2, 0))) then
                local topY = ground.Position.Y + ground.Size.Y / 2
                root.CFrame = CFrame.new(base.X, topY + hip + 0.1, base.Z) * root.CFrame.Rotation
                root.AssemblyLinearVelocity = Vector3.zero
                return true
            end
        end
    end

    AntiSuffocate = vape.Categories.Utility:CreateModule({
	Name = 'AntiSuffocate',
	Function = function(call)
		if call then
			repeat
				if entitylib.isAlive then
					local root = entitylib.character.RootPart
					if isSuffocating(root, Mode.Value) then
						if Mode.Value == 'TP' then
							teleportOut(root)
						else
							root.CFrame += Vector3.new(0, 0.5, 0)
							if root.AssemblyLinearVelocity.Y < -1 then
								root.AssemblyLinearVelocity = Vector3.zero
							end
						end
					end
				end
				task.wait()
			until not AntiSuffocate.Enabled
		end
	end,
	Tooltip = 'Prevents you from suffocating in blocks',
    })
    Mode = AntiSuffocate:CreateDropdown({
	Name = 'Mode',
	List = {'Push', 'TP'},
	Default = 'Push',
	Tooltip = 'Push nudges you up while fully buried. TP jumps you to the top and also fires on partial burials'
    })
end)

run(function()
    local AutoBalloon

    AutoBalloon = vape.Categories.Utility:CreateModule({
        Name = 'AutoBalloon',
        Function = function(callback)
            if callback then
                repeat task.wait() until store.matchState ~= 0 or (not AutoBalloon.Enabled)
                if not AutoBalloon.Enabled then return end

                local lowestpoint = math.huge
                for _, v in store.blocks do
                    local point = (v.Position.Y - (v.Size.Y / 2)) - 50
                    if point < lowestpoint then
                        lowestpoint = point
                    end
                end

                repeat
                    if entitylib.isAlive then
                        if entitylib.character.RootPart.Position.Y < lowestpoint and (lplr.Character:GetAttribute('InflatedBalloons') or 0) < 3 then
                            local balloon = getItem('balloon')
                            if balloon then
                                for _ = 1, 3 do
                                    bedwars.BalloonController:inflateBalloon()
                                end
                            end
                            task.wait(0.1)
                        end
                    end
                    task.wait(0.1)
                until not AutoBalloon.Enabled
            end
        end,
        Tooltip = 'Inflates when you fall into the void'
    })
end)

run(function()
    local AntiLasso
    local Chance
    local Check
    local currentConnections = {}
    local currentCharacter
    local activeLasso
    local ignoredLasso
    local lassoVersion = 0
    local returnFilter = RaycastParams.new()
    local returnOverlap = OverlapParams.new()

    returnFilter.FilterType = Enum.RaycastFilterType.Exclude
    returnFilter.RespectCanCollide = true
    returnFilter.IgnoreWater = true
    returnOverlap.FilterType = Enum.RaycastFilterType.Exclude
    returnOverlap.RespectCanCollide = true

    local function disconnectCharacter()
        for _, connection in currentConnections do
            connection:Disconnect()
        end
        table.clear(currentConnections)
        currentCharacter = nil
    end

    local function isFinite(value)
        return type(value) == 'number' and value == value and value > -math.huge and value < math.huge
    end

    local function isFiniteCFrame(value)
        if typeof(value) ~= 'CFrame' then return false end
        for _, component in {value:GetComponents()} do
            if not isFinite(component) then return false end
        end
        return true
    end

    -- What a lasso looks like on a character. The old check only ever accepted a direct child of
    -- the character holding a descendant named exactly 'Rope', which misses the constraint itself
    -- and anything the game renames between updates, so a lasso that carried no 'LassoHooked' tag
    -- was never seen at all.
    local function isLassoPart(inst)
        if inst:IsA('RopeConstraint') then return true end
        local name = inst.Name:lower()
        return name:find('lasso', 1, true) ~= nil or name:find('rope', 1, true) ~= nil
    end

    local function getLassoObject(character)
        for _, descendant in character:GetDescendants() do
            if isLassoPart(descendant) then
                return descendant
            end
        end
    end

    local function hasClearance(character, root, position)
        returnOverlap.FilterDescendantsInstances = {character, gameCamera}
        for _, part in workspace:GetPartBoundsInBox(CFrame.new(position), root.Size * Vector3.new(0.9, 1, 0.9), returnOverlap) do
            local queryIgnored = bedwars.QueryUtil.isQueryIgnored
            if part.CanCollide and not (type(queryIgnored) == 'function' and queryIgnored(bedwars.QueryUtil, part)) then
                return false
            end
        end
        return true
    end

    local function getSafeReturnCFrame(event)
        local character, root, saved = event.character, event.root, event.cframe
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if not isFiniteCFrame(saved) or not root.Parent or not humanoid or humanoid.Health <= 0 then return end
        local position = saved.Position
        if position.Y <= workspace.FallenPartsDestroyHeight + 12 then return end

        returnFilter.FilterDescendantsInstances = {character, gameCamera}
        local ground = workspace:Raycast(position + Vector3.yAxis * 3, -Vector3.yAxis * 99, returnFilter)
        if ground and position.Y - ground.Position.Y >= 1 and hasClearance(character, root, position) then
            return saved
        end

        local offsets = {Vector3.zero}
        for radius = 3, 12, 3 do
            for _, direction in {
                Vector3.xAxis,
                -Vector3.xAxis,
                Vector3.zAxis,
                -Vector3.zAxis,
                Vector3.new(1, 0, 1).Unit,
                Vector3.new(1, 0, -1).Unit,
                Vector3.new(-1, 0, 1).Unit,
                Vector3.new(-1, 0, -1).Unit
            } do
                table.insert(offsets, direction * radius)
            end
        end

        local best, bestDistance
        for _, offset in offsets do
            local origin = position + offset + Vector3.yAxis * 12
            local result = workspace:Raycast(origin, -Vector3.yAxis * 72, returnFilter)
            if result and result.Instance.CanCollide then
                local candidate = Vector3.new(origin.X, result.Position.Y + humanoid.HipHeight + root.Size.Y / 2, origin.Z)
                local distance = (candidate - position).Magnitude
                if candidate.Y > workspace.FallenPartsDestroyHeight + 12 and hasClearance(character, root, candidate)
                    and (not bestDistance or distance < bestDistance)
                then
                    best, bestDistance = candidate, distance
                end
            end
        end
        return best and CFrame.new(best) * saved.Rotation or nil
    end

    local function clearLasso(event)
        if activeLasso ~= event then return end
        activeLasso = nil
        if event.root.Parent then
            event.root.Anchored = false
        end
    end

    local function returnPlayer(event, visualReleased)
        if activeLasso ~= event or event.returned or not AntiLasso.Enabled then return false end
        if collectionService:HasTag(event.character, 'LassoHooked') then return false end
        if not visualReleased and getLassoObject(event.character) then return false end
        local root = event.root
        local returnCFrame = getSafeReturnCFrame(event)
        if not returnCFrame or lplr.Character ~= event.character or not entitylib.isAlive or entitylib.character.RootPart ~= root then
            clearLasso(event)
            return true
        end
        event.returned = true
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        root.CFrame = returnCFrame
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        if activeLasso == event then
            activeLasso = nil
        end
        return true
    end

    local function waitForRelease(event)
        task.spawn(function()
            local visualReleasedAt
            while activeLasso == event and AntiLasso.Enabled and lplr.Character == event.character and event.root.Parent do
                local tagged = collectionService:HasTag(event.character, 'LassoHooked')
                local visual = getLassoObject(event.character)
                if not tagged and not visual then
                    returnPlayer(event)
                    return
                end
                if not tagged then
                    visualReleasedAt = visualReleasedAt or tick()
                    if tick() - visualReleasedAt >= 1 then
                        returnPlayer(event, true)
                        return
                    end
                else
                    visualReleasedAt = nil
                end
                task.wait(0.05)
            end
        end)
    end

    local function startLasso(character, nativeEvent)
        if not AntiLasso.Enabled or character ~= lplr.Character or ignoredLasso == character then return end
        if activeLasso and activeLasso.character == character then
            if not nativeEvent or not activeLasso.releaseSeen then return end
            clearLasso(activeLasso)
        end
        if Random.new(os.clock()):NextNumber(1, 100) > Chance.Value or Check.Enabled and not entitylib.EntityPosition({
            Range = 50,
            Part = 'RootPart',
            Players = true
        }) then
            if nativeEvent then ignoredLasso = character end
            return
        end
        local root = character:FindFirstChild('HumanoidRootPart') or character.PrimaryPart
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if not root or not humanoid or humanoid.Health <= 0 or not isFiniteCFrame(root.CFrame) then return end
        if activeLasso then clearLasso(activeLasso) end
        lassoVersion += 1
        local event = {
            cframe = root.CFrame,
            character = character,
            root = root,
            token = lassoVersion
        }
        activeLasso = event
        root.Anchored = true
        waitForRelease(event)
    end

    local function releaseLasso(character)
        if ignoredLasso == character then
            ignoredLasso = nil
            return
        end
        local event = activeLasso
        if not event or event.character ~= character then return end
        event.releaseSeen = true
        task.defer(function()
            local deadline = tick() + 1
            repeat
                if activeLasso ~= event or returnPlayer(event) then return end
                task.wait()
            until tick() >= deadline
            returnPlayer(event, true)
        end)
    end

    local function Added(character)
        local previousCharacter = currentCharacter
        disconnectCharacter()
        if previousCharacter ~= character then ignoredLasso = nil end
        if not AntiLasso.Enabled or not character or not character.Parent then return end
        if activeLasso then clearLasso(activeLasso) end
        currentCharacter = character
        -- DescendantAdded, not ChildAdded. The rope is built under the object the game parents to
        -- the character, so at the instant ChildAdded fired that object was still empty and the
        -- lasso went unnoticed every time - which, on a build that no longer tags the character,
        -- left the module with nothing to react to at all.
        table.insert(currentConnections, character.DescendantAdded:Connect(function(descendant)
            if isLassoPart(descendant) then
                startLasso(character)
            end
        end))
        table.insert(currentConnections, character.Destroying:Connect(function()
            if currentCharacter == character then
                disconnectCharacter()
            end
            if activeLasso and activeLasso.character == character then
                clearLasso(activeLasso)
            end
        end))
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if humanoid then
            table.insert(currentConnections, humanoid.Died:Connect(function()
                if activeLasso and activeLasso.character == character then
                    clearLasso(activeLasso)
                end
            end))
        end
        if collectionService:HasTag(character, 'LassoHooked') or getLassoObject(character) then
            startLasso(character, collectionService:HasTag(character, 'LassoHooked'))
        end
    end

    AntiLasso = vape.Categories.Utility:CreateModule({
        Name = 'AntiLasso',
        Function = function(callback)
            if callback then
                AntiLasso:Clean(collectionService:GetInstanceAddedSignal('LassoHooked'):Connect(function(character)
                    if character == lplr.Character then
                        startLasso(character, true)
                    end
                end))
                AntiLasso:Clean(collectionService:GetInstanceRemovedSignal('LassoHooked'):Connect(function(character)
                    if character == lplr.Character then
                        releaseLasso(character)
                    end
                end))
                AntiLasso:Clean(entitylib.Events.LocalAdded:Connect(function(ent)
                    task.defer(function()
                        if AntiLasso.Enabled and ent and ent.Character then
                            Added(ent.Character)
                        end
                    end)
                end))
                AntiLasso:Clean(lplr.OnTeleport:Connect(function()
                    if activeLasso then clearLasso(activeLasso) end
                    ignoredLasso = nil
                    disconnectCharacter()
                end))
                if entitylib.isAlive then
                    Added(lplr.Character)
                end
            else
                lassoVersion += 1
                ignoredLasso = nil
                disconnectCharacter()
                if activeLasso then clearLasso(activeLasso) end
            end
        end,
        Tooltip = 'Prevents you from getting pulled by lasso projectile'
    })

    Chance = AntiLasso:CreateSlider({
        Name = 'Chance',
        Min = 0,
        Max = 100,
        Default = 100,
        Suffix = '%'
    })
    Check = AntiLasso:CreateToggle({Name = 'Only when targeting'})
end)

run(function()
    local AutoPearl
    local Legit
    local Back
    local Check
    local LandCheck
    local BackDelay
    local Limit

    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Include
    local projectileRemote = {InvokeServer = function(self, ...) end}
    task.spawn(function()
	projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local function firePearl(pos, spot, item)
	if Check.Enabled then
		for _, v in store.selfProjectiles do
			if v.Name == 'telepearl' then
				return
			end
		end
	end
	local hotbar, old = getHotbar(item.tool), store.hand

	switchItem(item.tool)
	if Legit.Enabled and hotbar then
		hotbarSwitch(hotbar)
	end

	local meta = bedwars.ProjectileMeta.telepearl
	local calc = prediction.SolveTrajectory(pos, meta.launchVelocity, meta.gravitationalAcceleration, spot, Vector3.zero, workspace.Gravity, 0, 0)
	local landed = false

	if calc then
		local dir = CFrame.lookAt(pos, calc).LookVector * meta.launchVelocity
		local projectile = bedwars.ProjectileController:createLocalProjectile(meta, 'telepearl', 'telepearl', pos, nil, dir, {drawDurationSeconds = 1})
		local res = projectileRemote:InvokeServer(
			item.tool,
			'telepearl',
			'telepearl',
			pos,
			pos,
			dir,
			httpService:GenerateGUID(true),
			{
                    drawDurationSeconds = 1,
                    shotId = httpService:GenerateGUID(false)
                },
			workspace:GetServerTimeNow() - 0.045
		)
		task.spawn(function()
			repeat
				task.wait()
			until not projectile or not projectile.Parent
			landed = true
		end)
		if res then
			pcall(function()
				res.Parent = replicatedStorage
			end)
		end
	end

	if Back.Enabled and LandCheck.Enabled then
		repeat
			task.wait()
		until landed
	end
	if Back.Enabled and old and old.tool then
		task.wait(BackDelay:GetRandomValue())
		switchItem(old.tool)
		if Legit.Enabled and getHotbar(old.tool) then
			hotbarSwitch(getHotbar(old.tool))
		end
	end
    end

    local function findNearGround(origin)
	for _, v in {Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(-1, 0, 0), Vector3.new(0, 0, -1)} do
		for i = 1, 24 do
			local ray = workspace:Raycast((origin.Position + (Vector3.yAxis * 3)) + (v * i), Vector3.new(0, -60, 0), rayCheck)
			if ray then
				return ray.Position
			end
		end
	end
	return nil
    end

    AutoPearl = vape.Categories.Utility:CreateModule({
	Name = 'AutoPearl',
	Function = function(callback)
		if callback then
			local check, lasty
			repeat
				if entitylib.isAlive and (not Limit.Enabled or store.hand.tool and store.hand.tool.Name == 'telepearl') then
					local root = entitylib.character.RootPart
					local pearl = getItem('telepearl')
					rayCheck.FilterDescendantsInstances = {store.map}
					rayCheck.CollisionGroup = root.CollisionGroup

					if entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
						lasty = root.CFrame
					end

					if pearl and root.Velocity.Y < -100 and not workspace:Raycast(root.Position, Vector3.new(0, -200, 0), rayCheck) then
						if not check then
							check = true
							local ground = findNearGround(root.CFrame + Vector3.new(0, 40, 0)) or findNearGround(lasty and lasty + Vector3.new(0, 5, 0) or root.CFrame)
							if ground then
								firePearl(root.Position, ground, pearl)
							end
						end
					else
						check = false
					end
				end
				task.wait(0.1)
			until not AutoPearl.Enabled
		end
	end,
	Tooltip = 'Automatically throws a pearl onto nearby ground after\nfalling a certain distance'
    })

    Legit = AutoPearl:CreateToggle({
	Name = 'Legit Switch',
	Tooltip = 'Visualizes the switching clientside',
	Default = true
    })
    Back = AutoPearl:CreateToggle({
	Name = 'Switch back',
	Default = true,
	Function = function(callback)
		if BackDelay then
			BackDelay.Object.Visible = callback
		end
		if LandCheck then
			LandCheck.Object.Visible = callback
		end
	end,
	Tooltip = 'Switches back to the last slot before pearl'
    })
    LandCheck = AutoPearl:CreateToggle({
	Name = 'Only after landed',
	Tooltip = 'Only switches back after your pearl landed',
	Darker = true
    })
    Check = AutoPearl:CreateToggle({
	Name = 'Pearl check',
	Tooltip = 'Doesn\'t throw a pearl if you are already pearling',
	Default = true
    })
    BackDelay = AutoPearl:CreateTwoSlider({
	Name = 'Switch Back Delay',
	Min = 0,
	Max = 2,
	DefaultMin = 0.1,
	DefaultMax = 0.2,
	Darker = true
    })
    Limit = AutoPearl:CreateToggle({
	Name = 'Limit to item',
	Tooltip = 'Only throws pearl when holding a pearl'
    })
end)

run(function()
    local TritonClutch
    local Legit
    local Back
    local LandCheck
    local BackDelay
    local Limit
    local Recall
    local NoCamera

    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Include
    local projectileRemote = {InvokeServer = function() end}
    task.spawn(function()
	projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local harpoonAbilities = {'harpoon', 'HARPOON', 'harpoon_throw', 'HARPOON_THROW', 'triton_harpoon', 'TRITON_HARPOON'}
    local virtualInputManager = cloneref(game:GetService('VirtualInputManager'))

    local function isHarpoonTool(tool)
	local name = tool and tool.Name and tool.Name:lower()
	return name == 'harpoon' or name == 'trident' or name == 'triton_harpoon'
    end

    local function clickHeldHarpoon(target)
	local camera = workspace.CurrentCamera
	if not camera then
		return false
	end

	local before = #store.selfProjectiles
	local viewport = camera.ViewportSize
	local original = camera.CFrame
	pcall(function()
		camera.CFrame = CFrame.lookAt(original.Position, target)
	end)
	virtualInputManager:SendMouseButtonEvent(viewport.X / 2, viewport.Y / 2, 0, true, game, 0)
	task.wait()
	virtualInputManager:SendMouseButtonEvent(viewport.X / 2, viewport.Y / 2, 0, false, game, 0)
	camera.CFrame = original

	local started = tick()
	repeat
		if #store.selfProjectiles > before then
			return true
		end
		task.wait()
	until tick() - started > 0.25
	return false
    end

    local function waitForHarpoonClutch()
	local started = tick()
	repeat
		task.wait()
		local root = entitylib.isAlive and entitylib.character.RootPart
		if root and root.Velocity.Y > -10 then
			return true
		end
	until not TritonClutch.Enabled or tick() - started > 3
	return false
    end

    task.spawn(function()
	local success, abilityIds = pcall(function()
		return require(replicatedStorage.TS.ability['ability-id']).AbilityId
	end)
	if success then
		for _, ability in abilityIds do
			local lowered = tostring(ability):lower()
			if lowered:find('harpoon', 1, true) then
				table.insert(harpoonAbilities, ability)
			end
		end
	end
    end)

    local function useAbility(list, payloads)
	for _, ability in list do
		local allowed = true
		pcall(function()
			allowed = not bedwars.AbilityController.canUseAbility or bedwars.AbilityController:canUseAbility(ability)
		end)

		if allowed then
			for _, data in payloads do
				local success, result = pcall(function()
					return bedwars.AbilityController:useAbility(ability, newproxy(true), data)
				end)
				if success and result ~= false then
					return true
				end

				success, result = pcall(function()
					return bedwars.AbilityController:useAbility(ability, data)
				end)
				if success and result ~= false then
					return true
				end

				pcall(function()
					bedwars.Client:Get(remotes.UseAbility).instance:FireServer(ability, data)
				end)
			end
		end
	end
	return false
    end

    local function fireHarpoonProjectile(pos, spot, item)
	local projectileType = 'harpoon_projectile'
	local meta = bedwars.ProjectileMeta[projectileType]
	if not meta then
		return false
	end

	local launchVelocity = meta.launchVelocity or 160
	local gravity = meta.gravitationalAcceleration or 0
	local calc = prediction.SolveTrajectory(pos, launchVelocity, gravity, spot, Vector3.zero, workspace.Gravity, 0, 0) or spot
	local dir = CFrame.lookAt(pos, calc).LookVector * launchVelocity
	local shotId = httpService:GenerateGUID(false)
	local landed = false
	local projectile

	pcall(function()
		projectile = bedwars.ProjectileController:createLocalProjectile(meta, projectileType, projectileType, pos, nil, dir, {drawDurationSeconds = 1})
	end)

	if projectile then
		task.spawn(function()
			repeat
				task.wait()
			until not projectile or not projectile.Parent
			landed = true
		end)
	end

	local success, result = pcall(function()
		return projectileRemote:InvokeServer(
			item.tool,
			projectileType,
			projectileType,
			pos,
			pos,
			dir,
			httpService:GenerateGUID(true),
			{
				drawDurationSeconds = 1,
				shotId = shotId
			},
			workspace:GetServerTimeNow() - 0.045
		)
	end)

	return success and result ~= nil, function()
		local started = tick()
		repeat
			task.wait()
		until landed or not TritonClutch.Enabled or tick() - started > 3
		return landed
	end
    end

    local function useHarpoon(pos, spot, item)
	local hotbar, old = getHotbar(item.tool), store.hand
	switchItem(item.tool)
	if Legit.Enabled and hotbar then
		hotbarSwitch(hotbar)
	end

	local used, clutchCheck, recallWait
	if not NoCamera.Enabled and clickHeldHarpoon(spot) then
		clutchCheck = waitForHarpoonClutch
		used = true
	else
		used, clutchCheck = fireHarpoonProjectile(pos, spot, item)
	end

	if not used then
		used = useAbility(harpoonAbilities, {
			{target = spot, origin = pos},
			{targetPosition = spot, position = pos},
			{position = spot},
			spot
		})
		clutchCheck = waitForHarpoonClutch
	end

	if used and Recall.Enabled then
		recallWait = function()
			task.wait(1.25)
			virtualInputManager:SendKeyEvent(true, Enum.KeyCode.C, false, game)
			task.wait()
			virtualInputManager:SendKeyEvent(false, Enum.KeyCode.C, false, game)

			local started, lastPosition, stable = tick(), nil, 0
			repeat
				task.wait(0.1)
				local root = entitylib.isAlive and entitylib.character.RootPart
				if root then
					local currentPosition = root.Position
					local moved = lastPosition and (currentPosition - lastPosition).Magnitude or math.huge
					if tick() - started > 0.75 and moved < 1 and root.Velocity.Magnitude < 8 then
						stable += 0.1
						if stable >= 0.3 then
							return true
						end
					else
						stable = 0
					end
					lastPosition = currentPosition
				end
			until not TritonClutch.Enabled or tick() - started > 7
			return false
		end
	end

	if Back.Enabled and LandCheck.Enabled and clutchCheck then
		clutchCheck()
	end
	if Back.Enabled and old and old.tool then
		if recallWait then
			recallWait()
		else
			task.wait(BackDelay:GetRandomValue())
		end
		switchItem(old.tool)
		if Legit.Enabled and getHotbar(old.tool) then
			hotbarSwitch(getHotbar(old.tool))
		end
	elseif recallWait then
		task.spawn(recallWait)
	end
    end

    local function findNearGround(origin, root)
	local best, bestScore
	local originPosition = origin.Position
	local velocity = root and root.Velocity or Vector3.zero
	local horizontalVelocity = Vector3.new(velocity.X, 0, velocity.Z)
	local fallSpeed = math.max(-velocity.Y, 0)
	local samples = {}

	local function addSample(position)
		table.insert(samples, position)
	end

	local function getAimPoint(ray, predictedPosition)
		local hit = ray.Position + (ray.Normal * 0.35)
		local part = ray.Instance
		if part and part:IsA('BasePart') then
			local size = part.Size
			local localPredicted = part.CFrame:PointToObjectSpace(predictedPosition)
			local edgeMargin = math.min(0.45, math.max(math.min(size.X, size.Z) * 0.2, 0.08))
			local xLimit = math.max((size.X * 0.5) - edgeMargin, 0)
			local zLimit = math.max((size.Z * 0.5) - edgeMargin, 0)
			localPredicted = Vector3.new(math.clamp(localPredicted.X, -xLimit, xLimit), size.Y * 0.5 + 0.25, math.clamp(localPredicted.Z, -zLimit, zLimit))
			hit = part.CFrame:PointToWorldSpace(localPredicted)
		end
		return hit
	end

	addSample(originPosition)
	for time = 0.15, 2.4, 0.15 do
		local predictedPosition = originPosition + (horizontalVelocity * time) + Vector3.new(0, (velocity.Y * time) - (workspace.Gravity * time * time * 0.5), 0)
		local center = Vector3.new(predictedPosition.X, originPosition.Y, predictedPosition.Z)
		addSample(center)
		for radius = 1, 12, 1 do
			for angle = 0, 315, 45 do
				local radians = math.rad(angle)
				addSample(center + Vector3.new(math.cos(radians) * radius, 0, math.sin(radians) * radius))
			end
		end
	end

	for radius = 16, 72, 4 do
		for angle = 0, 315, 45 do
			local radians = math.rad(angle)
			addSample(originPosition + (horizontalVelocity * 0.65) + Vector3.new(math.cos(radians) * radius, 0, math.sin(radians) * radius))
		end
	end

	for _, sample in samples do
		local ray = workspace:Raycast(sample + Vector3.new(0, 128, 0), Vector3.new(0, -420, 0), rayCheck)
		if ray then
			local drop = math.max(originPosition.Y - ray.Position.Y, 1)
			local timeToPlatform = math.clamp((math.sqrt((fallSpeed * fallSpeed) + (2 * workspace.Gravity * drop)) - fallSpeed) / workspace.Gravity, 0.05, 2.5)
			local predictedPosition = originPosition + (horizontalVelocity * timeToPlatform)
			local aimPoint = getAimPoint(ray, predictedPosition)
			local horizontalDistance = (Vector3.new(aimPoint.X, originPosition.Y, aimPoint.Z) - Vector3.new(originPosition.X, originPosition.Y, originPosition.Z)).Magnitude
			local predictedDistance = (Vector3.new(aimPoint.X, predictedPosition.Y, aimPoint.Z) - Vector3.new(predictedPosition.X, predictedPosition.Y, predictedPosition.Z)).Magnitude
			local score = (predictedDistance * 1.35) + (horizontalDistance * 0.25) + (drop * 0.015)
			if not bestScore or score < bestScore then
				best, bestScore = aimPoint, score
			end
		end
	end
	return best
    end


    TritonClutch = kits:CreateModule({
	Name = 'TritonClutch',
	Category = 'Ability',
	Function = function(callback)
		if callback then
			local lasty, attempted
			repeat
				if entitylib.isAlive and (not Limit.Enabled or isHarpoonTool(store.hand.tool)) then
					local root = entitylib.character.RootPart
					local harpoon = getItem('harpoon') or getItem('triton_harpoon') or getItem('trident')
					rayCheck.FilterDescendantsInstances = {store.map}
					rayCheck.CollisionGroup = root.CollisionGroup

					local onGround = entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air
					if onGround then
						lasty = root.CFrame
						attempted = false
					end

					if not onGround and not attempted and harpoon and root.Velocity.Y < -60 and not workspace:Raycast(root.Position, Vector3.new(0, -140, 0), rayCheck) then
						attempted = true
						local ground = findNearGround(root.CFrame, root) or findNearGround(lasty and lasty + Vector3.new(0, 5, 0) or root.CFrame, root)
						if ground then
							useHarpoon(root.Position, ground, harpoon)
						end
					end
				end
				task.wait(0.03)
			until not TritonClutch.Enabled
		end
	end,
	Tooltip = 'Automatically throws Triton\'s harpoon onto nearby ground after falling a certain distance'
    })

    Legit = TritonClutch:CreateToggle({
	Name = 'Legit Switch',
	Tooltip = 'Visualizes the switching clientside',
	Default = true
    })
    Back = TritonClutch:CreateToggle({
	Name = 'Switch back',
	Default = true,
	Function = function(callback)
		if BackDelay then
			BackDelay.Object.Visible = callback
		end
		if LandCheck then
			LandCheck.Object.Visible = callback
		end
	end,
	Tooltip = 'Switches back to the previous slot after Recall finishes, or after the clutch delay when Recall is off'
    })
    LandCheck = TritonClutch:CreateToggle({
	Name = 'Only after clutch',
	Tooltip = 'Waits for the harpoon clutch before switching back; Recall still waits until the recall finishes',
	Darker = true
    })
    BackDelay = TritonClutch:CreateTwoSlider({
	Name = 'Switch Back Delay',
	Min = 0,
	Max = 2,
	DefaultMin = 0.1,
	DefaultMax = 0.2,
	Darker = true
    })
    Limit = TritonClutch:CreateToggle({
	Name = 'Limit to items',
	Tooltip = "Only throws Triton's harpoon when holding the harpoon or trident"
    })
    NoCamera = TritonClutch:CreateToggle({
	Name = 'Prevent Camera Movement',
	Tooltip = 'Uses server projectile logic instead of moving your camera for the click fallback',
	Default = true
    })
    Recall = TritonClutch:CreateToggle({
	Name = 'Recall',
	Tooltip = 'Presses C to activate Recall / Go to base after clutching'
    })
end)



run(function()
    local AutoPlay
    local Random
    -- One queue attempt in flight at a time; the death and match-end paths can both fire.
    local queueing = false

    local function isEveryoneDead()
        return #bedwars.Store:getState().Party.members <= 0
    end

    -- BedWars only accepts a queue request from the party leader, and only while the party is not
    -- already queued. Playing solo there is no party at all, so reading Party.leader.userId threw
    -- straight out of the event handler and the queue was never even attempted - which is most of
    -- "AutoPlay doesn't queue". A missing leader is us.
    local function canQueue()
        local ok, res = pcall(function()
            local state = bedwars.Store:getState()
            if state.Game.customMatch then return false end
            local party = state.Party
            local leader = party and party.leader
            if leader and leader.userId and leader.userId ~= lplr.UserId then return false end
            return (party and party.queueState or 0) == 0
        end)
        return ok and res == true
    end

    local function pickMode()
        if not Random.Enabled then return store.queueType end
        local listofmodes = {}
        pcall(function()
            for i, v in bedwars.QueueMeta do
                if not v.disabled and not v.voiceChatOnly and not v.rankCategory then
                    table.insert(listofmodes, i)
                end
            end
        end)
        return #listofmodes > 0 and listofmodes[math.random(1, #listofmodes)] or store.queueType
    end

    local function joinQueue()
        if queueing or not AutoPlay.Enabled or not canQueue() then return end
        queueing = true
        local mode = pickMode()
        pcall(function() bedwars.QueueController:joinQueue(mode) end)
        -- The request sent on the match-end frame is sometimes swallowed while the end screen is
        -- still animating in. Check back once and send it again if nothing took, rather than
        -- firing blind and sitting in the lobby.
        task.delay(6, function()
            if AutoPlay.Enabled and canQueue() then
                pcall(function() bedwars.QueueController:joinQueue(mode) end)
            end
            queueing = false
        end)
    end

    AutoPlay = vape.Categories.Utility:CreateModule({
        Name = 'AutoPlay',
        Function = function(callback)
            if callback then
                queueing = false
                AutoPlay:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
                    if deathTable.finalKill and deathTable.entityInstance == lplr.Character and isEveryoneDead() and store.matchState ~= 2 then
                        joinQueue()
                    end
                end))
                AutoPlay:Clean(vapeEvents.MatchEndEvent.Event:Connect(joinQueue))
            end
        end,
        Tooltip = 'Automatically queues after the match ends'
    })
    Random = AutoPlay:CreateToggle({
        Name = 'Random',
        Tooltip = 'Chooses a random mode'
    })
end)

run(function()
	local LeaveParty
	LeaveParty = vape.Categories.Utility:CreateModule({
		Name = 'LeaveParty',
		Function = function(enabled)
			if not enabled then return end
			local ok = pcall(function()
				bedwars.PartyController:leaveParty()
			end)
			if not ok then
				notif('LeaveParty', 'Party controls are unavailable.', 4, 'warning')
			end
			-- Action module: it must not remain enabled after the one request.
			task.defer(function() if LeaveParty.Enabled then LeaveParty:Toggle() end end)
		end,
		Tooltip = 'Leaves the current BedWars party'
	})
end)

run(function()
    local AutoRelease
    local Percentage
    local Delay

    local launchHook, last = nil, 0
    local charge = 0

    AutoRelease = vape.Categories.Utility:CreateModule({
	Name = 'AutoRelease',
	Function = function(call)
		if call then
			launchHook = bedwars.ProjectileLaunchHook:Add('AutoRelease', 20, function(nextLaunch, ...)
				local projmeta = select(2, ...)
				if projmeta and typeof(projmeta) == 'table' then
					charge = (projmeta.velocityMultiplier / 1) * 100
					last = os.clock() + 0.1
				end

				return nextLaunch(...)
			end)

			repeat
				if last > os.clock() and charge >= Percentage.Value then
					task.wait(Delay.Value)
					mouse1click()
					task.wait(0.2)
				end
				task.wait()
			until not AutoRelease.Enabled
		else
			if launchHook then
				launchHook()
				launchHook = nil
			end
		end
	end,
        Tooltip = 'Automatically releases your projectile source when\nat certain charging percentage'
    })

    Percentage = AutoRelease:CreateSlider({
	Name = 'Percentage',
	Min = 0,
	Max = 100,
	Suffix = '%',
	Default = 100,
    })
    Delay = AutoRelease:CreateSlider({
	Name = 'Release delay',
	Min = 0,
	Max = 5,
	Default = 0.5,
	Decimal = 10,
	Suffix = function(val)
		return val <= 1 and 'sec' or 'secs'
	end,
    })
end)

run(function()
	local AutoShoot
	local Targets
	local Check
	local Projectiles
	local UseSophia
	local UseWhim
	local FireRate
	local SwitchDelay

	local fireDelays = {}
	local generation = 0
	local firing
	local projectileRemote
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Exclude

	local function getTarget(origin)
		local facing = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
		for _, target in entitylib.AllPosition({
			Origin = origin,
			Part = 'RootPart',
			Range = 22,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled,
			Limit = 10,
			Sort = sortmethods.Distance
		}) do
			local delta = (target.RootPart.Position - origin) * Vector3.new(1, 0, 1)
			if facing.Magnitude == 0 or delta.Magnitude == 0 or facing.Unit:Dot(delta.Unit) >= math.cos(math.rad(60)) then return target end
		end
	end

	local function getDirection(origin, target, projectileMeta)
		local speed = projectileMeta.launchVelocity
		if type(speed) ~= 'number' or speed <= 0 then return end
		if not target then return gameCamera.CFrame.LookVector * speed end
		rayCheck.FilterDescendantsInstances = {lplr.Character, target.Character, gameCamera}
		local gravity = projectileMeta.gravitationalAcceleration or 196.2
		local solution = solveBedwarsProjectile(origin, speed, gravity, target, target.RootPart.Position, {
			RaycastParams = rayCheck,
			Lifetime = projectileMeta.lifetimeSec or 3
		})
		return solution and solution.Velocity or nil
	end

	local function fireOne(data, target, token)
		local item, ammo, projectile, source, projectileMeta = table.unpack(data)
		if token ~= generation or not AutoShoot.Enabled or not entitylib.isAlive or not item.tool or not item.tool.Parent then return false end
		local now = workspace:GetServerTimeNow()
		if (fireDelays[item.itemType] or 0) > now then return false end
		local slot = getHotbar(item.tool)
		if not slot or not hotbarSwitch(slot) then return false end
		task.wait(math.clamp(lplr:GetNetworkPing(), 0, 0.2))
		if token ~= generation or not AutoShoot.Enabled or not entitylib.isAlive then return false end

		local root = entitylib.character.RootPart
		local rootPosition = root.Position
		local velocity = getDirection(rootPosition, target, projectileMeta)
		if not velocity then return false end
		local shootPosition = projectileLaunchOrigin(rootPosition, velocity)
		-- Re-solve from the actual launch offset so close targets do not receive a visibly
		-- different local trajectory from the server request.
		velocity = getDirection(shootPosition, target, projectileMeta) or velocity
		local id = httpService:GenerateGUID(true)
		local draw = {drawDurationSeconds = 1, shotId = httpService:GenerateGUID(false)}
		local created = pcall(bedwars.ProjectileController.createLocalProjectile, bedwars.ProjectileController,
			projectileMeta, ammo, projectile, shootPosition, id, velocity, draw)
		if not created then return false end

		local called, result = pcall(projectileRemote.InvokeServer, projectileRemote,
			item.tool, ammo, projectile, shootPosition, rootPosition, velocity, id, draw,
			workspace:GetServerTimeNow() - 0.045)
		fireDelays[item.itemType] = workspace:GetServerTimeNow() + (source.fireDelaySec or 0) + FireRate:GetRandomValue()
		if not called then return false end
		store.lastProjectileFire = workspace:GetServerTimeNow()
		if target then
			targetinfo.Targets[target] = tick() + 1
			prediction.trackShot(target.RootPart)
		end
		local sounds = source.launchSound
		local sound = type(sounds) == 'table' and #sounds > 0 and sounds[math.random(1, #sounds)] or nil
		if sound then pcall(bedwars.SoundManager.playSound, bedwars.SoundManager, sound) end
		return result ~= false
	end

	local function shoot(token)
		if firing or token ~= generation or not entitylib.isAlive then return end
		firing = token
		local originalSlot = store.hand.tool and getHotbar(store.hand.tool) or nil
		local origin = entitylib.character.RootPart.Position
		local target = getTarget(origin)
		if not Check.Enabled or target then
			for _, data in getProjectiles(Projectiles.ListEnabled, UseSophia.Enabled, UseWhim.Enabled) do
				if token ~= generation or not AutoShoot.Enabled then break end
				local ok, fired = pcall(fireOne, data, target, token)
				if ok and fired then task.wait(SwitchDelay.Value) end
			end
		end
		if token == generation and originalSlot ~= nil then hotbarSwitch(originalSlot) end
		if firing == token then firing = nil end
	end

	AutoShoot = vape.Categories.Utility:CreateModule({
		Name = 'AutoShoot',
		Function = function(enabled)
			generation += 1
			firing = nil
			if not enabled then return end
			local token = generation
			local ok, remote = pcall(function() return bedwars.Client:Get(remotes.FireProjectile).instance end)
			if not ok or not remote or type(remote.InvokeServer) ~= 'function' then
				notif('AutoShoot', 'The projectile remote is unavailable.', 5, 'warning')
				AutoShoot:Toggle()
				return
			end
			projectileRemote = remote
			local lastSwing = bedwars.SwordController.lastSwing or 0
			AutoShoot:Clean(task.spawn(function()
				while AutoShoot.Enabled and token == generation do
					local swing = bedwars.SwordController.lastSwing or 0
					if swing > lastSwing and tick() - swing <= 0.25 then
						lastSwing = swing
						task.spawn(shoot, token)
					else
						lastSwing = math.max(lastSwing, swing)
					end
					task.wait(0.03)
				end
			end))
		end,
		Tooltip = 'Fires compatible projectiles once after each manual sword swing'
	})
	Targets = AutoShoot:CreateTargets({Players = true})
	Check = AutoShoot:CreateToggle({
		Name = 'Target check',
		Default = true,
		Function = function(callback)
			if Targets.Object then Targets.Object.Visible = callback end
		end
	})
	Projectiles = AutoShoot:CreateTextList({Name = 'Projectiles', Default = {'arrow', 'snowball'}})
	UseSophia = AutoShoot:CreateToggle({Name = 'Use sophia', Tooltip = 'Also shoots compatible Sophia frost projectiles'})
	UseWhim = AutoShoot:CreateToggle({Name = 'Use whim', Tooltip = 'Also shoots compatible Whim book projectiles'})
	FireRate = AutoShoot:CreateTwoSlider({Name = 'Fire Rate', Min = 0, Max = 1, DefaultMin = 0.05, DefaultMax = 0.12, Decimal = 100})
	SwitchDelay = AutoShoot:CreateSlider({Name = 'Switch Delay', Min = 0, Max = 1, Decimal = 100, Suffix = 'seconds', Default = 0.02})
end)
run(function()
    local AutoToxic
    local GG
    local Delay
    local TrollTriggers
    local trollCooldown = 0
    local Toggles, Lists, said, dead = {}, {}, {}

    -- Actually push a line to chat. Split out so both the message picker below and
    -- the match-end "gg" can share the Delay slider: when Delay > 0 the send is
    -- deferred that many seconds (the message is still chosen now, so the
    -- no-repeat logic is unaffected).
    local function doSend(text)
        if not text or text == '' then return end
        local wait = Delay and Delay.Value or 0
        local function push()
            if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
                textChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(text)
            else
                replicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(text, 'All')
            end
        end
        if wait > 0 then
            task.delay(wait, function() pcall(push) end)
        else
            push()
        end
    end

    local function sendMessage(name, obj, default)
        local tab = Lists[name].ListEnabled
        local custommsg = #tab > 0 and tab[math.random(1, #tab)] or default
        if not custommsg then return end
        if #tab > 1 and custommsg == said[name] then
            repeat
                task.wait()
                custommsg = tab[math.random(1, #tab)]
            until custommsg ~= said[name]
        end
        said[name] = custommsg

        custommsg = custommsg and custommsg:gsub('<obj>', obj or '') or ''
        doSend(custommsg)
    end

    AutoToxic = vape.Categories.Utility:CreateModule({
        Name = 'AutoToxic',
        Function = function(callback)
            if callback then
                AutoToxic:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(bedTable)
                    if Toggles.BedDestroyed.Enabled and bedTable.brokenBedTeam.id == lplr:GetAttribute('Team') then
                        sendMessage('BedDestroyed', (bedTable.player.DisplayName or bedTable.player.Name), 'how dare you >:( | <obj>')
                    elseif Toggles.Bed.Enabled and bedTable.player.UserId == lplr.UserId then
                        local team = bedwars.QueueMeta[store.queueType].teams[tonumber(bedTable.brokenBedTeam.id)]
                        sendMessage('Bed', team and team.displayName:lower() or 'white', 'nice bed lul | <obj>')
                    end
                end))
                AutoToxic:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
                    if deathTable.finalKill then
                        local killer = playersService:GetPlayerFromCharacter(deathTable.fromEntity)
                        local killed = playersService:GetPlayerFromCharacter(deathTable.entityInstance)
                        if not killed or not killer then return end
                        if killed == lplr then
                            if (not dead) and killer ~= lplr and Toggles.Death.Enabled then
                                dead = true
                                sendMessage('Death', (killer.DisplayName or killer.Name), 'my gaming chair subscription expired :( | <obj>')
                            end
                        elseif killer == lplr and Toggles.Kill.Enabled then
                            sendMessage('Kill', (killed.DisplayName or killed.Name), 'vxp on top | <obj>')
                        end
                    end
                end))
                AutoToxic:Clean(vapeEvents.MatchEndEvent.Event:Connect(function(winstuff)
                    if GG.Enabled then
                        doSend('gg')
                    end

                    local myTeam = bedwars.Store:getState().Game.myTeam
                    if myTeam and myTeam.id == winstuff.winningTeamId or lplr.Neutral then
                        if Toggles.Win.Enabled then
                            sendMessage('Win', nil, 'yall garbage')
                        end
                    end
                end))

                -- Troll: watch incoming chat and clap back when another player calls you
                -- a hacker/cheater (or any configured trigger phrase). A short cooldown
                -- stops it spamming when several people pile on at once.
                local function handleIncoming(speakerName, text, speakerUserId)
                    if not (Toggles.Troll and Toggles.Troll.Enabled) or not text or text == '' then return end
                    if speakerUserId and speakerUserId == lplr.UserId then return end
                    if speakerName and speakerName == lplr.Name then return end
                    if tick() < trollCooldown then return end
                    local lower = text:lower()
                    for _, phrase in TrollTriggers.ListEnabled do
                        if phrase ~= '' and lower:find(phrase:lower(), 1, true) then
                            trollCooldown = tick() + 6
                            task.spawn(sendMessage, 'Troll', speakerName, 'mad cause bad | <obj>')
                            break
                        end
                    end
                end

                if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
                    AutoToxic:Clean(textChatService.MessageReceived:Connect(function(message)
                        local src = message.TextSource
                        handleIncoming(src and src.Name, message.Text, src and src.UserId)
                    end))
                else
                    AutoToxic:Clean(replicatedStorage.DefaultChatSystemChatEvents.OnMessageDoneFiltering.OnClientEvent:Connect(function(data)
                        if type(data) == 'table' then
                            handleIncoming(data.FromSpeaker, data.Message, nil)
                        end
                    end))
                end
            end
        end,
        Tooltip = 'Says a message after a certain action'
    })
    GG = AutoToxic:CreateToggle({
        Name = 'AutoGG',
        Default = true
    })
    Delay = AutoToxic:CreateSlider({
        Name = 'Delay',
        Min = 0,
        Max = 10,
        Default = 0,
        Decimal = 10,
        Suffix = 's',
        Tooltip = 'How long to wait after the triggering action before sending, 0 for instant'
    })
    for _, v in {'Kill', 'Death', 'Bed', 'BedDestroyed', 'Win'} do
        Toggles[v] = AutoToxic:CreateToggle({
            Name = v..' ',
            Function = function(callback)
                if Lists[v] then
                    Lists[v].Object.Visible = callback
                end
            end
        })
        Lists[v] = AutoToxic:CreateTextList({
            Name = v,
            Darker = true,
            Visible = false
        })
    end
    Toggles.Troll = AutoToxic:CreateToggle({
        Name = 'Troll ',
        Tooltip = 'Detects when someone calls you a hacker/cheater in chat and automatically replies',
        Function = function(callback)
            if TrollTriggers then TrollTriggers.Object.Visible = callback end
            if Lists.Troll then Lists.Troll.Object.Visible = callback end
        end
    })
    TrollTriggers = AutoToxic:CreateTextList({
        Name = 'Troll Triggers',
        Tooltip = 'Phrases said by others that trigger a reply (matched anywhere in their message)',
        Default = {'hacker', 'hacks', 'hacking', 'hax', 'cheater', 'cheating', 'cheat', 'exploiter', 'exploiting', 'aimbot'},
        Darker = true,
        Visible = false
    })
    Lists.Troll = AutoToxic:CreateTextList({
        Name = 'Troll Replies',
        Tooltip = 'Replies to send. <obj> is replaced with the accuser\'s name',
        Default = {'mad cause bad | <obj>', 'skill issue <obj>', 'cry about it <obj>', 'not my fault youre bad', 'imagine losing to a "hacker" lol'},
        Darker = true,
        Visible = false
    })
end)

run(function()
    local AutoVoidDrop
    local OwlCheck
    local PearlCheck

    local pearlRay = RaycastParams.new()
    pearlRay.RespectCanCollide = true
    pearlRay.FilterType = Enum.RaycastFilterType.Exclude

    -- Where a telepearl we threw is going to put us. The arc is walked forward in short steps
    -- with a cast between each pair, so the first thing it would hit is the landing. Estimated,
    -- not exact - it only has to answer "is there ground at the end of this", which is the
    -- difference between saving the loot and throwing it into the void for nothing.
    local function pearlLandsOnGround(pearl, lowestpoint)
        local position = pearl.Position
        local velocity = pearl.AssemblyLinearVelocity
        -- A pearl carried by a controller rather than by physics reports no velocity, and there
        -- is nothing to project from. Unknown counts as "keep the loot".
        if velocity.Magnitude < 1 then return true end

        local meta = bedwars.ProjectileMeta.telepearl
        local gravity = (meta and meta.gravitationalAcceleration) or workspace.Gravity
        pearlRay.FilterDescendantsInstances = {lplr.Character, gameCamera, pearl}

        local step = 0.05
        for _ = 1, 120 do
            local nextPosition = position + (velocity * step)
            local result = workspace:Raycast(position, nextPosition - position, pearlRay)
            if result then
                return result.Position.Y > lowestpoint
            end
            if nextPosition.Y < lowestpoint then return false end
            position = nextPosition
            velocity -= Vector3.new(0, gravity * step, 0)
        end
        -- Still airborne after six seconds: no landing found, so it is not saving us.
        return false
    end

    local function pearlWillSave(lowestpoint)
        for _, projectile in store.selfProjectiles do
            if projectile.Parent and projectile.Name == 'telepearl' and pearlLandsOnGround(projectile, lowestpoint) then
                return true
            end
        end
        return false
    end

    AutoVoidDrop = vape.Categories.Utility:CreateModule({
        Name = 'AutoVoidDrop',
        Function = function(callback)
            if callback then
                repeat task.wait() until store.matchState ~= 0 or (not AutoVoidDrop.Enabled)
                if not AutoVoidDrop.Enabled then return end

                local lowestpoint = math.huge
                for _, v in store.blocks do
                    local point = (v.Position.Y - (v.Size.Y / 2)) - 50
                    if point < lowestpoint then
                        lowestpoint = point
                    end
                end

                repeat
                    if entitylib.isAlive then
                        local root = entitylib.character.RootPart
                        if root.Position.Y < lowestpoint and (lplr.Character:GetAttribute('InflatedBalloons') or 0) <= 0 and not getItem('balloon') then
                            local saved = OwlCheck.Enabled and root:FindFirstChild('OwlLiftForce')
                                or (PearlCheck.Enabled and pearlWillSave(lowestpoint))
                            if not saved then
                                for _, item in {'iron', 'diamond', 'emerald', 'gold'} do
                                    item = getItem(item)
                                    if item then
                                        item = bedwars.Client:Get(remotes.DropItem):CallServer({
                                            item = item.tool,
                                            amount = item.amount
                                        })

                                        if item then
                                            item:SetAttribute('ClientDropTime', tick() + 100)
                                        end
                                    end
                                end
                            end
                        end
                    end

                    task.wait(0.1)
                until not AutoVoidDrop.Enabled
            end
        end,
        Tooltip = 'Drops resources when you fall into the void'
    })
    OwlCheck = AutoVoidDrop:CreateToggle({
        Name = 'Owl check',
        Default = true,
        Tooltip = 'Refuses to drop items if being picked up by an owl'
    })
    PearlCheck = AutoVoidDrop:CreateToggle({
        Name = 'Pearl check',
        Default = true,
        Tooltip = 'Keeps your loot if a telepearl you threw is still in the air and looks like it lands on ground'
    })
end)

run(function()
    local BackTrack
    local Mode
    local Latency
    local Tick

    BackTrack = vape.Categories.Utility:CreateModule({
        Name = 'BackTrack',
        Function = function(callback)
            if callback then
                repeat
                    local ent = entitylib.EntityPosition({
                        Part = 'RootPart',
                        Range = 22,
                        Players = true,
                        Wallcheck = true,
                    })

                    if ent then
                        if Mode.Value == 'Manual' then
                            setfflag('TargetTimeDelayFacctorTenths', '50000')
                            task.wait(0.05 * Tick.Value)
                            setfflag('TargetTimeDelayFacctorTenths', '20')
                            task.wait(0.05 * Tick.Value)
                        else
                            setfflag('TargetTimeDelayFacctorTenths', tostring(math.floor(20 + (Latency:GetRandomValue() / 20))))
                            task.wait(1)
                        end
                    else
                        setfflag('TargetTimeDelayFacctorTenths', '20')
                    end
                    task.wait()
                until not BackTrack.Enabled
            end
        end,
        Tooltip = 'Lags targets at certain times to increase attack distance'
    })
    getgenv().Backtrack = BackTrack
    Latency = BackTrack:CreateTwoSlider({
        Name = 'Latency',
        Min = 1,
        Max = 500,
        DefaultMin = 50,
        DefaultMax = 120,
        Darker = true,
    })
    Tick = BackTrack:CreateSlider({
        Name = 'Ticks',
        Min = 1,
        Max = 20,
        Default = 5,
        Darker = true,
        Visible = false,
    })
    Mode = BackTrack:CreateDropdown({
        Name = 'Mode',
        List = { 'Manual', 'Lag Based' },
        Default = 'Manual',
        Function = function(val)
            if Latency and Tick then
                Latency.Object.Visible = val == 'Manual'
                Tick.Object.Visible = val == 'Lag Based'
            end
        end,
    })
end)

run(function()
    -- CheatDetector
    --
    -- Everything here is measured through our own connection, which is the whole problem: what we
    -- see is a lagged, interpolated copy of what the server actually resolved. So every check is
    -- built the same way - a reading only counts when it is impossible rather than merely
    -- surprising, readings taken through bad conditions are thrown away instead of counted, and
    -- nobody is flagged until several independent readings of the same kind have stacked up.
    --
    -- Nothing here looks at what anybody is RUNNING. There is no module list, no remote name and
    -- no signature to keep up to date - every check reads position, timing and replicated state,
    -- which is all a cheat can never hide, because the whole point of a cheat is that the server
    -- and everyone else can see what it did.
    --
    -- One loop does all the polling. Each position-based check is a function fed the same
    -- once-per-tick snapshot of every player rather than its own thread walking the entity list,
    -- so the cost of the module is one pass over the players every tenth of a second no matter
    -- how many checks are ticked on.
    local CheatDetector
    local Toggles = {}

    -- Detections, in the order they are offered. A group with children is a heading: its own
    -- toggle gates the whole family, and the children pick which of them run.
    local GROUPS = {
        {Name = 'Impossible hits', Children = {'Killaura', 'SilentAim', 'HitBoxes', 'Reach'}},
        {Name = 'Blatant modules', Children = {'PlayerAttach', 'AntiDeath', 'Phase', 'Invisible', 'HighJump', 'Speed'}},
        {Name = 'Bypasses', Children = {'NoFallDamage', 'VoidFlight', 'ExtremeSpeed'}},
        {Name = 'AutoKit'},
        {Name = 'Crashers', Children = {'Animation', 'Remote'}},
        {Name = 'Breaker'},
        {Name = 'ProjectileAimbot and Aura'}
    }

    -- Off by default, and deliberately named so nobody leaves it on by accident. Every check below
    -- is written to read somebody else's replicated state, and the local player is normally exempt
    -- from all of them; this lifts that exemption so the detector measures us too. It changes who
    -- is looked at and nothing else - the checks still read behaviour, never which of our own
    -- modules happen to be on, so a flag here means the cheat was actually visible from outside.
    local DETECT_SELF = '[TEST] Detect self'

    -- How often every position-based check gets its sample.
    local POLL_INTERVAL = 0.1
    -- A strike older than this is forgotten. Long enough that a cheat running all match keeps
    -- stacking up, short enough that unrelated anomalies minutes apart never add together.
    local STRIKE_MEMORY = 45
    -- Nothing is measured through a connection worse than this. Above it, event timings and
    -- replicated positions are both fiction and every check would be reading noise. Our own
    -- behaviour is exempt: there is no network between us and our own character.
    local MAX_PING = 0.3
    -- A position step larger than this is streaming, a respawn or a real teleport, never movement.
    local TELEPORT_STEP = 100

    -- Speed. Sprint in this game is 20 studs/s and every legitimate way past that - a potion, a
    -- kit dash, a launch pad - is either a burst that decays within a second or announces itself
    -- through a status effect. So the limit is only a little over sprint, and what makes it safe
    -- is that it has to be HELD: the average has to stay over it across a continuous run of
    -- movement, which a dash, a pounce, a grapple or a knockback cannot do.
    local SPEED_LIMIT = 22
    local SPEED_WINDOW = 1.6
    -- No single sample above this is movement at all - it is a respawn, a streaming pop or a
    -- teleport that did not set the attribute. Counting one of those into a run is how a player
    -- who then simply sprints away gets flagged for it, so a sample this size ends the run.
    local SPEED_SANE = 60

    -- Reach. Every sword in the game swings 14.4 studs or less, so a hit landing past this is
    -- past the weapon whatever is being held. This is the one number that catches an aura built
    -- to fake its own position: the fake goes in the packet, but the body everyone else sees
    -- stays where it really is, and that is what gets measured here.
    local REACH_LIMIT = 15.5

    -- Killaura. No hand clicks faster than this, whatever the CPS cap says.
    local MIN_HUMAN_INTERVAL = 0.1
    -- An aura fires the instant the swing cooldown is up, every time, so the gaps between its
    -- hits stop varying. A hand saturating the same cooldown still scatters by tens of
    -- milliseconds, so the window is deliberately tighter than human jitter.
    local CADENCE_SAMPLES = 6
    local CADENCE_SPREAD = 0.03
    -- Sustained rate. A sword is on a cooldown near three tenths of a second, so even a hand
    -- that never misses and never stops cannot land four a second - which is where this sits,
    -- deliberately above the fastest legitimate weapon rather than at the pace of a fast mouse.
    local BURST_HITS, BURST_WINDOW = 10, 2.5
    -- Aura targeting: hitting this many different players inside the window means the aim moved
    -- between them instantly, which is the one signature clicking quickly cannot produce.
    local SWITCH_VICTIMS, SWITCH_WINDOW = 3, 1.2

    -- PlayerAttach. Riding somebody puts you inside arm's length of them and holds you there,
    -- with the separation barely moving, while the pair of you travel. Getting there is a jump
    -- no run can make.
    local ATTACH_RANGE = 3
    local ATTACH_SAMPLES = 10
    local ATTACH_TRAVEL = 6
    local ATTACH_JITTER = 1.2
    local ATTACH_JUMP = 12
    local ATTACH_RATE = 100

    -- AntiDeath. Parking the hitbox out of reach and bringing it back is a vertical step no fall
    -- produces: free fall tops out near 200 studs/s, so anything past this was set, not fallen.
    local VERTICAL_TELEPORT = 25
    local VERTICAL_RATE = 320
    local VERTICAL_REVERSALS, VERTICAL_MEMORY = 2, 3

    -- Crashers are floods, and the bar has to sit well above a player having a busy second -
    -- jumping while spamming a sword throws out a surprising number of both animations and
    -- replicated actions. These are per SECOND, not per three.
    local ANIMATION_FLOOD, ANIMATION_WINDOW = 45, 1
    local REMOTE_FLOOD, REMOTE_WINDOW = 45, 1

    -- How many readings of one kind before a player is flagged. Set per check rather than shared:
    -- a Reach reading is one clean measurement, a Phase reading is a guess about geometry we only
    -- half see, and they cannot sensibly share a threshold.
    local REQUIRED = {
        Killaura = 3,
        SilentAim = 4,
        HitBoxes = 4,
        Reach = 3,
        PlayerAttach = 2,
        AntiDeath = 2,
        Phase = 6,
        Invisible = 4,
        HighJump = 4,
        Speed = 3,
        NoFallDamage = 3,
        VoidFlight = 2,
        ExtremeSpeed = 2,
        AutoKit = 4,
        Animation = 3,
        Remote = 3,
        Breaker = 4,
        ProjectileAim = 4
    }

    local strikes = {}
    -- When each player last took a hit. Knockback throws people faster than they can run, so a
    -- speed sample taken just after one measures the hit, not the player.
    local lastHurt = {}

    local function enabled(name)
        local toggle = Toggles[name]
        return toggle ~= nil and toggle.Enabled == true
    end

    -- A child check runs only while its heading is on as well, so switching a family off switches
    -- off everything under it without disturbing which children were picked.
    local function checkEnabled(group, name)
        if not enabled(group) then return false end
        return group == name or enabled(name)
    end

    -- The one place the self exemption is decided. Checks ask this instead of comparing against
    -- lplr themselves, so the toggle reaches all of them at once and nothing is left half exempt.
    local function selfExcluded(plr)
        return plr == lplr and not enabled(DETECT_SELF)
    end

    -- entitylib keeps our own entity apart from the rest - entitylib.List is everyone but us - so a
    -- check that walks the list can never see the local player no matter what the guards say. This
    -- hands back that same list with our entity on the end while the toggle is on, which is what
    -- lets the polling checks read us without each of them knowing where our entity is kept.
    local function entities()
        if not enabled(DETECT_SELF) or not entitylib.isAlive or not entitylib.character then
            return entitylib.List
        end
        local list = table.clone(entitylib.List)
        table.insert(list, entitylib.character)
        return list
    end

    local function strikeCount(plr, reason)
        local perPlayer = strikes[plr]
        if not perPlayer then return 0 end
        local list = perPlayer[reason]
        if not list then return 0 end
        local now, count = tick(), 0
        for i = #list, 1, -1 do
            if now - list[i] > STRIKE_MEMORY then
                table.remove(list, i)
            else
                count += 1
            end
        end
        return count
    end

    local function Added(player, reason, detail)
        if not CheatersFlagged[player] then
            CheatersFlagged[player] = true
            whitelist.customtags[player.Name] = {{text = 'CHEATER', color = Color3.new(1, 0, 0)}}
            -- Say what was actually measured, not just which check fired. A flag you cannot
            -- sanity-check yourself is a flag you have to take on trust.
            notif('CheatDetector', `{player.Name} flagged for {reason:lower()}{detail and ' ('..detail..')' or ''}`, 10, 'alert')
        end
    end

    -- One reading is an oddity, several is a pattern. Nothing reaches Added until the pattern is
    -- there, at whatever count this particular check needs to be worth trusting.
    local function strike(plr, reason, label, detail)
        if not plr or selfExcluded(plr) or CheatersFlagged[plr] then return end
        strikes[plr] = strikes[plr] or {}
        strikes[plr][reason] = strikes[plr][reason] or {}
        table.insert(strikes[plr][reason], tick())
        if strikeCount(plr, reason) >= (REQUIRED[reason] or 5) then
            Added(plr, label or reason, detail)
        end
    end

    local function ping()
        local value = 0
        pcall(function()
            value = lplr:GetNetworkPing()
        end)
        return value
    end

    -- Our own connection is the measuring instrument. When it is bad, every reading of somebody
    -- else is wrong in a direction that produces false positives, so we take none at all. Nothing
    -- sits between us and our own character, so measuring ourselves is always allowed.
    local function conditionsUsable(plr)
        if plr == lplr then return true end
        return ping() <= MAX_PING
    end

    local function recentlyTeleported(plr)
        return (workspace:GetServerTimeNow() - (plr:GetAttribute('LastTeleported') or 0)) <= 1
    end

    local function correctionContext(plr, char)
        if recentlyTeleported(plr) or not char then return true end
        for name, value in char:GetAttributes() do
            local lowered = tostring(name):lower()
            if value and (lowered:find('teleport') or lowered:find('servercorrect') or lowered:find('respawn') or lowered:find('launch')) then
                if type(value) ~= 'number' or math.abs(workspace:GetServerTimeNow() - value) < 2 then return true end
            end
        end
        local humanoid = char:FindFirstChildOfClass('Humanoid')
        return humanoid and table.find({Enum.HumanoidStateType.Ragdoll, Enum.HumanoidStateType.FallingDown, Enum.HumanoidStateType.GettingUp}, humanoid:GetState()) ~= nil
    end

    ------------------------------------------------------------------------
    -- Status effects.
    ------------------------------------------------------------------------
    -- Kits are the reason speed and jump checks need this. A kit that is MEANT to move you fast -
    -- a reaper's drift, a dash, a wind push - replicates a status attribute onto the character
    -- while it is doing it, so the sample is thrown away rather than counted. Matched on what the
    -- effect is called rather than on a list of kits, so a kit added next update is covered by
    -- the words it uses, and a kit renamed does not quietly become undetectable.
    local EFFECT_WORDS = {
        Movement = {'speed', 'dash', 'sprint', 'haste', 'boost', 'launch', 'grapple', 'balloon', 'wind', 'momentum', 'charge', 'rush', 'swift', 'leap', 'pounce', 'slide', 'drift', 'frenzy'},
        Vertical = {'jump', 'launch', 'bounce', 'pad', 'grapple', 'balloon', 'levitat', 'fly', 'wind', 'rocket', 'leap', 'pounce'},
        Invisible = {'invis', 'vanish', 'cloak', 'ghost'},
        Ability = {'ability', 'kit_', 'kitability', 'cooldown'}
    }

    -- One pass over a character's attributes per tick, producing every flag the checks want.
    -- Reading them separately meant walking the same attribute table three times a tick per
    -- player for answers that all come out of the same read.
    local function effectsOf(char)
        local flags = {}
        if not char then return flags end
        for name, value in char:GetAttributes() do
            if type(name) ~= 'string' or value == false or value == 0 then continue end
            local lowered = name:lower()
            for key, words in EFFECT_WORDS do
                if flags[key] then continue end
                for _, word in words do
                    if lowered:find(word, 1, true) then
                        flags[key] = true
                        break
                    end
                end
            end
        end
        return flags
    end

    local function weaponReach(plr)
        local inv = store.inventories[plr]
        local hand = inv and inv.hand
        -- The old check read hand.tool.Name, which is nil for anything the game hands over as a
        -- plain item rather than a Tool - so the reach fell back to the default for half the
        -- weapons in the game and flagged anyone holding a long one.
        local itemType = hand and (hand.itemType or (hand.tool and hand.tool.Name))
        local meta = itemType and bedwars.ItemMeta[itemType]
        local sword = meta and meta.sword
        return (sword and sword.attackRange or 14.4)
    end

    -- Lowest solid ground anywhere on the map, minus a margin. Below this is the void, and nothing
    -- alive belongs there. Recomputed on a timer rather than per sample: it walks every block on
    -- the map, and the floor of the world does not move between ticks.
    local voidCached, voidStamp = -300, 0
    local function voidLevel()
        local now = os.clock()
        if now - voidStamp < 5 then return voidCached end
        voidStamp = now
        local lowest = math.huge
        for _, v in store.blocks do
            local point = (v.Position.Y - (v.Size.Y / 2)) - 50
            if point < lowest then
                lowest = point
            end
        end
        voidCached = lowest < math.huge and lowest or -300
        return voidCached
    end

    -- What the game itself says a kit's movement is worth. Read out of the kit metadata rather
    -- than from a list of kit names: a kit added, renamed or rebalanced next update is covered by
    -- whatever its own meta says about itself, and there is nothing here to keep up to date. Any
    -- move-speed multiplier the meta declares raises that player's ceiling by the same
    -- proportion, so a kit whose whole point is moving fast is never flagged for moving fast.
    local kitCeilings = {}
    local function speedCeiling(plr)
        local kit = plr:GetAttribute('PlayingAsKits') or plr:GetAttribute('PlayingAsKit')
        if type(kit) ~= 'string' or kit == '' or kit == 'none' then return SPEED_LIMIT end
        local cached = kitCeilings[kit]
        if cached then return cached end

        local multiplier = 1
        pcall(function()
            local meta = bedwars.BedwarsKitMeta and bedwars.BedwarsKitMeta[kit]
            if type(meta) ~= 'table' then return end
            local function scan(tab, depth)
                for key, value in tab do
                    if type(value) == 'number' and type(key) == 'string' then
                        local lowered = key:lower()
                        -- Only a movement multiplier, never a raw number and never a speed that
                        -- belongs to something else the kit throws.
                        if lowered:find('speed') and (lowered:find('multiplier') or lowered:find('move')) then
                            multiplier = math.max(multiplier, value)
                        end
                    elseif type(value) == 'table' and depth < 3 then
                        scan(value, depth + 1)
                    end
                end
            end
            scan(meta, 1)
        end)

        local ceiling = SPEED_LIMIT * math.clamp(multiplier, 1, 2)
        kitCeilings[kit] = ceiling
        return ceiling
    end

    -- Rolling counter shared by every rate-based check: record an event, get back how many landed
    -- inside `window`.
    local function bumpRate(store_, key, window)
        local list = store_[key]
        if not list then
            list = {}
            store_[key] = list
        end
        local now = os.clock()
        table.insert(list, now)
        for i = #list, 1, -1 do
            if now - list[i] > window then
                table.remove(list, i)
            end
        end
        return #list
    end

    ------------------------------------------------------------------------
    -- Animation watch, shared.
    ------------------------------------------------------------------------
    -- Two checks want the same fact from different angles: the crasher check wants how OFTEN a
    -- player starts animations, and killaura's packet signal wants whether they started one at
    -- all. One hook per character answers both.
    local animationLast, animationRates, animationHooked = {}, {}, {}
    -- How many hits anywhere in the match arrived with a swing behind them. Until the game has
    -- proven to us that it replicates swings at all, "no swing behind that hit" means nothing,
    -- and the packet signal stays switched off rather than flagging the entire lobby.
    local animationBacked = 0

    local function watchAnimations(list)
        for _, rec in list do
            local plr = rec.Player
            if animationHooked[plr] == rec.Character then continue end
            local humanoid = rec.Character:FindFirstChildOfClass('Humanoid')
            local animator = humanoid and humanoid:FindFirstChildOfClass('Animator')
            if not animator then continue end
            animationHooked[plr] = rec.Character
            CheatDetector:Clean(animator.AnimationPlayed:Connect(function()
                animationLast[plr] = os.clock()
                if not checkEnabled('Crashers', 'Animation') then return end
                if CheatersFlagged[plr] then return end
                -- Landing/fall-state animations are restarted by the stock controller and by
                -- NoFallDamage's landed-state path. They are movement state, not an animation
                -- flood, and counting them made the Animation toggle accuse ordinary falls.
                local state = humanoid:GetState()
                if state == Enum.HumanoidStateType.Freefall or state == Enum.HumanoidStateType.Landed
                    or math.abs((rec.RootPart and rec.RootPart.AssemblyLinearVelocity.Y) or 0) > 8 then return end
                if bumpRate(animationRates, plr, ANIMATION_WINDOW) >= ANIMATION_FLOOD then
                    animationRates[plr] = nil
                    strike(plr, 'Animation', 'animation spam', `{ANIMATION_FLOOD} animation starts inside {ANIMATION_WINDOW}s`)
                end
            end))
        end
    end

    -- Which heading each check belongs to, so a family can be switched off in one place.
    local CHECK_GROUP = {
        Killaura = 'Impossible hits',
        SilentAim = 'Impossible hits',
        HitBoxes = 'Impossible hits',
        Reach = 'Impossible hits',
        PlayerAttach = 'Blatant modules',
        AntiDeath = 'Blatant modules',
        Phase = 'Blatant modules',
        Invisible = 'Blatant modules',
        HighJump = 'Blatant modules',
        Speed = 'Blatant modules',
        NoFallDamage = 'Bypasses',
        VoidFlight = 'Bypasses',
        ExtremeSpeed = 'Bypasses',
        AutoKit = 'AutoKit',
        Animation = 'Crashers',
        Remote = 'Crashers',
        Breaker = 'Breaker',
        ProjectileAim = 'ProjectileAimbot and Aura'
    }
    -- The checks whose toggle name is the heading itself.
    local CHECK_TOGGLE = {
        AutoKit = 'AutoKit',
        Breaker = 'Breaker',
        ProjectileAim = 'ProjectileAimbot and Aura'
    }

    local function wanted(name)
        local group = CHECK_GROUP[name]
        return group ~= nil and checkEnabled(group, CHECK_TOGGLE[name] or name)
    end

    ------------------------------------------------------------------------
    -- Polling checks.
    ------------------------------------------------------------------------
    -- Each entry is a factory: it is called once when the module starts and hands back the
    -- function that runs against every snapshot, so all of a check's state is private to one
    -- run of the module and starts empty on the next.
    local Pollers = {}

    ------------------------------------------------------------------------
    -- Speed.
    ------------------------------------------------------------------------
    -- Not "how fast was that one step" - a knockback, a dash and a bad interpolation all answer
    -- that loudly. This measures a continuous run: distance actually covered over the time it
    -- took, with the run reset the moment anything makes a sample untrustworthy (a buff, a
    -- teleport, a hit taken, leaving the ground, or simply slowing down). What is left is speed
    -- that was HELD, which is the difference between a kit ability and a speed hack.
    Pollers.Speed = function()
        local tracks = {}
        return function(now, list)
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                local track = tracks[plr]
                -- A respawn is a new character in the same player's name, and the position it
                -- starts at has nothing to do with the one the last one died at.
                if not track or track.Character ~= rec.Character then
                    tracks[plr] = {Character = rec.Character, Ceiling = speedCeiling(plr), Position = rec.Flat, Time = now, Distance = 0, Start = now, Samples = 0, Above = 0}
                    continue
                end
                local ceiling = track.Ceiling or SPEED_LIMIT

                local delta = now - track.Time
                local step = (rec.Flat - track.Position).Magnitude
                track.Position, track.Time = rec.Flat, now

                local usable = delta >= 0.05 and delta <= 0.5
                    and step <= TELEPORT_STEP
                    and (step / delta) <= SPEED_SANE
                    and not rec.Teleported
                    and not rec.Effects.Movement
                    and not rec.Hurt
                    and math.abs(rec.Velocity.Y) < 14
                    -- Sprint pace keeps a run alive, anything below it ends the run. That is
                    -- deliberately generous: a kit dash decays into a sprint rather than a stop,
                    -- so the sprinting that follows stays in the window and drags the average
                    -- back under the limit, while a hack that simply holds one speed does not.
                    and (step / delta) > (ceiling * 0.85)
                if not usable then
                    track.Distance, track.Start, track.Samples, track.Above = 0, now, 0, 0
                    continue
                end

                track.Distance += step
                track.Samples += 1
                if (step / delta) > ceiling then
                    track.Above += 1
                end

                local span = now - track.Start
                if span >= SPEED_WINDOW and track.Samples >= 8 then
                    local average = track.Distance / span
                    local share = track.Above / track.Samples
                    track.Distance, track.Start, track.Samples, track.Above = 0, now, 0, 0
                    -- Both, and the second one is what keeps kits out of this. A dash, a pounce or
                    -- a wind push is a spike that decays: most of the window sits at running pace
                    -- even when the average of it is dragged over the limit. A hack holds one
                    -- speed, so nearly every sample in its window is over on its own.
                    if average > ceiling and share >= 0.7 then
                        strike(plr, 'Speed', 'speeding', `{math.floor(average)} studs/s held for {math.floor(span * 10) / 10}s, ceiling {math.floor(ceiling)}`)
                    end
                end
            end
            for plr in tracks do
                if not seen[plr] then tracks[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Bypass behaviour.
    ------------------------------------------------------------------------
    -- These checks intentionally measure outcomes rather than known module signatures. A bypass
    -- can rename itself, but it still has to keep a player above the void, move them at an
    -- impossible pace, or suppress the health loss from a long unassisted fall.
    Pollers.ExtremeSpeed = function()
        local held = {}
        return function(now, list, delta)
            for _, rec in list do
                local plr = rec.Player
                if rec.Teleported or rec.Effects.Movement or rec.Hurt or not rec.Grounded then
                    held[plr] = nil
                    continue
                end
                local speed = (rec.Velocity * Vector3.new(1, 0, 1)).Magnitude
                if speed > 40 then
                    local entry = held[plr] or {Since = now, Peak = speed}
                    entry.Peak = math.max(entry.Peak, speed)
                    held[plr] = entry
                    if now - entry.Since >= 0.6 then
                        held[plr] = nil
                        strike(plr, 'ExtremeSpeed', 'anticheat bypass', `{math.floor(entry.Peak)} studs/s without a movement effect`)
                    end
                else
                    held[plr] = nil
                end
            end
        end
    end

    Pollers.VoidFlight = function()
        local since = {}
        return function(now, list)
            local floor = voidLevel()
            for _, rec in list do
                local plr = rec.Player
                -- A genuine void fall keeps descending. Only a body held/flying for three seconds
                -- below all playable ground is suspicious; this also fixes AntiDeath flagging the
                -- first samples of somebody simply falling out of the map.
                if rec.Position.Y < floor and rec.Velocity.Y > -35 and not rec.Teleported and not rec.Effects.Vertical then
                    since[plr] = since[plr] or now
                    if now - since[plr] >= 3 then
                        since[plr] = now
                        strike(plr, 'VoidFlight', 'anticheat bypass', 'remained mobile over the void for more than 3s')
                    end
                else
                    since[plr] = nil
                end
            end
        end
    end

    Pollers.NoFallDamage = function()
        local falls = {}
        return function(now, list)
            for _, rec in list do
                local plr = rec.Player
                local fall = falls[plr]
                if rec.Teleported or rec.Effects.Vertical or rec.Effects.Ability then
                    falls[plr] = nil
                    continue
                end
                if not rec.Grounded then
                    fall = fall or {Peak = rec.Position.Y, Lowest = rec.Position.Y, Health = rec.Health}
                    fall.Peak = math.max(fall.Peak, rec.Position.Y)
                    fall.Lowest = math.min(fall.Lowest, rec.Position.Y)
                    fall.Health = math.max(fall.Health, rec.Health)
                    falls[plr] = fall
                elseif fall then
                    local distance = fall.Peak - rec.Position.Y
                    -- BedWars starts meaningful fall damage well below this. The generous height
                    -- keeps slopes, replicated ground jitter and ordinary jumps out. Wait through
                    -- the server's damage-settle window before deciding health never changed.
                    if distance >= 32 then
                        fall.Landed = fall.Landed or now
                        if now - fall.Landed >= 0.8 then
                            if rec.Health >= fall.Health - 1 and not rec.Hurt then
                                strike(plr, 'NoFallDamage', 'no fall damage', `fell {math.floor(distance)} studs without losing health`)
                            end
                            falls[plr] = nil
                        end
                    else
                        falls[plr] = nil
                    end
                end
            end
        end
    end

    ------------------------------------------------------------------------
    -- PlayerAttach.
    ------------------------------------------------------------------------
    -- Two halves of the same behaviour, either of which is enough on its own. Getting there: a
    -- position step no run can make, landing on top of somebody. Staying there: held inside arm's
    -- length of one player while the pair actually travel, with the separation barely changing -
    -- two players who merely happen to be close bob around each other by whole studs.
    Pollers.PlayerAttach = function()
        local held, previous = {}, {}
        return function(now, list, delta)
            local seen = {}
            for _, rec in list do
                local plr, position = rec.Player, rec.Position
                seen[plr] = true
                local last = previous[plr]
                -- Same player, different body: the step from where they died to where they
                -- respawned is not a step they took.
                local before = last and last.Character == rec.Character and last.Position or nil
                previous[plr] = {Character = rec.Character, Position = position}

                local nearest, nearestPlr = math.huge, nil
                for _, other in list do
                    if other.Player == plr then continue end
                    local separation = (position - other.Position).Magnitude
                    if separation < nearest then
                        nearest, nearestPlr = separation, other.Player
                    end
                end
                if not nearestPlr then
                    held[plr] = nil
                    continue
                end

                local step = before and (position - before).Magnitude or 0
                -- Rate, not raw distance: a poll stretched by a lag spike covers plenty of ground
                -- at a run, and calling that a teleport would flag whoever was standing nearby.
                local rate = delta > 0 and (step / delta) or 0
                if before and step > ATTACH_JUMP and rate > ATTACH_RATE and step <= TELEPORT_STEP and nearest <= ATTACH_RANGE * 2 and not rec.Teleported then
                    strike(plr, 'PlayerAttach', 'player attach', `{math.floor(step)} studs onto {nearestPlr.Name} in one step`)
                end

                if nearest > ATTACH_RANGE then
                    held[plr] = nil
                    continue
                end

                local entry = held[plr]
                if not entry or entry.Target ~= nearestPlr then
                    entry = {Target = nearestPlr, Count = 0, Travel = 0, Min = nearest, Max = nearest}
                    held[plr] = entry
                end
                entry.Count += 1
                entry.Travel += step
                entry.Min = math.min(entry.Min, nearest)
                entry.Max = math.max(entry.Max, nearest)
                if entry.Count >= ATTACH_SAMPLES and entry.Travel > ATTACH_TRAVEL and (entry.Max - entry.Min) < ATTACH_JITTER then
                    held[plr] = nil
                    strike(plr, 'PlayerAttach', 'player attach', `rode {nearestPlr.Name} at {math.floor(nearest * 10) / 10} studs`)
                end
            end
            for plr in held do
                if not seen[plr] then held[plr] = nil end
            end
            for plr in previous do
                if not seen[plr] then previous[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- AntiDeath.
    ------------------------------------------------------------------------
    -- The hitbox taken somewhere nothing can reach it and brought straight back. This does not
    -- flag somebody merely for spending time below the map: it records impossible boundary
    -- crossings and requires repeated teleports to and from the void, which is what parking a
    -- hitbox out of a fight and restoring it looks like from outside.
    Pollers.AntiDeath = function()
        local tracks = {}
        return function(now, list, delta)
            local floor = voidLevel()
            local seen = {}
            for _, rec in list do
                local plr, position = rec.Player, rec.Position
                seen[plr] = true
                local track = tracks[plr]
                if not track or track.Character ~= rec.Character then
                    tracks[plr] = {Character = rec.Character, Y = position.Y, Flat = rec.Flat, Below = position.Y < floor, Crossings = {}, Direction = 0, Reversals = {}}
                    continue
                end

                local rise = position.Y - track.Y
                local flatStep = (rec.Flat - track.Flat).Magnitude
                track.Y, track.Flat = position.Y, rec.Flat

                local below = position.Y < floor
                if rec.Teleported or delta <= 0 then
                    track.Below = below
                    continue
                end
                -- Straight up or straight down, faster than free fall, with the body barely
                -- moving sideways. Nothing physical does this. A normal void fall can cross the
                -- boundary once; AntiDeath has to cross it in both directions repeatedly.
                if math.abs(rise) < VERTICAL_TELEPORT or (math.abs(rise) / delta) < VERTICAL_RATE or flatStep > 15 then
                    track.Below = below
                    continue
                end

                if below ~= track.Below then
                    table.insert(track.Crossings, {Time = now, Below = below})
                    for i = #track.Crossings, 1, -1 do
                        if now - track.Crossings[i].Time > VERTICAL_MEMORY then
                            table.remove(track.Crossings, i)
                        end
                    end
                    local alternating = 0
                    for i = 2, #track.Crossings do
                        if track.Crossings[i].Below ~= track.Crossings[i - 1].Below then
                            alternating += 1
                        end
                    end
                    if alternating >= 3 then
                        table.clear(track.Crossings)
                        strike(plr, 'AntiDeath', 'anti death', 'repeatedly teleported to and from below the map')
                    end
                end
                track.Below = below

                local direction = rise > 0 and 1 or -1
                if track.Direction ~= 0 and direction ~= track.Direction then
                    table.insert(track.Reversals, now)
                end
                track.Direction = direction
                for i = #track.Reversals, 1, -1 do
                    if now - track.Reversals[i] > VERTICAL_MEMORY then
                        table.remove(track.Reversals, i)
                    end
                end
                if #track.Reversals >= VERTICAL_REVERSALS then
                    table.clear(track.Reversals)
                    track.Direction = 0
                    strike(plr, 'AntiDeath', 'anti death', `hitbox thrown {math.floor(math.abs(rise))} studs up and down`)
                end
            end
            for plr in tracks do
                if not seen[plr] then tracks[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Phase.
    ------------------------------------------------------------------------
    -- Standing inside solid geometry. Every part of this is arguable on its own - a body clips a
    -- block on a slope, streaming puts a block in late - so the reading needs the root buried in
    -- something solid across consecutive samples while the player is not being carried by
    -- anything, and it needs the most readings of any check before it flags. Sampled every third
    -- tick because it is the only check here that costs a spatial query.
    Pollers.Phase = function()
        local buried = {}
        local overlap = OverlapParams.new()
        overlap.FilterType = Enum.RaycastFilterType.Exclude
        local skip = 0
        return function(now, list)
            skip += 1
            if skip % 3 ~= 0 then return end
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                if rec.Teleported or rec.Effects.Movement then
                    buried[plr] = nil
                    continue
                end

                overlap.FilterDescendantsInstances = {rec.Character, lplr.Character, gameCamera}
                -- A box well inside the torso, so brushing a wall is not enough - the body has
                -- to be in the block.
                local parts = workspace:GetPartBoundsInBox(CFrame.new(rec.Position), Vector3.new(1, 1, 1), overlap)
                local solid = false
                for _, part in parts do
                    if part.CanCollide and part.Anchored then
                        solid = true
                        break
                    end
                end

                if solid then
                    buried[plr] = (buried[plr] or 0) + 1
                    if buried[plr] >= 4 then
                        buried[plr] = 0
                        strike(plr, 'Phase', 'phasing', 'stood inside a solid block')
                    end
                else
                    buried[plr] = nil
                end
            end
            for plr in buried do
                if not seen[plr] then buried[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Invisible.
    ------------------------------------------------------------------------
    -- Every limb fully transparent while the player is alive, moving and carrying no invisibility
    -- effect of their own. Movement is what separates this from a ragdoll or a death animation,
    -- and the status-effect check is what keeps the game's own invisibility potion out of it.
    Pollers.Invisible = function()
        local hidden = {}
        local skip = 0
        return function(now, list)
            -- Every fifth tick. Walking a character's whole descendant tree is the most expensive
            -- read in the module, and nobody turns invisible for a tenth of a second.
            skip += 1
            if skip % 5 ~= 0 then return end
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                if rec.Effects.Invisible or rec.Velocity.Magnitude < 4 then
                    hidden[plr] = nil
                    continue
                end

                local visible, counted = false, 0
                for _, part in rec.Character:GetDescendants() do
                    if part:IsA('BasePart') and part.Name ~= 'HumanoidRootPart' then
                        counted += 1
                        if part.Transparency < 0.95 then
                            visible = true
                            break
                        end
                    end
                end

                -- No limbs found at all means the character has not streamed in, which is not
                -- the same thing as being invisible.
                if counted >= 4 and not visible then
                    hidden[plr] = (hidden[plr] or 0) + 1
                    if hidden[plr] >= 3 then
                        hidden[plr] = 0
                        strike(plr, 'Invisible', 'invisibility', 'moving with every limb hidden')
                    end
                else
                    hidden[plr] = nil
                end
            end
            for plr in hidden do
                if not seen[plr] then hidden[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- HighJump.
    ------------------------------------------------------------------------
    -- Rising further off one jump than the game's own jump power allows. Measured as a climb from
    -- a standing start rather than as an instantaneous velocity, because a launch pad or a
    -- knockback shows up in velocity and both of those are legitimate.
    Pollers.HighJump = function()
        local tracked = {}
        return function(now, list)
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                if rec.Teleported or rec.Effects.Vertical or rec.Hurt then
                    tracked[plr] = nil
                    continue
                end

                local y = rec.Position.Y
                local entry = tracked[plr]
                if rec.Grounded then
                    tracked[plr] = {Base = y, Peak = y}
                elseif entry then
                    entry.Peak = math.max(entry.Peak, y)
                    -- Roblox's own jump tops out near 7 studs, and BedWars kits that go higher
                    -- all announce themselves through a status effect, which is excluded above.
                    -- 18 is far past anything left.
                    if (entry.Peak - entry.Base) > 18 then
                        tracked[plr] = nil
                        strike(plr, 'HighJump', 'high jump', `rose {math.floor(entry.Peak - entry.Base)} studs off one jump`)
                    end
                end
            end
            for plr in tracked do
                if not seen[plr] then tracked[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- AutoKit.
    ------------------------------------------------------------------------
    -- A kit ability is a cooldown, and a script fires it the instant it is up - every time. What
    -- gives it away is not the speed but the regularity: the gaps between activations stop
    -- varying. A hand cannot hold an interval to within a tenth of a second five times running.
    Pollers.AutoKit = function()
        local activations, previous = {}, {}
        return function(now, list)
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                local active = rec.Effects.Ability
                local was = previous[plr]
                previous[plr] = active
                if not active or was then continue end

                -- Rising edge: the ability just went off.
                local times = activations[plr]
                if not times then
                    times = {}
                    activations[plr] = times
                end
                table.insert(times, now)
                if #times > 6 then
                    table.remove(times, 1)
                end
                if #times < 6 then continue end

                local shortest, longest = math.huge, 0
                for i = 2, #times do
                    local gap = times[i] - times[i - 1]
                    shortest = math.min(shortest, gap)
                    longest = math.max(longest, gap)
                end
                -- Five gaps that agree to within a tenth of a second, and none of them long
                -- enough to be somebody simply playing at a steady pace.
                if (longest - shortest) < 0.1 and longest < 30 then
                    table.clear(times)
                    strike(plr, 'AutoKit', 'automated kit use', `5 activations {math.floor(longest * 100) / 100}s apart`)
                end
            end
            for plr in activations do
                if not seen[plr] then
                    activations[plr] = nil
                    previous[plr] = nil
                end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Event-driven checks.
    ------------------------------------------------------------------------
    -- Same idea as the pollers: a factory called once at startup which puts its connections in
    -- place. Everything they need about a player is read at the moment of the event.
    local Events = {}

    ------------------------------------------------------------------------
    -- Killaura.
    ------------------------------------------------------------------------
    -- Four things an aura does that a hand does not, any one of which is a reading:
    --
    --   * hits closer together than anybody can click at all;
    --   * a cadence that does not vary, because the aura fires the moment the cooldown is up
    --     rather than whenever a finger happened to come down;
    --   * a run of hits held at a rate no hand sustains;
    --   * damage on several different people in the time it takes to turn to face one of them.
    --
    -- Plus the packet case: an aura that talks straight to the server does not swing anything,
    -- so the damage lands with no animation behind it. That one is only trusted once other
    -- players in the same match have proven that swings do reach us, so a game that simply does
    -- not replicate them cannot make the check flag everybody.
    Events.Killaura = function()
        local last, intervals, victims, hits, quiet = {}, {}, {}, {}, {}

        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('Killaura') then return end
            if damageTable.damageType ~= 0 or not damageTable.fromEntity then return end

            local from = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not from or selfExcluded(from) or CheatersFlagged[from] then return end
            if not conditionsUsable(from) then return end

            local victim = damageTable.entityInstance and playersService:GetPlayerFromCharacter(damageTable.entityInstance)
            local now = os.clock()

            -- Was there a swing behind this hit?
            if (now - (animationLast[from] or 0)) <= 0.4 then
                animationBacked += 1
                quiet[from] = 0
            elseif animationBacked >= 5 then
                quiet[from] = (quiet[from] or 0) + 1
                if quiet[from] >= 6 then
                    quiet[from] = 0
                    strike(from, 'Killaura', 'using killaura', '6 hits with no swing behind them')
                end
            end

            -- Several different people inside the time it takes to turn around.
            if victim then
                local seen = victims[from]
                if not seen then
                    seen = {}
                    victims[from] = seen
                end
                seen[victim] = now
                local distinct = 0
                for plr, stamp in seen do
                    if now - stamp > SWITCH_WINDOW then
                        seen[plr] = nil
                    else
                        distinct += 1
                    end
                end
                if distinct >= SWITCH_VICTIMS then
                    table.clear(seen)
                    strike(from, 'Killaura', 'using killaura', `{distinct} different targets inside {SWITCH_WINDOW}s`)
                end
            end

            local previous = last[from]
            last[from] = now
            if not previous then return end

            local interval = now - previous
            -- Two events delivered in the same frame were batched by the network, not thrown that
            -- fast. Reading a batch as a zero interval is how a check like this flags people who
            -- are simply being replicated to us in bursts.
            if interval <= 0.008 then return end

            if interval < MIN_HUMAN_INTERVAL then
                strike(from, 'Killaura', 'using killaura', `hits {math.floor(interval * 1000)}ms apart`)
                return
            end

            -- Held rate. Not one fast hit - a run of them.
            if bumpRate(hits, from, BURST_WINDOW) >= BURST_HITS then
                hits[from] = nil
                strike(from, 'Killaura', 'using killaura', `{BURST_HITS} hits inside {BURST_WINDOW}s`)
            end

            -- Cadence. Only gaps short enough to be a weapon on cooldown are considered: a run of
            -- evenly spaced hits seconds apart is somebody trading, not a machine.
            local run = intervals[from]
            if not run then
                run = {}
                intervals[from] = run
            end
            if interval > 0.6 then
                table.clear(run)
                return
            end
            table.insert(run, interval)
            if #run > CADENCE_SAMPLES then
                table.remove(run, 1)
            end
            if #run < CADENCE_SAMPLES then return end

            local shortest, longest = math.huge, 0
            for _, value in run do
                shortest = math.min(shortest, value)
                longest = math.max(longest, value)
            end
            if (longest - shortest) <= CADENCE_SPREAD then
                table.clear(run)
                strike(from, 'Killaura', 'using killaura', `{CADENCE_SAMPLES} hits {math.floor(shortest * 1000)}ms apart to the millisecond`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- Reach.
    ------------------------------------------------------------------------
    -- The measurement an aura cannot fake. It can put whatever position it likes in the packet it
    -- sends the server, but the body the rest of us see stays where the player really is, so the
    -- distance between the two characters at the moment damage lands is the honest one. Every
    -- sword in the game swings 14.4 studs or less; past 15.5 the hit came from somewhere the
    -- weapon does not reach.
    Events.Reach = function()
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('Reach') then return end
            if damageTable.damageType ~= 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not attacker or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) or recentlyTeleported(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end

            local distance = (fromRoot.Position - toRoot.Position).Magnitude
            -- Ping converted into studs rather than added as seconds, and kept small: this is an
            -- allowance for our own view of two moving bodies, not for the weapon.
            local allowance = math.clamp(ping() * 20, 0, 3)
            local limit = math.max(weaponReach(attacker) + 1.1, REACH_LIMIT) + allowance

            if distance > limit then
                strike(attacker, 'Reach', 'using reach', `{math.floor(distance * 10) / 10} studs, limit {math.floor(limit * 10) / 10}`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- HitBoxes.
    ------------------------------------------------------------------------
    -- An expanded hitbox lives on the attacker's own client, so it is never visible from here
    -- directly. What it produces that a normal swing cannot is a hit landing while the attacker is
    -- facing well off the target: the swing resolved against a box far wider than the body. The
    -- distance has to be inside legitimate reach too, otherwise this is just Reach again and one
    -- swing would be counted twice.
    Events.HitBoxes = function()
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('HitBoxes') then return end
            if damageTable.damageType ~= 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not attacker or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) or recentlyTeleported(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end

            local delta = (toRoot.Position - fromRoot.Position)
            local distance = delta.Magnitude
            -- Point blank the angle means nothing - the bodies overlap and any heading hits - and
            -- past the weapon's own reach this is Reach's reading, not this one.
            if distance < 6 or distance > REACH_LIMIT then return end

            local facing = fromRoot.CFrame.LookVector * Vector3.new(1, 0, 1)
            local toward = delta * Vector3.new(1, 0, 1)
            if facing.Magnitude < 0.01 or toward.Magnitude < 0.01 then return end

            local angle = math.deg(math.acos(math.clamp(facing.Unit:Dot(toward.Unit), -1, 1)))
            -- 70 degrees off and still landing means the swing did not resolve against the body
            -- that is being drawn. Wide enough that our own interpolation of a strafing player
            -- cannot get there on its own.
            if angle > 70 then
                strike(attacker, 'HitBoxes', 'expanded hitboxes', `hit {math.floor(angle)} degrees off target`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- SilentAim.
    ------------------------------------------------------------------------
    -- The projectile equivalent: a shot that lands on someone the shooter was never pointing at.
    -- Only long shots are considered, because at close range the angle to a target is wide even
    -- when aimed honestly, and only non-melee damage, so a sword swing is never counted here.
    Events.SilentAim = function()
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('SilentAim') then return end
            if damageTable.damageType == 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not attacker or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) or recentlyTeleported(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end

            local delta = (toRoot.Position - fromRoot.Position) * Vector3.new(1, 0, 1)
            -- A thrown projectile arcs, and a short lob can leave at a heading well off the
            -- target quite legitimately. Distance is what makes the heading meaningful.
            if delta.Magnitude < 25 then return end

            local facing = fromRoot.CFrame.LookVector * Vector3.new(1, 0, 1)
            if facing.Magnitude < 0.01 then return end

            local angle = math.deg(math.acos(math.clamp(facing.Unit:Dot(delta.Unit), -1, 1)))
            if angle > 50 then
                strike(attacker, 'SilentAim', 'silent aim', `landed a shot {math.floor(angle)} degrees off their heading`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- ProjectileAimbot and Aura.
    ------------------------------------------------------------------------
    -- Aimbot is not one impossible shot, it is never missing. Landing projectile after projectile
    -- on live players at long range, faster than they can be aimed, is the thing no hand does.
    Events.ProjectileAim = function()
        local hits = {}
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('ProjectileAim') then return end
            if damageTable.damageType == 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            local victim = playersService:GetPlayerFromCharacter(damageTable.entityInstance)
            -- Players only. A projectile stream into a mob or a bed is a different thing entirely.
            if not attacker or not victim or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end
            if (toRoot.Position - fromRoot.Position).Magnitude < 30 then return end

            -- Four long-range projectile hits on players inside six seconds. Bows are slow to
            -- draw, so this is well past what the weapon itself allows aimed by hand.
            if bumpRate(hits, attacker, 6) >= 4 then
                hits[attacker] = nil
                strike(attacker, 'ProjectileAim', 'projectile aimbot', '4 long-range projectile hits inside 6s')
            end
        end))
    end

    ------------------------------------------------------------------------
    -- Breaker.
    ------------------------------------------------------------------------
    -- Blocks coming apart faster than a tool can swing, or coming apart from across the map. Both
    -- are read off the break event itself, which carries who did it and where.
    Events.Breaker = function()
        local rates = {}
        CheatDetector:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(data)
            if not wanted('Breaker') then return end
            local plr = data.player
            if not plr or selfExcluded(plr) or CheatersFlagged[plr] then return end
            if not conditionsUsable(plr) then return end

            local blockPosition = data.blockRef and data.blockRef.blockPosition
            if typeof(blockPosition) == 'Vector3' then
                local root
                for _, ent in entities() do
                    if ent.Player == plr then
                        root = ent.RootPart
                        break
                    end
                end
                if root and root.Parent then
                    local distance = (root.Position - (blockPosition * 3)).Magnitude
                    -- Block reach in this game is well under 30 studs even with every modifier.
                    if distance > 45 and not recentlyTeleported(plr) then
                        strike(plr, 'Breaker', 'block breaker', `broke a block {math.floor(distance)} studs away`)
                        return
                    end
                end
            end

            -- Twelve blocks inside two seconds. Flat out with the fastest tool in the game on the
            -- softest block is not close to this, and a burst that size cannot be a batch of
            -- replicated events either.
            if bumpRate(rates, plr, 2) >= 12 then
                rates[plr] = nil
                strike(plr, 'Breaker', 'block breaker', '12 blocks broken inside 2s')
            end
        end))
    end

    ------------------------------------------------------------------------
    -- Crashers: Remote.
    ------------------------------------------------------------------------
    -- Another player's remote traffic is not visible from here, but its effect is: a crasher
    -- pushes replicated actions out at a rate the game itself never produces. Block places and
    -- breaks and damage events are all counted together, because a crasher does not care which
    -- remote it is hammering. The bar is per second and set well past a busy one: jumping around
    -- spamming a sword while building throws out a lot of events, and none of that is a crash.
    Events.Remote = function()
        local rates = {}

        local function count(plr)
            if not wanted('Remote') then return end
            if not plr or selfExcluded(plr) or CheatersFlagged[plr] then return end
            if bumpRate(rates, plr, REMOTE_WINDOW) >= REMOTE_FLOOD then
                rates[plr] = nil
                strike(plr, 'Remote', 'remote spam', `{REMOTE_FLOOD} replicated actions inside {REMOTE_WINDOW}s`)
            end
        end

        CheatDetector:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(data)
            count(data.player)
        end))
        CheatDetector:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(function(data)
            count(data and data.player)
        end))
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not damageTable.fromEntity then return end
            count(playersService:GetPlayerFromCharacter(damageTable.fromEntity))
        end))
    end

    -- One snapshot of everybody worth measuring, taken once per tick and handed to every polling
    -- check. Attributes, ground state and velocity are read here rather than inside each check,
    -- so a player is walked over once however many checks are on.
    local function snapshot(now)
        local list = {}
        for _, ent in entities() do
            local plr, root, char = ent.Player, ent.RootPart, ent.Character
            if not plr or selfExcluded(plr) or CheatersFlagged[plr] then continue end
            if not root or not root.Parent or not char then continue end
            if (ent.Health or 0) <= 0 then continue end

            local position = root.Position
            local effects = effectsOf(char)
            if tostring(store.queueType):lower():find('custom') then effects.Ability = true end
            table.insert(list, {
                Player = plr,
                Character = char,
                Root = root,
                Position = position,
                Flat = position * Vector3.new(1, 0, 1),
                Velocity = root.AssemblyLinearVelocity,
                Grounded = (ent.Humanoid and ent.Humanoid.FloorMaterial ~= Enum.Material.Air) or false,
                Effects = effects,
                Teleported = correctionContext(plr, char),
                Hurt = (now - (lastHurt[plr] or 0)) < 1.5,
                Health = ent.Health or (ent.Humanoid and ent.Humanoid.Health) or 0
            })
        end
        return list
    end

    CheatDetector = vape.Categories.Utility:CreateModule({
        Name = 'CheatDetector',
        Function = function(callback)
            if callback then
                table.clear(strikes)
                table.clear(lastHurt)
                table.clear(animationLast)
                table.clear(animationRates)
                table.clear(animationHooked)
                animationBacked = 0
                voidStamp = 0

                -- Feeds the knockback suppression the speed and jump checks rely on.
                CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
                    local victim = damageTable.entityInstance and playersService:GetPlayerFromCharacter(damageTable.entityInstance)
                    if victim then
                        lastHurt[victim] = tick()
                    end
                end))

                -- Every check is put in place, whichever toggles happen to be ticked right now,
                -- and each one asks whether it is wanted as it runs. Building only the ticked
                -- ones meant a detection switched on mid-match did nothing at all until the
                -- module was cycled by hand, which is most of what "half of these do not work"
                -- was. An unwanted check costs one table lookup a tick.
                for name, event in Events do
                    local ok, err = pcall(event)
                    if not ok then
                        warn('[AetherV2] CheatDetector '..name..': '..tostring(err))
                    end
                end

                local running = {}
                for name, poller in Pollers do
                    local ok, fn = pcall(poller)
                    if ok and type(fn) == 'function' then
                        running[name] = fn
                    else
                        warn('[AetherV2] CheatDetector '..name..': '..tostring(fn))
                    end
                end

                local last = tick()
                repeat
                    local now = tick()
                    local delta = now - last
                    last = now

                    -- The animation watch is what the crasher check counts and what killaura
                    -- asks whether a swing happened at all, so it runs for either of them.
                    local watching = wanted('Animation') or wanted('Killaura')
                    local polling = false
                    for name in running do
                        if wanted(name) then
                            polling = true
                            break
                        end
                    end

                    if watching or polling then
                        -- A character coming apart mid-read throws, and an unguarded throw here
                        -- ends the loop and the whole module with it.
                        local taken, list = pcall(snapshot, now)
                        if taken and #list > 0 then
                            if watching then
                                pcall(watchAnimations, list)
                            end
                            for name, fn in running do
                                if not wanted(name) then continue end
                                local ok, err = pcall(fn, now, list, delta)
                                if not ok then
                                    warn('[AetherV2] CheatDetector '..name..': '..tostring(err))
                                end
                            end
                        end
                    end

                    task.wait(POLL_INTERVAL)
                until not CheatDetector.Enabled
            else
                table.clear(strikes)
                table.clear(lastHurt)
                table.clear(animationLast)
                table.clear(animationRates)
                table.clear(animationHooked)
                animationBacked = 0
            end
        end,
        Tooltip = 'Alerts for likely cheaters. Every detection needs several impossible readings, and ignores ones taken on a poor connection'
    })

    local GROUP_TOOLTIPS = {
        ['Impossible hits'] = 'Hits that cannot have been aimed or thrown by hand: killaura, silent aim, expanded hitboxes, reach past any weapon',
        ['Blatant modules'] = 'Movement and state nobody can produce by playing: attach, anti death, phase, invisibility, high jump, speed',
        ['Bypasses'] = 'Outcome-based checks for impossible movement, sustained void flight, and suppressed fall damage',
        ['AutoKit'] = 'Kit abilities fired on a fixed interval, the regularity no hand holds',
        ['Crashers'] = 'Floods meant to bury other clients - animations or replicated actions many times a second',
        ['Breaker'] = 'Blocks broken faster than a tool swings, or from across the map',
        ['ProjectileAimbot and Aura'] = 'Long-range projectiles landing on players faster than a bow can be drawn and aimed'
    }
    local CHILD_TOOLTIPS = {
        Killaura = 'Hit rate, an unvarying cadence, several targets at once, or damage with no swing behind it',
        SilentAim = 'Shots landing on someone the shooter was not pointing at',
        HitBoxes = 'Melee landing while facing well off the body being drawn',
        Reach = 'Hits landing past 15.5 studs, further than any sword in the game swings',
        PlayerAttach = 'Teleporting onto a player, or riding them with the gap between you barely moving',
        AntiDeath = 'Repeated impossible teleports to and from below the map, or rapid vertical reversals faster than gravity',
        Phase = 'The body stood inside solid geometry across consecutive samples',
        Invisible = 'Moving with every limb hidden and no invisibility effect of their own',
        HighJump = 'Rising far past jump power off one jump, with no launch or ability effect',
        Speed = 'Ground speed held past 22 studs/s - or past whatever the kit\'s own metadata says it is worth - with potions, dashes and knockback excluded',
        NoFallDamage = 'Falls over 32 studs that settle without health loss; teleports, kit abilities, launches and vertical effects are excluded',
        VoidFlight = 'A player held or moving below all playable ground for more than three seconds instead of naturally falling',
        ExtremeSpeed = 'Sustained movement over 40 studs/s without a kit movement effect, knockback, teleport, or launch',
        Animation = 'Animation starts many times a second, far past anything play produces',
        Remote = 'Replicated actions - places, breaks, hits - many times a second'
    }

    for _, group in GROUPS do
        Toggles[group.Name] = CheatDetector:CreateToggle({
            Name = group.Name,
            Default = true,
            Tooltip = GROUP_TOOLTIPS[group.Name],
            Function = function(callback)
                for _, child in (group.Children or {}) do
                    local toggle = Toggles[child]
                    if toggle and toggle.Object then
                        toggle.Object.Visible = callback
                    end
                end
            end
        })
        for _, child in (group.Children or {}) do
            Toggles[child] = CheatDetector:CreateToggle({
                Name = child,
                Default = true,
                Darker = true,
                Tooltip = CHILD_TOOLTIPS[child]
            })
        end
    end

    -- Last, and under everything else, because it is not a detection - it only changes who the
    -- detections above are allowed to look at. Takes effect immediately: the checks ask about it
    -- as they run rather than reading it once at startup, so there is no need to cycle the module.
    Toggles[DETECT_SELF] = CheatDetector:CreateToggle({
        Name = DETECT_SELF,
        Tooltip = 'Testing aid. Runs every enabled detection against you as well, on your behaviour alone - it never looks at which of your modules are on - and flags you like anyone else if one of them fires',
        Function = function()
            -- Readings taken either side of a change of mind about whether we count are not a
            -- pattern, so whichever way it just moved, our own history starts again from nothing.
            strikes[lplr] = nil
        end
    })
end)

run(function()
    local FakeLag
    local TransmissionOffset
    local Mode
    local Delay

    local rng
    local num = 0

    FakeLag = vape.Categories.Utility:CreateModule({
        Name = 'FakeLag',
        Function = function(callback)
            if callback then
                rng = Random.new()

                local clock, restore, after = os.clock(), os.clock(), 0
                repeat
                    local ms = Delay.Value / 1000

                    if Mode.Value == 'Dynamic' then
                        if (os.clock() - clock) >= ms or restore > os.clock() then
                            if clock ~= 9e9 then
                                -- TransmissionOffset is in milliseconds. It was added as raw
                                -- seconds, so the "flush" window lasted 1-10 SECONDS between
                                -- withhold bursts and Dynamic FakeLag barely lagged at all.
                                restore = os.clock() + (TransmissionOffset.Value / 1000)
                                clock = 9e9
                            end
                            setfflag('PhysicsSenderMaxBandwidthBps', '38760')
                        else
                            if clock == 9e9 then
                                clock = os.clock()
                                restore = 0
                            end
                            setfflag('PhysicsSenderMaxBandwidthBps', '0')
                        end
                    elseif Mode.Value == 'Repel' then
                        if store.update > tick() then
                            setfflag('PhysicsSenderMaxBandwidthBps', '0')
                            setfflag('S2PhysicsSenderRate', '0')
                            setfflag('DataSenderRate', '-1')
                            task.wait(rng:NextNumber(70, 150) / 1000)
                            setfflag('PhysicsSenderMaxBandwidthBps', '38760')
                            setfflag('DataSenderRate', '60')
                            setfflag('S2PhysicsSenderRate', '15')
                            after = os.clock() + rng:NextNumber(0.001, (Delay.Value / 1000))
                            store.update = 0
                            num = rng:NextNumber()
                        end
                        if os.clock() > after then
                            num = rng:NextNumber()
                            after = os.clock() + rng:NextNumber(0.001, (Delay.Value / 1000))
                        end
                    elseif Mode.Value == 'Latency' then
                        setfflag('PhysicsSenderMaxBandwidthBps', '0')
                        task.wait(Delay.Value / 1500)
                        setfflag('PhysicsSenderMaxBandwidthBps', '38760')
                        task.wait(ms)
                    end
                    runService.PreRender:Wait()
                until not FakeLag.Enabled
            else
                setfflag('DataSenderRate', '60')
                setfflag('PhysicsSenderMaxBandwidthBps', '38760')
            end
        end,
        Tooltip = 'Delays packets, simulating lag',
        ExtraText = function()
            return Mode and Mode.Value or 'Dynamic'
        end
    })
    getgenv().FakeLag = FakeLag

    TransmissionOffset = FakeLag:CreateSlider({
        Name = 'Transmission Offset',
        Min = 1,
        Max = 10,
        Default = 3,
        Decimal = 5,
        Darker = true,
    })
    Mode = FakeLag:CreateDropdown({
        Name = 'Mode',
        List = { 'Dynamic', 'Repel', 'Latency' },
        Default = 'Dynamic',
        Function = function(val)
            TransmissionOffset.Object.Visible = val == 'Dynamic'
            setfflag('PhysicsSenderMaxBandwidthBps', '38760')
        end,
    })
    Delay = FakeLag:CreateSlider({
        Name = 'Delay',
        Suffix = function()
            return 'ms'
        end,
        Min = 1,
        Max = 500,
        Default = 100,
    })
end)

run(function()
    local KnockbackDelay
    local Chance
    local AirDelay
    local GroundDelay
    local TargetCheck

    local old, rand
    local function apply(type, env, ...)
	local root, mass, dir, knockback = ...
	knockback = knockback and table.clone(knockback) or {}
	knockback[type] = env[type] and knockback[type] or 0
	return old(root, mass, dir, knockback, select(5, ...))
    end

    KnockbackDelay = vape.Categories.Utility:CreateModule({
	Name = 'KnockbackDelay',
	Function = function(callback)
		if callback then
			old, rand = bedwars.KnockbackUtil.applyKnockback, Random.new()
			bedwars.KnockbackUtil.applyKnockback = function(...)
				if rand:NextNumber(0, 100) > Chance.Value then
					return old(...)
				end

				local root, mass, dir, knockback = ...
				if not TargetCheck.Enabled or entitylib.EntityPosition({
					Range = 50,
					Part = 'RootPart',
					Players = true,
				}) then
					local env = {}
					task.delay(AirDelay:GetRandomValue() / 1000, apply, 'horizontal', env, root, mass, dir, knockback, select(5, ...))
					task.delay(GroundDelay:GetRandomValue() / 1000, apply, 'vertical', env, root, mass, dir, knockback, select(5, ...))
					return
				end
				return old(...)
			end
		else
			bedwars.KnockbackUtil.applyKnockback = old or bedwars.KnockbackUtil.applyKnockback
		end
	end,
	Tooltip = 'Delays incoming knockback packets'
    })

    Chance = KnockbackDelay:CreateSlider({
	Name = 'Chance',
	Min = 1,
	Max = 100,
	Default = 40,
	Suffix = '%',
    })
    AirDelay = KnockbackDelay:CreateTwoSlider({
	Name = 'Air delay',
	Min = 0,
	Max = 500,
	DefaultMin = 50,
	DefaultMax = 200,
    })
    GroundDelay = KnockbackDelay:CreateTwoSlider({
	Name = 'Ground delay',
	Min = 0,
	Max = 500,
	DefaultMin = 50,
	DefaultMax = 200,
    })
    TargetCheck = KnockbackDelay:CreateToggle({ Name = 'Target check' })
end)

run(function()
    local MissileTP

    MissileTP = kits:CreateModule({
        Name = 'MissileTP',
        Category = 'Ability',
        Function = function(callback)
            if callback then
                MissileTP:Toggle()
                local plr = entitylib.EntityMouse({
                    Range = 1000,
                    Players = true,
                    Part = 'RootPart'
                })

                if getItem('guided_missile') and plr then
                    local projectile = bedwars.RuntimeLib.await(bedwars.GuidedProjectileController.fireGuidedProjectile:CallServerAsync('guided_missile'))
                    if projectile then
                        local projectilemodel = projectile.model
                        if not projectilemodel.PrimaryPart then
                            projectilemodel:GetPropertyChangedSignal('PrimaryPart'):Wait()
                        end

                        local bodyforce = Instance.new('BodyForce')
                        bodyforce.Force = Vector3.new(0, projectilemodel.PrimaryPart.AssemblyMass * workspace.Gravity, 0)
                        bodyforce.Name = 'AntiGravity'
                        bodyforce.Parent = projectilemodel.PrimaryPart

                        repeat
                            projectile.model:SetPrimaryPartCFrame(CFrame.lookAlong(plr.RootPart.CFrame.p, gameCamera.CFrame.LookVector))
                            task.wait(0.1)
                        until not projectile.model or not projectile.model.Parent
                    else
                        notif('MissileTP', 'Missile on cooldown.', 3)
                    end
                end
            end
        end,
        Tooltip = 'Spawns and teleports a missile to a player\nnear your mouse'
    })
end)

run(function()
    local PickupRange
    local Range
    local Network
    local Lower

    PickupRange = vape.Categories.Utility:CreateModule({
        Name = 'PickupRange',
        Function = function(callback)
            if callback then
                local items = collection('ItemDrop', PickupRange)
                repeat
                    if entitylib.isAlive then
                        local localPosition = entitylib.character.RootPart.Position
                        for _, v in items do
                            if tick() - (v:GetAttribute('ClientDropTime') or 0) < 2 then continue end
                            if isnetworkowner(v) and Network.Enabled and entitylib.character.Humanoid.Health > 0 then
                                v.CFrame = CFrame.new(localPosition - Vector3.new(0, 3, 0))
                            end

                            if (localPosition - v.Position).Magnitude <= Range.Value then
                                if Lower.Enabled and (localPosition.Y - v.Position.Y) < (entitylib.character.HipHeight - 1) then continue end
                                task.spawn(function()
                                    bedwars.Client:Get(remotes.PickupItem):CallServerAsync({
                                        itemDrop = v
                                    }):andThen(function(suc)
                                        if suc and bedwars.SoundList then
                                            bedwars.SoundManager:playSound(bedwars.SoundList.PICKUP_ITEM_DROP)
                                            local sound = bedwars.ItemMeta[v.Name].pickUpOverlaySound
                                            if sound then
                                                bedwars.SoundManager:playSound(sound, {
                                                    position = v.Position,
                                                    volumeMultiplier = 0.9
                                                })
                                            end
                                        end
                                    end)
                                end)
                            end
                        end
                    end
                    task.wait(0.1)
                until not PickupRange.Enabled
            end
        end,
        Tooltip = 'Picks up items from a farther distance'
    })
    Range = PickupRange:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 10,
        Default = 10,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    Network = PickupRange:CreateToggle({
        Name = 'Network TP',
        Default = true
    })
    Lower = PickupRange:CreateToggle({Name = 'Feet Check'})
end)

run(function()
	local Scaffold
	local Count
	local Expand
	local Tower
	local Downwards
	local Diagonal
	local LimitItem
	local Mouse
	local BridgeWidth
	local KeepY
	local JumpBridge
	local BlockPreference
	local RestoreSlot
	local FillColor
	local OutlineColor
	local adjacent, lastpos, label, visualBlock = {}, Vector3.zero
	local visualTween, visualPos
	local visualSpeed = 0.1
	local lockedY, restoreSlot, nextJump = nil, nil, 0

	for x = -3, 3, 3 do
		for y = -3, 3, 3 do
			for z = -3, 3, 3 do
				local vec = Vector3.new(x, y, z)
				if vec ~= Vector3.zero then
					table.insert(adjacent, vec)
				end
			end
		end
	end

	local function nearCorner(poscheck, pos)
		local startpos = poscheck - Vector3.new(3, 3, 3)
		local endpos = poscheck + Vector3.new(3, 3, 3)
		local check = poscheck + (pos - poscheck).Unit * 100
		return Vector3.new(math.clamp(check.X, startpos.X, endpos.X), math.clamp(check.Y, startpos.Y, endpos.Y), math.clamp(check.Z, startpos.Z, endpos.Z))
	end

	local function blockProximity(pos)
		local mag, returned = 60
		local tab = getBlocksInPoints(bedwars.BlockController:getBlockPosition(pos - Vector3.new(21, 21, 21)), bedwars.BlockController:getBlockPosition(pos + Vector3.new(21, 21, 21)))
		for _, v in tab do
			local blockpos = nearCorner(v, pos)
			local newmag = (pos - blockpos).Magnitude
			if newmag < mag then
				mag, returned = newmag, blockpos
			end
		end
		table.clear(tab)
		return returned
	end

	local function checkAdjacent(pos)
		for _, v in adjacent do
			if getPlacedBlock(pos + v) then
				return true
			end
		end
		return false
	end

	local function getScaffoldBlock()
		if store.hand.toolType == 'block' then
			return store.hand.tool.Name, store.hand.amount
		elseif (not LimitItem.Enabled) then
			local items = (store.inventory.inventory or {}).items or {}
			if BlockPreference.Value == 'Wool first' then
				local wool, amount = getWool()
				if wool then return wool, amount end
			end
			local chosen
			for _, item in items do
				local meta = bedwars.ItemMeta[item.itemType]
				if meta and meta.block and (not chosen or (BlockPreference.Value == 'Highest count' and (item.amount or 0) > (chosen.amount or 0))) then
					chosen = item
					if BlockPreference.Value == 'Nearest slot' then break end
				end
			end
			if chosen then return chosen.itemType, chosen.amount end
		end

		return nil, 0
	end

	local function clearVisuals()
		if visualTween then
			visualTween:Cancel()
			visualTween = nil
		end
		if visualBlock then
			visualBlock.Parent = nil
		end
		visualPos = nil
	end

	local function updateVisual(pos)
		if not visualBlock or not pos then return end

		local blockpos = bedwars.BlockController:getBlockPosition(pos) * 3
		if visualPos == blockpos then return end

		if visualTween then
			visualTween:Cancel()
			visualTween = nil
		end

		if visualBlock.Parent == gameCamera then
			visualTween = tweenService:Create(visualBlock, TweenInfo.new(visualSpeed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {CFrame = CFrame.new(blockpos)})
			visualTween:Play()
		else
			visualBlock.CFrame = CFrame.new(blockpos)
			visualBlock.Parent = gameCamera
		end
		visualPos = blockpos
	end

	Scaffold = vape.Categories.Utility:CreateModule({
		Name = 'Scaffold',
		Function = function(callback)
			if label then
				label.Visible = callback
			end

			if callback then
				lockedY, restoreSlot, nextJump = nil, nil, 0
				repeat
					if entitylib.isAlive then
						local wool, amount = getScaffoldBlock()

						if Mouse.Enabled then
							if not inputService:IsMouseButtonPressed(0) then
								wool = nil
							end
						end

						if label then
							amount = amount or 0
							label.Text = amount..' <font color="rgb(170, 170, 170)">(Scaffold)</font>'
							label.TextColor3 = Color3.fromHSV((amount / 128) / 2.8, 0.86, 1)
						end

						if wool then
							local root = entitylib.character.RootPart
							-- Only take a block slot when needed, and restore the original slot
							-- on disable. This keeps combat/inventory flow intact after bridging.
							if store.hand.toolType ~= 'block' then
								for slot, entry in store.inventory.hotbar or {} do
									if entry.item and entry.item.itemType == wool then
										restoreSlot = restoreSlot or store.inventory.hotbarSlot
										hotbarSwitch(slot - 1)
										break
									end
								end
							end
							if Tower.Enabled and inputService:IsKeyDown(Enum.KeyCode.Space) and (not inputService:GetFocusedTextBox()) then
								root.Velocity = Vector3.new(root.Velocity.X, 38, root.Velocity.Z)
							end
							if JumpBridge.Enabled and not Tower.Enabled and entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air and entitylib.character.Humanoid.MoveDirection.Magnitude > 0.05 and tick() >= nextJump then
								entitylib.character.Humanoid.Jump = true
								nextJump = tick() + 0.24
							end

							for i = Expand.Value, 1, -1 do
								local currentpos = roundPos(root.Position - Vector3.new(0, entitylib.character.HipHeight + (Downwards.Enabled and inputService:IsKeyDown(Enum.KeyCode.LeftShift) and 4.5 or 1.5), 0) + entitylib.character.Humanoid.MoveDirection * (i * 3))
								local downwards = Downwards.Enabled and inputService:IsKeyDown(Enum.KeyCode.LeftShift)
								if KeepY.Enabled and not downwards then
									lockedY = lockedY or currentpos.Y
									currentpos = Vector3.new(currentpos.X, lockedY, currentpos.Z)
								else
									lockedY = currentpos.Y
								end
								if Diagonal.Enabled then
									if math.abs(math.round(math.deg(math.atan2(-entitylib.character.Humanoid.MoveDirection.X, -entitylib.character.Humanoid.MoveDirection.Z)) / 45) * 45) % 90 == 45 then
										local dt = (lastpos - currentpos)
										if ((dt.X == 0 and dt.Z ~= 0) or (dt.X ~= 0 and dt.Z == 0)) and ((lastpos - root.Position) * Vector3.new(1, 0, 1)).Magnitude < 2.5 then
											currentpos = lastpos
										end
									end
								end

								updateVisual(currentpos)
								local positions = {currentpos}
								if BridgeWidth.Value > 1 then
									local direction = entitylib.character.Humanoid.MoveDirection
									if direction.Magnitude < 0.05 then direction = root.CFrame.LookVector end
									local side = Vector3.new(-direction.Z, 0, direction.X)
									if side.Magnitude > 0 then
										side = side.Unit * 3
										for offset = 1, BridgeWidth.Value - 1 do
											table.insert(positions, currentpos + side * ((offset % 2 == 0 and -1 or 1) * math.ceil(offset / 2)))
										end
									end
								end
								for _, placepos in positions do
									local block, blockpos = getPlacedBlock(placepos)
									if not block then
										blockpos = checkAdjacent(blockpos * 3) and blockpos * 3 or blockProximity(placepos)
										if blockpos then Scaffold:Delay(0, function() bedwars.placeBlock(blockpos, wool, false) end) end
									end
								end
								lastpos = currentpos
							end
						end
					end
					task.wait(0.03)
				until not Scaffold.Enabled
				clearVisuals()
				if RestoreSlot.Enabled and restoreSlot ~= nil then hotbarSwitch(restoreSlot) end
				restoreSlot, lockedY = nil, nil
			end
		end,
		Tooltip = 'Helps you make bridges/scaffold walk.'
	})
	Expand = Scaffold:CreateSlider({
		Name = 'Expand',
		Min = 1,
		Max = 6
	})
	BridgeWidth = Scaffold:CreateSlider({
		Name = 'Bridge width', Min = 1, Max = 3, Default = 1,
		Tooltip = 'Places up to three blocks across while bridging'
	})
	KeepY = Scaffold:CreateToggle({Name = 'Keep Y', Default = true, Tooltip = 'Keeps a level bridge unless downwards mode is held'})
	JumpBridge = Scaffold:CreateToggle({Name = 'Jump bridge', Tooltip = 'Repeats natural jumps while moving on a bridge'})
	Tower = Scaffold:CreateToggle({
		Name = 'Tower',
		Default = true
	})
	Downwards = Scaffold:CreateToggle({
		Name = 'Downwards',
		Default = true
	})
	Diagonal = Scaffold:CreateToggle({
		Name = 'Diagonal',
		Default = true
	})
	LimitItem = Scaffold:CreateToggle({Name = 'Limit to items'})
	BlockPreference = Scaffold:CreateDropdown({
		Name = 'Block preference', List = {'Wool first', 'Nearest slot', 'Highest count'}, Default = 'Wool first',
		Tooltip = 'Chooses which inventory block Scaffold should use'
	})
	RestoreSlot = Scaffold:CreateToggle({Name = 'Restore slot', Default = true, Tooltip = 'Returns to the slot held before automatic block selection'})
	Mouse = Scaffold:CreateToggle({Name = 'Require mouse down'})
	Scaffold:CreateToggle({
		Name = 'Visual',
		Tooltip = 'Renders an overlay on the block about to be placed',
		Function = function(callback)
			FillColor.Object.Visible = callback
			OutlineColor.Object.Visible = callback
			if callback then
				visualBlock = Instance.new('Part')
				visualBlock.Size = Vector3.new(3, 3, 3)
				visualBlock.Anchored = true
				visualBlock.CanCollide = false
				visualBlock.CanQuery = false
				visualBlock.CanTouch = false
				visualBlock.CastShadow = false
				visualBlock.Transparency = 1
				local selection = Instance.new('SelectionBox')
				selection.Adornee = visualBlock
				selection.LineThickness = 0.04
				selection.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
				selection.Transparency = 1 - OutlineColor.Opacity
				selection.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
				selection.SurfaceTransparency = 1 - FillColor.Opacity
				selection.Parent = visualBlock
				bedwars.QueryUtil:setQueryIgnored(visualBlock, true)
			else
				clearVisuals()
				if visualBlock then visualBlock:Destroy() end
				visualBlock = nil
			end
		end
	})
	FillColor = Scaffold:CreateColorSlider({
		Name = 'Fill Color',
		DefaultSat = 0,
		DefaultOpacity = 0.4,
		Darker = true,
		Visible = false,
		Function = function(hue, sat, val, opacity)
			if visualBlock then
				visualBlock.SelectionBox.SurfaceColor3 = Color3.fromHSV(hue, sat, val)
				visualBlock.SelectionBox.SurfaceTransparency = 1 - opacity
			end
		end
	})
	OutlineColor = Scaffold:CreateColorSlider({
		Name = 'Outline Color',
		DefaultValue = 0,
		Darker = true,
		Visible = false,
		Function = function(hue, sat, val, opacity)
			if visualBlock then
				visualBlock.SelectionBox.Color3 = Color3.fromHSV(hue, sat, val)
				visualBlock.SelectionBox.Transparency = 1 - opacity
			end
		end
	})
	Count = Scaffold:CreateToggle({
		Name = 'Block Count',
		Function = function(callback)
			if callback then
				label = Instance.new('TextLabel')
				label.Size = UDim2.fromOffset(100, 20)
				label.Position = UDim2.new(0.5, 6, 0.5, 60)
				label.BackgroundTransparency = 1
				label.AnchorPoint = Vector2.new(0.5, 0)
				label.Text = '0'
				label.TextColor3 = Color3.new(0, 1, 0)
				label.TextSize = 18
				label.RichText = true
				label.Font = Enum.Font.Arial
				label.Visible = Scaffold.Enabled
				label.Parent = vape.gui
			else
				label:Destroy()
				label = nil
			end
		end
	})
end)

run(function()
    local StaffDetector
    local Mode
    local Clans
    local Party
    local Profile
    local Users
    local NotifyLeave
    local blacklistedclans = {'gg', 'gg2', 'DV', 'DV2'}
    local blacklisteduserids = {1502104539, 3826146717, 4531785383, 1049767300, 4926350670, 653085195, 184655415, 2752307430, 5087196317, 5744061325, 1536265275}
    local joined = {}
    -- Players that have been flagged as staff this session, so 'Notify on leave' can
    -- tell you the moment a detected mod leaves your game.
    local flagged = {}

    local function getRole(plr, id)
        local suc, res = pcall(function()
            return plr:GetRankInGroup(id)
        end)
        if not suc then
            notif('StaffDetector', res, 30, 'alert')
        end
        return suc and res or 0
    end

    local function staffFunction(plr, checktype)
        if not vape.Loaded then
            repeat task.wait() until vape.Loaded
        end

        notif('StaffDetector', 'Staff Detected ('..checktype..'): '..plr.Name..' ('..plr.UserId..')', 60, 'alert')
        whitelist.customtags[plr.Name] = {{text = 'GAME STAFF', color = Color3.new(1, 0, 0)}}
        flagged[plr.UserId] = {Name = plr.Name, Check = checktype}

        if Party.Enabled and not checktype:find('clan') then
            bedwars.PartyController:leaveParty()
        end

        if Mode.Value == 'Uninject' then
            task.spawn(function()
                vape:Uninject()
            end)
            game:GetService('StarterGui'):SetCore('SendNotification', {
                Title = 'StaffDetector',
                Text = 'Staff Detected ('..checktype..')\n'..plr.Name..' ('..plr.UserId..')',
                Duration = 60,
            })
        elseif Mode.Value == 'Requeue' then
            bedwars.QueueController:joinQueue(store.queueType)
        elseif Mode.Value == 'Profile' then
            vape.Save = function() end
            if vape.Profile ~= Profile.Value then
                vape:Load(true, Profile.Value)
            end
        elseif Mode.Value == 'AutoConfig' then
            local safe = {'AutoClicker', 'Reach', 'Sprint', 'HitFix', 'StaffDetector'}
            vape.Save = function() end
            for i, v in vape.Modules do
                if not (table.find(safe, i) or v.Category == 'Render') then
                    if v.Enabled then
                        v:Toggle()
                    end
                    v:SetBind('')
                end
            end
        end
    end

    local function checkFriends(list)
        for _, v in list do
            if joined[v] then
                return joined[v]
            end
        end
        return nil
    end

    local function checkJoin(plr, connection)
        if not plr:GetAttribute('Team') and plr:GetAttribute('Spectator') and not bedwars.Store:getState().Game.customMatch then
            connection:Disconnect()
            local tab, pages = {}, playersService:GetFriendsAsync(plr.UserId)
            for _ = 1, 200 do
                for _, v in pages:GetCurrentPage() do
                    table.insert(tab, v.Id)
                end
                if pages.IsFinished then break end
                pages:AdvanceToNextPageAsync()
            end

            local friend = checkFriends(tab)
            if not friend then
                staffFunction(plr, 'impossible_join')
                return true
            else
                notif('StaffDetector', string.format('Spectator %s joined from %s', plr.Name, friend), 20, 'warning')
            end
        end
    end

    local function playerAdded(plr)
        joined[plr.UserId] = plr.Name
        if plr == lplr then return end

        if table.find(blacklisteduserids, plr.UserId) or table.find(Users.ListEnabled, tostring(plr.UserId)) then
            staffFunction(plr, 'blacklisted_user')
        elseif getRole(plr, 5774246) >= 100 then
            staffFunction(plr, 'staff_role')
        else
            local connection
            connection = plr:GetAttributeChangedSignal('Spectator'):Connect(function()
                checkJoin(plr, connection)
            end)
            StaffDetector:Clean(connection)
            if checkJoin(plr, connection) then
                return
            end

            if not plr:GetAttribute('ClanTag') then
                plr:GetAttributeChangedSignal('ClanTag'):Wait()
            end

            if table.find(blacklistedclans, plr:GetAttribute('ClanTag')) and vape.Loaded and Clans.Enabled then
                connection:Disconnect()
                staffFunction(plr, 'blacklisted_clan_'..plr:GetAttribute('ClanTag'):lower())
            end
        end
    end

    StaffDetector = vape.Categories.Utility:CreateModule({
        Name = 'StaffDetector',
        Function = function(callback)
            if callback then
                table.clear(flagged)
                StaffDetector:Clean(playersService.PlayerAdded:Connect(playerAdded))
                StaffDetector:Clean(playersService.PlayerRemoving:Connect(function(plr)
                    local info = flagged[plr.UserId]
                    if info and NotifyLeave.Enabled then
                        notif('StaffDetector', 'Flagged staff left ('..info.Check..'): '..info.Name..' ('..plr.UserId..')', 20, 'warning')
                    end
                    flagged[plr.UserId] = nil
                end))
                for _, v in playersService:GetPlayers() do
                    task.spawn(playerAdded, v)
                end
            else
                table.clear(joined)
                table.clear(flagged)
            end
        end,
        Tooltip = 'Detects people with a staff rank ingame'
    })
    Mode = StaffDetector:CreateDropdown({
        Name = 'Mode',
        List = {'Uninject', 'Profile', 'Requeue', 'AutoConfig', 'Notify'},
        Function = function(val)
            if Profile.Object then
                Profile.Object.Visible = val == 'Profile'
            end
        end
    })
    Clans = StaffDetector:CreateToggle({
        Name = 'Blacklist clans',
        Default = true
    })
    Party = StaffDetector:CreateToggle({
        Name = 'Leave party'
    })
    NotifyLeave = StaffDetector:CreateToggle({
        Name = 'Notify on leave',
        Tooltip = 'Notifies you when a flagged staff member leaves your game',
        Default = true
    })
    Profile = StaffDetector:CreateTextBox({
        Name = 'Profile',
        Default = 'default',
        Darker = true,
        Visible = false
    })
    Users = StaffDetector:CreateTextList({
        Name = 'Users',
        Placeholder = 'player (userid)'
    })
end)

run(function()
    TrapDisabler = vape.Categories.Utility:CreateModule({
        Name = 'TrapDisabler',
        Tooltip = 'Disables Snap Traps'
    })
end)

run(function()
    local context = {
        vape = vape,
        vapeEvents = vapeEvents,
        entitylib = entitylib,
        bedwars = bedwars,
        store = store,
        lplr = lplr,
        playersService = playersService,
        runService = runService,
        collectionService = collectionService,
        replicatedStorage = replicatedStorage,
        httpService = httpService,
        guiService = guiService,
        coreGui = coreGui,
        gameCamera = gameCamera,
        inputService = inputService,
        remotes = remotes,
        sortmethods = sortmethods,
        breakmethods = breakmethods,
        frictionTable = frictionTable,
        updateVelocity = updateVelocity,
        getItem = getItem,
        getWool = getWool,
        getBestArmor = getBestArmor,
        getPlacedBlock = getPlacedBlock,
        switchItem = switchItem,
        isnetworkowner = isnetworkowner,
        notif = notif,
        placeBlock = bedwars.placeBlock,
        breakBlock = bedwars.breakBlock,
        debug = debug,
		Knit = bedwars.Knit,
		kits = kits,
        canDebug = canDebug
    }

    ----------------------------------------------------------------------------------------------
    -- AutoWin/Jade reactive runtime (direct implementation)
    ----------------------------------------------------------------------------------------------
local function registerAetherRuntime(context)
-- AetherV2 BedWars reactive runtime
-- Compiled directly in games/6872274481.lua with the live match-file context.
-- The dependency dump in libraries/bedwars is a reference only; this runtime deliberately
-- distinguishes live controllers/replicated state from compatibility fallbacks.

local ctx = context
assert(type(ctx) == 'table', 'Aether BedWars runtime requires context')

local vape = assert(ctx.vape, 'missing vape')
local vapeEvents = ctx.vapeEvents
local entitylib = assert(ctx.entitylib, 'missing entitylib')
local bedwars = assert(ctx.bedwars, 'missing bedwars')
local store = assert(ctx.store, 'missing store')
local lplr = assert(ctx.lplr, 'missing local player')
local playersService = assert(ctx.playersService, 'missing Players')
local runService = assert(ctx.runService, 'missing RunService')
local collectionService = assert(ctx.collectionService, 'missing CollectionService')
local replicatedStorage = assert(ctx.replicatedStorage, 'missing ReplicatedStorage')
local httpService = assert(ctx.httpService, 'missing HttpService')
local guiService = ctx.guiService
local coreGui = ctx.coreGui
local gameCamera = ctx.gameCamera or workspace.CurrentCamera
local inputService = ctx.inputService
local remotes = ctx.remotes or {}
local sortmethods = ctx.sortmethods or {}
local breakmethods = ctx.breakmethods or {}
local frictionTable = ctx.frictionTable or {}
local updateVelocity = ctx.updateVelocity or function() end
local getItem = assert(ctx.getItem, 'missing getItem')
local getWool = ctx.getWool
local getBestArmor = ctx.getBestArmor
local getPlacedBlock = assert(ctx.getPlacedBlock, 'missing getPlacedBlock')
local switchItem = assert(ctx.switchItem, 'missing switchItem')
local isnetworkowner = ctx.isnetworkowner or function() return true end
local notif = ctx.notif or function() end
local safePlaceBlock = ctx.placeBlock or bedwars.placeBlock
local safeBreakBlock = ctx.breakBlock or bedwars.breakBlock

local Runtime = {Version = 7, Errors = {}, Context = ctx}

local function now()
    return tick()
end

local function safe(label, fn, ...)
    if type(fn) ~= 'function' then return false, 'missing function' end
    local ok, result = pcall(fn, ...)
    if not ok then
        Runtime.Errors[label] = {At = now(), Error = tostring(result)}
        return false, result
    end
    return true, result
end

local function ask(label, fn, ...)
    local ok, result = safe(label, fn, ...)
    return ok and result or nil
end

local function moduleByName(name)
    if vape.Modules and vape.Modules[name] then return vape.Modules[name] end
    for _, panel in {vape.Kits, vape.Legit} do
        if panel and panel.Modules and panel.Modules[name] then return panel.Modules[name] end
    end
end

local function rootOfLocal()
    local char = entitylib.character
    if entitylib.isAlive and char and char.RootPart and char.RootPart.Parent then
        return char.RootPart, char, char.Humanoid
    end
end

local function partOf(object)
    if not object then return nil end
    if object:IsA('BasePart') then return object end
    return object.PrimaryPart or object:FindFirstChildWhichIsA('BasePart')
end

local function itemCount(name)
    local item = ask('inventory.getItem.'..tostring(name), getItem, name)
    return item and item.amount or 0
end

local function copyTable(source)
    local out = {}
    for key, value in pairs(source or {}) do out[key] = value end
    return out
end

--------------------------------------------------------------------------------
-- BedWars capability layer
--------------------------------------------------------------------------------
local Capabilities = {
    Match = {}, Metadata = {}, Inventory = {}, Blocks = {}, Abilities = {}, Kits = {}, Shop = {}, Queue = {}, Network = {},
    Status = {},
    Source = {LIVE = 'live', CONTROLLER = 'controller', REPLICATED = 'replicated', METADATA = 'metadata', FALLBACK = 'fallback', UNKNOWN = 'unknown'}
}
Runtime.BedWarsAPI = Capabilities

local referenceStates = {PRE = 0, RUNNING = 1, POST = 2}
Capabilities.Match.States = {
    PRE = (bedwars.MatchStates and bedwars.MatchStates.PRE) or referenceStates.PRE,
    RUNNING = (bedwars.MatchStates and bedwars.MatchStates.RUNNING) or referenceStates.RUNNING,
    POST = (bedwars.MatchStates and bedwars.MatchStates.POST) or referenceStates.POST
}

function Capabilities.Match:GetState()
    local state = store.matchState
    if type(state) == 'number' then return state, self.Source or Capabilities.Source.REPLICATED end
    local live = ask('match.store', function() return bedwars.Store:getState().Game.matchState end)
    if type(live) == 'number' then return live, Capabilities.Source.CONTROLLER end
    return Capabilities.Match.States.PRE, Capabilities.Source.FALLBACK
end

function Capabilities.Match:GetTeam()
    local team = lplr:GetAttribute('Team')
    if team ~= nil then return team, Capabilities.Source.REPLICATED end
    local value = ask('match.team', function() return bedwars.Store:getState().Game.myTeam end)
    if type(value) == 'table' then value = value.id end
    if value ~= nil then return value, Capabilities.Source.CONTROLLER end
    local char = lplr.Character
    value = char and char:GetAttribute('Team') or nil
    return value, value ~= nil and Capabilities.Source.REPLICATED or Capabilities.Source.UNKNOWN
end

function Capabilities.Metadata:GetItem(itemType)
    local meta = bedwars.ItemMeta and bedwars.ItemMeta[itemType]
    return meta, meta and Capabilities.Source.LIVE or Capabilities.Source.UNKNOWN
end

function Capabilities.Inventory:Get()
    local inv = store.inventory and store.inventory.inventory
    if type(inv) == 'table' then return inv, Capabilities.Source.REPLICATED end
    return {items = {}, armor = {}}, Capabilities.Source.UNKNOWN
end

function Capabilities.Inventory:GetHeld()
    return store.hand, store.hand and Capabilities.Source.REPLICATED or Capabilities.Source.UNKNOWN
end

function Capabilities.Shop:GetItem(itemType, shopId)
    if not bedwars.Shop or type(bedwars.Shop.getShopItem) ~= 'function' then return nil, Capabilities.Source.UNKNOWN end
    local item = ask('shop.item.'..tostring(itemType), function()
        return bedwars.Shop.getShopItem(itemType, lplr, shopId and {shopId = shopId} or nil)
    end)
    return item, item and Capabilities.Source.LIVE or Capabilities.Source.UNKNOWN
end

function Capabilities.Queue:GetMeta()
    return bedwars.QueueMeta or {}, bedwars.QueueMeta and Capabilities.Source.LIVE or Capabilities.Source.UNKNOWN
end

function Capabilities.Kits:GetEquipped()
    local kit = store.equippedKit
    if kit == nil or kit == '' then kit = lplr:GetAttribute('PlayingAsKit') or lplr:GetAttribute('PlayingAsKits') end
    return kit, kit and Capabilities.Source.REPLICATED or Capabilities.Source.UNKNOWN
end

function Capabilities.Blocks:Get(position)
    return ask('blocks.get', getPlacedBlock, position)
end

function Capabilities.Blocks:Place(position, itemType)
    return safe('blocks.place', safePlaceBlock, position, itemType, false)
end

function Capabilities.Blocks:Break(block)
    return safe('blocks.break', safeBreakBlock, block, true, true, nil, true, breakmethods.Distance, 360, false)
end

--------------------------------------------------------------------------------
-- Movement ownership. New systems use leases instead of independently writing movement.
-- Legacy movement modules are observed in one central compatibility boundary.
--------------------------------------------------------------------------------
local Movement = {
    Current = nil,
    Serial = 0,
    ExternalNames = {'LongJump', 'Fly', 'Speed', 'Scaffold', 'TPAura', 'RecoveryTP', 'AntiDeath'},
    Priorities = {Ordinary = 10, AutoWin = 40, Ability = 70, Emergency = 100}
}
Runtime.Movement = Movement

function Movement:_expired()
    return self.Current and self.Current.Expires and self.Current.Expires <= now()
end

function Movement:_clearExpired()
    if self:_expired() then self.Current = nil end
end

function Movement:GetOwner()
    self:_clearExpired()
    return self.Current and self.Current.Owner or nil
end

function Movement:GetExternalOwner(ignore)
    if store.rootpart and ignore ~= 'HitboxTransaction' then return 'HitboxTransaction' end
    for _, name in ipairs(self.ExternalNames) do
        if name ~= ignore then
            local module = moduleByName(name)
            if module and module.Enabled then return name end
        end
    end
end

function Movement:CanWrite(owner)
    self:_clearExpired()
    if not self.Current then return true end
    return self.Current.Owner == owner
end

function Movement:Acquire(owner, priority, ttl, onPreempt, allowExternal)
    self:_clearExpired()
    priority = priority or self.Priorities.Ordinary
	local external = if allowExternal then nil else self:GetExternalOwner(owner)
    if external and external ~= owner then return nil, 'external:'..external end
    local current = self.Current
    if current and current.Owner ~= owner and current.Priority > priority then return nil, 'owned:'..current.Owner end
    if current and current.Owner ~= owner and current.OnPreempt then safe('movement.preempt.'..current.Owner, current.OnPreempt, owner) end
    self.Serial += 1
    local serial = self.Serial
    local lease = {Owner = owner, Priority = priority, Expires = now() + (ttl or 0.5), Serial = serial, Released = false}
    function lease:Renew(seconds)
        if self.Released then return false end
        if Movement.Current ~= self then return false end
        self.Expires = now() + (seconds or ttl or 0.5)
        return true
    end
    function lease:Release()
        if self.Released then return end
        self.Released = true
        if Movement.Current == self then Movement.Current = nil end
    end
    lease.OnPreempt = onPreempt
    self.Current = lease
    return lease
end

--------------------------------------------------------------------------------
-- Module leases. Restore only values that still equal the value this lease wrote.
--------------------------------------------------------------------------------
local ModuleLeases = {Active = {}, Serial = 0}
Runtime.ModuleLeases = ModuleLeases

local function optionCurrent(option)
    if option.Enabled ~= nil then return option.Enabled, 'toggle' end
    return option.Value, 'value'
end

local function optionSet(option, value, kind)
    if kind == 'toggle' then
        if option.Enabled ~= value then safe('lease.option.toggle', function() option:Toggle() end) end
    elseif option.SetValue and option.Value ~= value then
        safe('lease.option.value', function() option:SetValue(value) end)
    end
end

function ModuleLeases:Acquire(owner, name, wantedOptions, wantEnabled)
    local key = owner..':'..name
    if self.Active[key] then return self.Active[key] end
    local module = moduleByName(name)
    if not module then return nil, 'missing module' end
    self.Serial += 1
    local lease = {Owner = owner, Name = name, Module = module, Options = {}, Released = false, Serial = self.Serial}
    lease.OldEnabled = module.Enabled and true or false
    lease.WroteEnabled = nil
    for optionName, wanted in pairs(wantedOptions or {}) do
        local option = module.Options and module.Options[optionName]
        if option then
            local old, kind = optionCurrent(option)
            if old ~= wanted then
                optionSet(option, wanted, kind)
                table.insert(lease.Options, {Option = option, Old = old, Written = wanted, Kind = kind})
            end
        end
    end
    if wantEnabled ~= false and not module.Enabled then
        safe('lease.module.enable.'..name, function() module:Toggle(true) end)
        if module.Enabled then lease.WroteEnabled = true end
    end
    function lease:Release()
        if self.Released then return end
        self.Released = true
        ModuleLeases.Active[key] = nil
        for index = #self.Options, 1, -1 do
            local entry = self.Options[index]
            local current = optionCurrent(entry.Option)
            if current == entry.Written then optionSet(entry.Option, entry.Old, entry.Kind) end
        end
        if self.WroteEnabled and self.Module.Enabled == true then
            safe('lease.module.restore.'..self.Name, function() self.Module:Toggle(true) end)
        end
    end
    self.Active[key] = lease
    return lease
end

function ModuleLeases:ReleaseOwner(owner)
    local list = {}
    for key, lease in pairs(self.Active) do if lease.Owner == owner then table.insert(list, lease) end end
    for _, lease in ipairs(list) do lease:Release() end
end

function ModuleLeases:Count(owner)
    local count = 0
    for _, lease in pairs(self.Active) do if not owner or lease.Owner == owner then count += 1 end end
    return count
end

--------------------------------------------------------------------------------
-- Shared JadeAbilityAdapter. Used by JIK and the LongJump Jade compatibility hook.
--------------------------------------------------------------------------------
local Jade = {
    Compatibility = {'jade_hammer_3', 'jade_hammer_2', 'jade_hammer_1', 'jade_hammer', 'jade_hammer_jump'},
    AbilityMap = {
        jade_hammer_3 = {'jade_hammer_3_jump', 'jade_hammer_jump'},
        jade_hammer_2 = {'jade_hammer_2_jump', 'jade_hammer_jump'},
        jade_hammer_1 = {'jade_hammer_jump', 'jade_hammer_1_jump'},
        jade_hammer = {'jade_hammer_jump'},
        jade_hammer_jump = {'jade_hammer_jump', 'jade_hammer_3_jump', 'jade_hammer_2_jump', 'jade_hammer_1_jump'}
    },
    Last = {}
}
Runtime.Jade = Jade

local function jadeTier(name)
    local normalized = tostring(name or ''):lower():gsub('[%s%-]+', '_')
    local tier = tonumber(normalized:match('jade_hammer_(%d+)'))
    return tier or (normalized:find('jade_hammer', 1, true) and 0 or -1)
end

local function normalizeItemType(value)
    if type(value) ~= 'string' then return nil end
    return value:lower():gsub('[%s%-]+', '_')
end

function Jade:IsHammerName(value)
    local normalized = normalizeItemType(value)
    return normalized == 'jade_hammer_jump' or (normalized ~= nil and normalized:match('^jade_hammer(_%d+)?$') ~= nil)
end

function Jade:_candidateNames()
    local names, seen = {}, {}
    for _, name in ipairs(self.Compatibility) do seen[name] = true; table.insert(names, name) end
    if type(bedwars.ItemMeta) == 'table' then
        for name, meta in pairs(bedwars.ItemMeta) do
			if type(name) == 'string' and self:IsHammerName(name) and type(meta) == 'table' and not seen[name] then
                seen[name] = true
                table.insert(names, name)
            end
        end
    end
    table.sort(names, function(a, b) return jadeTier(a) > jadeTier(b) end)
    return names
end

function Jade:GetBestHammer()
    local found, seen = {}, {}
    local function add(item, source, fallbackType)
        if type(item) ~= 'table' then return end
        local tool = item.tool
        local itemType = normalizeItemType(item.itemType or fallbackType or (tool and tool.Name))
        if not self:IsHammerName(itemType) then return end
        if (not tool or typeof(tool) ~= 'Instance' or not tool.Parent) and lplr.Character then
            local handValue = lplr.Character:FindFirstChild('HandInvItem')
            handValue = handValue and handValue.Value
            if handValue and self:IsHammerName(handValue.Name) then tool = handValue end
        end
        if not tool or typeof(tool) ~= 'Instance' or not tool.Parent then return end
		if seen[tool] then return end
		seen[tool] = true
        table.insert(found, {
            Item = {itemType = itemType, tool = tool, amount = item.amount or 1},
            Source = source,
            Tier = jadeTier(itemType)
        })
    end

    for _, name in ipairs(self:_candidateNames()) do
        add(ask('jade.item.'..name, getItem, name), Capabilities.Source.REPLICATED, name)
    end

    local observed = store.inventory and store.inventory.inventory
    if observed then
        add(observed.hand, Capabilities.Source.REPLICATED)
        for _, item in pairs(observed.items or {}) do add(item, Capabilities.Source.REPLICATED) end
    end
    add(store.hand, Capabilities.Source.LIVE)

    local function addTools(container, source)
        if not container then return end
        for _, tool in ipairs(container:GetChildren()) do
            if tool:IsA('Tool') and self:IsHammerName(tool.Name) then
                add({itemType = tool.Name, tool = tool}, source)
            end
        end
    end
    addTools(lplr.Character, Capabilities.Source.LIVE)
    addTools(lplr:FindFirstChildOfClass('Backpack'), Capabilities.Source.LIVE)

    table.sort(found, function(a, b) return a.Tier > b.Tier end)
    if found[1] then
        return found[1].Item, {Source = found[1].Source, Tier = found[1].Tier}
    end
    return nil, {Source = Capabilities.Source.REPLICATED, Reason = 'not-in-inventory'}
end

local function liveAbilityController()
    local controller = bedwars.AbilityController
    if not controller then return nil, Capabilities.Source.UNKNOWN, false end
    local knit = bedwars.Knit and bedwars.Knit.Controllers
    if knit and (controller == knit.AbilityController or controller == knit.JadeHammerController) then
        return controller, Capabilities.Source.CONTROLLER, true
    end
    -- The reference dump's compatibility AbilityController has a canUseAbility stub that always
    -- returns true. A controller we cannot positively tie to the live Knit graph is usable for a
    -- request fallback, but not authoritative for readiness.
    return controller, Capabilities.Source.FALLBACK, false
end

function Jade:ResolveAbility(hammer)
    local itemType = normalizeItemType(type(hammer) == 'table' and (hammer.itemType or (hammer.tool and hammer.tool.Name)) or tostring(hammer or ''))
    if not self:IsHammerName(itemType) then return nil, {Source = Capabilities.Source.UNKNOWN, Reason = 'not-a-jade-hammer'} end
    local candidates, seen = {}, {}
    local function add(value)
        if type(value) == 'string' and value ~= '' and not seen[value] then seen[value] = true; table.insert(candidates, value) end
    end
    for _, value in ipairs(self.AbilityMap[itemType] or {}) do add(value) end
    if itemType ~= 'jade_hammer_jump' then add(itemType..'_jump') end
    add('jade_hammer_jump')

    local meta = bedwars.ItemMeta and bedwars.ItemMeta[itemType]
    if type(meta) == 'table' then
        for key, value in pairs(meta) do
            local lowered = tostring(key):lower()
            if lowered:find('abil') and type(value) == 'string' then add(value) end
        end
    end

    local controller, source, authoritative = liveAbilityController()
    if controller then
        for _, candidate in ipairs(candidates) do
            local handler
            if type(controller.getAbilityHandler) == 'function' then
                handler = ask('jade.handler.'..candidate, controller.getAbilityHandler, controller, candidate)
            end
            if handler ~= nil then return candidate, {Source = source, Authoritative = authoritative, Handler = handler} end
            for _, field in ipairs({'abilities', 'Abilities', 'handlers', 'abilityHandlers'}) do
                if type(controller[field]) == 'table' and controller[field][candidate] ~= nil then
                    return candidate, {Source = source, Authoritative = authoritative, Handler = controller[field][candidate]}
                end
            end
        end
    end
    return candidates[1], {Source = Capabilities.Source.METADATA, Authoritative = false, Candidates = candidates}
end

function Jade:GetState(ability)
    local controller, source, authoritative = liveAbilityController()
    if controller and type(controller.canUseAbility) == 'function' then
        local ok, ready = pcall(controller.canUseAbility, controller, ability, {disableBlockedAbilityAlert = true})
        if ok and ready == false then
            return 'BLOCKED', {Source = source, Authoritative = authoritative, Reported = ready}
        elseif ok and authoritative then
            return 'READY', {Source = source, Authoritative = true, Reported = ready}
        elseif ok then
            return 'UNKNOWN', {Source = source, Authoritative = false, Reported = ready}
        end
    end
    return 'UNKNOWN', {Source = Capabilities.Source.UNKNOWN, Authoritative = false}
end

function Jade:Equip(hammer, timeout, cancelled)
    if not hammer or not hammer.tool then return false, 'missing-hammer' end
    local held = store.hand
    if held and held.tool == hammer.tool then return true, 'already-held' end
    safe('jade.switch', switchItem, hammer.tool, 0.05)
    local deadline = now() + (timeout or 0.8)
    repeat
        if cancelled and cancelled() then return false, 'cancelled' end
        held = store.hand
        if held and (held.tool == hammer.tool or held.itemType == hammer.itemType) then return true, 'replicated' end
        task.wait(0.03)
    until now() >= deadline
    return false, 'held-tool-not-acknowledged'
end

local function activationSignals(root, humanoid, ability)
    local state, source = Jade:GetState(ability)
    local attrs = {}
    local char = lplr.Character
    if char then
        for name, value in pairs(char:GetAttributes()) do
            local lower = tostring(name):lower()
            if lower:find('jade') or lower:find('hammer') or lower:find('ability') then attrs[name] = value end
        end
    end
    return {
        Position = root and root.Position,
        Velocity = root and root.AssemblyLinearVelocity or Vector3.zero,
        Floor = humanoid and humanoid.FloorMaterial,
        Readiness = state,
        ReadinessInfo = source,
        Attributes = attrs
    }
end

local function attributesChanged(before, after)
    for key, value in pairs(after or {}) do if before[key] ~= value then return true end end
    for key in pairs(before or {}) do if after[key] == nil then return true end end
    return false
end

function Jade:ObserveActivation(before, ability, timeout, cancelled)
    local deadline = now() + (timeout or 1.0)
    repeat
        if cancelled and cancelled() then return false, 'cancelled', nil end
        local root, _, humanoid = rootOfLocal()
        if not root then return false, 'character-lost', nil end
        local current = activationSignals(root, humanoid, ability)
        local moved = before.Position and (root.Position - before.Position).Magnitude > 1.25
        local velocityChanged = (root.AssemblyLinearVelocity - before.Velocity).Magnitude > 12
        local airborne = before.Floor ~= Enum.Material.Air and humanoid.FloorMaterial == Enum.Material.Air
        local cooldown = before.Readiness == 'READY' and current.Readiness == 'BLOCKED'
        local attribute = attributesChanged(before.Attributes, current.Attributes)
        if cooldown or airborne or moved or velocityChanged or attribute then
            return true, cooldown and 'cooldown-transition' or airborne and 'airborne-transition' or attribute and 'attribute-transition' or 'movement-transition', current
        end
        task.wait(0.03)
    until now() >= deadline
    return false, 'cast-not-confirmed', nil
end

function Jade:RequestActivation(hammer, ability, targetPosition, cancelled, options)
    local root, _, humanoid = rootOfLocal()
    if not root then return false, 'no-character' end
    local before = activationSignals(root, humanoid, ability)
    local request = {Sent = false, Paths = {}}

    -- Some live BedWars builds expose Jade through AbilityController rather than the
    -- tool input path. Prefer the real controller when the caller requests it, then
    -- use the existing compatibility paths below only if that request fails.
    local preferredController = type(options) == 'table' and options.PreferAbilityController == true
    if preferredController then
        local controller, source = liveAbilityController()
        if controller and type(controller.useAbility) == 'function' then
            local data = {origin = root.Position, target = targetPosition}
            local token = type(newproxy) == 'function' and newproxy(true) or nil
            local attempts = token and {
                {ability, token, data},
                {ability, data},
                {ability}
            } or {
                {ability, data},
                {ability}
            }
            for _, args in ipairs(attempts) do
                local ok, result = pcall(function()
                    return controller.useAbility(controller, table.unpack(args))
                end)
                table.insert(request.Paths, {
                    Path = 'AbilityController.preferred',
                    OK = ok,
                    Result = result,
                    Source = source
                })
                if ok and result ~= false then
                    request.Sent = true
                    break
                end
            end
        end
    end

    if not request.Sent then
        local controllers = {bedwars.JadeHammerController, bedwars.HammerController, bedwars.ToolController, bedwars.ViewmodelController}
        for _, controller in ipairs(controllers) do
            if controller then
                for _, method in ipairs({'useTool', 'activateTool', 'activate', 'useItem'}) do
                    if type(controller[method]) == 'function' then
                        local ok, result = pcall(controller[method], controller, hammer.tool, targetPosition)
                        table.insert(request.Paths, {Path = method, OK = ok, Result = result})
                        if ok and result ~= false then request.Sent = true; break end
                    end
                end
            end
            if request.Sent then break end
        end
    end

    if not request.Sent and hammer.tool and type(hammer.tool.Activate) == 'function' then
        local ok = pcall(hammer.tool.Activate, hammer.tool)
        table.insert(request.Paths, {Path = 'Tool.Activate', OK = ok})
        request.Sent = ok
    end

    if not request.Sent and inputService then
        local ok = pcall(function()
            local vim = game:GetService('VirtualInputManager')
            local center = gameCamera.ViewportSize / 2
            vim:SendMouseButtonEvent(center.X, center.Y, 0, true, game, 0)
            vim:SendMouseButtonEvent(center.X, center.Y, 0, false, game, 0)
        end)
        table.insert(request.Paths, {Path = 'VirtualInput', OK = ok})
        request.Sent = ok
    end

    -- Direct ability use is a compatibility request path, never success proof. Only use it when
    -- the live controller exists; the dump fallback is not allowed to manufacture authority.
    local controller, source, authoritative = liveAbilityController()
    if not request.Sent and controller and authoritative and type(controller.useAbility) == 'function' then
        local ok, result = pcall(controller.useAbility, controller, ability)
        table.insert(request.Paths, {Path = 'AbilityController.useAbility', OK = ok, Result = result, Source = source})
        request.Sent = ok and result ~= false
    end

    self.Last.Request = request
    if not request.Sent then return false, 'no-activation-path', request end
    local confirmed, reason, signal = self:ObserveActivation(before, ability, 1.1, cancelled)
    self.Last.Confirmation = {Confirmed = confirmed, Reason = reason, Signal = signal}
    return confirmed, reason, request
end

function Jade:GetCooldownState(ability)
    return self:GetState(ability)
end

function Jade:ActivateForTraversal(owner, direction, cancelled)
    local hammer = self:GetBestHammer()
    if not hammer then return {confirmed = false, reason = 'missing-hammer'} end
    local ability, abilityInfo = self:ResolveAbility(hammer)
    local ready, readyInfo = self:GetState(ability)
    if ready == 'BLOCKED' then return {confirmed = false, reason = 'cooldown', ability = ability, readiness = ready, readinessInfo = readyInfo} end
    local lease, leaseReason = Movement:Acquire(owner or 'LongJump', Movement.Priorities.Ability, 3, nil, true)
    if not lease then return {confirmed = false, reason = leaseReason} end
    local equipped, equipReason = self:Equip(hammer, 0.8, cancelled)
    if not equipped then lease:Release(); return {confirmed = false, reason = equipReason} end
    local root = rootOfLocal()
    local target = root and (root.Position + (direction or root.CFrame.LookVector) * 20) or nil
    local confirmed, reason = self:RequestActivation(hammer, ability, target, cancelled)
    task.delay(3, function() lease:Release() end)
    return {confirmed = confirmed, reason = reason, hammer = hammer, ability = ability, abilityInfo = abilityInfo, readiness = ready, readinessInfo = readyInfo, lease = lease}
end

--------------------------------------------------------------------------------
-- WorldSnapshot
--------------------------------------------------------------------------------
local WorldSnapshot = {}
WorldSnapshot.__index = WorldSnapshot
Runtime.WorldSnapshot = WorldSnapshot

function WorldSnapshot.new(owner)
    local self = setmetatable({}, WorldSnapshot)
    self.Owner = owner
    self.Version = 0
    self.DynamicAt = 0
    self.WorldAt = 0
    self.WorldDirty = true
    self.Signature = ''
    self.Beds = {}
    self.Generators = {}
    self.Shops = {}
    self.Enemies = {}
    self.Connections = {}
    local function dirty() self.WorldDirty = true end
    safe('snapshot.bed.add', function() table.insert(self.Connections, collectionService:GetInstanceAddedSignal('bed'):Connect(dirty)) end)
    safe('snapshot.bed.remove', function() table.insert(self.Connections, collectionService:GetInstanceRemovedSignal('bed'):Connect(dirty)) end)
    safe('snapshot.gen.add', function() table.insert(self.Connections, collectionService:GetInstanceAddedSignal('Generator'):Connect(dirty)) end)
    safe('snapshot.gen.remove', function() table.insert(self.Connections, collectionService:GetInstanceRemovedSignal('Generator'):Connect(dirty)) end)
    return self
end

function WorldSnapshot:Destroy()
    for _, connection in ipairs(self.Connections) do safe('snapshot.disconnect', connection.Disconnect, connection) end
    table.clear(self.Connections)
end

function WorldSnapshot:_refreshWorld()
    table.clear(self.Beds)
    local team = self.Team
    for _, bed in ipairs(collectionService:GetTagged('bed')) do
        local part = bed.Parent and partOf(bed) or nil
        if part then
            local own = team ~= nil and bed:GetAttribute('Team'..team..'NoBreak') and true or false
            table.insert(self.Beds, {
                Object = bed, Part = part, Position = part.Position, Own = own,
                Shielded = (bed:GetAttribute('BedShieldEndTime') or 0) > workspace:GetServerTimeNow()
            })
        end
    end
    table.clear(self.Generators)
    for _, object in ipairs(collectionService:GetTagged('Generator')) do
        local part = object.Parent and partOf(object) or nil
        if part then
            local id = tostring(object:GetAttribute('Id') or ''):lower()
            table.insert(self.Generators, {Object = object, Part = part, Position = part.Position, Kind = id:find('emerald') and 'emerald' or id:find('diamond') and 'diamond' or 'iron'})
        end
    end
    table.clear(self.Shops)
    for _, entry in pairs(store.shop or {}) do
        local part = entry.RootPart and partOf(entry.RootPart) or nil
        if entry.Shop and part then table.insert(self.Shops, {Entry = entry, Position = part.Position, Id = entry.Id}) end
    end
    self.WorldDirty = false
    self.WorldAt = now()
end

local function armourTier()
    local ladder = {'leather_chestplate', 'iron_chestplate', 'diamond_chestplate', 'emerald_chestplate'}
    local best = 0
    local inv = store.inventory and store.inventory.inventory
    for _, entry in pairs((inv and inv.armor) or {}) do
        if entry and entry ~= 'empty' and entry.itemType then best = math.max(best, table.find(ladder, entry.itemType) or 0) end
    end
    if best == 0 and getBestArmor then
        local item = ask('snapshot.bestArmor', getBestArmor, 1)
        if item and item.itemType then best = table.find(ladder, item.itemType) or 0 end
    end
    return best
end

local function blockInventory()
    local inv = store.inventory and store.inventory.inventory
    local bestName, total = nil, 0
    for _, item in pairs((inv and inv.items) or {}) do
        local meta = bedwars.ItemMeta and bedwars.ItemMeta[item.itemType]
        if meta and meta.block and not tostring(item.itemType):find('tnt') and not tostring(item.itemType):find('cannon') and not tostring(item.itemType):find('bed') then
            total += item.amount or 0
            bestName = bestName or item.itemType
        end
    end
    return total, bestName
end

function WorldSnapshot:Refresh(force)
    local t = now()
    if not force and t - self.DynamicAt < 0.12 then return self end
    self.DynamicAt = t
    self.MatchState, self.MatchSource = Capabilities.Match:GetState()
    self.Team, self.TeamSource = Capabilities.Match:GetTeam()
    self.Map = store.map
    self.Queue = store.queueType
    self.Kit = Capabilities.Kits:GetEquipped()
    self.Root, self.Character, self.Humanoid = rootOfLocal()
    self.Alive = self.Root ~= nil
    self.Position = self.Root and self.Root.Position or nil
    local health = self.Character and self.Character.Health or 0
    local maxHealth = self.Character and self.Character.MaxHealth or 100
    self.Health = health
    self.HealthFraction = maxHealth > 0 and math.clamp(health / maxHealth, 0, 1) or 0
    self.Inventory = (store.inventory and store.inventory.inventory) or {items = {}, armor = {}}
    self.Hotbar = store.inventory and store.inventory.hotbar or {}
    self.Held = store.hand
    self.Iron = itemCount('iron')
    self.Diamond = itemCount('diamond')
    self.Emerald = itemCount('emerald')
    self.Blocks, self.BlockItem = blockInventory()
    self.ArmorTier = armourTier()

    if self.WorldDirty or t - self.WorldAt > 0.8 then self:_refreshWorld() end
    self.OwnBedAlive = false
    self.EnemyBeds = {}
    for _, bed in ipairs(self.Beds) do
        if bed.Own then self.OwnBedAlive = true else table.insert(self.EnemyBeds, bed) end
    end
    self.LastLife = self.Team ~= nil and not self.OwnBedAlive

    table.clear(self.Enemies)
    for _, ent in ipairs(entitylib.List or {}) do
        local root = ent.RootPart
        local sameTeam = ent.Player and self.Team ~= nil and ent.Player:GetAttribute('Team') == self.Team
        if ent.Targetable and root and root.Parent and not sameTeam and (not ent.Health or ent.Health > 0) then
            table.insert(self.Enemies, ent)
        end
    end
    table.sort(self.Enemies, function(a, b)
        if not self.Position then return false end
        return (a.RootPart.Position - self.Position).Magnitude < (b.RootPart.Position - self.Position).Magnitude
    end)
    self.NearbyThreat = self.Enemies[1]
    self.NearbyThreatDistance = self.NearbyThreat and self.Position and (self.NearbyThreat.RootPart.Position - self.Position).Magnitude or math.huge
    self.MovementOwner = Movement:GetOwner() or Movement:GetExternalOwner('AutoWin')

    local signature = table.concat({tostring(self.MatchState), tostring(self.Team), tostring(self.OwnBedAlive), tostring(#self.EnemyBeds), tostring(self.Alive), tostring(self.Blocks), tostring(self.ArmorTier), tostring(#self.Enemies)}, ':')
    if signature ~= self.Signature then self.Signature = signature; self.Version += 1 end
    return self
end

--------------------------------------------------------------------------------
-- Failure memory
--------------------------------------------------------------------------------
local FailureMemory = {}
FailureMemory.__index = FailureMemory
Runtime.FailureMemory = FailureMemory
function FailureMemory.new() return setmetatable({Entries = {}}, FailureMemory) end
function FailureMemory:_key(objective, action, route)
    return table.concat({objective or '?', action or '?', route or '?'}, '|')
end
function FailureMemory:Record(objective, action, route, reason, worldVersion)
    local key = self:_key(objective, action, route)
    local entry = self.Entries[key] or {Count = 0, First = now()}
    entry.Count += 1; entry.Last = now(); entry.Reason = reason; entry.WorldVersion = worldVersion
    entry.Cooldown = math.min(2 ^ math.min(entry.Count, 5), 30)
    self.Entries[key] = entry
    return entry
end
function FailureMemory:Penalty(objective, action, route, worldVersion)
    local entry = self.Entries[self:_key(objective, action, route)]
    if not entry then return 0 end
    if worldVersion and entry.WorldVersion and worldVersion - entry.WorldVersion >= 3 then return math.max(0, entry.Count - 2) * 4 end
    if now() - entry.Last > (entry.Cooldown or 0) then return math.max(0, entry.Count - 1) * 6 end
    return entry.Count * 18
end
function FailureMemory:ClearStale(worldVersion)
    for key, entry in pairs(self.Entries) do
        if now() - entry.Last > 120 or (worldVersion and entry.WorldVersion and worldVersion - entry.WorldVersion > 8) then self.Entries[key] = nil end
    end
end

--------------------------------------------------------------------------------
-- Hierarchical Navigation V2
--------------------------------------------------------------------------------
local Navigation = {}
Navigation.__index = Navigation
Runtime.Navigation = Navigation
local CELL = 3
local STAND = 1.5
local HEAD = {Vector3.new(0, 1, 0), Vector3.new(0, 2, 0)}
local DIRS = {Vector3.new(1,0,0), Vector3.new(-1,0,0), Vector3.new(0,0,1), Vector3.new(0,0,-1)}
local DROPS = {0, -1, 1, -2, -3}

function Navigation.new(snapshot)
    return setmetatable({Snapshot = snapshot, Cache = {}, Recalculations = 0, Expansions = 0, Solid = {}, SolidAt = 0}, Navigation)
end
function Navigation:Cell(pos) return bedwars.BlockController:getBlockPosition(pos) end
function Navigation:World(cell) return cell * CELL end
function Navigation:ClearLocalCache() table.clear(self.Solid); self.SolidAt = now() end
function Navigation:SolidAt(cell)
    if now() - self.SolidAt > 0.35 then self:ClearLocalCache() end
    local key = string.format('%d,%d,%d', cell.X, cell.Y, cell.Z)
    if self.Solid[key] ~= nil then return self.Solid[key] end
    local world = self:World(cell)
    local solid = getPlacedBlock(world) ~= nil
    if not solid then
        local params = RaycastParams.new(); params.FilterType = Enum.RaycastFilterType.Exclude; params.RespectCanCollide = true
        params.FilterDescendantsInstances = {lplr.Character, gameCamera}
        solid = workspace:Raycast(world + Vector3.new(0,1.4,0), Vector3.new(0,-2.8,0), params) ~= nil
    end
    self.Solid[key] = solid
    return solid
end

local function heapPush(heap, node, score)
    local i = #heap + 1; heap[i] = {Node = node, Score = score}
    while i > 1 do local p = math.floor(i/2); if heap[p].Score <= heap[i].Score then break end; heap[p], heap[i] = heap[i], heap[p]; i = p end
end
local function heapPop(heap)
    if #heap == 0 then return nil end
    local top = heap[1]; heap[1] = heap[#heap]; heap[#heap] = nil
    local i = 1
    while true do
        local l, r, s = i*2, i*2+1, i
        if l <= #heap and heap[l].Score < heap[s].Score then s = l end
        if r <= #heap and heap[r].Score < heap[s].Score then s = r end
        if s == i then break end
        heap[i], heap[s] = heap[s], heap[i]; i = s
    end
    return top.Node
end
local function cellKey(cell) return string.format('%d,%d,%d', cell.X, cell.Y, cell.Z) end
local function heuristic(a,b) return math.abs(a.X-b.X)+math.abs(a.Z-b.Z)+math.abs(a.Y-b.Y)*1.35 end

function Navigation:_localPlan(fromPos, toPos, allowPlace, allowBreak, cancelled)
    self:ClearLocalCache()
    local startCell = self:Cell(Vector3.new(fromPos.X, fromPos.Y - STAND, fromPos.Z))
    local goalCell = self:Cell(Vector3.new(toPos.X, toPos.Y - STAND, toPos.Z))
    local open, came, g, closed = {}, {}, {}, {}
    local startKey = cellKey(startCell); g[startKey] = 0; heapPush(open, startCell, heuristic(startCell, goalCell))
    local best, bestH = startCell, heuristic(startCell, goalCell)
    local budget = math.clamp(450 + bestH * 18, 700, 3500)
    local expansions = 0
    while true do
        local current = heapPop(open); if not current then break end
        local key = cellKey(current)
        if not closed[key] then
            closed[key] = true; expansions += 1
            local h = heuristic(current, goalCell)
            if h < bestH then best, bestH = current, h end
            if h <= 0.5 or expansions >= budget then break end
            if expansions % 250 == 0 then task.wait(); if cancelled and cancelled() then return nil, expansions end end
            local base = g[key] or 0
            for _, dir in ipairs(DIRS) do
                for _, dy in ipairs(DROPS) do
                    local n = current + dir + Vector3.new(0,dy,0); local nk = cellKey(n)
                    if not closed[nk] and heuristic(n, goalCell) < bestH + 80 then
                        local bridge = not self:SolidAt(n)
                        if not bridge or (allowPlace and dy == 0) then
                            local blocked, mine = false, 0
                            for _, off in ipairs(HEAD) do
                                local head = n + off
                                if self:SolidAt(head) then
                                    if allowBreak and getPlacedBlock(self:World(head)) then mine += 1 else blocked = true end
                                end
                            end
                            if not blocked then
                                local cost = base + 1 + (bridge and 2.0 or 0) + mine*2.4 + math.abs(dy)*0.5
                                if cost < (g[nk] or math.huge) then g[nk] = cost; came[nk] = current; heapPush(open,n,cost+heuristic(n,goalCell)) end
                            end
                        end
                    end
                end
            end
            if allowPlace then
                local n = current + Vector3.new(0,1,0); local nk = cellKey(n)
                if not closed[nk] then
                    local cost = base + 4
                    if cost < (g[nk] or math.huge) then g[nk] = cost; came[nk] = current; heapPush(open,n,cost+heuristic(n,goalCell)) end
                end
            end
        end
    end
    self.Expansions = expansions
    local cells, cursor, guard = {}, best, 0
    while cursor and cellKey(cursor) ~= startKey and guard < 512 do table.insert(cells,1,cursor); cursor = came[cellKey(cursor)]; guard += 1 end
    return cells, expansions
end

local function groundScore(a,b)
    local distance = ((b-a)*Vector3.new(1,0,1)).Magnitude
    return distance + math.abs(b.Y-a.Y)*0.7
end

function Navigation:_strategicAnchors(snapshot, goal)
    local nodes = {{Kind='Start', Position=snapshot.Position}, {Kind='Goal', Position=goal}}
    for _, gen in ipairs(snapshot.Generators) do if gen.Kind ~= 'iron' then table.insert(nodes,{Kind='Generator',Position=gen.Position,Object=gen.Object}) end end
    for _, shop in ipairs(snapshot.Shops) do table.insert(nodes,{Kind='Shop',Position=shop.Position,Object=shop.Entry}) end
    for _, bed in ipairs(snapshot.Beds) do table.insert(nodes,{Kind=bed.Own and 'HomeBase' or 'EnemyBase',Position=bed.Position,Object=bed.Object}) end
    return nodes
end

function Navigation:_strategicPath(snapshot, goal)
    local nodes = self:_strategicAnchors(snapshot, goal)
    if #nodes <= 2 then return {nodes[1], nodes[2]} end
    local dist, prev, unvisited = {[1]=0}, {}, {}
    for i=1,#nodes do unvisited[i]=true end
    while true do
        local best, bestD
        for i in pairs(unvisited) do local d=dist[i] or math.huge; if not bestD or d<bestD then best,bestD=i,d end end
        if not best or best==2 then break end
        unvisited[best]=nil
        for j in pairs(unvisited) do
            local direct=(nodes[j].Position-nodes[best].Position).Magnitude
            if direct <= 135 or j==2 then
                local cost=bestD+groundScore(nodes[best].Position,nodes[j].Position)+(direct>90 and 18 or 0)
                if cost<(dist[j] or math.huge) then dist[j]=cost; prev[j]=best end
            end
        end
    end
    local ids={2}; local cursor=2; local guard=0
    while cursor~=1 and prev[cursor] and guard<32 do cursor=prev[cursor]; table.insert(ids,1,cursor); guard+=1 end
    if ids[1]~=1 then return {nodes[1],nodes[2]} end
    local path={}; for _,id in ipairs(ids) do table.insert(path,nodes[id]) end; return path
end

local function segmentKind(nav, previous, cell, allowBreak)
    if not nav:SolidAt(cell) then return 'Bridge' end
    if previous and cell.Y > previous.Y then return 'Climb' end
    if allowBreak then
        for _, off in ipairs(HEAD) do if getPlacedBlock(nav:World(cell+off)) then return 'Mine' end end
    end
    return 'Walk'
end

function Navigation:Plan(snapshot, goal, objective, allowBreak, cancelled)
    if not snapshot.Position or not goal then return nil, 'missing-position' end
    self.Recalculations += 1
    local strategic = self:_strategicPath(snapshot, goal)
    local route = {Objective=objective, Target=goal, Strategic=strategic, Segments={}, RequiredBlocks=0, ExpectedMining=0, Distance=0, ExpectedTime=0, Risk=0, Cost=0, WorldVersion=snapshot.Version, Recalculation=self.Recalculations, Expansions=0}
    local from = snapshot.Position
    for index=2,#strategic do
        local to = strategic[index].Position
        local cells, expansions = self:_localPlan(from,to,true,allowBreak,cancelled)
        route.Expansions += expansions or 0
        if not cells or #cells==0 then
            table.insert(route.Segments,{Kind='Wait',From=from,To=to,Reason='partial-route'}); route.Risk += 20
        else
            local previous = self:Cell(Vector3.new(from.X,from.Y-STAND,from.Z))
            local currentSegment
            for _,cell in ipairs(cells) do
                local kind=segmentKind(self,previous,cell,allowBreak)
                if not currentSegment or currentSegment.Kind~=kind then currentSegment={Kind=kind,Cells={}}; table.insert(route.Segments,currentSegment) end
                table.insert(currentSegment.Cells,cell)
                if kind=='Bridge' then route.RequiredBlocks += 1; route.Risk += 0.6 elseif kind=='Mine' then route.ExpectedMining += 1 end
                route.Distance += CELL; previous=cell
            end
        end
        from=to
    end
    route.RequiredBlocks += route.RequiredBlocks > 0 and 8 or 0
    route.ExpectedTime = route.Distance/16 + route.RequiredBlocks*0.08 + route.ExpectedMining*0.35
    route.Cost = route.ExpectedTime + route.Risk
    return route
end

--------------------------------------------------------------------------------
-- Loadout planner
--------------------------------------------------------------------------------
local LoadoutPlanner = {}
LoadoutPlanner.__index = LoadoutPlanner
Runtime.LoadoutPlanner = LoadoutPlanner
function LoadoutPlanner.new() return setmetatable({},LoadoutPlanner) end
function LoadoutPlanner:Evaluate(snapshot, route)
    local result={RequiredBlocks=route and route.RequiredBlocks or 8, Deficits={}, Purchases={}}
    result.RequiredBlocks=math.max(result.RequiredBlocks,8)
    if snapshot.Blocks<result.RequiredBlocks then result.Deficits.Blocks=result.RequiredBlocks-snapshot.Blocks end
    local desiredArmor=snapshot.LastLife and 2 or 1
    if snapshot.ArmorTier<desiredArmor then result.Deficits.Armor=desiredArmor-snapshot.ArmorTier end
    if result.Deficits.Blocks then table.insert(result.Purchases,{Kind='Blocks',Item='wool_white',Priority=100}) end
    local armour={'leather_chestplate','iron_chestplate','diamond_chestplate','emerald_chestplate'}
    if result.Deficits.Armor then table.insert(result.Purchases,{Kind='Armor',Item=armour[snapshot.ArmorTier+1],Priority=90}) end
    local tool=store.tools and store.tools.pickaxe
    if route and route.ExpectedMining>0 and not tool then table.insert(result.Purchases,{Kind='Tool',Item='wood_pickaxe',Priority=80}) end
    table.sort(result.Purchases,function(a,b)return a.Priority>b.Priority end)
    local ironNeed=0
    for _,purchase in ipairs(result.Purchases) do
        local item=Capabilities.Shop:GetItem(purchase.Item)
        if item and item.currency=='iron' then ironNeed+=item.price or 0 end
    end
    result.IronDeficit=math.max(ironNeed-snapshot.Iron,0)
    return result
end

--------------------------------------------------------------------------------
-- Action scheduler
--------------------------------------------------------------------------------
local ActionState={RUNNING='RUNNING',SUCCESS='SUCCESS',FAILED='FAILED',CANCELLED='CANCELLED',BLOCKED='BLOCKED'}
Runtime.ActionState=ActionState
local function action(kind,data)
    local a={Kind=kind,Data=data or {},State=ActionState.RUNNING,Started=now(),Reason=nil,Cancelled=false,ProgressAt=now()}
    function a:Cancel(reason) self.Cancelled=true; self.State=ActionState.CANCELLED; self.Reason=reason or 'cancelled' end
    function a:Finish(state,reason) self.State=state; self.Reason=reason; return state,reason end
    return a
end

local TravelAction={}
function TravelAction.new(director,objective,route)
    local a=action('Travel',{Objective=objective,Route=route,Segment=1,Cell=1,Best=math.huge,StallAt=now(),Lease=nil})
    return setmetatable(a,{__index=TravelAction})
end
function TravelAction:Cleanup()
    if self.Data.Lease then self.Data.Lease:Release(); self.Data.Lease=nil end
    local _,char=rootOfLocal(); if char and char.Humanoid then safe('travel.stop',char.Humanoid.Move,char.Humanoid,Vector3.zero,false) end
end
function TravelAction:Cancel(reason) self.Cancelled=true; self.State=ActionState.CANCELLED; self.Reason=reason; self:Cleanup() end
function TravelAction:Tick(director,snapshot)
    if self.Cancelled then return self.State,self.Reason end
    local route=self.Data.Route
    local goal=self.Data.Objective.Position
    if not snapshot.Alive or not goal then self:Cleanup(); return self:Finish(ActionState.CANCELLED,'character-or-target-lost') end
    if (snapshot.Position-goal).Magnitude <= (self.Data.Objective.StopRange or 8) then self:Cleanup(); return self:Finish(ActionState.SUCCESS,'arrived') end
    if snapshot.Version-route.WorldVersion>=4 then self:Cleanup(); return self:Finish(ActionState.BLOCKED,'route-stale') end
    if not self.Data.Lease then
        local lease,reason=Movement:Acquire('AutoWin',Movement.Priorities.AutoWin,0.5,function() self:Cancel('movement-preempted') end)
        if not lease then return self:Finish(ActionState.BLOCKED,reason) end
        self.Data.Lease=lease
    else self.Data.Lease:Renew(0.5) end
    local segment=route.Segments[self.Data.Segment]
    if not segment then self:Cleanup(); return self:Finish(ActionState.BLOCKED,'route-exhausted') end
    if segment.Kind=='Wait' then self:Cleanup(); return self:Finish(ActionState.BLOCKED,segment.Reason or 'route-wait') end
    local cell=segment.Cells and segment.Cells[self.Data.Cell]
    if not cell then self.Data.Segment+=1; self.Data.Cell=1; return ActionState.RUNNING end
    local root,char,humanoid=rootOfLocal(); if not root or not humanoid then self:Cleanup(); return self:Finish(ActionState.CANCELLED,'character-lost') end
    if segment.Kind=='Bridge' and not director.Navigation:SolidAt(cell) then
        if snapshot.Blocks<=0 or not snapshot.BlockItem then self:Cleanup(); return self:Finish(ActionState.BLOCKED,'no-blocks') end
        Capabilities.Blocks:Place(director.Navigation:World(cell),snapshot.BlockItem); director.Navigation:ClearLocalCache(); return ActionState.RUNNING
    elseif segment.Kind=='Mine' then
        for _,off in ipairs(HEAD) do local block=getPlacedBlock(director.Navigation:World(cell+off)); if block then Capabilities.Blocks:Break(block); director.Navigation:ClearLocalCache(); return ActionState.RUNNING end end
    elseif segment.Kind=='Climb' and humanoid.FloorMaterial~=Enum.Material.Air then
        safe('travel.jump',humanoid.ChangeState,humanoid,Enum.HumanoidStateType.Jumping)
    end
    local aim=director.Navigation:World(cell)+Vector3.new(0,(char.HipHeight or 2)+STAND,0)
    local delta=(aim-root.Position)*Vector3.new(1,0,1)
    if delta.Magnitude<1.7 then self.Data.Cell+=1; self.ProgressAt=now(); return ActionState.RUNNING end
    safe('travel.move',humanoid.Move,humanoid,delta.Unit,false)
    local distance=(goal-root.Position).Magnitude
    if distance<self.Data.Best-1 then self.Data.Best=distance; self.Data.StallAt=now(); self.ProgressAt=now() elseif now()-self.Data.StallAt>5 then self:Cleanup(); return self:Finish(ActionState.FAILED,'segment-stalled') end
    return ActionState.RUNNING
end

local BreakBedAction={}
function BreakBedAction.new(objective) return setmetatable(action('BreakBed',{Objective=objective,LastHit=0}),{__index=BreakBedAction}) end
function BreakBedAction:Tick(director,snapshot)
    local bed=self.Data.Objective.Target
    if not bed or not bed.Parent or not partOf(bed) then return self:Finish(ActionState.SUCCESS,'bed-gone') end
    local part=partOf(bed); if not snapshot.Position or (part.Position-snapshot.Position).Magnitude>28 then return self:Finish(ActionState.BLOCKED,'bed-out-of-range') end
    if (bed:GetAttribute('BedShieldEndTime') or 0)>workspace:GetServerTimeNow() then return self:Finish(ActionState.BLOCKED,'bed-shield') end
    if now()-self.Data.LastHit>=0.22 then self.Data.LastHit=now(); safe('autowin.breakbed',safeBreakBlock,part,true,true,nil,true,breakmethods.Distance,360,false); self.ProgressAt=now() end
    return ActionState.RUNNING
end

local CombatAction={}
function CombatAction.new(objective) return setmetatable(action('Combat',{Objective=objective,Aura=nil,Travel=nil,LastSeen=now()}),{__index=CombatAction}) end
function CombatAction:Cleanup() if self.Data.Aura then self.Data.Aura:Release(); self.Data.Aura=nil end; if self.Data.Travel then self.Data.Travel:Cancel('combat-cleanup'); self.Data.Travel=nil end end
function CombatAction:Cancel(reason) self.Cancelled=true;self.State=ActionState.CANCELLED;self.Reason=reason;self:Cleanup() end
function CombatAction:Tick(director,snapshot)
    local ent=self.Data.Objective.Target
    if not ent or not ent.RootPart or not ent.RootPart.Parent or (ent.Health and ent.Health<=0) then self:Cleanup();return self:Finish(ActionState.SUCCESS,'target-gone') end
    if snapshot.LastLife and snapshot.HealthFraction<0.38 then self:Cleanup();return self:Finish(ActionState.BLOCKED,'low-health-last-life') end
    local distance=(ent.RootPart.Position-snapshot.Position).Magnitude
