run(function()
    vape.Categories.World:CreateModule({
        Name = 'Anti-AFK',
        Function = function(callback)
            if callback then
                for _, v in getconnections(lplr.Idled) do
                    v:Disconnect()
                end

                for _, v in getconnections(runService.Heartbeat) do
                    if type(v.Function) == 'function' and table.find(debug.getconstants(v.Function), remotes.AfkStatus) then
                        v:Disconnect()
                    end
                end

                bedwars.Client:Get(remotes.AfkStatus):SendToServer({
                    afk = false
                })
            end
        end,
        Tooltip = 'Lets you stay ingame without getting kicked'
    })
end)

run(function()
    local AutoSuffocate
    local Range
    local LimitItem

    local function fixPosition(pos)
        return bedwars.BlockController:getBlockPosition(pos) * 3
    end

    AutoSuffocate = vape.Categories.World:CreateModule({
        Name = 'AutoSuffocate',
        Function = function(callback)
            if callback then
                repeat
                    local item = store.hand.toolType == 'block' and store.hand.tool.Name or not LimitItem.Enabled and getWool()

                    if item then
                        local plrs = entitylib.AllPosition({
                            Part = 'RootPart',
                            Range = Range.Value,
                            Players = true
                        })

                        for _, ent in plrs do
                            local needPlaced = {}

                            for _, side in Enum.NormalId:GetEnumItems() do
                                side = Vector3.fromNormalId(side)
                                if side.Y ~= 0 then continue end

                                side = fixPosition(ent.RootPart.Position + side * 2)
                                if not getPlacedBlock(side) then
                                    table.insert(needPlaced, side)
                                end
                            end

                            if #needPlaced < 3 then
                                table.insert(needPlaced, fixPosition(ent.Head.Position))
                                table.insert(needPlaced, fixPosition(ent.RootPart.Position - Vector3.new(0, 1, 0)))

                                for _, pos in needPlaced do
                                    if not getPlacedBlock(pos) then
                                        task.spawn(bedwars.placeBlock, pos, item)
                                        break
                                    end
                                end
                            end
                        end
                    end

                    task.wait(0.09)
                until not AutoSuffocate.Enabled
            end
        end,
        Tooltip = 'Places blocks on nearby confined entities'
    })
    Range = AutoSuffocate:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 20,
        Default = 20,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    LimitItem = AutoSuffocate:CreateToggle({
        Name = 'Limit to Items',
        Default = true
    })
end)

run(function()
    local AutoTool
    local old, event

    local function switchHotbarItem(block)
        if block and not block:GetAttribute('NoBreak') and not block:GetAttribute('Team'..(lplr:GetAttribute('Team') or 0)..'NoBreak') then
            local tool, slot = getBreakTool(bedwars.ItemMeta[block.Name].block.breakType), nil
            if tool then
                for i, v in store.inventory.hotbar do
                    if v.item and v.item.itemType == tool.itemType then slot = i - 1 break end
                end

                if hotbarSwitch(slot) then
                    if inputService:IsMouseButtonPressed(0) then
                        event:Fire()
                    end
                    return true
                end
            end
        end
    end

    AutoTool = vape.Categories.World:CreateModule({
        Name = 'AutoTool',
        Function = function(callback)
            if callback then
                event = Instance.new('BindableEvent')
                AutoTool:Clean(event)
                AutoTool:Clean(event.Event:Connect(function()
                    contextActionService:CallFunction('block-break', Enum.UserInputState.Begin, newproxy(true))
                end))
                old = bedwars.BlockBreaker.hitBlock
                bedwars.BlockBreaker.hitBlock = function(self, maid, raycastparams, ...)
                    local block = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = raycastparams})
                    if switchHotbarItem(block and block.target and block.target.blockInstance or nil) then return end
                    return old(self, maid, raycastparams, ...)
                end
            else
                bedwars.BlockBreaker.hitBlock = old
                old = nil
            end
        end,
        Tooltip = 'Automatically selects the correct tool'
    })
end)

run(function()
    local BedAssist
    local AimMode
    local Speed
    local Range
    local Shake
    local Angle
    local Sort
    local Mode
    local Limit

    local function ease(t)
        return t < 0.5 and 4 * t * t * t or 1 - math.pow(-2 * t + 2, 3) / 2
    end

    local started = 0
    local aimfuncs = {
        Simple = function(localcframe, pos, fps)
            local rng = Random.new()
            return localcframe:Lerp(
                CFrame.lookAt(
                    localcframe.p,
                    pos
                        + Vector3.new(
                            (rng:NextNumber() - 0.5) * Shake.Value * fps,
                            (rng:NextNumber() - 0.5) * Shake.Value * fps,
                            (rng:NextNumber() - 0.5) * Shake.Value * fps
                        )
                ),
                Speed.Value * fps
            ),
                Speed.Value
        end,
        Adaptive = function(localcframe, pos, fps)
            local prog, rng = ease(math.min((tick() - started) / (1 / (Speed.Value * 0.5)), 1)), Random.new()
            local speed = Speed.Value * prog
            return localcframe:Lerp(CFrame.lookAt(localcframe.p, pos + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
        end
    }

    local function getMousePosition()
        local suc, mouseinfo = pcall(function()
            return bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(0)
        end)

        if suc and mouseinfo then
            if mouseinfo.target and mouseinfo.target.blockRef then
                return mouseinfo.target.blockRef.blockPosition * 3
            end
            if mouseinfo.placementPosition then
                return mouseinfo.placementPosition * 3
            end
        end
        return nil
    end

    local function getBestPosition(block)
        local handler = bedwars.BlockController:getHandlerRegistry():getHandler(block.Name)
        local cost, pos = math.huge, nil
        local mag = 9e9

        local positions = (handler and handler:getContainedPositions(block) or { block.Position / 3 })

        for _, v in positions do
            local dpos, dcost = bedwars.calculateBreakPath(block, v * 3, breakmethods[Sort.Value], Angle.Value, getMousePosition())
            local dmag = dpos and (entitylib.character.RootPart.Position - dpos).Magnitude

            if dpos then
                if dcost < cost or (dcost == cost and dmag < mag) then
                    cost, pos, mag = dcost, dpos, dmag
                end
            end
        end

        if pos and (entitylib.character.RootPart.Position - pos).Magnitude <= Range.Value then
            return pos
        end
        return nil
    end

    BedAssist = vape.Categories.World:CreateModule({
        Name = 'BedAssist',
        Function = function(call)
            if call then
                repeat
                    task.wait()
                until store.matchState ~= 0 or not BedAssist.Enabled
                if not BedAssist.Enabled then
                    return
                end

                local beds = collection('bed', BedAssist, function(tab, obj)
                    task.delay(0, function()
                        if not obj:GetAttribute('Team' .. (lplr:GetAttribute('Team') or -1) .. 'NoBreak') then
                            table.insert(tab, obj)
                        end
                    end)
                end)
                local rng = Random.new()
                local lastbed = nil

                BedAssist:Clean(runService.PostSimulation:Connect(function(dt)
                    if entitylib.isAlive and (not Limit.Enabled or store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name].breakBlock) then
                        local localPosition = entitylib.character.RootPart.Position
                        for _, v in beds do
                            if (localPosition - v.Position).Magnitude <= Range.Value then
                                if lastbed ~= v then
                                    started = tick()
                                end
                                lastbed = v

                                local pos = getBestPosition(v)
                                if pos then
                                    local pred, speed = aimfuncs[AimMode.Value](gameCamera.CFrame, pos, dt)

                                    if Mode.Value == 'Mouse' then
                                        pos += Vector3.new(
                                            (rng:NextNumber() - 0.5) * Shake.Value * 0.1,
                                            (rng:NextNumber() - 0.5) * Shake.Value * 0.1,
                                            (rng:NextNumber() - 0.5) * Shake.Value * 0.1
                                        )
                                        local campos, vis = gameCamera:WorldToViewportPoint(pos)

                                        if vis then
                                            local vec2 = (
                                                Vector2.new(campos.X, campos.Y) - inputService:GetMouseLocation()
                                            ) * (speed * dt)
                                            mousemoverel(vec2.X, vec2.Y)
                                        end
                                    else
                                        gameCamera.CFrame = pred
                                    end
                                end
                                break
                            end
                        end
                    end
                end))
            end
        end,
        Tooltip = 'Smoothly aims towards a bed close to your mouse'
    })

    local list = {'Camera'}
    if inputService.MouseEnabled and mousemoverel then
        table.insert(list, 'Mouse')
    end
    AimMode = BedAssist:CreateDropdown({
        Name = 'Mode',
        List = {'Simple', 'Adaptive'},
        Default = 'Simple',
    })
    Mode = BedAssist:CreateDropdown({
        Name = 'Aim Mode',
        List = list,
        Default = 'Camera',
    })
    Sort = BedAssist:CreateDropdown({
        Name = 'Target Mode',
        List = {'Distance', 'Health'},
        Default = 'Distance',
    })
    Speed = BedAssist:CreateSlider({
        Name = 'Aim Speed',
        Min = 1,
        Max = 20,
        Default = 7,
    })
    Range = BedAssist:CreateSlider({
        Name = 'Assist Range',
        Min = 1,
        Max = 30,
        Default = 20,
        Suffix = function(val)
            return val <= 1 and 'stud' or 'studs'
        end,
    })
    Shake = BedAssist:CreateSlider({
        Name = 'Shake',
        Min = 1,
        Max = 100,
        Default = 3,
    })
    Angle = BedAssist:CreateSlider({
        Name = 'Max angle',
        Min = 1,
        Max = 360,
        Default = 200,
    })
    Limit = BedAssist:CreateToggle({Name = 'Limit to item', Default = true})
end)

run(function()
    local BedProtector
    local PlaceRange
    local Layers
    local Blacklist
    local Mode
    local Smart
    local Switch
    local WoolOnly
    local LimitItem
    local Template
    local EmergencyKey
    local previewParts = {}
    local templateSpecs = {
        ['Quick Wool'] = {Layers = 1, Wool = true},
        Layered = {Layers = 2, Wool = false},
        Defensive = {Layers = 3, Wool = false},
        ['Anti-Explosive'] = {Layers = 2, Wool = false}
    }

    local function clearPreview()
        for _, part in previewParts do part:Destroy() end
        table.clear(previewParts)
    end

    local function getBedNear()
        local localPosition = entitylib.isAlive and entitylib.character.RootPart.Position or Vector3.zero
        for _, v in collectionService:GetTagged('bed') do
            if (localPosition - v.Position).Magnitude < 14
                and v:GetAttribute('Team' .. (lplr:GetAttribute('Team') or -1) .. 'NoBreak') then
                return v
            end
        end
        return nil
    end

    local function getBlocks()
        local blocks = {}
        for _, item in store.inventory.inventory.items do
            local block = bedwars.ItemMeta[item.itemType].block
            if block and (not Template or Template.Value ~= 'Quick Wool' or item.itemType:find('wool'))
                and not table.find(Blacklist.ListEnabled, item.itemType:find('wool') and 'wool' or item.itemType) then
                table.insert(blocks, { item.itemType, block.health, item.tool })
            end
        end
        table.sort(blocks, function(a, b)
            return a[2] > b[2]
        end)
        return blocks
    end

    -- A BedWars bed is two grid cells long, and its pivot sits on the grid line
    -- between them. roundPos() therefore snapped the whole defence onto a single
    -- (rounded) cell, so the shell was built around half the bed and came out as an
    -- off-centre rectangle that left the other half exposed. Resolve BOTH occupied
    -- cells from the bed's orientation so the onion layers wrap the real footprint.
    local function bedCells(bed)
        local cf, size
        if bed:IsA('BasePart') then
            cf, size = bed.CFrame, bed.Size
        else
            cf = bed:GetPivot()
            local ok, ext = pcall(function() return bed:GetExtentsSize() end)
            size = ok and ext or Vector3.new(3, 3, 6)
        end
        local center = cf.Position
        -- The long horizontal axis is local X (RightVector) or local Z (LookVector),
        -- whichever the bed is 2 blocks along.
        local axis = (size.X >= size.Z) and cf.RightVector or cf.LookVector
        axis = Vector3.new(axis.X, 0, axis.Z)
        axis = axis.Magnitude > 0 and axis.Unit or Vector3.new(1, 0, 0)
        local a = roundPos(center + axis * 1.5)
        local b = roundPos(center - axis * 1.5)
        if a == b then b = roundPos(center - axis * 3) end
        return a, b
    end

    --[[
        Onion‑layer bed protection.

        protected = a set of positions (Vector3) that are already part of the defense.
        Initially contains only the bed position.
        For each layer:
            - Examine every position in the current protected set.
            - For each position, look at all adjacent horizontal positions (N, S, E, W)
              and the position directly above.
            - If an adjacent position is NOT already protected and does NOT contain
              a block placed by another player (or is air), it becomes part of the new layer.
            - After collecting all new positions for this layer, place them all.
            - Then merge them into the protected set.
        This guarantees that each layer is a complete shell surrounding the previous one,
        expands outward by 1 block in every horizontal direction, and increases height
        by exactly 1 block per layer.
    ]]

    --[[
        Bed patcher (replaced with the reference build's routine)

        The onion algorithm above builds a shell. Patching is a different job: the shell is
        already there and has holes in it, and running the builder to fill them re-walks the
        whole structure from the bed outwards every pass.

        Instead, walk the defence the way it was built - one horizontal ring per level, out
        from the bed - and place into any cell of that ring that is empty. Rings are generated
        in the bed's own orientation so the patch lines up with a defence that is not axis
        aligned, and a level whose centre column is missing is skipped entirely: there is no
        ring at a height the defence never reached.
    ]]
    local PATCH_LEVELS = 6

    -- A diamond ring of grid offsets at `radius` cells out and `radius - i` cells up. Taken
    -- from the reference build unchanged, because the order it yields cells in is what makes
    -- the patch fill inwards-out rather than jumping about.
    local function ringOffsets(radius, spacing)
        local offsets = {}
        for i = radius, 0, -1 do
            for j = i, 0, -1 do
                table.insert(offsets, Vector3.new(j, radius - i, i + 1 - j) * spacing)
                table.insert(offsets, Vector3.new(-j, radius - i, i + 1 - j) * spacing)
                table.insert(offsets, Vector3.new(j, radius - i, -(i - j)) * spacing)
                table.insert(offsets, Vector3.new(-j, radius - i, -(i - j)) * spacing)
            end
        end
        return offsets
    end

    -- The single block to patch with: the toughest one that passes the options. 'Limit to
    -- item' means exactly what is in your hand, and nothing at all if that is not a block.
    local function getPatchBlock()
        if LimitItem.Enabled then
            local hand = store.hand
            if not hand or hand.toolType ~= 'block' or not hand.tool then return nil end
            local itemType = hand.tool.Name
            if WoolOnly.Enabled and not itemType:find('wool') then return nil end
            if table.find(Blacklist.ListEnabled, itemType:find('wool') and 'wool' or itemType) then return nil end
            return {itemType, 0, hand.tool}
        end

        local best
        for _, item in store.inventory.inventory.items do
            local meta = bedwars.ItemMeta[item.itemType]
            local block = meta and meta.block
            if not block then continue end
            if WoolOnly.Enabled and not item.itemType:find('wool') then continue end
            if table.find(Blacklist.ListEnabled, item.itemType:find('wool') and 'wool' or item.itemType) then continue end
            if not best or (block.health or 0) > best[2] then
                best = {item.itemType, block.health or 0, item.tool}
            end
        end
        return best
    end

    local function patchBed(bed)
        local bedCFrame = bed:IsA('BasePart') and bed.CFrame or bed:GetPivot()
        -- The two cells the bed itself sits in. A ring passes over them, and asking the server
        -- to build into your own bed is never going to succeed.
        local cellA, cellB = bedCells(bed)

        -- Ring 1 is the shell touching the bed, which is part of any defence, so it is always
        -- worth scanning. Past that, a ring is only walked when the one inside it exists -
        -- otherwise the patcher would march outwards building a defence you never had, which
        -- is the shell builder's job, not this one's.
        --
        -- The reference build gated each ring on there being a block in the column directly
        -- above the bed. That is the first block an opponent breaks, so the moment somebody
        -- actually broke into the defence the patcher stopped repairing it.
        local previousFilled = true
        for level = 1, PATCH_LEVELS do
            if not BedProtector.Enabled or not previousFilled then return end

            local filled = false
            for _, offset in ringOffsets(level, 3) do
                if not BedProtector.Enabled then return end

                local position = (bedCFrame * CFrame.new(offset)).Position
                local cell = roundPos(position)
                if cell == cellA or cell == cellB then continue end
                if getPlacedBlock(position) then
                    filled = true
                    continue
                end

                if not entitylib.isAlive then return end
                if (entitylib.character.RootPart.Position - position).Magnitude > PlaceRange.Value then continue end

                local block = getPatchBlock()
                if not block then return end

                if Switch.Enabled then
                    local slot = getHotbar(block[3])
                    if slot and hotbarSwitch(slot) then task.wait() end
                end
                task.spawn(bedwars.placeBlock, position, block[1], false)
                filled = true
                task.wait(0.1)
            end
            previousFilled = filled
        end
    end

    BedProtector = vape.Categories.World:CreateModule({
        Name = 'BedProtector',
        Function = function(callback)
            if callback then
                local spec = templateSpecs[Template.Value]
                local estimated = spec and ((spec.Layers * spec.Layers * 16) + 6) or 0
                notif('BedProtector', Template.Value..' needs about '..estimated..' blocks', 5, 'info')
                BedProtector:Clean(inputService.InputBegan:Connect(function(input, processed)
                    if not processed and input.KeyCode.Name == EmergencyKey.Value and BedProtector.Enabled then
                        clearPreview()
                        BedProtector:Toggle()
                        notif('BedProtector', 'Emergency stop', 3, 'warning')
                    end
                end))
                repeat
                    local bed = getBedNear()
                    if bed and Mode.Value == 'Bed patcher' then
                        patchBed(bed)
                    elseif bed then
                        -- Seed the protected set with BOTH grid cells the bed occupies so
                        -- the shell wraps the whole two-block bed instead of half of it.
                        local cellA, cellB = bedCells(bed)
                        local protected = { [cellA] = true, [cellB] = true }

                        for i, block in getBlocks() do
                            local switch, old = Switch.Enabled, store.hand and store.hand.tool and getHotbar(store.hand.tool) or nil
                            local hotbar = switch and getHotbar(block[3]) or nil

                            for layer = 1, Layers.Value do
                                local newPositions = {}

                                -- For every block already in the protected structure...
                                for pos in pairs(protected) do
                                    -- Check all four horizontal directions.
                                    for dx = -3, 3, 3 do
                                        for dz = -3, 3, 3 do
                                            if dx ~= 0 or dz ~= 0 then
                                                local newPos = pos + Vector3.new(dx, 0, dz)
                                                if not protected[newPos] then
                                                    newPositions[newPos] = true
                                                end
                                            end
                                        end
                                    end
                                    -- Also check directly above.
                                    local upPos = pos + Vector3.new(0, 3, 0)
                                    if not protected[upPos] then
                                        newPositions[upPos] = true
                                    end
                                end

                                -- Order this layer's candidates nearest-first. Placing the
                                -- closest reachable blocks immediately removes the long stall
                                -- before the first block went down when the dictionary happened
                                -- to yield far/out-of-range positions first.
                                local ordered = {}
                                for newPos in pairs(newPositions) do
                                    table.insert(ordered, newPos)
                                end
                                local rootPos = entitylib.character.RootPart.Position
                                table.sort(ordered, function(a, b)
                                    return (rootPos - a).Magnitude < (rootPos - b).Magnitude
                                end)

                                -- Place all blocks in this new layer.
                                local placedAny = false
                                for _, newPos in ordered do
                                    if not BedProtector.Enabled then break end
                                    if getPlacedBlock(newPos) then
                                        protected[newPos] = true   -- mark as already protected (block exists)
                                        continue
                                    end
                                    if (entitylib.character.RootPart.Position - newPos).Magnitude > PlaceRange.Value then
                                        continue
                                    end
                                    if hotbar and hotbarSwitch(hotbar) then task.wait() end
                                    task.spawn(bedwars.placeBlock, newPos, block[1], false)
                                    placedAny = true
                                    protected[newPos] = true
                                    task.wait(0.05)
                                end

                                -- Nothing placed this layer means the bed is out of reach, so
                                -- there is no point walking the outer ones.
                                if not placedAny then break end
                                if not BedProtector.Enabled then break end
                            end

                            if switch and old and hotbarSwitch(old) then task.wait() end
                        end
                    else
                        if Mode.Value == 'On Key' then
                            notif('BedProtector', 'Unable to locate bed', 5)
                            BedProtector:Toggle()
                        end
                    end
                    -- Bed patcher re-scans faster so broken blocks are repaired promptly.
                    task.wait(Mode.Value == 'Bed patcher' and 0.2 or 0.5)
                    if Mode.Value == 'On Key' then
                        BedProtector:Toggle()
                        break
                    end
                until not BedProtector.Enabled
            end
            if not callback then clearPreview() end
        end,
        Tooltip = 'Automatically places strong blocks around the bed'
    })

    -- Options. Smart belongs to the shell builder and Wool only / Limit to item belong to the
    -- patcher, so each set follows the Mode dropdown.
    local function syncModeOptions()
        -- The dropdown fires its callback while it is still being created, before Mode itself
        -- has been assigned.
        if not Mode then return end
        if Smart and Smart.Object then Smart.Object.Visible = Mode.Value == 'Toggle' end
        local patching = Mode.Value == 'Bed patcher'
        if WoolOnly and WoolOnly.Object then WoolOnly.Object.Visible = patching end
        if LimitItem and LimitItem.Object then LimitItem.Object.Visible = patching end
    end

    Mode = BedProtector:CreateDropdown({
        Name = 'Mode',
        List = {'Toggle', 'On Key', 'Bed patcher'},
        Default = 'Toggle',
        Tooltip = 'Toggle builds and maintains the shell, On Key builds once, Bed patcher fills in what is missing',
        Function = function()
            syncModeOptions()
        end,
    })
    Template = BedProtector:CreateDropdown({
        Name = 'Template',
        List = {'Quick Wool', 'Layered', 'Defensive', 'Anti-Explosive'},
        Function = function(value)
            local spec = templateSpecs[value]
            if not spec or not Layers then return end
            Layers:SetValue(spec.Layers)
            if WoolOnly then WoolOnly:SetValue(spec.Wool) end
            clearPreview()
            local bed = getBedNear()
            if bed then
                local a, b = bedCells(bed)
                for _, centre in {a, b} do
                    for x = -spec.Layers, spec.Layers do
                        for z = -spec.Layers, spec.Layers do
                            if math.max(math.abs(x), math.abs(z)) ~= spec.Layers then continue end
                            local pos = centre + Vector3.new(x * 3, 0, z * 3)
                            if getPlacedBlock(pos) then continue end
                            local ghost = Instance.new('Part')
                            ghost.Name, ghost.Size, ghost.Position = 'BedProtectorPreview', Vector3.new(3, 3, 3), pos
                            ghost.Anchored, ghost.CanCollide, ghost.CanQuery = true, false, false
                            ghost.Material, ghost.Color, ghost.Transparency = Enum.Material.ForceField, Color3.fromRGB(90, 210, 140), 0.65
                            ghost.Parent = workspace
                            table.insert(previewParts, ghost)
                        end
                    end
                end
                task.delay(5, clearPreview)
            end
        end
    })
    EmergencyKey = BedProtector:CreateDropdown({Name = 'Emergency Stop', List = {'X', 'V', 'B', 'N', 'Delete'}, Default = 'X'})
    Blacklist = BedProtector:CreateTextList({
        Name = 'Blacklist',
        Default = {'siege_tnt', 'tnt'},
    })
    PlaceRange = BedProtector:CreateSlider({
        Name = 'Place Range',
        Min = 1, Max = 30, Default = 15,
    })
    Layers = BedProtector:CreateSlider({
        Name = 'Layers',
        Min = 1, Max = 5, Default = 1,
        Suffix = function(val) return val <= 1 and 'layer' or 'layers' end,
    })
    Switch = BedProtector:CreateToggle({Name = 'Auto Switch'})
    Smart = BedProtector:CreateToggle({Name = 'Smart', Default = true})
    WoolOnly = BedProtector:CreateToggle({
        Name = 'Wool only',
        Tooltip = 'Bed patcher only. Patches holes with wool instead of the toughest block you have'
    })
    LimitItem = BedProtector:CreateToggle({
        Name = 'Limit to item',
        Tooltip = 'Bed patcher only. Patches with the block in your hand and nothing else'
    })
    -- Mode's own callback runs while these two are still nil (it fires as the dropdown is
    -- created), so the first sync happens here instead.
    syncModeOptions()
end)
run(function()
    local BlockIn

    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude

    local BreakSpeed
    local PlaceMode
    local PlaceDelay
    local Bedfinder
    local LimitItem
    local UseBlacklist
    local Blacklist
    local Priority
    local ReturnSlot
    local WoolOnly
    local BedBreak

    local function isBlacklisted(itemType)
	return UseBlacklist and UseBlacklist.Enabled and Blacklist and table.find(Blacklist.ListEnabled, itemType)
    end

    local function getBlocks()
	local blocks = {}

	if LimitItem and LimitItem.Enabled then
		local itemType = store.hand.toolType == 'block' and store.hand.tool and store.hand.tool.Name
		local meta = itemType and bedwars.ItemMeta[itemType]
		local block = meta and meta.block
		if block and not isBlacklisted(itemType) and (store.hand.amount or 0) > 0
			and (not WoolOnly.Enabled or itemType:find('wool')) then
			table.insert(blocks, { itemType, block.health or 0, store.hand.tool, store.hand.amount })
		end
		return blocks
	end

	for _, item in store.inventory.inventory.items do
		local itemType = item.itemType
		local meta = itemType and bedwars.ItemMeta[itemType]
		local block = meta and meta.block
		if block and not isBlacklisted(itemType) and (item.amount or 0) > 0
			and (not WoolOnly.Enabled or itemType:find('wool')) then
			table.insert(blocks, { itemType, block.health or 0, item.tool, item.amount })
		end
	end
	table.sort(blocks, function(a, b)
		return Priority.Value == 'Lowest cost' and a[2] < b[2] or Priority.Value ~= 'Lowest cost' and a[2] > b[2]
	end)
	return blocks
    end

    local function getBed()
	local localPosition = entitylib.isAlive and entitylib.character.RootPart.Position or Vector3.zero
	for _, v in collectionService:GetTagged('bed') do
		if
			not v:GetAttribute('Team' .. (lplr:GetAttribute('Team') or -1) .. 'NoBreak')
			and (localPosition - v.Position).Magnitude <= 30
		then
			return v
		end
	end
	return
    end

    local function getPyramid(protectedDirection)
	local pattern = {
		Vector3.new(3, 0, 0),
		Vector3.new(0, 0, 3),
		Vector3.new(-3, 0, 0),
		Vector3.new(0, 0, -3),
		Vector3.new(3, 3, 0),
		Vector3.new(0, 3, 3),
		Vector3.new(-3, 3, 0),
		Vector3.new(0, 3, -3),
	}

	local rng = Random.new()

	if rng:NextNumber() < 0.95 then
		local extraCount = rng:NextInteger(1, 3)
		for _ = 1, extraCount do
			local dirX = (rng:NextInteger(0, 1) == 1 and 1 or -1)
			local dirZ = (rng:NextInteger(0, 1) == 1 and 1 or -1)
			local y = ({ 0, 3 })[rng:NextInteger(1, 2)]

			local offset = Vector3.new(3 * dirX, y, 3 * dirZ)

			if table.find(pattern, offset) then
				continue
			end
			table.insert(pattern, offset)
		end
	end

	local axis = rng:NextInteger(0, 1) == 1 and 'X' or 'Z'
	local dir = rng:NextInteger(0, 1) == 1 and 1 or -1
	local extraPos = axis == 'X' and Vector3.new(3 * dir, 6, 0) or Vector3.new(0, 6, 3 * dir)
	table.insert(pattern, extraPos)
	table.insert(pattern, Vector3.new(0, 6, 0))

	if protectedDirection then
		for index = #pattern, 1, -1 do
			local flat = pattern[index] * Vector3.new(1, 0, 1)
			if flat.Magnitude > 0 and flat.Unit:Dot(protectedDirection) > 0.65 then table.remove(pattern, index) end
		end
	end
	return pattern
    end

    BlockIn = vape.Categories.World:CreateModule({
	Name = 'BlockIn',
	Function = function(callback)
		if callback then
			local selfpos = entitylib.isAlive and entitylib.character.RootPart.Position or nil
			local previousSlot = store.inventory.hotbarSlot

			if selfpos then
				rayCheck.FilterDescendantsInstances = { lplr.Character, gameCamera }

				if Bedfinder.Enabled and not getBed() then
					notif('BlockIn', 'No bed found', 2, 'warning')
				elseif LimitItem and LimitItem.Enabled and store.hand.toolType ~= 'block' then
					notif('BlockIn', 'Hold a block first', 2, 'warning')
				else
					local oldPlaceCPS = bedwars.SharedConstants.BLOCK_PLACE_CPS
                    local restored = false
                    local function restoreState()
                        if restored then return end
                        restored = true
                        bedwars.SharedConstants.BLOCK_PLACE_CPS = oldPlaceCPS or 12
                        if ReturnSlot.Enabled and previousSlot ~= nil then hotbarSwitch(previousSlot) end
                    end
                    BlockIn:Clean(restoreState)
					bedwars.SharedConstants.BLOCK_PLACE_CPS = math.clamp(20, 1, 20)
					if PlaceMode.Value == 'Smart' then
						local ray
						for _, offset in { Vector3.new(0, -2, 0), Vector3.new(0, 1, 0) } do
							local placement = workspace:Raycast(
								selfpos + offset,
								entitylib.character.RootPart.CFrame.LookVector * 4,
								rayCheck
							)

							if placement and placement.Instance and placement.Instance:IsA('BasePart') then
								local pos = placement.Instance.Position
								local rounded = roundPos(pos)
								local oldSlot = store.hand and store.hand.tool and getHotbar(store.hand.tool)
								ray = placement.Instance:GetPivot().Position

								if bedwars.BlockController:isBlockBreakable({ blockPosition = pos / 3 }, lplr) then
									repeat
										if not entitylib.isAlive then
											break
										end
										task.spawn(bedwars.breakBlock, placement.Instance, false, nil, true, true)
										task.wait(BreakSpeed.Value)
									until not getPlacedBlock(rounded) or not BlockIn.Enabled or not entitylib.isAlive
								end

								if oldSlot then
									hotbarSwitch(oldSlot)
								end

								if BlockIn.Enabled and entitylib.isAlive then
									selfpos = entitylib.character.RootPart.Position
								end
							end
						end
						if ray then
							lplr.Character.Humanoid:MoveTo(Vector3.new(ray.X, selfpos.Y, ray.Z))
							lplr.Character.Humanoid.MoveToFinished:Wait()
							if entitylib.isAlive then
								selfpos = entitylib.character.RootPart.Position
							end
						end
					end

					local blocks = getBlocks()
                    local function currentBreakingDirection()
                        if not BedBreak.Enabled or not entitylib.isAlive or not inputService:IsMouseButtonPressed(0) then return nil end
                        local bed = getBed()
                        local selector = bedwars.BlockBreaker.clientManager:getBlockSelector()
                        local mouseinfo = selector and selector:getMouseInfo(0)
                        local target = mouseinfo and mouseinfo.target and mouseinfo.target.blockRef
                        if not bed or not target or (bed.Position - entitylib.character.RootPart.Position).Magnitude > 14 then return nil end
                        local delta = (target.blockPosition * 3 - entitylib.character.RootPart.Position) * Vector3.new(1, 0, 1)
                        return delta.Magnitude > 0.1 and delta.Unit or nil
                    end
					for i, block in blocks do
						if not BlockIn.Enabled or not entitylib.isAlive then
							break
						end
						if (block[4] or 0) <= 0 then
							continue
						end
						for index, v in store.inventory.hotbar do
							if v.item and v.item.tool == block[3] and index ~= (store.inventory.hotbarSlot + 1) then
								hotbarSwitch(index - 1)
								break
							end
						end
						local pattern = getPyramid(currentBreakingDirection())

						for i2, pos in pattern do
							if not BlockIn.Enabled or not entitylib.isAlive then
								break
							end
							if getPlacedBlock(selfpos + pos) and i2 ~= 10 then
								continue
							end
                            -- Re-read the active break ray before every placement. If the player
                            -- changes block or face mid-run, never close that new attack corridor.
                            local direction = currentBreakingDirection()
                            local flat = pos * Vector3.new(1, 0, 1)
                            if direction and flat.Magnitude > 0 and flat.Unit:Dot(direction) > 0.65 then continue end
                            local worldPosition = selfpos + pos
                            local placed = getPlacedBlock(worldPosition)
                            for _ = 1, 3 do
                                if placed or not BlockIn.Enabled or not entitylib.isAlive then break end
                                bedwars.placeBlock(worldPosition, block[1], true)
                                local deadline = tick() + 0.35
                                repeat
                                    task.wait()
                                    placed = getPlacedBlock(worldPosition)
                                until placed or tick() >= deadline or not BlockIn.Enabled or not entitylib.isAlive
                            end
                            if not placed and BlockIn.Enabled then
                                notif('BlockIn', 'Placement was not confirmed; leaving the opening clear', 3, 'warning')
                            end
							local delay = PlaceDelay:GetRandomValue()
							if delay > 0 then
								task.wait(delay)
							end
						end
					end

					if #blocks < 1 then
						notif('BlockIn', 'Missing blocks', 4, 'warning')
					end
                    restoreState()
				end
			end
			if BlockIn.Enabled then
				BlockIn:Toggle()
			end
		end
	end,
	Tooltip = 'Automatically places strong blocks around yourself'
    })

    BreakSpeed = BlockIn:CreateSlider({
	Name = 'Break speed',
	Min = 0,
	Max = 0.3,
	Default = 0.25,
	Decimal = 100,
	Tooltip = 'How long it takes to break the surrounding block (smart mode)',
	Suffix = 'seconds',
    })
    PlaceMode = BlockIn:CreateDropdown({
	Name = 'Placement Mode',
	List = { 'Normal', 'Smart' },
	Default = 'Normal',
    })
    PlaceDelay = BlockIn:CreateTwoSlider({
	Name = 'Place Delay',
	Min = 0,
	Max = 5,
	DefaultMin = 0.07,
	DefaultMax = 0.1,
	Decimal = 5,
    })
    Bedfinder = BlockIn:CreateToggle({ Name = 'Bed finder' })
    BedBreak = BlockIn:CreateToggle({Name = 'Bed break', Tooltip = 'Keeps the active bed-breaking side open while patching outside gaps'})
    Priority = BlockIn:CreateDropdown({Name = 'Block priority', List = {'Hardest', 'Lowest cost'}, Default = 'Hardest'})
    ReturnSlot = BlockIn:CreateToggle({Name = 'Return to last slot', Default = true})
    WoolOnly = BlockIn:CreateToggle({Name = 'Wool only'})
    LimitItem = BlockIn:CreateToggle({
	Name = 'Limit to items',
	Tooltip = 'Only block-in with the block you are holding',
    })
    UseBlacklist = BlockIn:CreateToggle({
	Name = 'Use blacklist',
	Default = true,
	Function = function(call)
		if Blacklist then
			Blacklist.Object.Visible = call
		end
	end,
    })
    Blacklist = BlockIn:CreateTextList({
	Name = 'Blacklists',
	Placeholder = 'block',
	Default = {
		'cannon',
		'tnt',
		'siege_tnt',
	},
    })
end)

run(function()
    local Schematica
    local File
    local Mode
    local Transparency
    local Rotation
    local Mirror
    local VerticalOffset
    local Layer
    local parts, guidata, poschecklist = {}, {}, {}
    local point1, point2

    for x = -3, 3, 3 do
        for y = -3, 3, 3 do
            for z = -3, 3, 3 do
                if Vector3.new(x, y, z) ~= Vector3.zero then
                    table.insert(poschecklist, Vector3.new(x, y, z))
                end
            end
        end
    end

    local function checkAdjacent(pos)
        for _, v in poschecklist do
            if getPlacedBlock(pos + v) then return true end
        end
        return false
    end

    local function getPlacedBlocksInPoints(s, e)
        local list, blocks = {}, bedwars.BlockController:getStore()
        for x = (e.X > s.X and s.X or e.X), (e.X > s.X and e.X or s.X) do
            for y = (e.Y > s.Y and s.Y or e.Y), (e.Y > s.Y and e.Y or s.Y) do
                for z = (e.Z > s.Z and s.Z or e.Z), (e.Z > s.Z and e.Z or s.Z) do
                    local vec = Vector3.new(x, y, z)
                    local block = blocks:getBlockAt(vec)
                    if block and block:GetAttribute('PlacedByUserId') == lplr.UserId then
                        list[vec] = block
                    end
                end
            end
        end
        return list
    end

    local function loadMaterials()
        for _, v in guidata do
            v:Destroy()
        end
        local suc, read = pcall(function()
            return isfile(File.Value) and httpService:JSONDecode(readfile(File.Value))
        end)

        if suc and read then
            local items = {}
            for _, v in read do
                items[v[2]] = (items[v[2]] or 0) + 1
            end

            for i, v in items do
                local holder = Instance.new('Frame')
                holder.Size = UDim2.new(1, 0, 0, 32)
                holder.BackgroundTransparency = 1
                holder.Parent = Schematica.Children
                local icon = Instance.new('ImageLabel')
                icon.Size = UDim2.fromOffset(24, 24)
                icon.Position = UDim2.fromOffset(4, 4)
                icon.BackgroundTransparency = 1
                icon.Image = bedwars.getIcon({itemType = i}, true)
                icon.Parent = holder
                local text = Instance.new('TextLabel')
                text.Size = UDim2.fromOffset(100, 32)
                text.Position = UDim2.fromOffset(32, 0)
                text.BackgroundTransparency = 1
                local ownedItem = getItem(i)
                local owned = ownedItem and ownedItem.amount or 0
                text.Text = (bedwars.ItemMeta[i] and bedwars.ItemMeta[i].displayName or i)..': '..owned..' / '..v..(owned < v and '  missing '..(v - owned) or '')
                text.TextXAlignment = Enum.TextXAlignment.Left
                text.TextColor3 = uipallet.Text
                text.TextSize = 14
                text.FontFace = uipallet.Font
                text.Parent = holder
                table.insert(guidata, holder)
            end
            table.clear(read)
            table.clear(items)
        end
    end

    local function save()
        if point1 and point2 then
            local tab = getPlacedBlocksInPoints(point1, point2)
            local savetab = {}
            point1 = point1 * 3
            for i, v in tab do
                i = bedwars.BlockController:getBlockPosition(CFrame.lookAlong(point1, entitylib.character.RootPart.CFrame.LookVector):PointToObjectSpace(i * 3)) * 3
                table.insert(savetab, {
                    {
                        x = i.X,
                        y = i.Y,
                        z = i.Z
                    },
                    v.Name
                })
            end
            point1, point2 = nil, nil
            writefile(File.Value, httpService:JSONEncode(savetab))
            notif('Schematica', 'Saved '..getTableSize(tab)..' blocks', 5)
            loadMaterials()
            table.clear(tab)
            table.clear(savetab)
        else
            local mouseinfo = bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(0)
            if mouseinfo and mouseinfo.target then
                if point1 then
                    point2 = mouseinfo.target.blockRef.blockPosition
                    notif('Schematica', 'Selected position 2, toggle again near position 1 to save it', 3)
                else
                    point1 = mouseinfo.target.blockRef.blockPosition
                    notif('Schematica', 'Selected position 1', 3)
                end
            end
        end
    end

    local function load(read)
        local mouseinfo = bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(0)
        if mouseinfo and mouseinfo.target then
            local position = CFrame.new(mouseinfo.placementPosition * 3) * CFrame.Angles(0, math.rad(math.round(math.deg(math.atan2(-entitylib.character.RootPart.CFrame.LookVector.X, -entitylib.character.RootPart.CFrame.LookVector.Z)) / 45) * 45), 0)

            for _, v in read do
                local x, y, z = v[1].x, v[1].y, v[1].z
                if Mirror.Enabled then x = -x end
                local rotation = math.rad(tonumber(Rotation.Value) or 0)
                local transformed = CFrame.Angles(0, rotation, 0):VectorToWorldSpace(Vector3.new(x, y + VerticalOffset.Value * 3, z))
                if Layer.Value > 0 and math.floor(y / 3) + 1 ~= Layer.Value then continue end
                local blockpos = bedwars.BlockController:getBlockPosition((position * CFrame.new(transformed)).p) * 3
                if parts[blockpos] then continue end
                local handler = bedwars.BlockController:getHandlerRegistry():getHandler(v[2]:find('wool') and getWool() or v[2])
                if handler then
                    local part = handler:place(blockpos / 3, 0)
                    part.Transparency = Transparency.Value
                    part.CanCollide = false
                    part.Anchored = true
                    part.Parent = workspace
                    local existing = getPlacedBlock(blockpos)
                    part.Color = existing and (existing.Name == v[2] and Color3.fromRGB(75, 200, 105) or Color3.fromRGB(230, 150, 45)) or Color3.fromRGB(225, 75, 85)
                    parts[blockpos] = part
                end
            end
            table.clear(read)

            repeat
                if entitylib.isAlive then
                    local localPosition = entitylib.character.RootPart.Position
                    for i, v in parts do
                        local reachable = (i - localPosition).Magnitude < 60 and checkAdjacent(i)
                        v.Color = reachable and Color3.fromRGB(225, 75, 85) or Color3.fromRGB(110, 110, 120)
                        if reachable then
                            if not Schematica.Enabled then break end
                            if not getItem(v.Name) then continue end
                            bedwars.placeBlock(i, v.Name, false)
                            task.delay(0.1, function()
                                local block = getPlacedBlock(i)
                                if block then
                                    v:Destroy()
                                    parts[i] = nil
                                end
                            end)
                        end
                    end
                end
                task.wait()
            until getTableSize(parts) <= 0

            if getTableSize(parts) <= 0 and Schematica.Enabled then
                notif('Schematica', 'Finished building', 5)
                Schematica:Toggle()
            end
        end
    end

    Schematica = vape.Categories.World:CreateModule({
        Name = 'Schematica',
        Function = function(callback)
            if callback then
                if not File.Value:find('.json') then
                    notif('Schematica', 'Invalid file', 3)
                    Schematica:Toggle()
                    return
                end

                if Mode.Value == 'Save' then
                    save()
                    Schematica:Toggle()
                else
                    local suc, read = pcall(function()
                        return isfile(File.Value) and httpService:JSONDecode(readfile(File.Value))
                    end)

                    if suc and read then
                        load(read)
                    else
                        notif('Schematica', 'Missing / corrupted file', 3)
                        Schematica:Toggle()
                    end
                end
            else
                for _, v in parts do
                    v:Destroy()
                end
                table.clear(parts)
            end
        end,
        Tooltip = 'Save and load placements of buildings'
    })
    File = Schematica:CreateTextBox({
        Name = 'File',
        Function = function()
            loadMaterials()
            point1, point2 = nil, nil
        end
    })
    Mode = Schematica:CreateDropdown({
        Name = 'Mode',
        List = {'Load', 'Save'}
    })
    Transparency = Schematica:CreateSlider({
        Name = 'Transparency',
        Min = 0,
        Max = 1,
        Default = 0.7,
        Decimal = 10,
        Function = function(val)
            for _, v in parts do
                v.Transparency = val
            end
        end
    })
    Rotation = Schematica:CreateDropdown({Name = 'Rotation', List = {'0', '90', '180', '270'}})
    Mirror = Schematica:CreateToggle({Name = 'Mirror'})
    VerticalOffset = Schematica:CreateSlider({Name = 'Vertical offset', Min = -20, Max = 20, Default = 0})
    Layer = Schematica:CreateSlider({Name = 'Layer view', Min = 0, Max = 30, Default = 0, Tooltip = '0 shows every layer'})
end)

--[[
    Inventory
]]

run(function()
    local ArmorSwitch
    local Mode
    local Targets
    local Range

    ArmorSwitch = vape.Categories.Inventory:CreateModule({
        Name = 'ArmorSwitch',
        Function = function(callback)
            if callback then
                if Mode.Value == 'Toggle' then
                    repeat
                        local state = entitylib.EntityPosition({
                            Part = 'RootPart',
                            Range = Range.Value,
                            Players = Targets.Players.Enabled,
                            NPCs = Targets.NPCs.Enabled,
                            Wallcheck = Targets.Walls.Enabled
                        }) and true or false

                        for i = 0, 2 do
                            if (store.inventory.inventory.armor[i + 1] ~= 'empty') ~= state and ArmorSwitch.Enabled then
                                bedwars.Store:dispatch({
                                    type = 'InventorySetArmorItem',
                                    item = store.inventory.inventory.armor[i + 1] == 'empty' and state and getBestArmor(i) or nil,
                                    armorSlot = i
                                })
                                vapeEvents.InventoryChanged.Event:Wait()
                            end
                        end
                        task.wait(0.1)
                    until not ArmorSwitch.Enabled
                else
                    ArmorSwitch:Toggle()
                    for i = 0, 2 do
                        bedwars.Store:dispatch({
                            type = 'InventorySetArmorItem',
                            item = store.inventory.inventory.armor[i + 1] == 'empty' and getBestArmor(i) or nil,
                            armorSlot = i
                        })
                        vapeEvents.InventoryChanged.Event:Wait()
                    end
                end
            end
        end,
        Tooltip = 'Puts on / takes off armor when toggled for baiting'
    })
    Targets = ArmorSwitch:CreateTargets({
        Players = true,
        NPCs = true
    })
    Mode = ArmorSwitch:CreateDropdown({
        Name = 'Mode',
        List = {'Toggle', 'On Key'}
    })
    Range = ArmorSwitch:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 30,
        Default = 30,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
end)

--[[
    AutoBank

    Two ways of putting resources somewhere safe, picked with Mode.

    Skybox is the reference build's design and does not use a chest at all. Whitelisted
    resources are DROPPED, and every drop we made is then held far out of the world where
    nobody can reach it - the item entity is ours to move, so parking it at the top of the
    skybox is a safe deposit box that no server-side range check applies to. Walk up to a shop
    (or die) and the whole stash is pulled back to your head and picked up.

    Chest is the legit one: it does exactly what banking by hand does. Nothing is dropped and
    nothing is held anywhere it should not be - stand within range of your personal chest and
    the whitelisted resources go into it through the same remote the chest UI uses, so from
    the server's point of view this is a player at their chest putting things away. It can
    take the lot back out again when you are at a shop and about to spend it.

    A count of everything currently banked can be shown above the hotbar, in either mode.
]]
run(function()
    local AutoBank
    local Whitelist
    local DisplayResources
    local Mode
    local ChestRange
    local Withdraw
    local BeforeDeath
    local HPThreshold
    local BeforeDeathWhitelist
    local UI

    -- Drops we made and are currently holding out of the world.
    local droppedItems = {}
    -- itemType -> when we may next try to drop it. A stack the server refuses would otherwise
    -- be re-dropped ten times a second for the rest of the match.
    local dropCooldowns = {}
    -- Tools with an in-flight DropItem request and drops with an in-flight pickup request.
    -- The main loop runs faster than either remote can respond, so these guards prevent the
    -- same stack being banked or restored more than once.
    local pendingDrops = {}
    local pendingReclaims = {}
    -- Drops being returned must no longer be held at BANK_ORIGIN. Without a separate release
    -- state, PreRender moved them back into the sky on the very next frame, racing the pickup
    -- remote and making retrieval depend on lucky timing.
    local releasingDrops = {}
    local displayEntries = {}
    -- A danger state is one trip below the configured health threshold.  It is deliberately
    -- separate from the normal banking loop: a low-health player can remain in danger for a
    -- while and must not re-send ChestGiveItem requests every update.
    local dangerTriggered = false
    local dangerCharacter
    local beforeDeathDepositing = false
    local chestDepositBusy = false
	local dangerConnections = {}
	local evaluateDanger

    -- Keep the stash inside the local character's simulation radius. Parking drops at a fixed
    -- Y=100000 eventually hands their network ownership back to the server; after that, changing
    -- CFrame only moves the client's copy and PickupItem rejects it as still being out of range.
    -- Following the player a few hundred studs overhead remains unreachable while preserving the
    -- ownership needed to bring the server-authoritative drop back down later.
    local BANK_HEIGHT = 120
    local BANK_SPACING = 4
    local BANK_COLUMNS = 8

    local function untrackDrop(drop)
        releasingDrops[drop] = nil
        pendingReclaims[drop] = nil
        local index = table.find(droppedItems, drop)
        if index then
            table.remove(droppedItems, index)
        end
    end

    -- Bring one drop back to the head and ask for it. PickupItem only transfers one item from a
    -- stacked drop per request, so keep requesting until the server removes the emptied drop.
    local function reclaim(drop)
        if not drop or not drop.Parent then
            untrackDrop(drop)
            return
        end
        if not entitylib.isAlive then return end

        releasingDrops[drop] = true
        -- Keep moving the drop to the player even while a previous pickup request is pending.
        -- This matters during disable cleanup, when the PreRender skybox holder is disconnected.
        drop.Velocity = Vector3.zero
        drop.CFrame = entitylib.character.Head.CFrame
        if pendingReclaims[drop] then return end
        pendingReclaims[drop] = true

		local ok = pcall(function()
			-- Use the same stable handler path as cv.  The generated Client remote
			-- changes shape between BedWars builds, which made reclaim silently stop.
			bedwars.Handler:Get('PickupItemDrop'):Fire('CallServerAsync', {itemDrop = drop}):andThen(function(success)
                pendingReclaims[drop] = nil
                if not drop.Parent then
                    untrackDrop(drop)
                elseif AutoBank.Enabled then
                    -- A false response can simply mean the server has not observed the move
                    -- from the sky yet. Keep the drop at the player and retry; stacked drops
                    -- also require more than one successful pickup request.
                    task.delay(success and 0.03 or 0.1, reclaim, drop)
                end
            end, function()
                pendingReclaims[drop] = nil
                if AutoBank.Enabled and drop.Parent then
                    task.delay(0.1, reclaim, drop)
                end
            end)
        end)
        if not ok then
            pendingReclaims[drop] = nil
            if AutoBank.Enabled and drop.Parent then
                task.delay(0.1, reclaim, drop)
            end
        end
    end

    -- True while standing at a shop NPC, which is the cue to hand the stash back.
    local function atShop()
        if not entitylib.isAlive then return false end
        local opened = false
        pcall(function()
            opened = bedwars.AppController:isAppOpen('BedwarsItemShopApp') or bedwars.AppController:isAppOpen('TeamUpgradeApp')
        end)
        if opened then return true end
        local position = entitylib.character.RootPart.Position
        for _, npc in store.shop do
            local root = npc.RootPart
            if root and root.Parent and (root.Position - position).Magnitude <= 30 then
                return true
            end
        end
        return false
    end

    ------------------------------------------------------------------------------------------
    -- Chest mode
    ------------------------------------------------------------------------------------------

    local function inventoryRemotes()
        return bedwars.Client:GetNamespace('Inventory')
    end

    -- The folder our banked items actually live in. This is always the deposit target, whichever
    -- world object we happen to be stood at - so being next to somebody else's chest can never
    -- put our resources into theirs.
    local function ownPersonalFolder()
        local inventories = replicatedStorage:FindFirstChild('Inventories')
        return inventories and inventories:FindFirstChild(lplr.Name .. '_personal') or nil
    end

    local function chestPart(chest)
        return chest:IsA('Model') and chest.PrimaryPart or (chest:IsA('BasePart') and chest) or nil
    end

    -- Are we close enough to a personal chest for a deposit to look like one? The chest is only
    -- the proximity gate here, not the destination, which is what keeps this honest: no remote
    -- goes out until we are genuinely stood at one, exactly as a player has to be.
    local function atPersonalChest()
        if not entitylib.isAlive then return false end
        local opened = false
        pcall(function()
            opened = bedwars.AppController:isAppOpen('ChestApp')
        end)
        if opened then return true end
        local position = entitylib.character.RootPart.Position
        for _, chest in collectionService:GetTagged('personal-chest') do
            local part = chestPart(chest)
            if part and part.Parent and (part.Position - position).Magnitude <= ChestRange.Value then
                return true
            end
        end
        return false
    end

    -- What is sitting in the chest, by item type, for the hotbar display.
    local function chestTotals(folder)
        local totals = {}
        if not folder then return totals end
        for _, entry in folder:GetChildren() do
            totals[entry.Name] = (totals[entry.Name] or 0) + (entry:GetAttribute('Amount') or 1)
        end
        return totals
    end

    -- Put the whitelisted stacks in. SetObservedChest is what the client sends when the chest UI
    -- opens and what the server checks the deposit against, so it brackets the deposits rather
    -- than being sent per item.
    local function depositToChest(folder, allowedItems)
        if chestDepositBusy then return false end
        allowedItems = allowedItems or Whitelist.ListEnabled
        local wanted = {}
        for _, item in store.inventory.inventory.items do
            local name = item.itemType or (item.tool and item.tool.Name)
            if name and item.tool and table.find(allowedItems, name) and (dropCooldowns[name] or 0) < os.clock() then
                table.insert(wanted, {Name = name, Tool = item.tool})
            end
        end
        if #wanted == 0 then return false end

        chestDepositBusy = true
        pcall(function()
            inventoryRemotes():Get('SetObservedChest'):SendToServer(folder)
        end)
        for _, entry in wanted do
            if not AutoBank.Enabled then break end
            local ok, given = pcall(function()
                return inventoryRemotes():Get('ChestGiveItem'):CallServer(folder, entry.Tool)
            end)
            if not ok or not given then
                -- Refused - a full chest, or a stack the server will not take. Back off rather
                -- than asking again ten times a second for the rest of the match.
                dropCooldowns[entry.Name] = os.clock() + 5
            end
        end
        pcall(function()
            inventoryRemotes():Get('SetObservedChest'):SendToServer(nil)
        end)
        chestDepositBusy = false
        return true
    end

    local function currentHealthPercent()
        local character = lplr.Character
        if not character then return nil end
        -- BedWars keeps the authoritative health values as character attributes. Fall back to
        -- Humanoid values for transitions while those attributes are being recreated on respawn.
        local health = character:GetAttribute('Health')
        local maximum = character:GetAttribute('MaxHealth')
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if type(health) ~= 'number' then health = humanoid and humanoid.Health end
        if type(maximum) ~= 'number' or maximum <= 0 then maximum = humanoid and humanoid.MaxHealth end
        if type(health) ~= 'number' or type(maximum) ~= 'number' or maximum <= 0 then return nil end
        return math.clamp((health / maximum) * 100, 0, 100)
    end

	local function queueEmergencyDrop(item, token, bankPosition, bankCharacter)
		local name, tool = item and (item.itemType or (item.tool and item.tool.Name)), item and item.tool
		if not name or not tool or pendingDrops[tool] or (dropCooldowns[name] or 0) >= os.clock() then return false end
		pendingDrops[tool] = true
		local amount = item.amount
		-- Do not task.cancel a coroutine blocked inside the remote call: the server may already
		-- have dropped the stack. The generation check owns the late reply and immediately
		-- reclaims it after a disable/respawn instead of abandoning it in the world.
		task.spawn(function()
			local ok, drop = pcall(function()
				local handler = bedwars.Handler and bedwars.Handler:Get('DropItem')
				if not handler then error('DropItem remote unavailable') end
				return handler:Fire('CallServer', {item = tool, amount = amount})
			end)
			pendingDrops[tool] = nil
			if not ok or not drop or not drop.Parent then
				dropCooldowns[name] = os.clock() + 1
				return
			end
			if not table.find(droppedItems, drop) then
				table.insert(droppedItems, drop)
				drop:ClearAllChildren()
				drop.AncestryChanged:Once(function() untrackDrop(drop) end)
			end
			if typeof(bankPosition) == 'Vector3' and drop.Parent then
				pcall(function()
					drop.Velocity = Vector3.zero
					drop.CFrame = CFrame.new(bankPosition + Vector3.new(0, BANK_HEIGHT, 0))
				end)
			end
			if not AutoBank.Enabled or AutoBank.Generation ~= token or lplr.Character ~= bankCharacter then reclaim(drop) end
		end)
		return true
	end

    local function bankBeforeDeath()
        if beforeDeathDepositing or not AutoBank.Enabled or not BeforeDeath.Enabled then return end
        beforeDeathDepositing = true
		local token = AutoBank.Generation
		local bankCharacter = lplr.Character
		local character = entitylib.character
		local root = character and character.RootPart
		local bankPosition = root and root.Position
		local deposited = false
		if Mode.Value == 'Chest' and not chestDepositBusy then
			local folder = entitylib.isAlive and ownPersonalFolder() or nil
			if folder and atPersonalChest() then
				deposited = depositToChest(folder, BeforeDeathWhitelist.ListEnabled)
			end
		end
		-- A lethal hit does not leave time to walk to a chest. If the legit chest path is not
		-- available, immediately use the module's existing drop-and-hold bank for the selected
		-- stacks. Every request is guarded by the current module generation so late replies cannot
		-- re-apply state after a toggle or respawn.
		if not deposited then
			local inventory = store.inventory and store.inventory.inventory
			for _, item in type(inventory) == 'table' and inventory.items or {} do
				local name = item.itemType or (item.tool and item.tool.Name)
				if name and table.find(BeforeDeathWhitelist.ListEnabled, name) then
					queueEmergencyDrop(item, token, bankPosition, bankCharacter)
				end
			end
		end
		beforeDeathDepositing = false
    end

	local function disconnectDangerConnections()
		for _, connection in dangerConnections do pcall(function() connection:Disconnect() end) end
		table.clear(dangerConnections)
	end

	local function bindDangerCharacter(character)
		disconnectDangerConnections()
		dangerCharacter, dangerTriggered = character, false
		if not character then return end
		evaluateDanger = function()
			if not AutoBank.Enabled or not BeforeDeath.Enabled or lplr.Character ~= character then return end
			local percent = currentHealthPercent()
			if not percent then return end
			if percent <= HPThreshold.Value then
				if not dangerTriggered then dangerTriggered = true; bankBeforeDeath() end
			elseif percent >= math.min(100, HPThreshold.Value + 5) then
				dangerTriggered = false
			end
		end
		for _, attribute in {'Health', 'MaxHealth'} do
			table.insert(dangerConnections, character:GetAttributeChangedSignal(attribute):Connect(evaluateDanger))
		end
		local humanoid = character:FindFirstChildOfClass('Humanoid')
		if humanoid then
			table.insert(dangerConnections, humanoid.HealthChanged:Connect(evaluateDanger))
			table.insert(dangerConnections, humanoid:GetPropertyChangedSignal('MaxHealth'):Connect(evaluateDanger))
		end
		evaluateDanger()
	end

    -- Take matching stacks back out. ChestGetItem transfers one item per call rather than the
    -- Accessory's entire Amount, so issue one request for every item that was counted.
    local function withdrawFromChest(folder, itemType)
        local contents = folder:GetChildren()
        if #contents == 0 then return end

        pcall(function()
            inventoryRemotes():Get('SetObservedChest'):SendToServer(folder)
        end)
        local requestBudget = 8
        for _, entry in contents do
            if not AutoBank.Enabled then break end
            if entry:IsA('Accessory') and table.find(Whitelist.ListEnabled, entry.Name)
                and (not itemType or entry.Name == itemType) then
                local amount = math.max(entry:GetAttribute('Amount') or 1, 1)
                for _ = 1, amount do
                    if not AutoBank.Enabled or not entry.Parent or requestBudget <= 0 then break end
                    pcall(function()
                        inventoryRemotes():Get('ChestGetItem'):CallServer(folder, entry)
                    end)
                    requestBudget -= 1
                end
            end
            if requestBudget <= 0 then break end
        end
        pcall(function()
            inventoryRemotes():Get('SetObservedChest'):SendToServer(nil)
        end)
    end

    local function addDisplayEntry(itemType)
        local icon = Instance.new('ImageButton')
        icon.Name = itemType
        icon.Image = bedwars.getIcon({itemType = itemType}, true)
        icon.Size = UDim2.fromOffset(32, 32)
        icon.BackgroundTransparency = 1
        icon.LayoutOrder = #UI:GetChildren()
        icon.Parent = UI
        local amount = Instance.new('TextLabel')
        amount.Name = 'Amount'
        amount.Size = UDim2.fromScale(1, 1)
        amount.BackgroundTransparency = 1
        amount.Text = ''
        amount.TextColor3 = Color3.new(1, 1, 1)
        amount.TextSize = 16
        amount.TextStrokeTransparency = 0.3
        amount.Font = Enum.Font.Arial
        amount.Parent = icon
        displayEntries[itemType] = amount
        icon.Activated:Connect(function()
            -- cv storage is always a held item drop, so a resource icon returns
            -- that matching drop directly instead of branching into Chest mode.
            for _, drop in table.clone(droppedItems) do
                if drop.Name == itemType then reclaim(drop) end
            end
        end)
    end

    AutoBank = vape.Categories.Inventory:CreateModule({
        Name = 'AutoBank',
        Function = function(callback)
            if callback then
                -- cv's AutoBank loop.  Keep the current display helper and the
                -- Before death hook, but use cv's direct drop/hold/reclaim flow
                -- rather than the alternate chest/banking implementation below.
                UI = Instance.new('Frame')
                UI.Size = UDim2.new(1, 0, 0, 32)
                UI.AnchorPoint = Vector2.new(0.5, 0)
                UI.Position = UDim2.new(0.5, 0, 0, -240)
                UI.BackgroundTransparency = 1
                UI.Visible = DisplayResources.Enabled
                UI.Parent = vape.gui
                AutoBank:Clean(UI)
                local layout = Instance.new('UIListLayout')
                layout.FillDirection = Enum.FillDirection.Horizontal
                layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
                layout.SortOrder = Enum.SortOrder.LayoutOrder
                layout.Parent = UI

                table.clear(displayEntries)
                for _, itemType in Whitelist.ListEnabled do
                    addDisplayEntry(itemType)
                end

                local near = false
                local base = CFrame.new(1e3, 1e5, 1e3)
				local rows = Random.new():NextInteger(1, 20000)
				local holdAccumulator = 0
				AutoBank:Clean(runService.Heartbeat:Connect(function(delta)
					holdAccumulator += delta
					if holdAccumulator < 0.05 then return end
					holdAccumulator = 0
					local totals = {}
					for index, drop in droppedItems do
						if drop and drop.Parent then
							totals[drop.Name] = (totals[drop.Name] or 0) + (drop:GetAttribute('Amount') or 0)
							drop.Velocity = Vector3.zero
							if entitylib.isAlive then
								drop.CFrame = near and entitylib.character.Head.CFrame
									or base + Vector3.new((index % rows) * 1200, 0, math.floor(index / rows) * 1200)
							end
						else
							untrackDrop(drop)
						end
                    end
                    for itemType, label in displayEntries do
                        label.Text = tostring(totals[itemType] or 0)
                    end
                end))

				AutoBank:Clean(disconnectDangerConnections)
				AutoBank:Clean(lplr.CharacterAdded:Connect(bindDangerCharacter))
				bindDangerCharacter(lplr.Character)

                repeat
                    local hotbar = lplr.PlayerGui:FindFirstChild('hotbar')
                    local hotbarFrame = hotbar and hotbar:FindFirstChild('1')
                    hotbar = hotbarFrame and hotbarFrame:FindFirstChild('HotbarHealthbarContainer')
                    if hotbar then
                        UI.Position = UDim2.new(0.5, 0, 0, (hotbar.AbsolutePosition.Y + guiService:GetGuiInset().Y) - 60)
                    end

					if entitylib.isAlive and not atShop() then
						near = false
						local inventory = store.inventory and store.inventory.inventory
						for _, item in type(inventory) == 'table' and inventory.items or {} do
							local name = item.tool and item.tool.Name or item.itemType
							if name and item.tool and table.find(Whitelist.ListEnabled, name)
								and not pendingDrops[item.tool] and (dropCooldowns[name] or 0) < os.clock() then
								local token = AutoBank.Generation
								local bankCharacter = lplr.Character
								pendingDrops[item.tool] = true
								task.spawn(function()
									local ok, drop = pcall(function()
										return bedwars.Handler:Get('DropItem'):Fire('CallServer', {
											item = item.tool,
											amount = item.amount
										})
									end)
									pendingDrops[item.tool] = nil
									if not ok or not drop or not drop.Parent then
										dropCooldowns[name] = os.clock() + 5
									elseif not AutoBank.Enabled or AutoBank.Generation ~= token or lplr.Character ~= bankCharacter then
										reclaim(drop)
									elseif not table.find(droppedItems, drop) then
										table.insert(droppedItems, drop)
										drop:ClearAllChildren()
										drop.AncestryChanged:Once(function()
											untrackDrop(drop)
										end)
									end
								end)
							end
                        end
					elseif entitylib.isAlive then
						near = true
						for _, drop in droppedItems do
							if drop and drop.Parent then reclaim(drop) end
						end
					end
                    task.wait(0.1)
                until not AutoBank.Enabled
                return
            end

            if not callback then
                -- Give everything back rather than leaving it stranded in the sky. Bounded:
                -- drain what we can and stop, instead of spinning until the module is switched
                -- back on (which is what the reference build did, and never returned).
                local deadline = tick() + 3
                while #droppedItems > 0 and tick() < deadline and entitylib.isAlive do
                    for _, drop in table.clone(droppedItems) do
                        reclaim(drop)
                    end
                    task.wait(0.1)
                end
                -- Never forget a live drop that the server has not returned yet. If cleanup
                -- times out (for example while respawning), the next enable can restore it.
                for _, drop in table.clone(droppedItems) do
                    if not drop or not drop.Parent then untrackDrop(drop) end
                end
                table.clear(pendingDrops)
                table.clear(pendingReclaims)
            end
        end
    })
end)

run(function()
    local NoBob
    local oldPlayAnimation

    local function refreshViewmodel()
        pcall(function()
            bedwars.InventoryViewmodelController:handleStore(
                bedwars.Store:getState()
            )
        end)
    end

    NoBob = vape.Categories.Render:CreateModule({
        Name = 'NoBob',
        Function = function(callback)
            if callback then
                oldPlayAnimation = bedwars.ViewmodelController.playAnimation

                bedwars.ViewmodelController.playAnimation = function(self, animationType, ...)
                    if animationType == bedwars.AnimationType.FP_WALK then
                        return
                    end

                    return oldPlayAnimation(self, animationType, ...)
                end

                -- Rebuild the held-item viewmodel so an already-playing
                -- walking animation is cleared immediately.
                refreshViewmodel()
            else
                if oldPlayAnimation then
                    bedwars.ViewmodelController.playAnimation = oldPlayAnimation
                    oldPlayAnimation = nil
                end

                -- Restore the normal BedWars viewmodel state.
                refreshViewmodel()
            end
        end,
        Tooltip = 'Removes the sword bob animation while moving'
    })
end)